const h=[{id:"o201",n:201,t:0,origin:"original",eco:"P1",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","vision","root-cause"],type:"mc",q:"A hybrid product program builds a connected thermostat: hardware follows phase gates while the firmware team works in sprints. The charter says the goal is 'a simple home-comfort experience.' For two months, firmware demos have been rejected by hardware leads who say the result is 'not what we signed up for,' while firmware insists it follows the charter. The demo notes say only 'rejected', with no reasons recorded. Nobody has yet compared how the two groups understand the goal. What should the project manager do first?",opts:["Analyze the rejected-demo notes against the charter with the sponsor, then reissue clearer wording before the next sprint demo","Escalate the two months of rejected demos to the program sponsor, with both groups' positions, and ask her to rule on which reading stands","Bring the firmware product owner and hardware leads together to compare how each reads 'simple home-comfort experience' and where they differ","Ask the firmware product owner to write acceptance criteria describing 'simple' for each story, with a hardware lead reviewing them each sprint"],ans:[2],why:["Sai: phân tích ghi chú demo cùng sponsor rồi ban hành câu chữ mới là hợp lý nếu ghi chú nêu lý do từ chối, nhưng ở đây ghi chú chỉ ghi 'rejected' không có lý do nên không cho biết hai nhóm lệch ở đâu; câu mới vẫn có thể bị đọc theo hai nghĩa.","Sai: nhờ sponsor phân xử là bước leo thang hợp lệ khi hai bên đã trình bày rõ lập trường; ở đây chưa ai đặt hai cách hiểu cạnh nhau nên sponsor sẽ phải phán mà thiếu dữ kiện.","Đúng: demo bị từ chối suốt hai tháng dù firmware nói bám charter, ghi chú không nêu lý do và chưa ai so sánh cách hiểu của hai nhóm. PM đưa product owner firmware và các hardware lead ngồi cạnh nhau để tìm chỗ hai cách hiểu lệch trước khi sửa bất cứ thứ gì.","Sai: tiêu chí chấp nhận do product owner soạn cho từng story là công cụ tốt, nhưng viết chúng khi chưa biết hai nhóm lệch hiểu ở đâu là xử lý triệu chứng; vấn đề nằm ở cách hiểu mục tiêu chung, không ở từng story."],exp:"Task P1 (Develop a common vision), enabler 'break down situations to identify the root cause of a misunderstanding of the vision'. Khi sản phẩm bị từ chối lặp lại, trước hết tìm xem hai bên hiểu tầm nhìn khác nhau ở đâu. Quy tắc nhớ: hiểu nguyên nhân trước, sửa tài liệu hoặc quy trình sau; sponsor là bước leo thang chứ không phải bước đầu."},{id:"o202",n:202,t:0,origin:"original",eco:"P2",domain:"people",approach:"agile",tags:["agile","eco-2026","conflict","ground-rules"],type:"mc",q:"A scrum team's two senior developers disagree on whether to refactor the payment module this sprint. Their working agreement says technical disagreements are settled in a 15-minute discussion after stand-up. Instead, one developer has posted a sharp criticism of the other's design in the team channel, and two junior members have stopped commenting in stand-up. The next retrospective is nine days away. What should the project manager do?",opts:["Put a disagreement-handling topic on the next retrospective agenda and have the scrum master recap the working agreement","Allow the tech lead to make the final refactoring call after hearing both designs, then record the decision for the sprint","Pair the two developers on the payment module this sprint so that they settle the design question and the scope in code","Meet both developers about the channel post and hold the post-stand-up discussion their working agreement requires"],ans:[3],why:["Sai: retrospective là diễn đàn tốt để rà soát cách xử lý bất đồng, nhưng còn chín ngày nữa; trong lúc đó bài công kích vẫn nằm trên kênh và hai thành viên junior đã im lặng, nên việc giữa hai developer cần xử lý trước.","Sai: nhờ tech lead chốt quyết định kỹ thuật là hợp lý khi đội bế tắc về thiết kế, nhưng vấn đề ở đây là cách hai người bất đồng đã vi phạm thỏa thuận làm việc; quyết định refactor không sửa hành vi hay khôi phục bầu không khí.","Sai: lập trình cặp là cách tốt để giải quyết bất đồng thiết kế, nhưng stem cho thấy vấn đề là bài công kích trên kênh chung và hai thành viên junior ngừng phát biểu; ghép cặp không xử lý việc vi phạm thỏa thuận làm việc.","Đúng: thỏa thuận làm việc đã nêu rõ cách xử lý bất đồng kỹ thuật (thảo luận 15 phút sau stand-up) nhưng một người đã đăng bài công kích thay vì làm theo. PM trao đổi với cả hai về bài đăng và tổ chức đúng buổi thảo luận đó."],exp:"Task P2 (Manage conflicts), enabler 'manage and rectify ground rule violations'. Khi đội đã có working agreement, PM dùng chính thỏa thuận đó làm nền: nhắc lại, tạo điều kiện thực hiện đúng cách, không áp đặt hay né tránh. Bẫy: 'đợi retrospective' nghe hợp agile nhưng là chậm trễ khi thành viên đã ngại lên tiếng."},{id:"o203",n:203,t:0,origin:"original",eco:"P3",domain:"people",approach:"agile",tags:["agile","eco-2026","leadership-style","situational-leadership"],type:"mc",q:"A project manager moves to an agile team of six contract developers who have never worked in sprints. Having just led a mature self-organizing team, the manager adopts a hands-off style and lets the new team plan freely. After two sprints the team has missed both sprint goals, and members say they are unsure who decides what. The team has asked for guidance on how sprints should run. How should the project manager adjust?",opts:["Enlist the sponsor to bring in an experienced Scrum coach to run the team's ceremonies in place of the project manager","Facilitate a retrospective on the two missed sprint goals and let the team agree its own remedies before the next sprint","Provide clear structure and coaching on sprint practices for now, then hand over decisions as the team gains capability","Switch the team to a baselined plan with a detailed work breakdown structure, so each task has a fixed owner"],ans:[2],why:["Sai: một coach giàu kinh nghiệm có thể giúp, nhưng giao toàn bộ việc điều phối ceremony cho người khác là bỏ vai trò dẫn dắt của PM; vấn đề nằm ở phong cách lãnh đạo chưa phù hợp, không phải thiếu người tổ chức buổi họp.","Sai: retrospective là công cụ tốt khi đội đã có nền tảng, nhưng đội này chưa từng làm sprint và chính họ xin hướng dẫn; để họ tự đề ra biện pháp mà không có cấu trúc là tiếp tục buông tay.","Đúng: đội mới, chưa quen sprint, và đã nói rõ họ không biết ai quyết gì. PM chuyển sang cấu trúc cộng huấn luyện, rồi trao quyền dần khi năng lực đội tăng, đúng situational leadership.","Sai: kế hoạch baseline với WBS chi tiết là cách làm đúng của dự án predictive; ở đây đội đang theo agile nên đổi phương pháp là trả lời sai câu hỏi về phong cách lãnh đạo và làm mất lợi ích của sprint."],exp:"Task P3 (Lead the project team), enabler 'determine an appropriate leadership style'. Phong cách lãnh đạo phải đổi theo mức độ trưởng thành của đội (situational leadership): càng mới càng cần hướng dẫn, càng trưởng thành càng trao quyền. Bẫy: nghĩ rằng làm agile nghĩa là luôn buông tay."},{id:"o204",n:204,t:0,origin:"original",eco:"P4",domain:"people",approach:"predictive",tags:["predictive","eco-2026","stakeholder-identification","register"],type:"mc",q:"During excavation for a hospital wing, a neighborhood association writes that vibration is damaging nearby homes. The project manager has already added the association to the stakeholder register and analyzed it: high interest, moderate influence, and a specific concern about cracked walls. The site's vibration monitors show readings within permit limits, and the baselined plan has a formal communications management plan. Nobody has yet contacted the association. What should the project manager do next?",opts:["Ask the stakeholder-engagement lead to update the register with the association's interest, influence, and concerns, then reassess its engagement level","Reply formally, over the site engineer's signature, that readings are within permit limits, and route follow-up questions through the contractor's liaison","Sit down with the association's leaders and the site engineer to share the monitoring readings and settle how concerns will be raised and answered","Commission an independent survey of the nearby homes by a surveyor the association agrees to, then reply to it with the findings"],ans:[2],why:["Sai: để người phụ trách tương tác cập nhật register và đánh giá lại mức độ tương tác là bước đúng khi bên liên quan mới xuất hiện, nhưng stem cho biết việc này đã xong; làm lại chỉ kéo dài thời gian trong khi hội chưa được liên hệ.","Sai: trả lời chính thức rằng số liệu đạt giới hạn cấp phép là đúng sự thật nhưng một chiều; mối quan ngại cụ thể (nứt tường) cần đối thoại, và chuyển câu hỏi qua đầu mối của nhà thầu là sai kênh trong kế hoạch truyền thông.","Đúng: hội đã được ghi nhận và phân tích (quan tâm cao, ảnh hưởng vừa, lo ngại cụ thể), có số đo rung và chưa ai liên hệ. Bước tiếp theo là cùng kỹ sư công trường gặp lãnh đạo hội, chia sẻ số liệu và thống nhất kênh tiếp nhận mối lo theo kế hoạch truyền thông.","Sai: khảo sát độc lập do đơn vị hội chấp nhận là hành động có giá trị nếu hội phản bác số liệu, nhưng hội chưa được xem số liệu nào; đặt khảo sát trước khi liên hệ nghĩa là hội tiếp tục chờ mà không nhận được phản hồi."],exp:"Task P4 (Engage stakeholders), enabler 'execute the stakeholder engagement plan'. Bên liên quan mới đã được nhận diện và phân tích thì bước tiếp theo là tương tác theo kế hoạch truyền thông: gặp, chia sẻ dữ liệu, thống nhất kênh. Quy tắc nhớ: phân tích xong thì hành động, đừng phân tích lại."},{id:"o227",n:227,t:0,origin:"original",eco:"P1",domain:"people",approach:"predictive",tags:["predictive","eco-2026","vision","baseline"],type:"mc",q:"A new predictive ERP project is approaching baseline approval. In separate interviews the sponsor described success as a 15 percent reduction in operating cost, while the operations director described it as no disruption to order fulfilment during rollout. At a joint session last week both leaders accepted that each goal matters, but the charter still lists only broad benefits and the baseline review is on Friday. What should the project manager do next?",opts:["Reconvene the sponsor and the operations director in a facilitated workshop and record the priority they agree in the charter","Add a benefits register to the plan that tracks cost reduction and fulfilment continuity as separate measures after go-live","Write both goals as measurable success criteria in the charter, obtain both leaders' sign-off, and baseline the plan on Friday","Rank the sponsor's cost target above the other goal in the charter and log the fulfilment concern in the risk register"],ans:[2],why:["Sai: họp thêm để hai lãnh đạo chốt thứ tự ưu tiên là đúng nếu họ chưa thừa nhận mục tiêu của nhau, nhưng ở đây cả hai đã chấp nhận cả hai mục tiêu; cái còn thiếu là tiêu chí đo được.","Sai: sổ theo dõi lợi ích sau go-live là đúng nếu tiêu chí thành công đã được ký, nhưng ở đây charter chỉ ghi lợi ích chung và baseline duyệt vào thứ Sáu, nên phải chốt tiêu chí trước khi theo dõi.","Đúng: hai lãnh đạo đã thừa nhận cả hai mục tiêu, charter còn chung chung và baseline vào thứ Sáu. Viết cả hai thành tiêu chí đo được, xin cả hai ký, rồi mới baseline là bước còn thiếu.","Sai: đặt mục tiêu chi phí lên trên là đúng nếu sponsor đã nói mục tiêu giao hàng nằm ngoài phạm vi, nhưng ở đây cả hai mục tiêu đều đã được chấp nhận, nên hạ một bên xuống thành rủi ro là sai."],exp:"Task P1, enabler 'help ensure a shared vision with key stakeholders'. Khi các bên đã thừa nhận cả hai mục tiêu, việc còn lại là biến chúng thành tiêu chí đo được và xin sign-off trước khi baseline. Quy tắc nhớ: đã đối thoại xong thì chốt bằng văn bản đo được, đừng họp lại hay đẩy cho change control."},{id:"o228",n:228,t:0,origin:"original",eco:"P1",domain:"people",approach:"agile",tags:["agile","eco-2026","vision","promotion"],type:"mc",q:"Six months into building a mobile banking app, three squads each prioritize their own features and sprint reviews show inconsistent user flows. The product vision was agreed in a launch workshop and is still considered valid, but when the project manager asks team members to state it, most cannot. What should the project manager do?",opts:["Run a workshop with the squad leads to restate the vision in simpler words and have each squad confirm its own wording","Open every planning and review session with the vision and trace each backlog item back to it","Have the product owner reprioritize the backlog across the three squads by value and publish the new order at the next review","Commission a UX designer to align the squads' user flows before the next sprint review, one squad at a time"],ans:[1],why:["Sai: viết lại tầm nhìn bằng từ đơn giản là hợp lý khi tầm nhìn khó hiểu, nhưng stem nói tầm nhìn vẫn còn hiệu lực và đã được thống nhất; mỗi squad tự xác nhận phiên bản riêng sẽ làm ba cách hiểu thay vì một.","Đúng: tầm nhìn còn hiệu lực nhưng hầu hết thành viên không nêu được; PM đưa tầm nhìn vào nghi thức hằng ngày (planning, review) và gắn từng backlog item vào nó, đây là cách promote tầm nhìn.","Sai: sắp xếp lại backlog theo giá trị là việc của product owner và có ích, nhưng nó xử lý hệ quả (ưu tiên lệch) chứ không xử lý nguyên nhân là các squad không nhớ tầm nhìn nên sẽ lệch lại.","Sai: rà soát luồng người dùng với UX designer sửa được triệu chứng thấy ở sprint review, nhưng là vấn đề thứ cấp; gốc rễ là ba squad không cùng hướng về một tầm nhìn nên sự thiếu nhất quán sẽ quay lại."],exp:"Task P1, enabler 'promote the shared vision'. Tầm nhìn chỉ có tác dụng khi xuất hiện trong ra quyết định hằng ngày: kế hoạch sprint, ưu tiên backlog, buổi review. Quy tắc nhớ: promote là gắn vào nghi thức và công việc, không phải nhắc lại bằng thông báo."},{id:"o229",n:229,t:0,origin:"original",eco:"P1",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","ai","vision","validation"],type:"mc",q:"On a hybrid logistics platform project, the project manager used a generative AI assistant to turn workshop notes into a draft vision statement. The draft reads well, but the compliance group says it omits their audit-trail priority and field operations calls it generic, and nobody has checked the draft against the workshop notes. The phase-gate review is two weeks away. What should the project manager do?",opts:["Check the draft against the workshop notes with both groups, correct what the AI missed, and get their confirmation","Merge both groups' written edits into the draft, and have the sponsor approve the final wording for the gate package","Label the draft provisional in the gate package, have the PMO lead list both groups' open comments, and revise the wording after the review","Verify the draft against the AI vendor's accuracy report, then circulate the corrected version to both groups for information"],ans:[0],why:["Đúng: chưa ai đối chiếu bản nháp AI với ghi chép workshop, và hai nhóm phản hồi khác nhau. PM phải coi bản nháp là đầu vào, kiểm chứng cùng các bên rồi chỉnh đến khi họ xác nhận; AI không thay thế sự đồng thuận.","Sai: gộp chỉnh sửa rồi xin sponsor duyệt là đúng nếu hai nhóm đã thống nhất nội dung và chỉ cần thẩm quyền chốt, nhưng ở đây hai nhóm đọc bản nháp theo hai hướng và chưa ai đối chiếu với workshop.","Sai: đánh dấu tạm thời trong gói phase-gate và nhờ PMO lead liệt kê góp ý là đúng nếu gate chấp nhận mục còn mở và còn thời gian sửa sau, nhưng ở đây bản nháp chưa được kiểm chứng và còn hai tuần, đủ để xác nhận trước gate.","Sai: đối chiếu với báo cáo độ chính xác của nhà cung cấp AI nghe thận trọng, nhưng báo cáo đó chỉ nói về độ chính xác chung, không so bản nháp với ghi chép workshop mà hai nhóm đang phản ánh; gửi để biết cũng không tạo xác nhận của họ."],exp:"Task P1 (Develop a common vision), enabler 'help ensure a shared vision with key stakeholders', trong bối cảnh dùng AI. AI hỗ trợ soạn thảo nhưng đầu ra phải được kiểm chứng và các bên liên quan phải cùng xác nhận; trách nhiệm cuối cùng thuộc PM. Bẫy: coi văn bản trôi chảy là văn bản đã được đồng thuận."},{id:"o230",n:230,t:0,origin:"original",eco:"P1",domain:"people",approach:"predictive",tags:["predictive","eco-2026","vision","change-control"],type:"mc",q:"An 18-month predictive ERP replacement has a baselined plan and a vision of 'one ERP for the company's two plants.' At month nine the company announces a merger that will add three more plants within two years. The sponsor has confirmed that the merger is going ahead and that the new ERP must serve all five plants, and the project manager's impact assessment shows about six months of added work. The team keeps working to the original plan. What should the project manager do?",opts:["Submit a change request that extends the vision to five plants, then take it to the change control board","Reassess the merger's impact on the vision with the sponsor, then decide whether any change is needed","Cut the ERP scope back to the original two plants and have the program office plan a separate follow-on project for the three new ones","Finish the current phase against the approved vision and put the five-plant scope into the next phase's planning"],ans:[0],why:["Đúng: sponsor đã xác nhận cần phục vụ năm nhà máy và PM đã đánh giá tác động (thêm khoảng sáu tháng). Với dự án predictive đã baseline, bước tiếp theo là gửi change request để đưa thay đổi qua change control.","Sai: đánh giá lại tác động cùng sponsor là bước đúng khi mới có tin sáp nhập, nhưng stem cho biết sponsor đã xác nhận và PM đã có số liệu; làm lại chỉ trì hoãn thay đổi chính thức.","Sai: tách thành dự án nối tiếp là cách xử lý phạm vi hợp lệ khi sponsor chấp nhận, nhưng stem nói sponsor đã xác nhận ERP mới phải phục vụ cả năm nhà máy; PM không thể tự thu hẹp mục tiêu đã xác nhận.","Sai: dồn phạm vi năm nhà máy sang kế hoạch của giai đoạn sau nghe hợp lý, nhưng đội vẫn làm tiếp theo một tầm nhìn đã biết là lỗi thời và thiết kế giai đoạn hiện tại có thể không phục vụ được năm nhà máy."],exp:"Task P1, enabler 'keep the vision current'. Khi bối cảnh thay đổi, rà soát tầm nhìn cùng các bên liên quan; trong dự án predictive, thay đổi phạm vi hay mục tiêu đã baseline phải đi qua change control. Bẫy: sửa tài liệu một mình hoặc chờ phase gate."},{id:"o231",n:231,t:0,origin:"original",eco:"P1",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","vision","root-cause","vendor"],type:"mc",q:"A hybrid digital banking program has a vendor team of eight joining in month three. A pulse check shows most vendor members describe the program's vision incorrectly, while internal team members describe it well. The vision was presented at the kickoff workshop and then shared with the vendor lead by email. What should the project manager do first?",opts:["Direct the vendor lead to re-brief the vendor team on the vision using the kickoff slides, with attendance recorded","Talk to several vendor members about how they received the vision and where they differ","Review the vision document with the vendor lead and simplify its wording for readers working in a second language","Include the vision in the vendor onboarding pack and have each member sign a read-and-understood form"],ans:[1],why:["Sai: briefing lại bằng slide kickoff lặp lại đúng kênh đã không hiệu quả; chưa biết vì sao vendor hiểu sai thì không có lý do để tin lần phổ biến thứ hai sẽ khác.","Đúng: nhóm nội bộ hiểu đúng còn vendor thì sai dù cùng một nội dung; PM hỏi trực tiếp các thành viên vendor để biết nguyên nhân (đến sau, kênh truyền, ngôn ngữ, động cơ) trước khi thiết kế biện pháp.","Sai: đơn giản hóa câu chữ có thể đúng nếu ngôn ngữ là nguyên nhân, nhưng đó mới là giả định; stem chưa cho thấy nguyên nhân nên sửa tài liệu trước khi hỏi là kê đơn trước khi chẩn đoán.","Sai: đưa vào gói onboarding và yêu cầu ký đã đọc là một thủ tục hợp lệ, nhưng chữ ký chỉ chứng minh đã nhận chứ không chứng minh đã hiểu; nó cũng không cho biết vì sao hiểu sai."],exp:"Task P1, enabler 'break down situations to identify the root cause of a misunderstanding of the vision'. Khi một nhóm hiểu sai, hỏi và quan sát để biết lý do (đến sau, kênh truyền, ngôn ngữ, động cơ) rồi mới thiết kế biện pháp. Quy tắc nhớ: chẩn đoán trước khi kê đơn."},{id:"o232",n:232,t:0,origin:"original",eco:"P1",domain:"people",approach:"agile",tags:["agile","eco-2026","vision","product-owner"],type:"mc",q:"A start-up's agile team is building a subscription product. The product owner wants to target small clinics, while the head of sales is pitching hospital chains, and backlog priorities swing every sprint as each lobbies the team. The team is small and cannot build for both segments at once. The team is confused about which customers they serve. What should the project manager do?",opts:["Review customer interviews and market data with the product owner and let the product owner choose the segment","Build features for both segments for a few sprints, then use sprint-review results to show which segment responds best","Define one persona for each segment and have the team size the backlog against both before the next planning session","Ask the product owner and the sales head to agree target customers and value in a vision session with the team"],ans:[3],why:["Sai: product owner sở hữu backlog và dữ liệu thị trường là đầu vào tốt, nhưng người phụ trách bán hàng đang vận động mạnh cho phân khúc khác; chỉ một bên chốt thì bên kia không đồng thuận và xung đột sẽ lặp lại.","Sai: thử nghiệm song song hai phân khúc là kỹ thuật agile hợp lệ khi đội đủ sức, nhưng stem nói đội nhỏ không làm cả hai được; chia sức làm đội thêm rối trong khi chưa ai thống nhất tầm nhìn.","Sai: persona và ước lượng theo hai phân khúc là kỹ thuật hữu ích để làm rõ khách hàng, nhưng nó không giải quyết bất đồng giữa product owner và trưởng bộ phận bán hàng; đội nhỏ vẫn không biết phải phục vụ ai.","Đúng: product owner và trưởng bộ phận bán hàng kéo ưu tiên hai hướng và đội bối rối. PM tạo điều kiện để hai người cùng thống nhất khách hàng mục tiêu và giá trị, với sự tham gia của đội."],exp:"Task P1, enabler 'help ensure a shared vision with key stakeholders'. Trong agile, tầm nhìn sản phẩm được xây qua hợp tác với product owner và các bên liên quan chủ chốt, rồi mới dẫn dắt thứ tự backlog. Bẫy: đẩy cho người có thẩm quyền quyết thay vì tạo đồng thuận."},{id:"o233",n:233,t:0,origin:"original",eco:"P1",domain:"people",approach:"predictive",tags:["predictive","eco-2026","vision","communication-channels"],type:"mc",q:"A predictive hospital IT implementation has an approved vision and a communications plan, but a sampling at three sites shows most nurses and ward clerks have never heard of the project goals and are repeating rumors about job cuts. Most ward staff rarely use the intranet during shifts. Training is scheduled for four months from now. What should the project manager do?",opts:["Survey staff at all three sites on what they have heard and what they want to know, then design the messages from the results","Bring the vision into the training curriculum and publish the training schedule to each ward now","Tailor the vision message for nurses and ward clerks and deliver it through ward huddles and site champions","Record a short video message from the sponsor and post it on the hospital intranet for staff at all three sites"],ans:[2],why:["Sai: khảo sát nhu cầu thông tin là việc tốt khi chưa biết gì về người nhận, nhưng mẫu ba site đã cho thấy điều cần biết: nhân viên chưa nghe mục tiêu và đang tin tin đồn cắt việc; khảo sát thêm chỉ kéo dài thời gian.","Sai: đưa tầm nhìn vào chương trình đào tạo là đúng nội dung nhưng quá muộn; bốn tháng nữa mới đào tạo, trong lúc đó tin đồn tiếp tục lan.","Đúng: y tá và nhân viên khoa chưa nghe mục tiêu và đang lan truyền tin đồn. PM chủ động truyền thông đúng người, đúng kênh họ tin cậy (họp nhanh tại khoa, người đại diện tại site) và không đợi đến lúc đào tạo.","Sai: video của sponsor là cách truyền thông tốt cho nhiều đối tượng, nhưng stem nói nhân viên khoa hiếm khi dùng intranet trong ca; kênh này không đến được người cần nghe và không giải đáp tin đồn cắt việc."],exp:"Task P1, enabler 'promote the shared vision'. Quảng bá tầm nhìn là truyền thông chủ động, tùy biến theo nhóm nghe và kênh họ tin cậy. Quy tắc nhớ: đúng người, đúng kênh, đúng thời điểm; không đợi đến đào tạo."},{id:"o234",n:234,t:0,origin:"original",eco:"P1",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","vision","customer-feedback"],type:"mc",q:"A hybrid fitness-app program has delivered its third release. Usage analytics and interviews show customers value social challenges far more than the advanced analytics dashboards that dominate the vision statement written at kickoff. The product owner and the key stakeholders reviewed the evidence in a workshop this week and agree the vision no longer fits. The product owner now wants to reorder the backlog. What should the project manager do?",opts:["Hold another review session with the key stakeholders to examine the usage evidence before touching the vision","Let the product owner reorder the backlog now and revise the vision wording at the next phase-gate review","Run an A/B test of social challenges against the analytics dashboards in the next release before deciding on the vision","Revise the vision to put social challenges first, get the stakeholders' approval, then update the backlog"],ans:[3],why:["Sai: xem lại bằng chứng cùng các bên chủ chốt là đúng bước khi chưa ai thấy dữ liệu, nhưng stem cho biết họ vừa làm điều đó tuần này và đã đồng ý; họp lại chỉ kéo dài.","Sai: sắp xếp backlog trước rồi sửa tầm nhìn ở gate sau khiến đội làm theo một hướng khác với văn bản tầm nhìn trong nhiều tuần; thứ tự đúng là tầm nhìn trước, backlog sau.","Sai: A/B test là cách kiểm chứng tốt khi chưa có bằng chứng, nhưng phân tích sử dụng và phỏng vấn đã cho thấy khách hàng ưu tiên tính năng xã hội và các bên đã đồng ý; thử nghiệm thêm chỉ trì hoãn việc cập nhật tầm nhìn.","Đúng: các bên đã xem bằng chứng và thống nhất tầm nhìn không còn phù hợp. PM cập nhật tầm nhìn, xin phê duyệt của họ, rồi mới điều chỉnh backlog."],exp:"Task P1, enabler 'keep the vision current'. Tầm nhìn là tài liệu sống: khi các bên đã xem bằng chứng và đồng ý thì PM sửa tầm nhìn, xin phê duyệt rồi mới chỉnh backlog. Quy tắc nhớ: tầm nhìn trước, backlog sau; đã đối thoại xong thì đừng họp lại."},{id:"o235",n:235,t:0,origin:"original",eco:"P1",domain:"people",approach:"agile",tags:["agile","eco-2026","vision","root-cause","refinement"],type:"mc",q:"For three sprints in a row, stakeholders at the sprint review say the increment 'is not what we expected,' although the team delivered every story exactly as written and met the definition of done. The product vision is documented and known to the team. What should the project manager do first?",opts:["Require stakeholder approval of each story in writing before sprint planning and track the turnaround time","Schedule a hardening sprint after each release so rejected increments can be reworked","Trace how stakeholder needs turned into stories to find where the intent was lost","Write acceptance criteria with examples for each story and have stakeholders confirm them at refinement"],ans:[2],why:["Sai: phê duyệt story bằng văn bản làm chậm luồng công việc và chỉ kiểm tra chữ viết, trong khi stem cho thấy đội đã giao đúng từng story; thiếu sót nằm ở chỗ nhu cầu bị chuyển sai thành story.","Sai: sprint hardening để làm lại phần bị từ chối chữa hậu quả sau cùng; nó không cho biết vì sao kết quả sai kỳ vọng nên cùng loại lỗi sẽ lặp lại ở các sprint kế.","Đúng: đội giao đúng từng story và đạt definition of done mà stakeholder vẫn nói không như mong đợi, nghĩa là ý định bị mất trên đường từ nhu cầu tới story. PM lần ngược chuỗi này để tìm chỗ mất ý định.","Sai: tiêu chí chấp nhận có ví dụ là thực hành tốt, nhưng stem cho biết mọi story đã đạt đúng như viết; thêm chi tiết khi chưa biết ý định mất ở khâu nào là thêm quy trình trước khi chẩn đoán."],exp:"Task P1, enabler 'break down situations to identify the root cause of a misunderstanding of the vision'. Khi kết quả đúng tài liệu mà vẫn sai kỳ vọng, vấn đề nằm ở khâu chuyển nhu cầu thành yêu cầu. Quy tắc nhớ: đi ngược chuỗi từ tầm nhìn đến story trước khi thêm quy trình."},{id:"o236",n:236,t:0,origin:"original",eco:"P1",domain:"people",approach:"predictive",tags:["predictive","eco-2026","vision","project-handover"],type:"mc",q:"A project manager takes over a predictive manufacturing-line upgrade from a colleague who left. The charter contains a vision statement signed by the sponsor, but nothing shows that department heads in quality, maintenance, and production ever reviewed it. The former project manager left no handover notes and cannot be reached, and the project files and meeting minutes show nothing. Planning workshops start next week. What should the project manager do?",opts:["Obtain the sponsor's written statement that the department heads were briefed on the vision during initiation","Review the vision with the department heads and record their sign-off, since the workshops will build on it","Run the planning workshops as scheduled and collect the department heads' comments on the vision as the WBS takes shape","Trace the vision's approval history with the former project manager's deputy to confirm who reviewed it"],ans:[1],why:["Sai: lời xác nhận của sponsor chỉ nói rằng đã có thông báo, không chứng minh các trưởng bộ phận đã hiểu và đồng ý; đồng thuận đến từ đối thoại với chính họ, không từ văn bản của người khác.","Đúng: tài liệu bàn giao không có dấu vết nào cho thấy các trưởng bộ phận quality, maintenance, production đã xem tầm nhìn. PM tự rà soát cùng họ và ghi nhận sự đồng ý trước khi workshop lập kế hoạch dựa trên nó.","Sai: để workshop chạy rồi thu ý kiến về tầm nhìn trong lúc dựng WBS là xếp sai thứ tự; nếu họ không đồng ý, kế hoạch đang xây trên nền chưa được đồng thuận.","Sai: truy dấu qua người phó của PM cũ là kênh gián tiếp; stem đã cho biết hồ sơ và biên bản không có gì, nên đây là ngõ cụt còn các trưởng bộ phận thì ngay trước mắt để hỏi thẳng."],exp:"Task P1, enabler 'help ensure a shared vision with key stakeholders'. Khi tiếp quản dự án, kiểm tra xem tầm nhìn đã được các bên chủ chốt hiểu và đồng ý chưa, không mặc định. Quy tắc nhớ: đồng thuận đến từ đối thoại với người liên quan, không từ chữ ký hay lời kể lại."},{id:"o237",n:237,t:0,origin:"original",eco:"P1",domain:"people",approach:"predictive",tags:["predictive","eco-2026","vision","root-cause","regional-managers"],type:"mc",q:"Three weeks after a phase gate on a predictive retail-systems rollout, several regional managers submit quarterly plans that keep legacy store processes the project vision was meant to replace. The vision was presented at the gate review and the minutes were distributed. What should the project manager do first?",opts:["Talk with the regional managers to learn how they read the vision and what drives their quarterly plans this week","Review the quarterly plans against the vision and send each regional manager a list of gaps to correct","Run a webinar for the regional managers and their planners that walks through the vision and the legacy processes it retires","Prompt the sponsor to direct the regional managers to take legacy processes out of their quarterly plans"],ans:[0],why:["Đúng: tầm nhìn đã được trình bày và có biên bản, nhưng kế hoạch của các regional manager vẫn đi ngược; PM cần biết họ hiểu sai, có động cơ khác hay đang bị ràng buộc trước khi chọn biện pháp.","Sai: so kế hoạch với tầm nhìn và gửi danh sách lỗi chỉ cho biết cái sai chứ không cho biết vì sao họ lập kế hoạch như vậy; nguyên nhân chưa rõ nên danh sách sửa có thể bị bỏ qua tiếp.","Sai: một buổi webinar trình bày lại tầm nhìn lặp lại đúng điều đã làm ở gate review; chưa biết lý do thì phổ biến lần hai khó thay đổi hành vi.","Sai: nhờ sponsor ra chỉ thị là leo thang bằng quyền trước khi tìm hiểu nguyên nhân; nó có thể dập tắt vấn đề tạm thời nhưng không khắc phục lý do thật khiến họ giữ quy trình cũ."],exp:"Task P1, enabler 'break down situations to identify the root cause of a misunderstanding of the vision'. Hành vi đi ngược tầm nhìn có thể do hiểu sai, do động cơ hoặc do mục tiêu cá nhân xung đột. Trước khi nhắc nhở, ra lệnh hay thêm kiểm soát, hãy nói chuyện để biết nguyên nhân."},{id:"o238",n:238,t:0,origin:"original",eco:"P1",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","vision","steering-group"],type:"mc",q:"Midway through a hybrid supply-chain modernization, a new vice president of logistics joins the steering group and sends the steering group a written memo setting out in detail that the agreed vision was drawn up without regard to supplier onboarding, which her department depends on, and asks the project manager for a written answer on whether onboarding was considered. The vision came out of two workshops with minutes on file, but the project manager joined after the first workshop and cannot say whether onboarding was discussed. Sprints for the next release start Monday. What should the project manager do first?",opts:["Meet the vice president to hear the concern in full, and take any valid points back to the steering group","Reopen the vision workshop with all steering members and re-vote on supplier onboarding before the release starts","Extend the vision to include supplier onboarding as the vice president asks, and notify the other steering members","Check the minutes of the two vision sessions and ask the sponsor whether supplier onboarding was discussed and why it was left out"],ans:[3],why:["Sai: đúng nếu chưa rõ mối lo của bà phó chủ tịch, nhưng ở đây bà đã nêu đầy đủ trong bản ghi nhớ gửi nhóm điều hành; nghe lại không giải đáp được điều PM còn thiếu là onboarding đã được bàn hay chưa, nên phải kiểm biên bản trước.","Sai: mở lại workshop và bỏ phiếu lại là đúng nếu biên bản cho thấy bộ phận logistics không được tham vấn, nhưng ở đây chưa ai kiểm tra biên bản; mở lại trước khi biết sẽ làm đảo lộn quyết định đã có.","Sai: mở rộng tầm nhìn theo yêu cầu là đúng nếu nhóm điều hành đã đồng ý đưa onboarding vào, nhưng ở đây chưa có đồng ý nào, và đổi một chiều rồi báo sau phá vỡ đồng thuận của cả nhóm.","Đúng: PM không có mặt ở workshop đầu nên chưa biết onboarding đã được bàn hay chưa; biên bản và sponsor có thể trả lời ngay trước thứ Hai. Xác minh sự thật trước, rồi mới trao đổi với bà phó chủ tịch."],exp:"Task P1, enabler 'help ensure a shared vision with key stakeholders'. Khi một bên mới đặt câu hỏi về quyết định đã có mà PM không nắm lịch sử, việc đầu tiên là xác minh sự thật từ biên bản và người có mặt, rồi mới đối thoại hoặc điều chỉnh. Quy tắc nhớ: kiểm chứng trước, phản ứng sau; không đổi vision dựa trên lời kể chưa kiểm."},{id:"o239",n:239,t:0,origin:"original",eco:"P2",domain:"people",approach:"agile",tags:["agile","eco-2026","conflict","conflict-sources","scrum-teams"],type:"mc",q:"Two scrum teams share a billing component. Builds keep failing after merges, and each team blames the other in the joint retrospective: Team A calls Team B's merges careless, and Team B calls Team A's tests flaky. Velocity for both has dropped for three sprints. Both teams have said another joint session would only repeat the accusations until facts are on the table. The project manager is asked to resolve the dispute. What should the project manager do first?",opts:["Ask both scrum masters to facilitate a joint no-blame session in which the two teams agree improvements to merging and testing","Commission the architect to redesign the billing component and split its ownership between the two teams","Compare the build logs with each team's merge and test records, and talk to both teams to find the sources of the failures","Assess both teams' velocity trends with their scrum masters, then assign coaching to the team whose velocity fell further"],ans:[2],why:["Sai: buổi chung không đổ lỗi do hai scrum master điều phối là đúng nếu hai đội đã sẵn sàng nhìn dữ kiện, nhưng ở đây cả hai nói họp chung sẽ chỉ lặp lại cáo buộc khi chưa có dữ kiện; phải có dữ kiện và nguồn gốc xung đột trước.","Sai: thiết kế lại component để tách quyền sở hữu là đúng nếu nguồn gốc là cấu trúc dùng chung, nhưng ở đây chưa ai biết nguyên nhân; giải pháp kiến trúc tốn kém khi chưa chẩn đoán là hành động quá sớm.","Đúng: hai đội chỉ trỏ nhau và từ chối họp chung khi chưa có dữ kiện. PM đối chiếu build log với hồ sơ merge và test của từng đội, đồng thời nghe cả hai bên để tìm nguồn gốc thật của lỗi.","Sai: phân tích xu hướng velocity cùng scrum master nghe cẩn trọng, nhưng velocity của cả hai đội đều giảm là triệu chứng, không chỉ ra nguồn gốc lỗi build; giao coaching cho một đội khi chưa có bằng chứng là chọn phe và làm xung đột nặng thêm."],exp:"Task P2 (Manage conflicts), enabler 'identify conflict sources'. Khi hai bên đổ lỗi, thu thập dữ kiện khách quan và nghe từng bên để tìm nguồn gốc thật (quy trình, tài nguyên, mục tiêu, cá nhân). Quy tắc nhớ: chẩn đoán trước khi áp giải pháp."},{id:"o240",n:240,t:0,origin:"original",eco:"P2",domain:"people",approach:"predictive",tags:["predictive","eco-2026","conflict","context-analysis","procurement"],type:"mc",q:"On a predictive building project, the structural engineer and the procurement lead disagree about switching steel suppliers after a delivery delay. The engineer opposes the switch because of the substitute's weaker delivery record, although its certification was verified against the specification last week, while procurement stresses a contract clause with daily penalties. The schedule is baselined and the decision window is two weeks. What should the project manager do before choosing a resolution approach?",opts:["Escalate the supplier switch to the change control board with both positions and let the board decide","Weigh penalty exposure, delivery risk, and float against each party's interests before choosing an approach","Facilitate a session where both parties compromise on a split order, placing half the steel with the substitute","Request the substitute's certification documents and have the engineer verify them against the specification"],ans:[1],why:["Sai: change control board là diễn đàn đúng cho thay đổi đã baseline, nhưng bất đồng này giữa hai chuyên gia chưa được phân tích, và đẩy lên ban làm mất thời gian trong cửa sổ quyết định hai tuần.","Đúng: phải chọn cách giải quyết xung đột trong hai tuần, với rủi ro giao hàng và phạt theo ngày kéo ngược nhau. PM so sánh mức phạt, độ tin cậy giao hàng, float còn lại và lợi ích của từng bên trước khi chọn hướng.","Sai: thỏa hiệp chia đôi đơn hàng là một kỹ thuật xử lý xung đột hợp lệ, nhưng chọn nó khi chưa phân tích bối cảnh là đoán; nó có thể cho ra kết quả không thỏa mãn bên nào.","Sai: kiểm tra lại chứng nhận của nhà cung cấp mới đúng nếu chứng nhận còn nghi vấn, nhưng stem cho biết chứng nhận đã được xác minh tuần trước; làm lại không giải quyết lo ngại về độ tin cậy giao hàng lẫn mối lo về mức phạt hằng ngày."],exp:"Task P2, enabler 'analyze the context for the conflict'. Mức độ nghiêm trọng, thời hạn, quan hệ và lợi ích của các bên quyết định chiến lược (collaborate, compromise, ...). Quy tắc nhớ: phân tích bối cảnh rồi mới chọn kỹ thuật giải quyết xung đột."},{id:"o241",n:241,t:0,origin:"original",eco:"P2",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","conflict","resolution-follow-through"],type:"mc",q:"On a hybrid platform project, the UX lead and the backend lead settled their dispute over API stability: core endpoints freeze at the phase gate, and additive changes are announced at a weekly contract review. Both agreed in a meeting. A week later no review has been scheduled and each lead assumes the other will organize it. What should the project manager do?",opts:["Request both leads' email acknowledgement of the agreement and file it with the architecture decisions, then move on to the next issue","Document the leads' decision and schedule the weekly contract review it needs, then check it after two sprints","Ask each lead what is blocking the review and whether the agreed rules still work for both before scheduling anything","Send the agreement to the sponsor so that the sponsor can make sure both leads follow through on the weekly review"],ans:[1],why:["Sai: xác nhận bằng email và lưu hồ sơ ghi lại được thỏa thuận nhưng không đặt lịch hay gán người tổ chức buổi review hằng tuần; hai lead vẫn mỗi người nghĩ người kia sẽ làm.","Đúng: thỏa thuận đã có nhưng không ai tổ chức buổi review nên chưa thực hiện được. PM ghi lại quyết định, đặt lịch review hằng tuần và kiểm tra hiệu quả sau hai sprint để xung đột thực sự khép lại.","Sai: hỏi lại từng lead về trở ngại và hiệu lực quy tắc là việc đáng làm khi thỏa thuận có vấn đề, nhưng stem đã nói rõ nguyên nhân là mỗi người nghĩ người kia sẽ tổ chức; không cần hỏi lại trước khi lên lịch.","Sai: chuyển thỏa thuận cho sponsor để giám sát là đẩy việc thực thi lên cấp cao; đây là việc điều phối trong tầm PM và hai lead đã tự đồng ý với nhau."],exp:"Task P2, enabler 'implement an agreed-on resolution strategy'. Thống nhất xong chưa phải giải quyết xong: phải gán việc, đặt lịch, ghi tài liệu và theo dõi kết quả. Bẫy: nghĩ rằng đồng ý bằng lời là kết thúc xung đột."},{id:"o242",n:242,t:0,origin:"original",eco:"P2",domain:"people",approach:"agile",tags:["agile","eco-2026","conflict","vendor","working-agreement"],type:"mc",q:"A scrum team works in the same sprints as engineers from an external vendor. Disagreements over interface definitions have twice led vendor engineers to email their own managers directly, bypassing the team. The vendor engineers have never seen the team's working agreement on handling conflicts. The vendor contract has no clause covering technical disputes. What should the project manager do?",opts:["Have the vendor's delivery manager coach the engineers on raising interface disputes with the team before involving managers","Set up a weekly interface-definition meeting for both groups' engineers, chaired by the product owner, to settle disputes early","Walk the vendor engineers through the team's conflict principles and settle with them how those apply to the joint sprints","Revise the team's working agreement to cover vendor engineers and have the product owner approve the new version"],ans:[2],why:["Sai: nhờ quản lý vendor huấn luyện kỹ sư của họ là chuyển việc cho người ngoài tầm; các kỹ sư chưa từng thấy nguyên tắc của đội nên vấn đề là họ chưa biết cách xử lý, không phải thiếu người nhắc.","Sai: họp định nghĩa interface hằng tuần có thể giảm số bất đồng, nhưng đó là vấn đề thứ cấp; nó không cho vendor biết nguyên tắc xử lý xung đột nên họ vẫn có thể gửi email thẳng cho quản lý.","Đúng: vendor chưa từng thấy thỏa thuận làm việc của đội và hợp đồng không có điều khoản về tranh chấp kỹ thuật. PM trình bày nguyên tắc xung đột và cùng họ thống nhất cách áp dụng cho cả hai nhóm.","Sai: sửa thỏa thuận cho gồm cả vendor và nhờ product owner duyệt khi chưa có vendor tham gia là áp đặt từ một phía; người không tham gia xây dựng thường không cảm thấy bị ràng buộc."],exp:"Task P2, enabler 'communicate conflict management principles with the team and external stakeholders'. Nguyên tắc xử lý xung đột phải được chia sẻ với cả đối tác bên ngoài và cùng thống nhất cách áp dụng. Quy tắc nhớ: cùng xây dựng thì mới cùng tuân thủ."},{id:"o243",n:243,t:0,origin:"original",eco:"P2",domain:"people",approach:"predictive",tags:["predictive","eco-2026","conflict","ground-rules","distributed-team"],type:"mc",q:"A predictive regulatory-reporting project is kicking off with 14 team members spread across three time zones, many of whom have not worked together. The project manager wants to prevent avoidable conflicts and wants the team to adhere to common working norms from the start. What should the project manager do?",opts:["Adapt the PMO's ground-rule template for distributed teams, review it with the functional managers, and issue it in the team charter","Run a kickoff session where the team drafts its own rules for communication, response times, escalation; record them in the charter","Ask each functional manager to brief their own staff on conduct and response times from the PMO guidelines, and collect acknowledgements","Publish a meeting calendar with a core-hours overlap for the three time zones, as agreed with the functional managers, and cite it in the charter"],ans:[1],why:["Sai: dùng mẫu của PMO là đúng nếu nhóm đã quen làm việc chung và chỉ cần quy tắc chuẩn, nhưng ở đây 14 người chưa từng làm chung, và quy tắc có sẵn không tạo cảm giác sở hữu để họ tuân thủ.","Đúng: 14 người ở ba múi giờ, nhiều người chưa quen nhau, và PM muốn cả đội tuân thủ ngay từ đầu. Đội tự xây quy tắc về liên lạc, thời gian phản hồi và leo thang rồi ghi vào team charter mới tạo được sự sở hữu.","Sai: để từng quản lý chức năng phổ biến là đúng nếu mỗi nhóm đã có văn hóa chung và chỉ cần nhắc, nhưng ở đây mỗi quản lý sẽ giải thích một kiểu, và chỉ có xác nhận đã đọc chứ không có cam kết của cả đội.","Sai: lịch họp và giờ trùng là đúng nếu vấn đề chỉ là điều phối thời gian, nhưng ở đây còn cần chuẩn mực về liên lạc và leo thang; lịch do quản lý chức năng thỏa thuận cũng chưa phải quy tắc do đội đặt ra."],exp:"Task P2, enabler 'establish an environment that fosters adherence to common ground rules'. Ground rules do chính đội xây dựng, ghi vào team charter ngay từ đầu, giúp phòng ngừa xung đột. Bẫy: mẫu có sẵn từ PMO hoặc quản lý chức năng không tạo cảm giác sở hữu."},{id:"o244",n:244,t:0,origin:"original",eco:"P2",domain:"people",approach:"predictive",tags:["predictive","eco-2026","conflict","ground-rules","violation"],type:"mc",q:"A predictive project's team charter requires weekly status inputs by noon on Thursday so the steering report can go out on Friday. A senior engineer has submitted late for four weeks, delaying the report, and two colleagues have started submitting late as well. The project manager has spoken privately with the engineer twice; each time the engineer agreed to comply, and nothing changed. The charter says repeated misses after a private discussion go to the team member's functional manager. What should the project manager do?",opts:["Raise the pattern at the next team meeting, showing the submission dates and the effect on the steering report","Escalate to the engineer's functional manager with the four weeks of submission dates, and ask for a corrective plan","Redesign the status-input process with the three late submitters, shortening the form and moving the deadline in the charter","Move the steering report to Monday, record the change in the communications management plan, and inform the committee"],ans:[1],why:["Sai: nêu công khai ở cuộc họp đội là đúng nếu charter chưa có bước xử lý, nhưng ở đây charter đã quy định trễ lặp lại sau khi nói riêng thì chuyển lên functional manager; PM đã nói riêng hai lần nên làm theo charter.","Đúng: PM đã trao đổi riêng hai lần, người kỹ sư đồng ý nhưng không đổi, và hai người khác bắt đầu trễ theo. Cách riêng đã thất bại, nên bước hợp lý là leo thang lên quản lý chức năng, người có quyền với kỹ sư, kèm số liệu bốn tuần.","Sai: thiết kế lại quy trình nhập là đúng nếu quy tắc thứ Năm vốn không thực tế, nhưng ở đây hạn chót đã được đội chấp nhận trong charter và chưa ai nói quy tắc sai; nới hạn sẽ thưởng cho hành vi vi phạm.","Sai: dời báo cáo sang thứ Hai là đúng nếu steering đồng ý chu kỳ chậm hơn, nhưng ở đây hạn thứ Sáu là yêu cầu của kế hoạch truyền thông; đổi lịch báo cáo né vấn đề hành vi và không xử lý nguyên nhân."],exp:"Task P2, enabler 'manage and rectify ground rule violations'. Xử lý vi phạm theo thang: trao đổi riêng trước; khi đã làm mà không hiệu quả và vi phạm lan ra, leo thang lên người có thẩm quyền với người vi phạm (quản lý chức năng) kèm dữ kiện. Quy tắc nhớ: riêng trước, leo thang sau khi riêng đã thất bại."},{id:"o245",n:245,t:0,origin:"original",eco:"P2",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","ai","conflict","ground-rules"],type:"mc",q:"A hybrid analytics team may use an approved generative AI tool for drafting reports; company policy requires human review of the output but does not say how. Two analysts use the tool for nearly every deliverable, while the QA lead insists on fully manual drafting and criticizes the analysts in review meetings. Meetings have become tense, and a report was delayed. What should the project manager do?",opts:["Meet the analysts and the QA lead to hear each view, and settle with the team how AI drafts are marked, checked, signed off","Ask the compliance office to publish a team-level AI guideline on marking and review that each member must follow","Have the QA lead check each AI-assisted report against an error checklist while the analysts keep using the tool","Rule that AI-drafted sections must be marked and peer-reviewed, and announce the rule at the next team meeting"],ans:[0],why:["Đúng: chính sách công ty cho dùng AI và đòi người duyệt nhưng không nói cách làm, còn hai bên đang căng thẳng. PM nghe từng người rồi cùng đội thống nhất cách đánh dấu, kiểm tra và ký duyệt bản nháp AI.","Sai: nhờ bộ phận compliance ra hướng dẫn là đúng nếu chính sách công ty còn trống về việc dùng AI, nhưng ở đây chính sách đã cho phép và chỉ thiếu cách làm cụ thể của đội; văn bản từ trên xuống không giải quyết căng thẳng.","Sai: để QA lead kiểm từng báo cáo bằng checklist là đúng nếu mâu thuẫn chỉ nằm ở chất lượng đầu ra, nhưng ở đây QA lead đang chỉ trích các nhà phân tích, nên giao thêm quyền kiểm cho người đó làm xung đột nặng hơn.","Sai: ra quy tắc đánh dấu và duyệt chéo rồi thông báo là đúng nếu cả đội đã đồng ý nguyên tắc, nhưng ở đây hai bên bất đồng và đang căng thẳng; quy tắc áp đặt không tạo sở hữu và có thể bị phớt lờ."],exp:"Task P2 (Manage conflicts), enabler 'identify conflict sources' kèm 'establish an environment that fosters adherence to common ground rules', trong bối cảnh dùng AI. AI chỉ là bối cảnh: PM vẫn phân tích nguồn xung đột, tuân thủ chính sách tổ chức và để đội cùng xây quy tắc, trong đó người chịu trách nhiệm cuối cùng về nội dung vẫn là con người."},{id:"o246",n:246,t:0,origin:"original",eco:"P2",domain:"people",approach:"agile",tags:["agile","eco-2026","conflict","conflict-sources","distributed-team"],type:"mc",q:"In a distributed agile team, remote members tell the project manager that important decisions are made in hallway conversations among the co-located members, and co-located members feel the remote group is 'difficult and slow to respond.' Tension appears in stand-ups and in chat. What should the project manager do first?",opts:["Require co-located members to record each decision in the team tool by the end of the day, and have remote members review them","Talk to both groups and observe a few ceremonies to find what causes the information gap between them","Plan an in-person team-building event, and use it to build rapport and resolve friction between the groups","Poll the whole team on communication satisfaction in an anonymous survey and present the results at the next retrospective"],ans:[1],why:["Sai: ghi quyết định vào công cụ chung là biện pháp tốt cho bất đối xứng thông tin, nhưng đó là giả định về nguyên nhân; chưa biết vì sao quyết định rơi vào hành lang thì quy định mới có thể bị bỏ qua.","Đúng: hai nhóm đổ lỗi qua lại và căng thẳng đã bộc lộ ở stand-up và chat. PM nghe cả hai phía và quan sát một vài buổi họp để tìm nguồn gốc khoảng cách thông tin trước khi đề xuất giải pháp.","Sai: sự kiện gặp mặt trực tiếp có thể xây quan hệ, nhưng nó không xử lý nguồn gốc là quyết định bị ra ngoài tầm nhìn của nhóm từ xa; căng thẳng sẽ quay lại khi họ trở về.","Sai: khảo sát ẩn danh toàn đội cho dữ liệu chung, nhưng chậm đến buổi retrospective và không cho thấy cụ thể cơ chế nào gây ra khoảng cách; quan sát trực tiếp cả hai nhóm nhanh và rõ hơn."],exp:"Task P2, enabler 'identify conflict sources'. Xung đột giữa hai nhóm thường có nguồn là bất đối xứng thông tin, quy trình hay kỳ vọng. Quy tắc nhớ: lắng nghe và quan sát cả hai phía để tìm nguồn trước khi đề xuất giải pháp."},{id:"o247",n:247,t:0,origin:"original",eco:"P2",domain:"people",approach:"predictive",tags:["predictive","eco-2026","conflict","resource-negotiation","matrix-organization"],type:"mc",q:"A predictive systems-integration project depends on a key network engineer who belongs to a functional department. The functional manager has been pulling the engineer to operations incidents for about three days each week without telling the project manager, and the engineer's activities are slipping against the baseline. The project manager has asked the functional manager twice to protect the engineer's project time; both times the answer was that incident duty is set by the operations director and cannot change at his level. What should the project manager do?",opts:["Log the hours the engineer spends on operations incidents for two weeks, and add the figures to the schedule risks","Escalate to the sponsor with the slippage figures, and ask for a ruling on the engineer's project time against incident duty","Request a second network engineer from the PMO resource pool to take the project tasks that the incidents displace","Negotiate a fixed incident-duty rota with the functional manager that leaves the engineer two guaranteed project days a week"],ans:[1],why:["Sai: ghi nhận giờ vào rủi ro là đúng nếu chưa có dữ liệu và chưa trao đổi với quản lý chức năng, nhưng ở đây độ trễ đã đo được trên baseline và PM đã hỏi hai lần; ghi chép không giải quyết việc ai có quyền điều người.","Đúng: PM đã thương lượng hai lần, quản lý chức năng nói quyết định trực sự cố thuộc giám đốc vận hành, vượt quyền cả hai. Quyết định về nguồn lực liên phòng ban phải leo thang lên sponsor kèm số liệu trễ.","Sai: xin kỹ sư thứ hai từ PMO là đúng nếu có nguồn dự phòng và vấn đề chỉ là thiếu người, nhưng ở đây kỹ sư chủ chốt có kỹ năng riêng và gốc vấn đề là xung đột ưu tiên giữa hai bộ phận chưa được giải quyết.","Sai: thương lượng lịch trực cố định với quản lý chức năng là đúng nếu ông ấy có quyền quyết định, nhưng ở đây ông đã nói quyết định thuộc giám đốc vận hành; đàm phán lần nữa ở cấp đó sẽ không có kết quả."],exp:"Task P2, enabler 'implement an agreed-on resolution strategy' (leo thang khi vượt thẩm quyền). Xung đột nguồn lực trong tổ chức ma trận: đàm phán trực tiếp trước; khi quyết định nằm ở cấp cao hơn cả hai bên thì leo thang lên sponsor kèm dữ liệu tác động. Quy tắc nhớ: hợp tác trước, leo thang khi đã thử và quyền quyết định ở cấp trên."},{id:"o248",n:248,t:0,origin:"original",eco:"P2",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","conflict","client-communication","escalation-path"],type:"mc",q:"On a hybrid customer-portal project, the client's operations staff send complaints straight to individual developers by phone and chat during sprints. The developers resent the interruptions and sometimes answer defensively, and the client calls the project 'unresponsive.' The contract names the project manager as main contact but sets no response times, and the client's operations lead says her staff need a fast route for urgent faults. What should the project manager do?",opts:["Tell the developers to refer every client contact to the project manager, and send the client's staff a notice naming one contact","Interview the client's operations staff about which developers they call and why, and share the patterns with the team","Settle a channel and response times for concerns with client operations, and brief both groups on the agreed route","Ask the client's executive sponsor to instruct operations staff to route every concern through the project manager"],ans:[2],why:["Sai: chặn kênh và thông báo một đầu mối là đúng nếu hợp đồng đã quy định thời gian phản hồi và khách đã đồng ý, nhưng ở đây hợp đồng không có thời gian phản hồi và bên vận hành cần đường nhanh, nên chỉ chặn sẽ tăng bất mãn.","Sai: phỏng vấn nhân viên khách để hiểu mẫu liên hệ là đúng nếu chưa biết vì sao họ gọi thẳng, nhưng ở đây lý do đã rõ (cần đường nhanh cho lỗi khẩn); điều còn thiếu là thỏa thuận kênh chứ không phải thêm thông tin.","Đúng: hợp đồng chỉ nêu PM là đầu mối, không có thời gian phản hồi, và trưởng bộ phận vận hành của khách cần đường nhanh. PM thỏa thuận kênh và thời gian phản hồi với bà ấy rồi phổ biến cho cả hai nhóm.","Sai: nhờ sponsor của khách ra lệnh là đúng nếu trưởng bộ phận vận hành từ chối hợp tác, nhưng ở đây bà ấy sẵn sàng bàn về đường nhanh; dùng quyền cấp trên khi chưa thử thỏa thuận sẽ làm hỏng quan hệ."],exp:"Task P2, enabler 'communicate conflict management principles with the team and external stakeholders'. Với bên ngoài, thỏa thuận rõ kênh, người chịu trách nhiệm và cách leo thang giúp phòng ngừa xung đột. Bẫy: chặn kênh mà không đưa kênh thay thế."},{id:"o249",n:249,t:0,origin:"original",eco:"P2",domain:"people",approach:"agile",tags:["agile","eco-2026","conflict","working-agreement","retrospective"],type:"mc",q:"A nine-member agile team has a working agreement that the scrum master wrote during the first week and posted on the wall. Four months later, three members say they never agreed to it, and the team regularly ignores the rule about keeping stand-ups to 15 minutes. What should the project manager do?",opts:["Lead a retrospective where the team and scrum master review each rule, keep what is accepted, and rewrite the rest in the agreement","Interview each member one-to-one about the rules they reject, and give the scrum master a summary to revise the agreement","Ask the scrum master to extend stand-ups to 30 minutes at the team's request, and leave the rest of the working agreement unchanged","Rotate the stand-up facilitator role so each member enforces the 15-minute rule in turn, and note the rotation in the agreement"],ans:[0],why:["Đúng: bản thỏa thuận do scrum master viết ở tuần đầu, ba người nói chưa từng đồng ý, và đội phớt lờ quy tắc. Cả đội cùng rà soát và viết lại từng quy tắc trong retrospective mới tạo sự sở hữu và tuân thủ.","Sai: phỏng vấn riêng rồi gửi tóm tắt cho scrum master là đúng nếu thành viên ngại nói trước cả đội, nhưng ở đây vấn đề là quy tắc không thuộc về đội; để scrum master tự sửa vẫn là quy tắc áp đặt.","Sai: kéo dài stand-up là đúng nếu đội đã cùng đánh giá và thấy 15 phút không khả thi, nhưng ở đây chưa ai rà soát quy tắc; đổi một con số mà giữ nguyên bản thỏa thuận do một người viết không giải quyết sở hữu.","Sai: luân phiên người điều phối là đúng nếu đội đã đồng ý quy tắc và chỉ cần cơ chế thực thi, nhưng ở đây ba người nói chưa đồng ý; bắt từng người thực thi quy tắc họ không nhận làm tăng phản kháng."],exp:"Task P2, enabler 'establish an environment that fosters adherence to common ground rules'. Quy tắc làm việc do đội cùng xây và định kỳ rà soát (thường ở retrospective) mới được tuân thủ. Quy tắc nhớ: sở hữu tạo ra tuân thủ."},{id:"o250",n:250,t:0,origin:"original",eco:"P2",domain:"people",approach:"predictive",tags:["predictive","eco-2026","conflict","ground-rules","change-control"],type:"mc",q:"The team charter on a predictive software-delivery project says that scope requests from the customer must go through the change request process. At a weekly meeting the customer representative thanks a developer for agreeing, in a hallway chat, to build an extra report. The developer had not told the project manager, and the report is not in the baseline. What should the project manager do?",opts:["Deliver the report from schedule buffer and cost reserve, and agree this with the customer to protect the relationship","Coach the developer on the rule, then submit a change request for the report and explain the process to the customer","Estimate the report's effort and cost with the developer and quote the customer a price and date for approval","Get the functional manager to remind the developer of the charter rules and approve the extra report within team capacity"],ans:[1],why:["Sai: dùng buffer và reserve để làm thêm báo cáo là chấp nhận yêu cầu ngoài baseline mà không đánh giá; quan hệ khách hàng không phải lý do bỏ qua quy trình đã thống nhất trong team charter.","Đúng: developer đã hứa ngoài quy trình và yêu cầu không nằm trong baseline. PM huấn luyện developer về quy tắc, đưa yêu cầu vào change request và giải thích cho khách, vừa xử lý hành vi vừa xử lý hệ quả.","Sai: ước lượng chi phí và báo giá là một phần của đánh giá thay đổi, nhưng báo giá trực tiếp cho khách bỏ qua quy trình change request; người vi phạm cũng không được nhắc về quy tắc.","Sai: nhờ quản lý chức năng nhắc developer và duyệt báo cáo trong năng lực của đội là chuyển việc ra ngoài dự án, và vẫn cho phép yêu cầu ngoài baseline đi vào mà không qua change control."],exp:"Task P2, enabler 'manage and rectify ground rule violations'. Xử lý vi phạm nhắm vào cả hành vi (trao đổi với người vi phạm) lẫn hệ quả (đưa yêu cầu qua change control). Quy tắc nhớ: không để yêu cầu ngoài baseline lọt vào phạm vi mà không đánh giá."},{id:"o251",n:251,t:0,origin:"original",eco:"P3",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","team-expectations","mixed-disciplines"],type:"mc",q:"A new hybrid team combines hardware engineers who work to phase-gate specifications with software developers who deliver in two-week sprints. Hardware engineers expect detailed specs and formal sign-offs, while developers expect frequent change and informal feedback. In the first month the two workstreams' plans have not clashed, but frustration is rising over how each group expects change, feedback, and 'done' to be handled. What should the project manager do?",opts:["Run a working session with both groups and the product owner to agree how planning, change, and sign-off work, including what 'done' means","Map the hardware specifications against the sprint backlog with both leads, and record the plan clashes in the integrated plan","Direct the scrum master to apply the sprint ceremonies to the whole team, with hardware engineers reporting progress on the sprint board","Brief each discipline's manager on both ways of working, and ask them to explain the other discipline to their members at the next team meeting"],ans:[0],why:["Đúng: kế hoạch hai nhánh chưa xung đột; bực bội đến từ cách mỗi nhóm kỳ vọng về thay đổi, phản hồi và 'done'. Hai nhóm cùng product owner thỏa thuận các kỳ vọng đó, gồm định nghĩa hoàn thành cho từng sản phẩm bàn giao.","Sai: đối chiếu spec với backlog là đúng nếu các kế hoạch đang đụng nhau, nhưng ở đây stem nói kế hoạch chưa xung đột; vấn đề là kỳ vọng làm việc, nên lập bản đồ kế hoạch không giải quyết bực bội.","Sai: để scrum master áp nghi thức sprint cho cả đội là đúng nếu phần cứng không phải tuân thủ gate và spec chính thức, nhưng ở đây phần cứng vẫn bị ràng buộc theo phase-gate; áp một phương pháp bỏ qua nhu cầu của một nhóm.","Sai: nhờ quản lý từng ngành giải thích là đúng nếu rào cản chỉ là thiếu hiểu biết lẫn nhau, nhưng ở đây hai nhóm cần chính họ cùng đặt kỳ vọng; truyền đạt qua quản lý không tạo thỏa thuận chung của đội."],exp:"Task P3 (Lead the project team), enabler 'establish expectations at the team level'. Trong đội hybrid, kỳ vọng về thay đổi, phản hồi và tiêu chí hoàn thành cần được thống nhất chung. Quy tắc nhớ: kỳ vọng do đội cùng đặt thì đội mới theo."},{id:"o252",n:252,t:0,origin:"original",eco:"P3",domain:"people",approach:"predictive",tags:["predictive","eco-2026","empowerment","decision-boundaries"],type:"mc",q:"A predictive plant-relocation project has a detailed work breakdown structure, and the project manager assigns daily tasks to a team of experienced technicians. Technicians often wait for instructions, and they propose deciding the order of tasks within each work package themselves as a team. The schedule is baselined with approved milestones and quality criteria. How should the project manager respond?",opts:["Name the most senior technician as foreman who assigns tasks within each work package and reports to the project manager","Hand the technicians a Kanban board for each work package and let them pull work and reset dates as flow demands","Invite the technicians to re-estimate the remaining work packages and re-baseline the schedule with their own durations","Keep the baselined milestones and scope fixed, and let the technicians decide task order within each work package"],ans:[3],why:["Sai: chỉ định một trưởng nhóm kỹ thuật viên giao việc chỉ chuyển quyền chỉ đạo từ PM sang một người; các kỹ thuật viên vẫn chờ lệnh và đề xuất tự quyết của cả đội bị bỏ qua.","Sai: bảng Kanban và kéo việc là thực hành agile tốt, nhưng stem nói lịch đã baseline với mốc và tiêu chí chất lượng được duyệt; tự đặt lại ngày theo dòng chảy là đổi baseline mà không qua change control.","Sai: ước lượng lại và re-baseline lịch theo thời lượng của đội thay đổi baseline không có lý do; đội chỉ đề xuất sắp xếp thứ tự việc, không đề xuất đổi mốc đã duyệt.","Đúng: kỹ thuật viên có kinh nghiệm và muốn tự sắp xếp trong từng work package. PM giữ mốc, phạm vi và tiêu chí chất lượng đã baseline làm ranh giới, rồi để đội quyết cách làm bên trong, đúng nguyên tắc empower."],exp:"Task P3, enabler 'empower the team'. Trao quyền không có nghĩa buông kiểm soát: nêu rõ ranh giới (phạm vi, mốc, chất lượng) rồi để đội quyết cách làm bên trong. Bẫy: nghĩ predictive thì PM phải giao từng việc."},{id:"o253",n:253,t:0,origin:"original",eco:"P3",domain:"people",approach:"agile",tags:["agile","eco-2026","ai","team-adoption","varied-perspectives"],type:"mc",q:"A scrum team of eight has been given a company-approved AI coding assistant, but only two developers use it. Others say they fear code-quality problems or worry the tool will be used to justify smaller teams. Leadership expects a velocity gain by next quarter, and has told neither the team nor the project manager whether team size is linked to the tool. What should the project manager do first?",opts:["Confirm with leadership whether team size is linked to the tool, and tell the team the answer before pushing adoption","Pair the two active users with colleagues in a mentoring rota, so the tool spreads through the team by example","Make use of the assistant part of the definition of done, and track each developer's usage against the velocity target","Offer training and let the team set in a retrospective how AI output is reviewed, to answer the code-quality fear"],ans:[0],why:["Đúng: một nửa nỗi lo (đội bị cắt giảm) là câu hỏi về sự thật mà chỉ lãnh đạo trả lời được, và chưa ai biết. PM xác nhận với lãnh đạo trước rồi nói lại với đội, thay vì thúc việc áp dụng khi chưa rõ.","Sai: kèm cặp chéo là đúng nếu e ngại chỉ do thiếu kỹ năng, nhưng ở đây nỗi lo về cắt giảm chưa được giải đáp; ví dụ từ hai người dùng tích cực không xóa được lo ngại về việc làm.","Sai: đưa công cụ vào definition of done và đo mức dùng là đúng nếu việc dùng AI là yêu cầu bắt buộc đã được đội chấp nhận, nhưng ở đây áp đặt khi họ đang lo mất việc làm tăng kháng cự và biến công cụ thành chỉ tiêu.","Sai: đào tạo và retrospective về cách duyệt đầu ra AI là đúng nếu nỗi lo chỉ là chất lượng mã, nhưng ở đây còn lo cắt giảm nhân sự chưa ai xác nhận; bước này giải một nửa vấn đề và đến sau khi biết sự thật."],exp:"Task P3, enabler 'support the team's varied experiences, skills, and perspectives' kèm 'establish expectations at the team level', với AI làm bối cảnh. Khi nỗi lo của đội dựa trên một sự thật chưa ai biết (có liên quan đến cắt giảm hay không), PM xác nhận với lãnh đạo trước rồi trả lời đội; đào tạo và quy tắc duyệt đầu ra đến sau. Servant leader không ép công cụ mới lên đội."},{id:"o254",n:254,t:0,origin:"original",eco:"P3",domain:"people",approach:"predictive",tags:["predictive","eco-2026","problem-solving","impediments"],type:"mc",q:"An installation crew of six on a predictive data-center fit-out cannot enter the client's secure site because badge approvals take ten working days. The crew will be idle starting Monday, and the schedule has little float. The crew lead asks the project manager for help. Racks and cable assemblies for this fit-out are already in the baseline scope and can be prefabricated at the contractor's workshop. What should the project manager do?",opts:["Reassign the crew to the contractor's other active project for the ten days, then bring them back when the badges clear","Use the ten days for safety training and a rehearsal of the installation sequence, then start on site when badges arrive","Report the delay to the sponsor and request a schedule extension equal to the ten-day badge approval period","Move the crew to off-site prefabrication of racks and cable assemblies and ask client security for temporary escorted access"],ans:[3],why:["Sai: chuyển đội sang dự án khác của nhà thầu giữ được năng suất, nhưng không làm tiến công việc của dự án này; khi quay về còn rủi ro đội không có sẵn, trong khi có việc trong baseline làm được ngay.","Sai: đào tạo an toàn và diễn tập có giá trị nhưng không tạo ra sản phẩm giao; với lịch có ít float và việc tiền chế đã nằm trong baseline, dùng thời gian này không tận dụng được.","Sai: xin gia hạn lịch là leo thang khi chưa dùng hết cách nằm trong thẩm quyền; PM có thể giữ đội làm việc có ích trước khi nghĩ tới việc dời mốc.","Đúng: đội sáu người bị chặn vì thẻ ra vào mười ngày và lịch gần như không có float. Giá đỡ và bó cáp đã trong baseline có thể tiền chế ở xưởng, nên PM chuyển đội sang đó và xin quyền vào tạm để loại trở ngại."],exp:"Task P3, enabler 'solve problems'. PM (servant leader) loại bỏ trở ngại ngoài tầm với của đội và giữ đội làm việc có giá trị, không để đội chờ. Quy tắc nhớ: tự giải quyết trong thẩm quyền trước, leo thang sau."},{id:"o255",n:255,t:0,origin:"original",eco:"P3",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","voice-of-the-team","reporting-overhead"],type:"mc",q:"A hybrid insurance-platform team reports that preparing the weekly steering slide deck takes roughly 20 percent of its capacity, and the team raised it in two retrospectives. The sponsor believes reporting is light and has not seen the numbers. The deck follows a template mandated by the governance charter, which says any change to reporting format needs a steering committee decision. The project manager attends the committee. What should the project manager do?",opts:["Agree with the sponsor, using the retrospective notes, to cut the weekly reporting, and tell the committee afterwards","Reuse the sprint review slides as the steering deck, and ask the team to stop reformatting them to the template","Escalate the reporting load to the steering committee, backed by capacity data, and propose a lighter format for decision","Take over preparing the weekly steering slides personally, and return the team's freed capacity to delivery work"],ans:[2],why:["Sai: thống nhất cắt báo cáo với sponsor là đúng nếu sponsor có quyền tự đổi mẫu, nhưng ở đây governance charter giao quyết định đổi định dạng cho steering committee; làm trước rồi báo sau vượt thẩm quyền.","Sai: dùng lại slide sprint review là đúng nếu mẫu bắt buộc cho phép nội dung đó, nhưng ở đây mẫu do charter quy định; tự bỏ mẫu mà không có quyết định của committee là phá vỡ quy tắc quản trị.","Đúng: gánh nặng 20 phần trăm có số liệu, mẫu do charter quy định và đổi định dạng cần quyết định của steering committee mà PM có mặt. Leo thang kèm dữ liệu và đề xuất định dạng nhẹ hơn là kênh đúng.","Sai: tự làm slide thay đội là đúng nếu quản lý quá tải ngắn hạn và mẫu không đổi được, nhưng ở đây vấn đề là chi phí báo cáo cấu trúc; PM tự hấp thụ giấu vấn đề và không đại diện tiếng nói của đội."],exp:"Task P3, enabler 'represent the voice of the team'. PM mang dữ liệu của đội đến đúng cơ quan có thẩm quyền: khi quy định (governance charter) giao quyết định cho steering committee thì leo thang kèm số liệu và đề xuất. Quy tắc nhớ: đại diện đội nghĩa là mang bằng chứng lên đúng cấp, không tự quyết thay, không tự hấp thụ vấn đề."},{id:"o256",n:256,t:0,origin:"original",eco:"P3",domain:"people",approach:"agile",tags:["agile","eco-2026","varied-perspectives","estimation","facilitation"],type:"mc",q:"In sprint planning, three senior engineers dominate the discussion and estimates. Two junior developers and the tester, who joined from another industry, rarely speak. Later, tasks involving test data and legacy modules are repeatedly underestimated, though the juniors had doubts at the time. The working agreement already says everyone speaks in turn, yet the seniors still dominate, and the juniors tell the project manager they hesitate to disagree aloud. What should the project manager do?",opts:["Interview the juniors and the tester one-to-one about what they doubted, and share the findings with the senior engineers","Assign the senior engineers to estimate the test-data and legacy-module items, with the rest of the team commenting afterwards","Remind the team of the working agreement on speaking in turn, and revisit the rule at the next retrospective","Change the planning format so each member writes an estimate before discussion starts, and rotate the speaking order"],ans:[3],why:["Sai: phỏng vấn riêng rồi chuyển cho các senior là đúng nếu chưa biết người ít nói nghĩ gì, nhưng ở đây họ đã nói họ ngại phản đối thành tiếng; vấn đề là môi trường họp, không phải thiếu thông tin về nỗi lo của họ.","Sai: giao ước tính cho senior là đúng nếu các hạng mục đó chỉ cần chuyên môn sâu, nhưng ở đây ước tính sai chính vì ý kiến của người ít nói bị bỏ qua; giao hết cho senior làm tình trạng trầm trọng hơn.","Sai: nhắc quy tắc thay phiên là đúng nếu chưa có thỏa thuận về cách nói, nhưng ở đây working agreement đã có quy tắc đó mà senior vẫn lấn át; nhắc lại không đổi được cấu trúc cuộc họp.","Đúng: quy tắc thay phiên đã có mà senior vẫn lấn át, và người trẻ ngại phản đối thành tiếng. Viết ước tính trước khi thảo luận và đổi thứ tự phát biểu sửa môi trường để mọi người đóng góp, thay vì đòi họ tự đổi."],exp:"Task P3, enabler 'support the team's varied experiences, skills, and perspectives'. Đội đa dạng chỉ phát huy khi môi trường cho phép mọi người đóng góp; PM thay đổi cách điều phối chứ không đòi người ít nói tự thay đổi. Bẫy: giao toàn bộ cho người có kinh nghiệm nhất."},{id:"o257",n:257,t:0,origin:"original",eco:"P3",domain:"people",approach:"predictive",tags:["predictive","eco-2026","roles","raci","test-approval"],type:"mc",q:"On a predictive medical-device project, two team leads each sign off test results for the same subsystem, and each assumes the other is responsible for verifying regression tests. Last week a defect passed both sign-offs, and the release candidate was delayed. The responsibility assignment matrix does not cover test approval, and both leads say they will accept any split the project manager records, provided it is written down. What should the project manager do?",opts:["Require both leads to co-sign every test result before release, and record the double signature in the quality plan","Escalate the sign-off gap to the quality assurance manager, and ask that office to own test approval on the project","Review the last release's sign-off records with both leads to find where the regression check was dropped","Settle with both leads who approves test results and who owns regression decisions, and update the responsibility matrix"],ans:[3],why:["Sai: bắt cả hai đồng ký là đúng nếu rủi ro cần hai lớp kiểm tra độc lập, nhưng ở đây vấn đề là mỗi người nghĩ người kia chịu trách nhiệm; hai chữ ký giữ nguyên sự mơ hồ và thêm việc cho cả hai.","Sai: leo thang lên quản lý QA là đúng nếu hai trưởng nhóm không thể thỏa thuận với nhau, nhưng ở đây cả hai nói sẽ chấp nhận cách chia PM ghi lại; chưa cần cấp trên khi hai bên sẵn sàng.","Sai: rà soát hồ sơ ký duyệt của bản trước là đúng nếu chưa biết vì sao khuyết điểm lọt qua, nhưng ở đây nguyên nhân đã rõ (RAM không phủ việc duyệt kiểm thử); tìm thêm bằng chứng không sửa được khoảng trống vai trò.","Đúng: RAM không phủ việc duyệt kiểm thử và hai trưởng nhóm sẵn sàng chấp nhận cách chia nếu được ghi rõ. PM chốt cùng họ ai duyệt kết quả và ai quyết định hồi quy, rồi cập nhật RAM để một việc có một người chịu trách nhiệm."],exp:"Task P3, enabler 'establish clear roles and responsibilities within the team'. Vai trò mơ hồ dẫn tới 'ai cũng nghĩ người kia làm'. Ghi rõ người chịu trách nhiệm và người có quyền quyết trong RAM/RACI và xác nhận với đội. Quy tắc nhớ: một việc, một người chịu trách nhiệm cuối cùng."},{id:"o258",n:258,t:0,origin:"original",eco:"P3",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","leadership-style","servant-leadership","phase-gate"],type:"mc",q:"A hybrid hospital-software project finished its regulated design phase under a directive project manager who assigned tasks and reviewed every document. The build phase now runs in sprints with the same capable team, yet the manager still assigns tasks and joins every working session, and team members say they feel micromanaged. Gate-level regulatory constraints still apply. How should the manager adjust?",opts:["Let the team decide build-phase matters by consensus, including the regulatory items that apply at the gates","Switch to servant leadership for the build phase and focus on removing impediments within the gate rules","Hold a daily two-hour working session with the whole team so the manager can coach decisions as they happen","Ask the team in a retrospective how it wants to be led, and adjust the style after the next gate review"],ans:[1],why:["Sai: quyết định theo đồng thuận phù hợp với nhiều việc ở giai đoạn build, nhưng các hạng mục quy định ở gate là ràng buộc cứng; giao hết cho đội quyết là bỏ qua ranh giới tuân thủ.","Đúng: cùng một đội đủ năng lực nhưng giai đoạn build chạy theo sprint nên phong cách chỉ đạo gây cảm giác bị giám sát quá mức. PM chuyển sang servant leadership, loại trở ngại và vẫn giữ ràng buộc quy định ở gate.","Sai: coaching sát sao có ích cho đội mới, nhưng stem nói đội đã có năng lực và đang thấy bị giám sát quá mức; thêm phiên làm việc dài hằng ngày làm cảm giác đó nặng hơn.","Sai: hỏi đội muốn được dẫn dắt thế nào là hợp lý, nhưng chờ sau gate mới điều chỉnh khiến cảm giác bị giám sát kéo dài; stem đã cho thấy phong cách hiện tại không còn phù hợp."],exp:"Task P3, enabler 'determine an appropriate leadership style'. Trong dự án hybrid, phong cách có thể khác nhau giữa các giai đoạn: chỉ đạo hơn khi cần tuân thủ chặt, phục vụ và trao quyền khi đội đã trưởng thành. Quy tắc nhớ: phong cách theo ngữ cảnh, không theo thói quen."},{id:"o259",n:259,t:0,origin:"original",eco:"P3",domain:"people",approach:"agile",tags:["agile","eco-2026","problem-solving","retrospective","root-cause"],type:"mc",q:"An agile team has missed its sprint goal three sprints in a row. Carry-over work is rising, and members offer different explanations: unclear stories, interruptions from support tickets, and unstable test environments. Nobody has collected data on any of them, and the product owner suggests simply committing to less. What should the project manager do first?",opts:["Cut the sprint commitment by 20 percent with the product owner, and review it once velocity recovers","Introduce a stricter definition of ready, and admit only fully refined stories into the sprint backlog from now on","Gather carry-over reasons, ticket counts, and environment downtime from three sprints to see which explanation holds","Dedicate one developer per sprint to support tickets, and track the effect on the sprint goal over two sprints"],ans:[2],why:["Sai: giảm cam kết là đúng nếu dữ liệu cho thấy đội luôn nhận quá sức, nhưng ở đây chưa ai thu thập dữ liệu; giảm 20 phần trăm khi chưa biết nguyên nhân chỉ che triệu chứng và để lại nguyên nhân thật.","Sai: definition of ready chặt hơn là đúng nếu bằng chứng cho thấy story chưa rõ là nguyên nhân chính, nhưng ở đây đó mới chỉ là một trong ba giả thuyết chưa kiểm chứng; áp quy trình mới có thể không đụng tới gốc.","Đúng: ba lời giải thích khác nhau và chưa ai có dữ liệu, trong khi product owner đề nghị cam kết ít hơn. PM thu thập lý do tồn đọng, số ticket và thời gian môi trường sập qua ba sprint để biết giả thuyết nào đúng.","Sai: dành một lập trình viên cho ticket hỗ trợ là đúng nếu dữ liệu chứng minh ticket là nguyên nhân chính, nhưng ở đây chưa có dữ liệu; cơ cấu lại đội dựa trên một giả thuyết có thể bỏ sót nguyên nhân khác."],exp:"Task P3, enabler 'solve problems'. Khi đội có nhiều giả thuyết về nguyên nhân mà chưa có dữ liệu, bước đầu là thu thập dữ kiện để kiểm chứng từng giả thuyết, rồi để đội cùng chọn thử nghiệm cải tiến ở retrospective. Quy tắc nhớ: kiểm chứng nguyên nhân bằng dữ liệu trước khi đổi cam kết hoặc cấu trúc."},{id:"o260",n:260,t:0,origin:"original",eco:"P3",domain:"people",approach:"predictive",tags:["predictive","eco-2026","voice-of-the-team","schedule-compression"],type:"mc",q:"A sponsor shortens the delivery date of a predictive logistics project by four weeks after a competitor's announcement. The team's analysis shows the new date would require skipping integration testing or about 30 percent overtime for six weeks. Team members are anxious and have asked the project manager to speak for them. What should the project manager do?",opts:["Present the team's analysis to the sponsor together with the available options and the risks of each","Rebuild the schedule with integration testing running in parallel with development, and submit it as the new baseline","Invite the sponsor to meet the team so that members can voice their concerns about the new date themselves","Run a risk workshop with the team to quantify the schedule and quality risks of the new date, then choose a response"],ans:[0],why:["Đúng: đội đã phân tích và chỉ ra ngày mới cần bỏ kiểm thử tích hợp hoặc tăng ca khoảng 30 phần trăm. PM đại diện tiếng nói của đội bằng cách đưa phân tích, các phương án và rủi ro tới sponsor để quyết có thông tin.","Sai: chạy tích hợp song song với phát triển là kỹ thuật nén lịch hợp lệ (fast tracking), nhưng phân tích của đội đã tính các cách nén; đưa lịch mới làm baseline mà chưa thảo luận với sponsor đặt họ trước việc đã rồi.","Sai: sponsor gặp đội trực tiếp là hợp lý khi cần, nhưng các thành viên đang lo lắng và đã nhờ PM nói thay; đẩy họ ra trước sponsor khi chưa có phân tích rõ ràng khiến họ dễ bị áp lực.","Sai: workshop rủi ro để định lượng ảnh hưởng của ngày mới là việc đúng khi chưa có phân tích, nhưng đội đã có phân tích rồi; họp thêm chỉ trì hoãn việc đưa dữ liệu tới người quyết."],exp:"Task P3, enabler 'represent the voice of the team'. PM mang dữ liệu và các lựa chọn của đội đến người có thẩm quyền để quyết định có thông tin, thay vì tự chịu hoặc chỉ chuyển lời. Quy tắc nhớ: đại diện bằng bằng chứng và phương án."},{id:"o261",n:261,t:0,origin:"original",eco:"P3",domain:"people",approach:"predictive",tags:["predictive","eco-2026","varied-perspectives","remote-team","design-review"],type:"mc",q:"A predictive product-engineering project has headquarters leads who write designs and a remote-site team who implement them. Remote team members, who report through a different management line, rarely question the designs, and several defects traceable to design flaws were found only during integration. Design reviews are held in a large call led by headquarters. Remote members have told the project manager they often spot problems in the designs but see no opening to say so in the call. What should the project manager do?",opts:["Review the integration defect records with both teams, and confirm which design flaws the remote team had noticed","Introduce a verification step in which headquarters leads compare each implementation with the designs before integration","Ask the remote site manager to coach team members on raising design concerns during the review calls","Restructure the design reviews so remote members submit written comments beforehand and speak first in the discussion"],ans:[3],why:["Sai: rà soát hồ sơ lỗi để xác nhận người từ xa đã thấy gì là đúng nếu chưa biết họ có nhận ra vấn đề, nhưng ở đây họ đã nói họ thường thấy lỗi thiết kế mà không có cơ hội nói; không cần chứng minh thêm.","Sai: thêm bước kiểm tra do trụ sở thực hiện là đúng nếu lỗi nằm ở khâu triển khai, nhưng ở đây lỗi xuất phát từ thiết kế mà đội từ xa thấy trước; kiểm tra thêm đặt kiểm soát vào sai chỗ và không mở kênh cho họ.","Sai: nhờ quản lý site huấn luyện là đúng nếu rào cản là kỹ năng nói của từng người, nhưng ở đây rào cản là cách tổ chức cuộc gọi lớn do trụ sở dẫn dắt; huấn luyện cá nhân không sửa môi trường họp.","Đúng: người từ xa thấy lỗi thiết kế nhưng không có chỗ để nói trong cuộc gọi lớn do trụ sở dẫn dắt. PM thiết kế lại buổi review: nhận bình luận viết trước và cho họ phát biểu đầu tiên, sửa môi trường thay vì đòi họ nói."],exp:"Task P3, enabler 'support the team's varied experiences, skills, and perspectives'. Muốn tận dụng góc nhìn khác nhau phải thiết kế môi trường để mọi người nói được (kênh viết, review có cấu trúc, mời phản biện). Quy tắc nhớ: sửa môi trường, đừng chỉ yêu cầu người ít nói nói nhiều hơn."},{id:"o262",n:262,t:0,origin:"original",eco:"P3",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","empowerment","decision-rights","regulatory"],type:"mc",q:"A hybrid pharma-reporting project works in sprints, but regulatory sign-off at the gate belongs to the quality director. The project manager wants to empower the team, but testers are unsure which acceptance decisions they can make themselves within a sprint and keep asking for approval. The quality director has said she will delegate sprint-level acceptance once the boundary is written down. What should the project manager do?",opts:["Have testers log their acceptance questions for two sprints, and review with the quality director which ones need approval","Authorize the team to approve increments for release once the definition of done is met, regulatory items included","Take over acceptance decisions personally, and pass the regulatory ones to the quality director at each gate","Draw up decision rights signed by the quality director: the team accepts sprint increments, regulatory sign-off stays at the gate"],ans:[3],why:["Sai: ghi lại câu hỏi hai sprint rồi duyệt là đúng nếu chưa rõ loại quyết định nào cần phê duyệt, nhưng ở đây giám đốc chất lượng sẵn sàng giao quyền chỉ cần ranh giới được viết ra; chờ hai sprint làm đội tiếp tục hỏi.","Sai: trao toàn quyền phê duyệt bản phát hành là đúng nếu không có thẩm quyền quy định ở gate, nhưng ở đây ký duyệt pháp lý thuộc giám đốc chất lượng; trao hết cho đội vượt quyền của người đó.","Sai: PM tự quyết mọi việc chấp nhận là đúng nếu đội chưa đủ năng lực, nhưng ở đây mục tiêu là trao quyền; PM giữ hết biến mình thành điểm nghẽn và đội tiếp tục hỏi xin phép.","Đúng: giám đốc chất lượng sẵn sàng giao quyền nếu ranh giới được viết ra. PM lập quyền quyết định cùng bà ấy: đội chấp nhận sprint increment, ký duyệt pháp lý vẫn ở gate; ranh giới rõ cho phép trao quyền đúng chỗ."],exp:"Task P3, enabler 'empower the team' (kèm 'establish clear roles and responsibilities'). Trao quyền hiệu quả cần ranh giới quyết định rõ ràng, đặc biệt khi có thẩm quyền quy định ở mức gate. Bẫy: hoặc trao tất cả hoặc giữ tất cả."},{id:"o263",n:263,t:0,origin:"original",eco:"P4",domain:"people",approach:"agile",tags:["agile","eco-2026","stakeholder-analysis","adoption"],type:"mc",q:"A product team building a call-center tool demonstrates each sprint to the operations executive, who gives quick approvals. The call-center floor manager, whose 120 agents will use the tool daily, never speaks in reviews, and agent adoption will determine the benefits. The product owner treats the executive as the sole decision maker. What should the project manager do?",opts:["Keep the demos focused on the operations executive's priorities and brief the floor manager after each release","Analyze the floor manager's influence on adoption and plan how the agents can take part in sprint reviews","Ask the executive whether the floor manager's team has concerns, and relay the answer to the product owner","Put the floor manager on the release-notes distribution list and invite questions by email after each sprint"],ans:[1],why:["Sai: tập trung demo cho người duyệt và báo sau cho người dùng là cách làm quen thuộc, nhưng 120 agent dùng hằng ngày quyết định thành công nên không thể chỉ nghe kết quả sau phát hành.","Đúng: executive duyệt nhanh nhưng floor manager im lặng, trong khi mức độ dùng của 120 agent quyết định lợi ích. PM phân tích ảnh hưởng của floor manager lên việc áp dụng và lên kế hoạch cho agent tham gia review.","Sai: hỏi executive về mối lo của floor manager là đến thông tin qua trung gian; executive không đại diện cho người dùng hằng ngày nên câu trả lời có thể thiếu hoặc lệch.","Sai: thêm vào danh sách ghi chú phát hành và mời hỏi qua email là kênh một chiều và thụ động; người đã im lặng ở review khó bỗng trở thành người đặt câu hỏi."],exp:"Task P4 (Engage stakeholders), enabler 'analyze stakeholders'. Quyền phê duyệt không bằng mức ảnh hưởng tới giá trị; người ít lên tiếng vẫn có thể quyết định thành bại. Quy tắc nhớ: phân tích bên liên quan theo tác động, không theo độ ồn."},{id:"o264",n:264,t:0,origin:"original",eco:"P4",domain:"people",approach:"predictive",tags:["predictive","eco-2026","communication-plan","tailoring"],type:"mc",q:"A predictive infrastructure project sends the same 30-page monthly status report to every stakeholder. The CFO says it is too detailed, the finance director wants cost variance by work package, and field supervisors admit they never open it. Interviews last week confirmed what each group needs: the CFO a one-page summary, the finance director monthly cost variance by work package, and the field supervisors a short weekly look-ahead. The communications management plan has not been revised since planning. What should the project manager do?",opts:["Tailor the communications management plan so that each group receives content in its own format and frequency","Place a one-page executive summary at the front of the report and keep the 30-page body for everyone else","Interview the CFO, finance director, and field supervisors again about their reporting needs before revising the plan","Move the report onto an online dashboard that the three groups can open on demand, and retire the monthly document"],ans:[0],why:["Đúng: các cuộc phỏng vấn tuần trước đã xác nhận nhu cầu của từng nhóm (tóm tắt một trang, chênh lệch chi phí theo work package, bản nhìn trước hằng tuần). PM cập nhật kế hoạch truyền thông để mỗi nhóm nhận nội dung, định dạng và tần suất riêng.","Sai: thêm bản tóm tắt vào đầu báo cáo giải quyết nhu cầu của CFO, nhưng finance director và field supervisor vẫn nhận bản 30 trang; chưa tùy biến cho từng nhóm như dữ liệu phỏng vấn đã cho thấy.","Sai: phỏng vấn lại cùng các nhóm về nhu cầu là đúng bước nếu chưa biết họ cần gì, nhưng stem cho biết họ vừa phỏng vấn tuần trước và nhu cầu đã rõ; làm lại chỉ trì hoãn việc sửa kế hoạch.","Sai: một dashboard trực tuyến cho ba nhóm là công cụ hữu ích nhưng chưa tùy biến nội dung và tần suất; nhóm field supervisor vốn không mở báo cáo sẽ không chắc mở dashboard, và bỏ báo cáo hằng tháng có thể làm mất thông tin chính thức."],exp:"Task P4, enabler 'analyze and tailor communication to stakeholder needs'. Khi nhu cầu từng nhóm đã được xác nhận, PM cập nhật kế hoạch truyền thông theo từng nhóm: nội dung, định dạng, tần suất. Quy tắc nhớ: đã hỏi xong thì sửa kế hoạch, đừng hỏi lại và đừng phát một bản cho tất cả."},{id:"o265",n:265,t:0,origin:"original",eco:"P4",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","engagement-plan","execution"],type:"mc",q:"The stakeholder engagement plan for a hybrid smart-ticketing project calls for monthly sprint-demo walkthroughs with the transport authority liaison to move them from resistant to supportive. In three months only one walkthrough took place because the team was busy, and the liaison has now complained about being left out. What should the project manager do?",opts:["Offer the liaison read access to the sprint board and backlog so that progress is visible at any time between sprints","Hold a walkthrough this sprint, give the monthly sessions a named team owner, then put them on the team calendar","Reassess the liaison's influence and attitude with the sponsor before deciding whether to resume the walkthroughs","Move the walkthroughs to a quarterly cadence that the team's current delivery capacity can sustain"],ans:[1],why:["Sai: quyền xem sprint board giúp minh bạch tiến độ, nhưng người liên lạc phàn nàn vì bị bỏ ra ngoài; kế hoạch tương tác cần các buổi trình diễn trực tiếp để chuyển họ từ chống đối sang ủng hộ.","Đúng: kế hoạch tương tác đã nêu rõ buổi trình diễn hằng tháng nhưng chỉ làm một lần vì đội bận. PM thực hiện lại ngay một buổi, gán người phụ trách có tên và đưa vào lịch đội để không bỏ sót nữa.","Sai: đánh giá lại ảnh hưởng và thái độ cùng sponsor có thể hữu ích khi phân tích đã lỗi thời, nhưng nguyên nhân thất bại ở đây là việc thực hiện, không phải sai phân tích; họp đánh giá chỉ làm chậm thêm.","Sai: giảm xuống mỗi quý để phù hợp năng lực đội là thu hẹp cam kết đúng lúc người liên lạc đang bất mãn; nó làm tín hiệu bị bỏ ra ngoài mạnh hơn."],exp:"Task P4, enabler 'execute the stakeholder engagement plan'. Kế hoạch tương tác phải được thực hiện như đã định, có người phụ trách, và được rà soát hiệu quả. Bẫy: giảm cam kết vì đội bận hoặc bù bằng tài liệu."},{id:"o266",n:266,t:0,origin:"original",eco:"P4",domain:"people",approach:"agile",tags:["agile","eco-2026","trust","transparency","stakeholder-skepticism"],type:"mc",q:"Business stakeholders at a bank are skeptical of a new agile project and keep asking for a fixed-scope plan with committed dates. They say previous projects 'never showed anything until the end.' The team has a prioritized backlog and delivers working increments every two weeks. How should the project manager build their trust?",opts:["Convert the backlog into a detailed fixed-scope plan with committed dates, and report progress against it monthly","Ask the stakeholders to describe what went wrong on earlier projects, and summarize their needs for a fixed-scope plan","Hold an agile-practices workshop for the stakeholders, and walk them through how scope is managed per sprint","Share the backlog and progress data openly, invite the stakeholders to every review, and deliver what each sprint promised"],ans:[3],why:["Sai: kế hoạch phạm vi cố định với mốc cam kết là đúng nếu hợp đồng bắt buộc cách làm đó, nhưng ở đây đội đã có backlog ưu tiên và giao tăng trưởng mỗi hai tuần; quay lại kế hoạch cứng bỏ lợi thế agile mà không tạo niềm tin.","Sai: nghe họ kể sai sót quá khứ là đúng nếu chưa hiểu vì sao họ không tin, nhưng ở đây họ đã nói lý do (không thấy gì đến cuối); thu thập nhu cầu cho kế hoạch cố định củng cố đúng điều họ muốn tránh.","Sai: workshop về agile là đúng nếu họ chưa hiểu cách quản lý phạm vi, nhưng ở đây vấn đề là thiếu thấy kết quả sớm; giải thích bằng lời không tạo niềm tin bằng việc cho họ nhìn thấy sản phẩm.","Đúng: họ nghi ngờ vì các dự án trước không cho thấy gì đến cuối. PM cho họ thấy tiến độ và backlog công khai, mời dự mọi review và giữ lời cam kết từng sprint; niềm tin đến từ minh bạch và giữ lời hứa."],exp:"Task P4, enabler 'build trust and influence stakeholders to accomplish project objectives'. Niềm tin đến từ minh bạch, tham gia và giữ lời hứa; ảnh hưởng đến từ quan hệ, không từ quyền lực. Quy tắc nhớ: cho họ thấy, đừng chỉ nói."},{id:"o267",n:267,t:0,origin:"original",eco:"P4",domain:"people",approach:"predictive",tags:["predictive","eco-2026","alignment","scope-trade-off","change-control"],type:"mc",q:"A predictive order-management upgrade has an approved objective of cutting order processing time by 30 percent. The sales director asks for extra customer-profile screens that the project manager's analysis shows would add steps to every order and cancel about a third of the target, while the operations director insists on the 30 percent. In a joint meeting both rejected a compromise and neither accepts the other's authority. The scope baseline contains neither the screens nor any trade-off, and the objective belongs to the sponsor. What should the project manager do?",opts:["Show both directors the effect on the objective, and facilitate a prioritized settlement through change control","Escalate the clash to the sponsor, backed by the impact analysis, and ask for a ruling on the screens against the 30 percent target","Include half of the requested screens as a compromise, and record the reduced gain in the scope baseline","Decline the screens as out of baseline, and tell the sales director to raise them in a later release"],ans:[1],why:["Sai: facilitate thương lượng qua change control là đúng nếu hai giám đốc chưa thử nói chuyện hoặc còn khả năng nhượng bộ, nhưng ở đây cả hai đã bác thỏa hiệp và không công nhận thẩm quyền của nhau; PM không thể tự dàn xếp tiếp.","Đúng: PM đã phân tích tác động, hai giám đốc bác thỏa hiệp, và mục tiêu 30 phần trăm thuộc sponsor. Xung đột giữa hai giám đốc về mục tiêu của sponsor phải leo thang lên sponsor kèm phân tích để ra phán quyết.","Sai: lấy một nửa số màn hình là đúng nếu phân tích cho thấy một nửa vẫn nằm trong 30 phần trăm, nhưng ở đây hai bên bác thỏa hiệp và mỗi màn hình đều làm tăng bước; chia đôi mà không có cơ sở là chọn nửa vời.","Sai: từ chối vì ngoài baseline là đúng nếu sales không có quyền đề xuất, nhưng ở đây sales là giám đốc có ảnh hưởng và yêu cầu hợp lệ phải đi qua change control; PM không được tự từ chối thay sponsor."],exp:"Task P4, enabler 'optimize alignment among stakeholder needs, expectations, and project objectives'. Khi nhu cầu của hai bên liên quan xung đột với mục tiêu của sponsor và PM đã phân tích tác động mà hai bên không nhượng bộ, PM leo thang lên sponsor kèm bằng chứng để có phán quyết. Bẫy: tự chọn phe hoặc chia đôi mà không có cơ sở."},{id:"o268",n:268,t:0,origin:"original",eco:"P4",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","stakeholder-identification","register"],type:"mc",q:"A project manager starts a hybrid public-service portal (sprint-built, with phase-gated approvals for the tax-agency link) and the sponsor provides a list of eight stakeholders, all from the sponsor's own department. The portal will serve citizens, connect to a tax agency's system, and store personal data. The project manager suspects the list is incomplete. How should the project manager build the stakeholder register?",opts:["Brainstorm with the sponsor and the eight listed stakeholders who else the portal affects, and add their suggestions","Combine the charter with 'who else is affected?' interviews and registers of similar past public-service projects","Reuse the stakeholder list from the previous project, which had the same sponsor and the same team","Add citizen groups and the tax agency to the sponsor's list, since they are obvious, and record the register as complete"],ans:[1],why:["Sai: brainstorm với chính tám người cùng phòng ban sẽ dựa vào cùng góc nhìn nội bộ; họ khó nhận ra các nhóm bên ngoài (công dân, cơ quan thuế, người xử lý dữ liệu cá nhân).","Đúng: danh sách của sponsor toàn người nội bộ, trong khi cổng phục vụ công dân, nối với hệ thống cơ quan thuế và lưu dữ liệu cá nhân. PM dùng nhiều nguồn: charter, phỏng vấn hỏi còn ai bị ảnh hưởng, và hồ sơ dự án dịch vụ công tương tự.","Sai: dùng lại danh sách dự án trước vì cùng sponsor và đội là sao chép góc nhìn cũ; cổng thông tin công dân có người dùng và cơ quan khác hẳn nên danh sách sẽ thiếu.","Sai: tự thêm các nhóm hiển nhiên rồi coi register là đầy đủ chỉ khép lại một vài khoảng trống; không có phương pháp tìm kiếm có hệ thống thì các nhóm kém hiển nhiên (như người quản lý dữ liệu) vẫn bị sót."],exp:"Task P4, enabler 'identify stakeholders'. Nhận diện bên liên quan dùng nhiều nguồn: tài liệu dự án, phỏng vấn (hỏi 'còn ai'), dữ liệu dự án tương tự, và cả bên ngoài tổ chức. Quy tắc nhớ: đừng dựa vào một danh sách."},{id:"o269",n:269,t:0,origin:"original",eco:"P4",domain:"people",approach:"predictive",tags:["predictive","eco-2026","communication-tailoring","executive-reporting"],type:"mc",q:"A non-technical executive sponsor of a predictive facility-automation project says, 'Just tell me whether we are OK.' The monthly package the project manager sends her contains a 40-line technical risk log and engineering metrics, and she has missed two decisions that were buried in it. What should the project manager do?",opts:["Send a brief business-language summary of decisions needed and top risks, with technical detail on request","Ask her which indicators she wants in the monthly package and how she wants decisions flagged for her","Add a decision-tracker page at the front of the monthly package and keep the technical risk log attached for reference","Set up a monthly walkthrough where the lead engineer explains the risk log and metrics to her in person"],ans:[0],why:["Đúng: sponsor không chuyên kỹ thuật, chỉ muốn biết 'ổn hay không' và đã bỏ lỡ hai quyết định chôn trong bản kỹ thuật. PM dịch thông tin sang ngôn ngữ kinh doanh ngắn gọn: trạng thái, quyết định cần làm, rủi ro hàng đầu, chi tiết khi cần.","Sai: hỏi sponsor chỉ số cần xem là thói quen tốt, nhưng bà đã nói rõ muốn biết 'ổn hay không' và đã bỏ lỡ quyết định; hỏi thêm làm chậm việc đổi sang bản tóm tắt.","Sai: thêm trang theo dõi quyết định giúp thấy quyết định, nhưng vẫn gửi 40 dòng log kỹ thuật kèm theo; bà vẫn phải đọc ngôn ngữ kỹ thuật để hiểu bối cảnh.","Sai: buổi giải thích hằng tháng bởi kỹ sư buộc sponsor học ngôn ngữ kỹ thuật và tốn thời gian của bà; PM nên là người dịch thông tin thay vì chuyển việc cho kỹ sư."],exp:"Task P4, enabler 'analyze and tailor communication to stakeholder needs'. Truyền thông hiệu quả theo người nhận: ngắn, rõ, ngôn ngữ của họ, gắn với quyết định cần làm. Quy tắc nhớ: PM dịch thông tin cho sponsor, không bắt sponsor học ngôn ngữ kỹ thuật."},{id:"o270",n:270,t:0,origin:"original",eco:"P4",domain:"people",approach:"agile",tags:["agile","eco-2026","engagement-plan","adaptation","clinical-users"],type:"mc",q:"The engagement plan for an agile hospital-scheduling project relies on clinical staff giving feedback at each sprint review. Attendance has fallen to one nurse per review because the sessions fall during ward rounds, and the feedback that reaches the team comes late and second-hand. Nurses have told the project manager informally that they want to take part, but nobody has asked them what would work. What should the project manager do?",opts:["Report the low attendance to the sponsor and ask her to have the ward managers release nurses from rounds to attend reviews","Analyze attendance and review-feedback quality with the product owner to decide which review slots to change","Ask clinical staff and the ward managers which timing and format suit them, and trial short ward-based feedback sessions","Form a clinical advisory group of two nurses that meets monthly with the product owner and relays ward feedback"],ans:[2],why:["Sai: nhờ sponsor yêu cầu quản lý khoa cho y tá rời ca là đúng nếu họ đã nói muốn tham dự nhưng bị cấm, nhưng ở đây chưa ai hỏi họ điều gì phù hợp; leo thang trước khi thử điều chỉnh lịch là bỏ qua giải pháp trong tầm tay PM.","Sai: phân tích số liệu tham dự và chất lượng phản hồi cùng product owner nghe cẩn trọng, nhưng nguyên nhân đã rõ (buổi review trùng giờ đi buồng); thứ còn thiếu là điều y tá thấy phù hợp, và phân tích thêm không trả lời được điều đó.","Đúng: y tá nói muốn tham gia nhưng chưa ai hỏi họ điều gì phù hợp, và buổi review trùng giờ đi buồng. PM hỏi nhân viên lâm sàng cùng quản lý khoa về thời điểm và hình thức, rồi thử các buổi phản hồi ngắn ngay tại khoa; điều chỉnh theo người tham gia.","Sai: nhóm cố vấn hai y tá họp hàng tháng là đúng nếu không thể thay đổi lịch review, nhưng ở đây chưa hỏi nhóm lớn; hai đại diện và họp tháng sẽ chuyển tiếp phản hồi chậm và qua trung gian như hiện nay."],exp:"Task P4, enabler 'execute the stakeholder engagement plan'. Thực hiện kế hoạch tương tác không có nghĩa lặp lại một lịch cố định: khi hiệu quả thấp, hỏi bên liên quan và điều chỉnh cách tiếp cận. Quy tắc nhớ: thích nghi theo người, không bắt họ thích nghi theo lịch."},{id:"o271",n:271,t:0,origin:"original",eco:"P4",domain:"people",approach:"predictive",tags:["predictive","eco-2026","trust","community-engagement"],type:"mc",q:"A predictive wind-farm project needs a local permit supported by a community leader. She distrusts the project because a previous developer broke promises about local jobs. The permit hearing is in ten weeks. The project manager has compliance reports and a community benefits budget approved by the sponsor, but the budget document does not say whether it covers any local-jobs commitment. What should the project manager do first?",opts:["Ask the local government's community office what drives her distrust, and tailor the permit presentation to it","Ask the sponsor to confirm what the community benefits budget can commit on local jobs before any promise is made to her","Announce a binding local-jobs target at a public meeting before the hearing, and seek the sponsor's approval afterwards","Commission an independent community-impact study, and present its findings at the hearing to answer the jobs concern"],ans:[1],why:["Sai: hỏi văn phòng cộng đồng của chính quyền là đúng nếu chưa biết vì sao bà ấy nghi ngờ, nhưng ở đây lý do đã rõ (nhà phát triển trước thất hứa về việc làm); điều cần biết là dự án này có thể cam kết gì.","Đúng: bà ấy mất tin vì thất hứa về việc làm, mà ngân sách cộng đồng chưa nói có bao phủ cam kết việc làm hay không. PM xác nhận với sponsor dự án có thể cam kết gì trước khi hứa, để mọi lời hứa sau đó giữ được.","Sai: công bố chỉ tiêu việc làm ràng buộc là đúng nếu sponsor đã duyệt cam kết đó, nhưng ở đây chưa có; hứa trước rồi xin duyệt sau lặp lại đúng kiểu thất hứa đã phá niềm tin và có thể phải rút lại.","Sai: nghiên cứu tác động độc lập là đúng nếu mối lo chính là tác động môi trường hoặc xã hội cần số liệu, nhưng ở đây mối lo là lời hứa việc làm bị phá; báo cáo không thay thế cam kết có thể giữ được."],exp:"Task P4, enabler 'build trust and influence stakeholders to accomplish project objectives'. Niềm tin bị phá vì thất hứa chỉ được xây lại bằng cam kết giữ được: PM xác nhận trước với sponsor điều dự án thực sự có thể hứa, rồi mới gặp và cam kết từng bước nhỏ. Quy tắc nhớ: đừng hứa điều chưa xác nhận."},{id:"o272",n:272,t:0,origin:"original",eco:"P4",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","alignment","expectations","scope-date-trade-off"],type:"mc",q:"A hybrid mobile-banking release has a launch date fixed in the release plan and tied to a marketing event in June, while the team builds in sprints. Team velocity forecasts about 75 percent of the planned scope by then. The sponsor has confirmed that the date cannot move, but she accepts a smaller first release if partners are told beforehand and the cut features follow in the next release. Marketing has already promised the full feature list to partners. What should the project manager do?",opts:["Hold a session with the sponsor and marketing to discuss the forecast and decide the trade-offs together","Have marketing move the event and the partner announcements back so that the planned features can be completed","Cut the lowest-value features from the first release, brief partners through marketing before the event, then schedule the rest","Fast-track by adding two contract developers now so that the forecast reaches the full scope by the event"],ans:[2],why:["Sai: họp để cùng bàn đánh đổi là đúng khi các bên chưa nói với nhau, nhưng sponsor đã chốt ngày không dời và chấp nhận bản nhỏ hơn nếu báo trước đối tác; họp thêm chỉ làm chậm.","Sai: dời sự kiện và thông báo đối tác bị loại trừ vì sponsor đã nói ngày không thể thay đổi; đây là lựa chọn đúng nếu ngày còn linh hoạt.","Đúng: ngày cố định, velocity chỉ đạt khoảng 75 phần trăm phạm vi, và sponsor chấp nhận phát hành nhỏ hơn nếu đối tác biết trước. PM cắt tính năng giá trị thấp nhất, báo marketing và đối tác trước sự kiện, và xếp phần còn lại vào bản sau.","Sai: thêm hai lập trình viên hợp đồng giữa chừng sẽ mất thời gian làm quen và làm chậm đội hiện tại; dự báo phạm vi đầy đủ vào ngày sự kiện không chắc đạt được."],exp:"Task P4, enabler 'optimize alignment among stakeholder needs, expectations, and project objectives'. Khi sponsor đã chấp nhận ngày cố định và bản phát hành nhỏ hơn, PM thực hiện: cắt tính năng giá trị thấp nhất, báo trước cho marketing và đối tác, lên lịch phần còn lại. Quy tắc nhớ: đã thống nhất đánh đổi thì làm, đừng họp lại."},{id:"o273",n:273,t:0,origin:"original",eco:"P4",domain:"people",approach:"agile",tags:["agile","eco-2026","stakeholder-analysis","organizational-change"],type:"mc",q:"After a reorganization, a new vice president of operations has begun contacting team members directly to request changes. The product owner of an agile project dismisses her as 'noise' because she is not on the stakeholder map, yet her department will own the product after launch and her requests are reshaping priorities. What should the project manager do first?",opts:["Re-analyze the stakeholder map for her interests and influence before planning how to engage her","Escalate to the sponsor and ask for a ruling on which of the new vice president's requests the product may accept","Invite her to the next sprint review to present her requests directly to the team and the product owner","Update the product vision to include her department's operational goals before the next release is planned"],ans:[0],why:["Đúng: tổ chức vừa tái cấu trúc, bà phó chủ tịch không có trong bản đồ nhưng bộ phận bà sẽ sở hữu sản phẩm và yêu cầu của bà đang đổi ưu tiên. PM phân tích lại lợi ích, ảnh hưởng và kỳ vọng của bà rồi mới lập kế hoạch tương tác.","Sai: nhờ sponsor phân xử là bước leo thang hợp lệ khi có xung đột ưu tiên, nhưng PM chưa phân tích mối quan hệ và ảnh hưởng của bà; sponsor sẽ quyết mà thiếu dữ kiện về bên liên quan mới.","Sai: mời bà trình bày ở sprint review là cách tương tác hợp lý, nhưng làm trước khi phân tích khiến PM chưa biết bà muốn gì và cần mức tương tác nào; có thể đặt đội vào thế bị động.","Sai: cập nhật tầm nhìn theo mục tiêu của bộ phận bà là nhượng bộ trước khi phân tích; PM chưa biết lợi ích và kỳ vọng thật của bà nên thay đổi tầm nhìn có thể lệch khỏi nhu cầu của các bên khác."],exp:"Task P4, enabler 'analyze stakeholders'. Bản đồ bên liên quan phải được cập nhật khi tổ chức thay đổi; mức ảnh hưởng thực tế quan trọng hơn việc có tên trong danh sách. Quy tắc nhớ: phân tích lại trước khi nhượng bộ hay phớt lờ."}],i=[{id:"o205",n:205,t:0,origin:"original",eco:"P5",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","stakeholder-categorization","influence-impact"],type:"mc",q:'A hospital group is rolling out a new scheduling system using a hybrid approach: the payroll integration follows a fixed plan, while the clinician screens are built in sprints. The stakeholder register is a flat list of 38 names, and each department has already sent the PM its "must-haves". The PM has two weeks to prepare the alignment sessions. What should the PM do first?',opts:["Analyze the departments' must-have lists for overlaps with each department head, then group the attendees by the themes that emerge","Categorize the 38 stakeholders by influence plus expectation impact, then identify who joins which session","Ask each department head to nominate delegates, and plan the sessions around the delegates put forward","Hold calls with the heads who sent the longest must-have lists to hear their concerns in detail first"],ans:[1],why:["Sai: phân tích must-have cùng các trưởng phòng rồi gom theo chủ đề là bước hợp lý khi đã biết ai cần ngồi cùng nhau, nhưng ở đây sổ stakeholder còn là danh sách phẳng 38 tên nên chủ đề chưa gắn được với mức ảnh hưởng của từng người.","Đúng: sổ stakeholder mới là danh sách phẳng 38 tên, nên PM phân nhóm theo ảnh hưởng và tác động kỳ vọng để quyết định ai vào phiên nào trong hai tuần chuẩn bị.","Sai: để phòng ban cử đại diện là hợp lý khi đã biết nhóm nào cần có mặt, nhưng ở đây PM chưa phân loại nên không biết người có ảnh hưởng lớn có bị bỏ sót không; chọn người dự là việc của PM.","Sai: nghe sâu từng trưởng phòng là việc tốt khi chuẩn bị, nhưng ở đây độ dài danh sách must-have không cho biết ai ảnh hưởng nhiều nhất, nên ưu tiên theo đó dễ bỏ sót người có quyền lực mà ít lên tiếng."],exp:'Task P5 có enabler "categorize stakeholders": phân loại trước để biết nên đưa ai vào cuộc thảo luận nào, với mức chuẩn bị nào. Bẫy là nhảy ngay vào họp chung hoặc để sponsor quyết thay. Quy tắc nhớ: phân tích và phân nhóm trước, facilitate sau.'},{id:"o206",n:206,t:0,origin:"original",eco:"P6",domain:"people",approach:"agile",tags:["agile","eco-2026","customer-satisfaction","feedback"],type:"mc",q:"A streaming-service team ships every sprint, and every story meets its acceptance criteria. Beta-user satisfaction has fallen across the last three releases. The PM and the product owner have already interviewed 12 beta users and studied the usage data: most users abandon the app at the new navigation menu, and a rework is already in the backlog, ranked low. Velocity is stable. What should the project manager do next?",opts:["Interview a further group of beta users about the navigation menu to confirm what the first interviews showed","Submit the navigation rework to the change control board so that it is reviewed before the next release","Review the backlog with the product owner, moving the navigation rework to the top for the next sprint","Add a navigation usability check to the definition of done, and test new stories against it"],ans:[2],why:["Sai: phỏng vấn thêm hợp lý khi dữ liệu còn mâu thuẫn, nhưng ở đây 12 buổi phỏng vấn và dữ liệu sử dụng đã cùng chỉ vào menu điều hướng; làm thêm chỉ kéo dài khi hướng xử lý đã rõ.","Sai: change control board đúng với dự án predictive có baseline, nhưng ở đây là backlog agile do product owner sắp thứ tự; thêm một vòng duyệt chỉ làm chậm việc sửa.","Đúng: nguyên nhân đã rõ và việc làm lại điều hướng đang nằm cuối backlog, nên PM cùng product owner đưa nó lên đầu cho sprint tới; product owner là người quyết định thứ tự backlog.","Sai: thêm kiểm tra khả dụng vào definition of done là cải tiến tốt cho các story sau, nhưng chỉ xử lý vấn đề phụ; menu điều hướng đang khiến người dùng rời bỏ vẫn chưa được sửa."],exp:'Task P6, enabler "monitor customer satisfaction and respond as needed": khi PM và product owner đã tìm ra nguyên nhân từ phía người dùng, bước còn lại là hành động quyết định, đưa việc sửa lên đầu backlog qua product owner. Phỏng vấn thêm hay thêm thủ tục chỉ kéo dài thời gian khách còn thất vọng.'},{id:"o207",n:207,t:0,origin:"original",eco:"P7",domain:"people",approach:"predictive",tags:["predictive","eco-2026","critical-knowledge","tacit-knowledge"],type:"mc",q:"A rail-signalling project in predictive execution, with a baselined schedule and scope, depends on a senior engineer who retires in six months. After interviewing her, the project manager has listed the five tasks only she can perform and ranked them by schedule impact; two of them sit on the critical path. The supervised handover will add effort to the baselined schedule. Her manager asks for a knowledge transfer plan that the project can start this month. What should the project manager do next?",opts:["Rank the five tasks by schedule impact, then confirm the ranking with her manager before any transfer starts","Ask her to write a complete signalling manual, then hold a review of it before she retires in six months","Assign a named successor to each of the five tasks, then put the added handover effort through change control","Record a series of video interviews with her on the five tasks, then store them in the knowledge repository"],ans:[2],why:["Sai: đúng nếu chưa biết việc nào quan trọng, nhưng ở đây PM đã liệt kê và xếp hạng năm việc, biết hai việc nằm trên đường găng; thêm vòng xác nhận chỉ làm mất thời gian còn lại.","Sai: đúng nếu cần ghi lại tri thức hiện, nhưng ở đây phần còn lại là tri thức ngầm của năm việc cụ thể; một cuốn manual toàn hệ thống tốn công mà không dạy được cách xử lý tình huống.","Đúng: năm việc đã được xếp hạng, hai việc nằm trên đường găng, dự án đã baseline và bàn giao có giám sát sẽ thêm công sức vào lịch, nên bước quyết định là giao người kế nhiệm cho từng việc rồi đưa phần công sức bổ sung qua change control để vào lịch trong sáu tháng.","Sai: đúng nếu chỉ cần lưu lại điều nói được, nhưng ở đây hai việc trên đường găng cần người kế nhiệm thực hành dưới sự giám sát; video chỉ giữ phần nói được, còn phần phán đoán thì không."],exp:'Task P7, enabler "identify knowledge critical to the project" và "gather knowledge": khi đã biết và xếp hạng việc chỉ một người làm được, PM phải hành động, giao người kế nhiệm và đưa công việc bàn giao vào lịch qua change control vì dự án đã baseline. Tài liệu hoặc video riêng lẻ không chuyển được tri thức ngầm.'},{id:"o208",n:208,t:0,origin:"original",eco:"P8",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","reporting-requirements","governance"],type:"mc",q:"A bank launches a hybrid digital-lending program under strict oversight: the credit engine follows a fixed plan, and the borrower app is built in sprints. The project manager is about to design the status reporting. The sponsor, the risk committee, the regulator, and the delivery teams are all expected to receive some form of reporting, but nobody has said what is needed or how often. What should the project manager do first?",opts:["Work with the compliance lead to compile the reporting each oversight body requires, then set a cadence for each audience","Assess with the scrum masters which sprint metrics the delivery teams already track, then build the first report from those","Reuse the status report template from the last successful program with its PMO owner, then adjust it after the first cycle","Draft a reporting calendar from the PMO's standard cadence, then invite each audience to comment on it"],ans:[0],why:["Đúng: ngân hàng chịu giám sát chặt và chưa ai nêu cần báo cáo gì, nên PM xác định nghĩa vụ báo cáo của risk committee và cơ quan quản lý rồi mới đặt tần suất cho từng nhóm.","Sai: cùng scrum master tìm hiểu số liệu đội đang theo dõi là hữu ích cho báo cáo nội bộ, nhưng ở đây chương trình bị giám sát và chưa ai nói cơ quan quản lý cần gì; báo cáo xây từ số liệu của đội sẽ thiếu nghĩa vụ bắt buộc.","Sai: mẫu của chương trình trước, dùng cùng chủ sở hữu ở PMO, dùng được khi cùng loại giám sát, nhưng ở đây chưa biết yêu cầu của cơ quan quản lý nên chỉnh sau chu kỳ đầu có nguy cơ nộp thiếu nội dung bắt buộc.","Sai: lịch báo cáo theo chuẩn PMO đúng khi nghĩa vụ đã rõ, nhưng ở đây chưa ai nêu tần suất cần; xin góp ý trên lịch dựng sẵn đảo thứ tự, vì yêu cầu phải được xác định trước rồi mới có lịch."],exp:'Task P8, enabler "understand reporting requirements": trước khi tạo báo cáo, PM xác định ai cần thông tin gì, theo yêu cầu quản trị và pháp lý nào, tần suất ra sao. Bẫy: dùng mẫu có sẵn hoặc làm báo cáo cho một đối tượng.'},{id:"o274",n:274,t:0,origin:"original",eco:"P5",domain:"people",approach:"predictive",tags:["predictive","eco-2026","expectations-gap","requirements"],type:"mc",q:"A data-center build is in execution with an approved scope baseline. The client's operations lead has told the PM she expects the cooling system to tolerate two simultaneous unit failures, while the contract requires one redundant unit. The PM has since met her: it is an operating requirement for the tenant SLA. The engineers estimate a second redundant unit at 380,000 USD and five weeks on the critical path. No change request exists. What should the project manager do next?",opts:["Meet the operations lead once more to confirm the expectation and compare it against the contract specification","Ask the client's sponsor to approve the extra unit directly so that the team can start procurement","Submit a change request with the cost and schedule impact to the change control board for a decision","Record the gap in the risk register with a response plan and reassess it when commissioning begins"],ans:[2],why:["Sai: xác nhận kỳ vọng là bước đúng khi mới nghe qua hành lang, nhưng ở đây PM đã gặp chị ấy, đã biết đó là yêu cầu vận hành và đã có ước tính chi phí; họp lại không thêm thông tin nào.","Sai: sponsor có thể duyệt thêm ngân sách, nhưng ở đây phạm vi đã có baseline nên thay đổi phải đi qua change control; duyệt trực tiếp để mua sắm bỏ qua đánh giá tác động lên đường găng.","Đúng: kỳ vọng đã được xác nhận và tác động đã được ước tính (380.000 USD, năm tuần), nên bước đúng là nộp change request kèm tác động cho change control board quyết định.","Sai: đưa vào risk register đúng với rủi ro chưa chắc xảy ra, nhưng ở đây là yêu cầu đã được xác nhận nằm ngoài hợp đồng; để đến lúc commissioning thì chi phí và thời gian sửa đổi sẽ lớn hơn nhiều."],exp:'Task P5, enabler "identify stakeholder expectations" rồi quản lý thay đổi: kỳ vọng ngoài hợp đồng đã được xác nhận và đánh giá tác động thì không còn là việc để hỏi thêm, PM nộp change request cho change control board. Thay đổi trên baseline luôn đi qua kênh chính thức.'},{id:"o275",n:275,t:0,origin:"original",eco:"P5",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","facilitation","conflicting-deadlines"],type:"mc",q:"A fintech payment app follows a hybrid plan: regulatory milestones are fixed, features are delivered iteratively. Marketing has promised partners a full-feature launch in Q2. Compliance says nothing goes live before the external audit ends in Q3, and the auditor has confirmed that end date in writing. Each side has lobbied the sponsor separately and has not seen the other's constraints. The sponsor has asked the project manager to bring back one plan both sides can commit to, not a ruling. What is the best next step?",opts:["Meet the external auditor with compliance to pin down the audit end date, then set the launch date after it","Hold a joint session of marketing plus compliance, then record the agreed scope in the release plan","Present both positions to the sponsor with a recommendation, then pass the sponsor's ruling to both teams","Split the release into a Q2 limited release and a Q3 complete release, then ask each team to accept its part"],ans:[1],why:["Sai: đúng nếu ngày kết thúc audit còn mơ hồ, nhưng ở đây kiểm toán viên đã xác nhận ngày bằng văn bản; họp thêm với kiểm toán không có thông tin mới, còn PM tự đặt ngày thì marketing bị đặt trước việc đã rồi.","Đúng: sponsor yêu cầu một kế hoạch cả hai bên cùng cam kết và hai bên chưa thấy ràng buộc của nhau, nên PM tổ chức buổi làm việc chung rồi ghi phạm vi và ngày đã thống nhất vào release plan.","Sai: đúng nếu sponsor đã yêu cầu một phán quyết, nhưng ở đây sponsor muốn kế hoạch hai bên cùng cam kết; chuyển lên để sponsor phán thì một bên thua cuộc và PM bỏ qua bước căn chỉnh.","Sai: đúng nếu hai bên đã cho thấy họ chấp nhận tách bản phát hành, nhưng ở đây họ chưa nhìn ràng buộc của nhau; đưa sẵn phương án rồi xin chấp nhận là áp đặt trước khi căn chỉnh."],exp:'Task P5, enabler "facilitate discussions to align expectations": khi hai bên có kỳ vọng đối lập và sponsor muốn một cam kết chung, PM tạo cuộc thảo luận chung dựa trên ràng buộc thật của từng bên. Quyết định đơn phương hay chuyển lên để sponsor phán đều bỏ qua bước căn chỉnh.'},{id:"o276",n:276,t:0,origin:"original",eco:"P5",domain:"people",approach:"predictive",tags:["predictive","eco-2026","mentoring","new-stakeholder"],type:"mc",q:'A municipal water-treatment upgrade is managed with a baselined plan and a formal change process. The city has appointed a new community liaison who has never worked on a capital project. In three weeks she has filed six design-change requests; each went through the change request form and impact analysis and was rejected by the change control board. She keeps filing new ones and tells the PM she does not see what "the baseline" is or why her ideas are blocked. An experienced liaison from a previous city project has offered to help. What should the project manager do?',opts:["Seat her on the change control board, then let her learn the process by voting on requests in review","Keep processing her requests as change requests with impact analysis, then send her each board decision with costs","Meet the city's sponsor, then agree how design requests from the liaison will be routed to the project team","Arrange for the experienced liaison to mentor her on the baseline, then walk her through the next requests"],ans:[3],why:["Sai: đúng nếu chị đã nắm baseline và chỉ thiếu thẩm quyền, nhưng ở đây chị chưa hiểu baseline là gì; ngồi trong hội đồng sớm thì chị phê duyệt hay phản đối khi chưa hiểu tác động.","Sai: đúng nếu yêu cầu của chị còn đi ngoài quy trình, nhưng ở đây cả sáu yêu cầu đã qua change request và phân tích tác động; làm tiếp đúng như vậy chỉ cho thêm loạt từ chối mà không giúp chị hiểu.","Sai: đúng nếu yêu cầu của chị bị lạc giữa nhiều đầu mối, nhưng ở đây kênh đã chạy đúng và yêu cầu nào cũng được xử lý; thống nhất lại đường đi với sponsor không thay đổi chuyện chị chưa hiểu baseline.","Đúng: quy trình đã chạy đúng nhưng chị không hiểu baseline nên cứ nộp thêm; PM kết nối người đồng nghiệp giàu kinh nghiệm đang sẵn lòng giúp để chị hiểu baseline và quy trình thay đổi, rồi cùng rà các yêu cầu tiếp theo."],exp:'Task P5 còn có enabler "organize and act on mentoring opportunities": khi quy trình đã vận hành đúng mà stakeholder mới vẫn không hiểu vì sao yêu cầu bị chặn, PM chủ động kết nối họ với người có kinh nghiệm để họ hiểu dự án và đặt kỳ vọng thực tế. Thêm vào hội đồng hay lặp lại quy trình chỉ xử lý triệu chứng.'},{id:"o277",n:277,t:0,origin:"original",eco:"P5",domain:"people",approach:"agile",tags:["agile","eco-2026","backlog-prioritization","role-clarity"],type:"mc",q:"In a Scrum team's refinement session, the sales director wants a customization feature while the support director wants stability fixes. Both say theirs is the top priority, and the team's capacity allows only one for the next sprint. The project manager has already led a 30-minute value discussion: the stability fixes address 60% of weekly support tickets, while the customization is tied to one prospect. The product owner still hesitates to choose between two senior leaders. What should the project manager do?",opts:["Ask the product owner to make the ordering call now and explain the reasoning to both directors","Hold a second discussion with both directors to reach agreement on business value before ordering","Escalate the choice to the sponsor so that neither director feels overruled by the product owner","Run a vote among the developers on which request to take and have the product owner accept it"],ans:[0],why:["Đúng: giá trị của hai yêu cầu đã được thảo luận và dữ liệu đã có, nên PM yêu cầu product owner ra quyết định thứ tự ngay và giải thích minh bạch cho hai giám đốc; thứ tự backlog là quyền của product owner.","Sai: thêm một buổi thảo luận giá trị là bước đúng khi dữ liệu còn thiếu, nhưng ở đây buổi 30 phút đã cho thấy 60% ticket thuộc về stability; họp lại chỉ kéo dài việc product owner ngại quyết định.","Sai: leo thang lên sponsor đúng khi product owner không có thẩm quyền, nhưng ở đây thứ tự backlog thuộc product owner và đủ dữ liệu để chọn; đẩy lên cao làm yếu vai trò của chính product owner.","Sai: lấy ý kiến developer có giá trị về độ khó, nhưng ở đây câu hỏi là giá trị kinh doanh, vốn thuộc về product owner; bỏ phiếu của đội dev đổi người ra quyết định mà không giải quyết sự ngại ngần."],exp:'Task P5, enabler "facilitate discussions to align expectations", trong agile: PM đã tạo thảo luận và có dữ liệu, bước còn lại là để product owner ra quyết định thứ tự và giải thích minh bạch. PM không chọn hộ, cũng không chuyển quyết định sang người khác.'},{id:"o278",n:278,t:0,origin:"original",eco:"P5",domain:"people",approach:"predictive",tags:["predictive","eco-2026","re-categorization","stakeholder-register"],type:"mc",q:'Six months into a predictive pharmaceutical-plant project, the procurement director, listed in the register as low interest, blocks a vendor milestone payment because the progress reports lack the format his audit team requires. The contract is silent on report format, he was never consulted on reporting, and so far he has only said the format "is not acceptable". The vendor is threatening to stop work. What should the project manager do?',opts:["Ask the vendor to reformat the progress reports to his audit team's template, then resubmit the payment claim","Re-assess his position in the register, then meet him to learn what his audit team needs from the reports","Escalate the payment block to the sponsor and legal, then ask that the milestone payment be released","Draft a communications plan update that adds audit-format reports, then send it to him for approval"],ans:[1],why:["Sai: đúng nếu ông đã đưa ra mẫu cụ thể và hợp đồng có yêu cầu, nhưng ở đây ông mới chỉ nói chưa chấp nhận được; nhà thầu chỉnh theo phỏng đoán thì có thể sai mẫu và ông lại từ chối tiếp.","Đúng: ông được xếp low interest nhưng đang chặn thanh toán và chưa nói rõ cần gì, nên PM đánh giá lại vị trí của ông trong sổ stakeholder rồi gặp để biết nhóm audit cần gì ở báo cáo.","Sai: đúng nếu hợp đồng quy định mẫu báo cáo và ông vi phạm, nhưng ở đây hợp đồng không nói gì về mẫu; không có căn cứ mạnh thì cách này biến nhu cầu chưa được lắng nghe thành tranh chấp.","Sai: đúng nếu PM đã biết nhóm audit cần nội dung gì, nhưng ở đây ông chưa nói rõ; cập nhật communications plan và gửi ông duyệt trước khi trao đổi là đảo thứ tự."],exp:'Task P5 gồm "categorize stakeholders" và "identify expectations": phân loại không phải làm một lần. Khi sự cố lộ ra phân loại sai và kỳ vọng chưa rõ, PM cập nhật vị trí stakeholder và gặp trực tiếp để làm rõ. Sửa tài liệu hay dựa vào hợp đồng khi chưa hiểu nhu cầu chỉ che vấn đề gốc.'},{id:"o279",n:279,t:0,origin:"original",eco:"P5",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","facilitation","pilot-scope"],type:"mc",q:"An ERP rollout uses a hybrid approach. The steering committee approved a pilot for three business units only, with the remaining units following in phase 2. The heads of two excluded units have emailed the sponsor and the project manager, stating they were promised inclusion and that their processes are mission-critical. The sponsor has already told the project manager that no inclusion was promised and asked the project manager to answer the two heads. What should the project manager do first?",opts:["Check with the sponsor what was actually said to the two heads, then reply once the sponsor has confirmed it","Explain the approved pilot scope to the two heads, hearing what they believe was promised to them","Draft a change request to bring the two units into the pilot, with an impact estimate for the steering committee","Offer the two units an early phase 2 start, and present the re-sequenced roadmap to the steering committee"],ans:[1],why:["Sai: hỏi sponsor điều đã nói là đúng nếu chưa rõ sự thật, nhưng ở đây sponsor đã xác nhận không hứa gì và giao PM trả lời; hỏi lại chỉ làm hai trưởng đơn vị chờ thêm mà không nghe điều họ tin.","Đúng: hai trưởng đơn vị gửi email trực tiếp cho PM, nên PM giải thích phạm vi pilot đã duyệt và nghe điều họ tin đã được hứa trước, từ đó mới có cơ sở cho bước tiếp theo.","Sai: change request đúng nếu phạm vi cần mở rộng, nhưng ở đây PM chưa nghe họ và chưa biết lời hứa là gì; làm hồ sơ cho steering committee trước khi làm rõ có thể giải quyết sai vấn đề.","Sai: sắp lại lộ trình để đưa họ vào sớm có thể là giải pháp sau này, nhưng ở đây PM chưa biết họ cần gì và vào khi nào; đưa đề xuất lên steering committee trước khi nghe là quá sớm."],exp:'Task P5, enabler "facilitate discussions to align expectations": khi kỳ vọng lệch với quyết định đã duyệt, PM trao đổi trực tiếp để giải thích và lắng nghe điều có thể mong đợi. Không đổi phạm vi bên ngoài quy trình, không chỉ gửi biên bản.'},{id:"o280",n:280,t:0,origin:"original",eco:"P5",domain:"people",approach:"agile",tags:["agile","eco-2026","mentoring","product-owner-coaching"],type:"mc",q:"A Scrum team has a first-time product owner who struggles to say no to senior stakeholders. Stakeholders now send requests straight to developers, and the sprint goal has been disrupted twice. An experienced product owner from another product line has offered some time. What is the best action for the project manager?",opts:["Arrange coaching from the experienced product owner and set one channel for stakeholder requests","Run a workshop with the stakeholders on the product owner's role, and review the outcome with the sponsor","Have the developers log the requests that stakeholders send them so that the product owner can sort them","Have the experienced product owner take the backlog for two sprints while the new one observes"],ans:[0],why:["Đúng: product owner mới ngại từ chối cấp cao và yêu cầu đang chen vào sprint, nên PM sắp xếp cố vấn từ người đã có kinh nghiệm và đặt một kênh tiếp nhận yêu cầu duy nhất.","Sai: hội thảo về vai trò product owner với stakeholder có ích, nhưng ở đây nguyên nhân là product owner chưa đủ tự tin nói không; nếu không giúp chính người đó thì sau hội thảo yêu cầu vẫn dồn về developer.","Sai: developer ghi lại yêu cầu rồi chuyển cho product owner có thể giữ được thông tin, nhưng ở đây developer là người đang bị làm gián đoạn; việc này đẩy thêm công sắp xếp lên người không có thẩm quyền ưu tiên.","Sai: nhờ product owner kinh nghiệm cầm backlog tạm thời nhanh chóng ổn định được, nhưng ở đây người mới cần học cách nói không; lấy backlog khỏi tay họ làm họ mất quyền sở hữu và không học được gì."],exp:'Task P5 có enabler "mentoring opportunities": PM tổ chức cố vấn cho người đang gặp khó và thiết lập cách làm việc rõ ràng với stakeholder. Đừng tiếp quản vai trò hay đẩy trách nhiệm cho developer.'},{id:"o281",n:281,t:0,origin:"original",eco:"P5",domain:"people",approach:"predictive",tags:["predictive","eco-2026","ai","validation","stakeholder-interviews"],type:"mc",q:"Before a predictive rail-signalling project baselines its requirements, the PM used an AI assistant to summarize 40 stakeholder interview transcripts into a list of expectations. The summary showed broad consensus but omitted the safety officer's brief, cautious comments. After checking the transcript and speaking with the safety officer, the PM confirmed and added a requirement that train detection must fail safe within two seconds. Nobody knows why the tool dropped those comments. The baseline review is in five days, and a transcript check can be finished in that time. What should the PM do next?",opts:["Verify the other 39 summaries against the transcripts, quiet speakers first, then baseline the requirements","Log the AI omission in the quality log, then baseline the requirements with the safety requirement included","Re-run the AI summary on all 40 transcripts with a stricter prompt, then compare the new list with the current one","Take the safety requirement to the sponsor, then ask for a ruling on whether the baseline date should move"],ans:[0],why:["Đúng: không ai biết vì sao công cụ bỏ sót và còn đủ năm ngày, nên PM đối chiếu 39 bản tóm tắt còn lại với transcript, ưu tiên người nói ít, rồi mới baseline; PM chịu trách nhiệm về đầu ra của AI.","Sai: đúng nếu nguyên nhân đã rõ và chỉ nằm ở một transcript, nhưng ở đây chưa ai biết vì sao công cụ bỏ sót; ghi log rồi baseline ngay khiến các thiếu sót khác có thể lọt vào baseline.","Sai: đúng nếu không còn thời gian đối chiếu thủ công, nhưng ở đây còn năm ngày và công cụ chưa được giải thích lỗi; chạy lại cùng công cụ không phải kiểm chứng độc lập với nguồn.","Sai: đúng nếu việc kiểm tra sẽ vượt quá ngày baseline và PM không đủ quyền, nhưng ở đây còn đủ thời gian để PM tự kiểm tra; hỏi sponsor chỉ dời quyết định mà không thêm căn cứ."],exp:'Task P5, enabler "identify stakeholder expectations", với AI làm bối cảnh: một lỗi đã lộ ra mà chưa rõ nguyên nhân thì PM phải kiểm chứng phần còn lại với nguồn gốc trước khi baseline. PM chịu trách nhiệm về đầu ra của công cụ AI; ghi nhận sai sót và leo thang chỉ cần khi kiểm chứng cho thấy không đủ thời gian.'},{id:"o282",n:282,t:0,origin:"original",eco:"P5",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","acceptance-criteria","vendor-expectations"],type:"mc",q:"A hybrid project to deliver a logistics platform has a signed contract with a vendor, which allows acceptance terms to be refined by a note signed by both parties. The vendor believed a feature was accepted once it reached the test environment; the client's product owner expected acceptance only after user testing across three sprints. In a joint session they signed a note defining acceptance as passing three sprints of user testing. The first release has now passed all three sprints with no open defects, but the vendor's test report predates the note and never mentions the three-sprint rule. The first-release invoice is pending. What should the project manager do?",opts:["Convene the vendor and the product owner to redefine the acceptance evidence, then approve the invoice","Verify the sprint test report against the signed acceptance note, then approve the first-release invoice","Hold the invoice until legal confirms the signed note matches the contract wording, then approve it","Approve the invoice but retain part of it on release 2, then release the retention at the end of the defects period"],ans:[1],why:["Sai: đúng nếu vendor và product owner còn hiểu khác nhau về bằng chứng nghiệm thu, nhưng ở đây họ đã ký biên bản và không có tranh chấp; họp lại không thêm thông tin nào.","Đúng: biên bản đã ký và ba sprint đã đạt, nhưng báo cáo kiểm thử viết trước biên bản và không nhắc quy tắc ba sprint; PM đối chiếu báo cáo với biên bản đã ký rồi mới duyệt hóa đơn, để thanh toán dựa trên bằng chứng.","Sai: đúng nếu biên bản có vẻ mâu thuẫn với hợp đồng, nhưng ở đây hợp đồng cho phép tinh chỉnh điều kiện nghiệm thu bằng biên bản ký chung; giữ tiền chờ pháp lý làm hỏng quan hệ mà không có lý do cụ thể.","Sai: đúng nếu hợp đồng có điều khoản giữ lại một phần tiền, nhưng ở đây không có và không còn lỗi mở; thêm điều kiện mới sau khi hai bên đã thống nhất là phá niềm tin."],exp:'Task P5, enabler "facilitate discussions to align expectations", với vendor là stakeholder bên ngoài: sau khi buổi làm việc chung đã tạo ra tiêu chí nghiệm thu được ký, PM hành động theo thỏa thuận, nhưng trước khi thanh toán phải đối chiếu bằng chứng với đúng tiêu chí đã ký. Họp lại hay thêm điều kiện mới làm hỏng niềm tin vừa xây.'},{id:"o283",n:283,t:0,origin:"original",eco:"P5",domain:"people",approach:"predictive",tags:["predictive","eco-2026","facilitation","preparation","one-on-one"],type:"mc",q:"A manufacturing company is retrofitting a production line under a predictive plan. Plant operations, quality, and finance each hold different views on when the line may be shut down for installation, and none of them has yet explained why their dates matter. The sponsor has not been involved. The project manager has scheduled an alignment workshop next week with all three. What should the PM do before the workshop?",opts:["Draft a shutdown schedule with the plant scheduler, then use the workshop to collect objections to it","Escalate the three positions to the sponsor, then ask the sponsor to open the workshop with guidance on the dates","Speak to each of the three one-on-one, then build the workshop agenda around their real constraints and reasons","Prepare a risk analysis of each shutdown window with the plant scheduler, then present it at the workshop to frame the options"],ans:[2],why:["Sai: đúng nếu mỗi bên đã nêu ràng buộc của mình, nhưng ở đây chưa ai nói lý do cho ngày của mình; lịch dựng khi chưa biết ràng buộc dễ bị bác và biến buổi họp thành tranh cãi.","Sai: đúng nếu ba bên đã bế tắc và cần quyền lực của sponsor, nhưng ở đây sponsor chưa tham gia và workshop mới là nơi các bên tự căn chỉnh; để sponsor mở đầu bằng định hướng làm họ ít dám nói ràng buộc thật.","Đúng: chưa bên nào nói lý do cho ngày của mình, nên PM gặp riêng từng người trước rồi dựng chương trình workshop từ ràng buộc thật thay vì từ lập trường.","Sai: đúng nếu các ràng buộc đã rõ và chỉ cần so sánh phương án, nhưng ở đây PM chưa biết ràng buộc nên các khung thời gian đưa ra có thể bỏ sót điều quan trọng với một bên."],exp:'Task P5 gồm cả "identify stakeholder expectations" và "facilitate discussions": thứ tự đúng là hiểu từng bên rồi mới họp chung. Bẫy là nhảy vào workshop hoặc chuẩn bị sẵn một đáp án trước khi nghe.'},{id:"o284",n:284,t:0,origin:"original",eco:"P5",domain:"people",approach:"agile",tags:["agile","eco-2026","early-expectations","non-functional"],type:"mc",q:"An agile team is about to start sprint 1 of a global booking product after a vision workshop. Two regional sales directors did not attend, and both are available this week. A colleague mentions, as a guess, that they probably expect the product to support multiple languages and currencies from day one. If that is true, it would change the architecture chosen in the first sprints, and nothing about it is in the backlog. What should the project manager do?",opts:["Ask the directors' line manager for their expectations in writing, then pass the written answer to the product owner","Add placeholder stories for multiple languages and currencies, then ask the product owner to size them","Interview the two directors to confirm the multilingual expectation, then brief the product owner","Raise the matter at sprint 1 planning, then let the team decide the architecture for multiple languages"],ans:[2],why:["Sai: đúng nếu hai giám đốc không liên lạc được trong thời gian ngắn, nhưng ở đây cả hai có mặt trong tuần này; hỏi qua quản lý của họ thì thông tin có thể sai lệch và họ chưa được lắng nghe.","Sai: đúng nếu kỳ vọng đã được xác nhận và chỉ cần ước lượng, nhưng ở đây mới là lời đoán của đồng nghiệp; ước lượng trên giả định chưa xác nhận có thể làm lệch thứ tự backlog.","Đúng: kỳ vọng mới là lời đoán nhưng có thể đổi kiến trúc những sprint đầu và hai giám đốc đang có mặt, nên PM xác nhận trực tiếp với họ rồi mang điều đã xác nhận tới product owner, người sắp xếp backlog.","Sai: đúng nếu yêu cầu đã rõ và việc cần bàn chỉ còn là thiết kế kỹ thuật, nhưng ở đây chưa ai xác nhận kỳ vọng thật; đội không có căn cứ để quyết định kiến trúc."],exp:'Task P5, enabler "identify stakeholder expectations", trong agile: một kỳ vọng nghe qua người khác chưa phải dữ kiện. Khi nó có thể tác động quyết định sớm và người liên quan có mặt, PM xác nhận trực tiếp rồi chuyển qua product owner, người vẫn là chủ của backlog. Chờ phản hồi ở sprint review không phải lúc nào cũng đủ sớm.'},{id:"o285",n:285,t:0,origin:"original",eco:"P6",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","changed-expectations","change-control"],type:"mc",q:"A retailer's reporting platform is delivered under a hybrid contract: the core data layer has a fixed scope under change control, and dashboards are built in sprints. After the retailer merged with a competitor, its analytics lead said the dashboards must combine two product catalogs. The PM has met the lead; the team estimates that merging the catalogs needs a new key in the data layer, three weeks and 60,000 USD, outside the fixed scope. What should the PM do?",opts:["Raise a data-layer change request, adding the dashboard stories to the backlog with the product owner","Meet the analytics lead once more to confirm the merged-catalog requirement before preparing any paperwork","Add the data-layer work to the next sprint as a backlog item and show it to the customer at the sprint demo","Have the customer's sponsor approve the extra work by email so that the team can start this sprint"],ans:[0],why:["Đúng: phần data layer có phạm vi cố định, ước tính đã có (ba tuần, 60.000 USD) nên PM nộp change request, còn phần dashboard làm lặp thì đưa vào backlog cùng product owner.","Sai: xác nhận lại yêu cầu là đúng khi còn mơ hồ, nhưng ở đây PM đã gặp analytics lead và đội đã ước tính tác động; họp lại không thêm thông tin và kéo dài thời gian có chi phí.","Sai: đưa việc vào backlog đúng cho dashboard làm theo sprint, nhưng data layer có phạm vi cố định dưới change control; làm trong sprint rồi báo cáo sau bỏ qua duyệt thay đổi và chi phí phát sinh.","Sai: sponsor của khách có thể duyệt, nhưng ở đây hợp đồng yêu cầu thay đổi phạm vi phải đi qua change control; email duyệt không chính thức không ghi nhận tác động và dễ gây tranh chấp thanh toán."],exp:'Task P6, enabler "align and maintain outcomes to customer expectations", trong hợp đồng hybrid: tác động đã rõ, PM áp dụng đúng kênh theo từng phần, change request cho phần có baseline và backlog cho phần lặp. Làm trước rồi hợp thức hóa sau hay duyệt qua email đều bỏ qua change control.'},{id:"o286",n:286,t:0,origin:"original",eco:"P6",domain:"people",approach:"predictive",tags:["predictive","eco-2026","satisfaction-survey","internal-customer"],type:"mc",q:`An internal IT team is migrating the finance department's reporting system under a predictive plan. Schedule and cost indices are on target. The quarterly satisfaction survey of the finance department falls from 4.4 to 3.1; the comments, written by finance analysts who use the reports daily, say they keep "learning of delays after the fact". Finance leadership has not asked for any new meeting. What should the project manager do?`,opts:["Add a schedule-variance note to each monthly status report, then compare the survey score next quarter","Consult the finance analysts about which delay news they expect, how early, then change delay reporting","Request the survey vendor's response data by department, then compare it with the previous survey's questions","Set up a monthly steering call with finance leadership, then make delay forecasts a standing agenda item"],ans:[1],why:["Sai: đúng nếu bình luận phàn nàn báo cáo thiếu thông tin tiến độ, nhưng ở đây họ phàn nàn biết tin chậm sau khi sự việc xảy ra; thêm một dòng vào báo cáo tháng không đổi cách và thời điểm thông báo.","Đúng: chỉ số tiến độ tốt nhưng điểm hài lòng giảm vì nhóm phân tích tài chính biết tin chậm sau khi sự việc xảy ra, nên PM nói chuyện với họ về điều họ muốn nghe và khi nào rồi đổi cách báo cáo chậm trễ.","Sai: đúng nếu bình luận không nêu được nguyên nhân giảm điểm, nhưng ở đây bình luận đã nêu rõ việc biết tin chậm; phân tích dữ liệu khảo sát theo phòng ban không thay đổi trải nghiệm của khách nội bộ.","Sai: đúng nếu lãnh đạo tài chính đã nói họ cần kênh này, nhưng ở đây người bình luận là nhân viên dùng báo cáo hằng ngày và lãnh đạo chưa yêu cầu gì; đặt kênh trước khi hỏi có thể sai đối tượng."],exp:'Task P6, enabler "monitor satisfaction/expectations and respond as needed": hài lòng là cảm nhận của khách, không suy ra từ chỉ số dự án. PM tìm hiểu kỳ vọng thật của người đã phàn nàn (ở đây là được báo sớm về chậm trễ) rồi thay đổi cách tương tác, thay vì thêm kênh hay số liệu theo phỏng đoán.'},{id:"o287",n:287,t:0,origin:"original",eco:"P6",domain:"people",approach:"agile",tags:["agile","eco-2026","internal-customer","adoption"],type:"mc",q:'An agile team builds an internal tool for the operations department. Demos run at the end of each sprint, but the operations representatives rarely attend, and usage statistics show that the delivered features are barely used. The product owner says the demos are "fine" and the backlog is on track. Operations staff have not been asked about their daily routine since the kickoff. What should the project manager do?',opts:["Analyze the usage statistics with the product owner to see which delivered features are used, then adjust the backlog","Move the demo to the operations team's own site and time, then ask their supervisor to nominate attendees","Shadow operations staff during a shift with their supervisor's agreement, then ask what they expect from the tool in their routine","Ask the product owner to build an in-app feedback form, then review the ratings at each sprint review"],ans:[2],why:["Sai: phân tích số liệu sử dụng cùng product owner là đúng nếu chưa biết tính năng nào bị bỏ, nhưng số liệu đã cho thấy tính năng ít được dùng; phân tích thêm không cho biết vì sao bộ phận vận hành không dùng và họ cần gì.","Sai: đúng nếu vấn đề chỉ là người vận hành vắng mặt, nhưng ở đây tính năng giao ra cũng ít được dùng; dời giờ họp và nhờ cấp trên cử người vẫn không cho PM biết kỳ vọng thật trong công việc hằng ngày.","Đúng: khách nội bộ vắng demo, ít dùng tính năng và chưa được hỏi về công việc hằng ngày từ lúc khởi động, nên PM quan sát họ làm việc rồi hỏi kỳ vọng thay vì suy đoán qua phản hồi gián tiếp.","Sai: đúng nếu người dùng đã dùng nhiều nhưng ít lên tiếng, nhưng ở đây họ gần như không mở tính năng nên form trong ứng dụng sẽ ít phản hồi; quan sát tại chỗ nhanh và sâu hơn."],exp:'Task P6, enabler "identify internal and external customer expectations": khách nội bộ cũng là khách hàng. Khi họ không tham gia và không dùng sản phẩm, PM đến gần để tìm hiểu kỳ vọng thật thay vì thêm số liệu, dời họp hay chờ phản hồi gián tiếp.'},{id:"o288",n:288,t:0,origin:"original",eco:"P6",domain:"people",approach:"predictive",tags:["predictive","eco-2026","acceptance-criteria","transparency"],type:"mc",q:"A predictive project is delivering a booking portal to an external airline customer. The signed acceptance criterion requires page responses under two seconds, and the contract says any change to a criterion needs the customer's signature. Pre-acceptance testing shows 2.4 seconds under peak load. The team has confirmed the cause (a missing database index), costed a two-week fix within the existing budget, and prepared the test report. The customer has not been told. Acceptance is three weeks away. What should the project manager do next?",opts:["Run load tests on a staging copy of the portal, then tell the customer once the cause is confirmed","Raise a change request to relax the criterion to three seconds, then send it to the customer for signature","Go live on the current date, then complete the tuning in the warranty period and note the gap in handover","Present the test report with the two-week fix plan to the customer, then ask for a decision on the acceptance date"],ans:[3],why:["Sai: đúng nếu nguyên nhân còn chưa chắc, nhưng ở đây đội đã xác nhận nguyên nhân (thiếu index) và có báo cáo kiểm thử; thử thêm trước khi báo khách chỉ làm mất vài tuần quý giá.","Sai: đúng nếu không thể đạt tiêu chí trong ngân sách, nhưng ở đây sửa được trong hai tuần trong ngân sách; hạ chuẩn khi chưa thử sửa là tự làm yếu cam kết đã ký.","Sai: đúng nếu khách đã đồng ý chấp nhận lệch tiêu chí, nhưng ở đây tiêu chí đã ký chưa đạt, khách chưa được báo và còn ba tuần; đưa lên sản xuất rồi mới chỉnh là bỏ qua điều kiện nghiệm thu.","Đúng: nguyên nhân đã rõ, kế hoạch sửa hai tuần trong ngân sách đã có và khách chưa được báo, nên PM trình báo cáo kiểm thử cùng kế hoạch sửa cho khách và xin quyết định về ngày nghiệm thu; khách cùng quyết định thì giữ được niềm tin."],exp:'Task P6, enabler "align and maintain outcomes to customer expectations": khi kết quả lệch tiêu chí đã ký và PM đã có nguyên nhân cùng phương án, bước đúng là chủ động báo khách với kế hoạch và xin quyết định. Che giấu, hạ chuẩn hay kiểm thử lại không cần thiết đều làm mất niềm tin hoặc thời gian.'},{id:"o289",n:289,t:0,origin:"original",eco:"P6",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","ai","satisfaction-monitoring","sentiment-dashboard"],type:"mc",q:'A hybrid program installs hardware on a phased plan and builds companion software in sprints. A sentiment dashboard, generated by an AI tool from customer emails and tickets, shows "positive" for the customer base this month. The account manager reports, informally, that three large customers are complaining about delayed installations. The PM has not yet seen any of the original messages or spoken to those customers. What should the project manager do?',opts:["Ask the AI vendor to explain how the score is calculated, then decide whether the dashboard can be trusted for reporting","Log the three complaints in the issue log with the account manager, then get revised installation dates from the installers","Verify the score against the source messages with the account manager, then speak with the three customers about their delays","Adjust the tool's settings with the data team, then retrain it on the recent complaint emails and the tickets"],ans:[2],why:["Sai: đúng nếu không có khách nào phàn nàn thật, nhưng ở đây ba khách lớn đang phàn nàn; hỏi nhà cung cấp trước khiến vấn đề của họ chưa được xử lý.","Sai: đúng nếu PM đã nghe khách và biết họ lo gì, nhưng ở đây PM chưa xem tin nhắn gốc hay nói chuyện với ai; ghi log và xin ngày mới chưa chắc giải quyết điều họ quan tâm.","Đúng: điểm tích cực của AI mâu thuẫn với báo cáo của account manager và PM chưa xem tin nhắn gốc, nên PM đối chiếu điểm với tin nhắn gốc rồi nói chuyện trực tiếp với ba khách; PM vẫn chịu trách nhiệm phản hồi khách.","Sai: đúng nếu việc đối chiếu cho thấy công cụ phân loại sai hàng loạt, nhưng ở đây PM chưa kiểm chứng gì; chỉnh công cụ không giải quyết điều ba khách đang phàn nàn."],exp:'Task P6, enabler "monitor customer satisfaction/expectations and respond", với AI làm bối cảnh: đầu ra AI chỉ là dữ liệu đầu vào, PM kiểm chứng bằng dữ liệu gốc và tiếp xúc trực tiếp khách trước khi hành động. Người chịu trách nhiệm phản hồi vẫn là PM.'},{id:"o290",n:290,t:0,origin:"original",eco:"P6",domain:"people",approach:"agile",tags:["agile","eco-2026","hidden-expectation","field-conditions"],type:"mc",q:'A team is building a records app for a rural clinic network, an external customer. Every sprint review is approved and acceptance criteria are met. During a site visit, two nurses tell the PM that "it just dies when the signal drops". Offline use has never appeared in the backlog, and the PM does not yet know which tasks are affected. What should the project manager do?',opts:["Ask clinic staff which tasks they do offline, then add offline criteria via the product owner","Ask the team to prototype offline record sync in the next sprint, then test it with the clinic staff","Add an offline requirement to the definition of done, then confirm the idea with the product owner","Check the app's usage and error logs for connection failures, then decide whether offline use is a real need"],ans:[0],why:["Đúng: nhu cầu offline lộ ra từ thực địa nhưng chưa rõ nhiệm vụ nào bị ảnh hưởng và chưa từng vào backlog, nên PM làm rõ cách nhân viên làm việc rồi đưa tiêu chí offline vào backlog qua product owner.","Sai: đúng nếu nhu cầu offline đã cụ thể, nhưng ở đây chưa biết nhiệm vụ nào cần offline; đội xây nguyên mẫu trước khi hiểu có thể làm sai trọng tâm trong một sprint.","Sai: đúng nếu mọi tính năng đều phải chạy offline, nhưng ở đây chưa biết phạm vi; definition of done áp dụng cho mọi story nên đưa vào đó khi chưa hiểu mức cần là quá rộng.","Sai: đúng nếu PM mới nghe đồn và cần bằng chứng, nhưng ở đây hai y tá đã nói thẳng; nhật ký lỗi cho biết dấu hiệu kỹ thuật, không cho biết nhân viên cần làm gì khi mất kết nối."],exp:'Task P6, enabler "identify internal and external customer expectations": sự chấp nhận ở sprint review không bảo đảm khớp với điều kiện sử dụng thật. PM tìm kỳ vọng tiềm ẩn từ môi trường khách hàng rồi đưa vào backlog qua product owner, thay vì xây trước hay sửa definition of done khi chưa hiểu phạm vi.'},{id:"o291",n:291,t:0,origin:"original",eco:"P6",domain:"people",approach:"predictive",tags:["predictive","eco-2026","customer-turnover","scope-clarity"],type:"mc",q:"Midway through a predictive construction contract, the customer replaced its project representative. The new representative says her predecessor promised weekly on-site walk-throughs. The contract and plan include only monthly inspections. The PM has met her: she needs weekly visits to catch problems in concrete pours early, and she rejected photo reports and remote monitoring as substitutes. The PM estimates the weekly visits at four extra staff-days a month, outside the baseline. What should the project manager do?",opts:["Meet the representative again to understand why she wants weekly visits instead of monthly inspections","Ask the sponsor to settle the matter directly with the customer's senior executives this week","Propose supplementing the monthly inspections with photo reports of each pour, within the current budget","Raise a change request for weekly walk-throughs with cost and schedule effect for customer approval"],ans:[3],why:["Sai: tìm hiểu lý do là bước đúng khi chưa rõ, nhưng ở đây PM đã gặp bà và biết bà cần phát hiện sớm lỗi đổ bê tông; họp lại chỉ lặp lại thông tin đã có.","Sai: sponsor có thể làm việc với lãnh đạo khách khi bế tắc, nhưng ở đây vấn đề có thể xử lý ở cấp dự án bằng change request; đẩy lên cấp cao biến một yêu cầu thay đổi thành tranh chấp.","Sai: phương án trong ngân sách nên thử trước, nhưng ở đây bà đã từ chối ảnh chụp và giám sát từ xa; đề xuất lại làm bà thấy mình không được lắng nghe.","Đúng: nhu cầu đã rõ, các phương án trong baseline đã bị từ chối và chi phí vượt baseline, nên PM nộp change request kèm tác động để khách quyết định có trả thêm không."],exp:'Task P6, enabler "identify and maintain customer expectations": khi người đại diện đổi, PM tìm hiểu nhu cầu thật và thử phương án trong baseline trước. Khi các phương án đó đã bị từ chối và nhu cầu vượt baseline, change request là đường đi đúng để khách quyết định; không nhận ngầm và không từ chối cứng.'},{id:"o292",n:292,t:0,origin:"original",eco:"P6",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","customer-deadline","sequencing"],type:"mc",q:"A SaaS provider is onboarding a large enterprise customer with a hybrid plan: infrastructure steps are sequenced and fixed, while configuration is delivered in sprints. The customer said data migration must finish before its quarter-end, but the plan schedules migration in sprint 9, two weeks after that date. The PM has asked why: quarter-end is the audit cut-off. The team found migration can move to sprint 7 by swapping it with two configuration sprints, at no extra cost. What should the project manager do?",opts:["Ask the customer for the audit rules to find out whether a partial migration would meet the quarter-end","Re-sequence the migration into sprint 7 through change control, then update the baseline and customer","Add engineers to the migration work to bring it forward, while keeping the same sequence of steps","Keep migration in sprint 9 and offer the customer extra audit support for the two weeks after quarter-end"],ans:[1],why:["Sai: hỏi thêm về quy định audit đúng khi chưa biết phải đạt gì, nhưng ở đây PM đã biết quarter-end là hạn cắt audit và đội đã có phương án đổi thứ tự; hỏi tiếp không thêm giá trị.","Đúng: lý do của khách đã rõ và đội tìm ra cách chuyển migration lên sprint 7 mà không tốn thêm, nên PM đổi thứ tự qua change control, cập nhật baseline và báo khách.","Sai: thêm kỹ sư là cách rút ngắn thông thường, nhưng ở đây bước hạ tầng có thứ tự cố định nên thêm người không đưa việc lên sớm hơn; phương án đổi thứ tự không tốn thêm đã có.","Sai: hỗ trợ audit thêm có giá trị với khách, nhưng ở đây hạn quarter-end là cắt audit nên migration sau hạn vẫn không thỏa; trong khi có cách đạt hạn mà không tốn chi phí."],exp:'Task P6, enabler "align and maintain outcomes to customer expectations": khi PM đã hiểu lý do của hạn và đội tìm được phương án trong kế hoạch, bước đúng là thực hiện thay đổi có kiểm soát (đổi thứ tự, cập nhật baseline). Hỏi thêm hay tăng người không giải quyết đúng ràng buộc.'},{id:"o293",n:293,t:0,origin:"original",eco:"P6",domain:"people",approach:"predictive",tags:["predictive","eco-2026","engagement-pattern","survey"],type:"mc",q:`A predictive software-integration project has met every milestone acceptance criterion. After milestone 4, the customer's short survey shows a lower satisfaction score. The open comment reads: "we only hear from you when there is a problem; a short monthly note saying what is on track would help". Milestone 5 is six weeks away. What is the most appropriate response from the project manager?`,opts:["Add a monthly status call with the customer's sponsor to the plan, then use it to present milestone results","Record the comment in the lessons-learned register, then review it with the team in the closing phase","Meet the customer's team to explore which updates they find useful, then redesign the whole engagement","Add a monthly on-track note to the communications plan, then ask the customer's team to confirm its format"],ans:[3],why:["Sai: đúng nếu sponsor của khách đã yêu cầu họp định kỳ, nhưng ở đây khách xin một ghi chú ngắn hằng tháng chứ không phải cuộc họp; thêm cuộc gọi với sponsor không phải thứ họ nói họ cần.","Sai: đúng nếu dự án sắp đóng và không còn cơ hội điều chỉnh, nhưng ở đây còn sáu tuần tới mốc 5; để bài học đến giai đoạn đóng thì không sửa được trải nghiệm hiện tại.","Sai: đúng nếu bình luận mơ hồ về điều khách muốn, nhưng ở đây khách đã nêu cụ thể một ghi chú ngắn hằng tháng; họp để tìm hiểu lại điều đã được nói rõ là tốn thời gian của cả hai bên.","Đúng: khách đã nói rõ họ muốn gì và khi nào, nên PM cập nhật communications management plan thêm ghi chú hằng tháng rồi xác nhận định dạng với đội của khách trước mốc 5."],exp:'Task P6, enabler "monitor satisfaction and respond as needed": đạt tiêu chí nghiệm thu chưa phải đủ, tương tác cũng là một phần trải nghiệm. Khi khách đã nêu rõ điều họ muốn, PM đưa nó vào kế hoạch truyền thông và xác nhận lại với khách, thay vì mở thêm cuộc họp tìm hiểu hay chờ đến lúc đóng dự án.'},{id:"o294",n:294,t:0,origin:"original",eco:"P6",domain:"people",approach:"agile",tags:["agile","eco-2026","acceptance-criteria","shared-understanding"],type:"mc",q:`In a sprint review, finance says, for the third time, that a report story marked "automated" is not what they expected. The story's goal reads "scheduled report arrives in the inbox with no manual action", but its acceptance criteria only say "export button available". The PM and finance have since met and agreed that finance wants zero manual steps from the scheduled run to the inbox; the team delivered a one-click export that meets the written criteria. The story description already states the goal correctly. What should the project manager do next?`,opts:["Hold a clarification session with finance on the meaning of automated, then update the story description","Rewrite the acceptance criteria as examples alongside finance, then ask the product owner to reorder the backlog","Run a story-mapping workshop with all finance users, then rebuild the report backlog from the map","Accept the story as done, then add finance's zero-manual-steps request as a new item behind the current backlog"],ans:[1],why:["Sai: họp làm rõ với finance rồi sửa mô tả story là đúng nếu kỳ vọng còn mơ hồ hoặc mô tả sai, nhưng ở đây PM và finance đã thống nhất điều cần và mô tả story đã đúng; lỗi nằm ở tiêu chí chấp nhận, nên họp thêm lặp lại điều đã biết trong khi story vẫn chưa đạt.","Đúng: kỳ vọng của finance đã rõ và tiêu chí chỉ ghi nút xuất file chứ không ghi tự động hoàn toàn, nên PM cùng finance viết lại tiêu chí thành ví dụ cụ thể rồi nhờ product owner đưa story lên đầu backlog; sửa tiêu chí xử lý đúng nguyên nhân lặp lại ba lần.","Sai: đúng nếu nhiều story của finance cùng mơ hồ, nhưng ở đây chỉ một story sai lệch và kỳ vọng đã rõ; dựng lại cả backlog bằng workshop là quá rộng cho một tiêu chí viết sai.","Sai: đúng nếu tiêu chí phản ánh đúng ý định của story và finance chỉ đổi ý, nhưng ở đây mục tiêu story ghi tự động còn tiêu chí viết sai; coi là xong rồi xếp yêu cầu mới ở cuối làm khách thất vọng thêm."],exp:'Task P6, enabler "align and maintain outcomes to customer expectations": khi kỳ vọng đã được làm rõ và tiêu chí viết chưa phản ánh đúng mục tiêu story, hành động tiếp theo là sửa tiêu chí thành ví dụ cụ thể rồi nhờ product owner xếp lại ưu tiên. Làm rõ thêm hay coi là hoàn thành vì đạt tiêu chí chữ viết đều bỏ lỡ nguyên nhân gốc.'},{id:"o295",n:295,t:0,origin:"original",eco:"P6",domain:"people",approach:"predictive",tags:["predictive","eco-2026","adoption","project-closure"],type:"mc",q:"A predictive warehouse-system project is two weeks from formal closure. All deliverables passed acceptance and the closure paperwork is ready. The customer's operations manager mentions that dispatchers avoid the new scanning feature and still work around it manually. Nobody has asked the dispatchers why, and the project team is still on the project for these two weeks. What should the project manager do?",opts:["Escalate to the sponsor for post-closure training funding, then close the project on schedule","Raise a change request to redesign the scanning feature, then base the redesign on how dispatchers prefer to work","Meet the operations manager to hand over the adoption issue from the lessons-learned register at closure","Meet the operations manager with the dispatchers to learn what blocks use, then decide whether closure should proceed"],ans:[3],why:["Sai: đúng nếu đã biết rào cản là kỹ năng, nhưng ở đây chưa ai nghe dispatcher nên chưa biết nguyên nhân là đào tạo, thiết kế hay quy trình; xin tiền đào tạo là kết luận sớm.","Sai: đúng nếu đã biết vấn đề nằm ở thiết kế, nhưng ở đây chưa ai hỏi dispatcher; nộp change request thiết kế lại trước khi tìm hiểu là chạy trước phân tích.","Sai: đúng nếu dự án hết nguồn lực để xử lý, nhưng ở đây còn hai tuần và đội vẫn còn; chỉ ghi bài học rồi chuyển cho quản lý vận hành thì kết quả mong muốn của khách vẫn không đạt.","Đúng: bàn giao đạt nghiệm thu nhưng dispatcher tránh dùng tính năng và chưa ai hỏi vì sao, nên PM gặp quản lý vận hành cùng dispatcher để biết điều gì cản trở rồi mới quyết định có đóng dự án đúng hạn hay không."],exp:'Task P6, enabler "monitor customer satisfaction/expectations and respond as needed": nghiệm thu đạt chưa chắc khách đạt mục tiêu. Khi nguyên nhân chưa rõ và còn thời gian, PM kiểm tra việc áp dụng thực tế và nghe người dùng trước khi đóng, thay vì chọn giải pháp (đào tạo, thiết kế lại) trước khi hiểu vấn đề.'},{id:"o296",n:296,t:0,origin:"original",eco:"P7",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","gather-knowledge","vendor-handover"],type:"mc",q:"Phase 1 of a hybrid ERP program, delivered by a vendor under a fixed-price contract, ends next week, and the vendor's configuration team then moves to other clients. Phase 2 will be built by an internal team in sprints. The vendor's documentation lists the settings but not why the design choices were made. The contract has no clause requiring knowledge transfer beyond documentation, and only the sponsor and procurement can authorize changes to it. A week of capture sessions would be enough. What should the project manager do?",opts:["Escalate to the sponsor and procurement, then request a contract amendment for capture sessions","Extend the vendor contract by three months, then keep the team on call as a permanent reference","Request the vendor's handover package and the team's contact list, then send questions as they arise","Ask the vendor to add a glossary of the settings and their defaults, then have the phase 2 team review it"],ans:[0],why:["Đúng: đội cấu hình sắp rời, hợp đồng giá cố định không bắt buộc chuyển giao lý do thiết kế và chỉ sponsor cùng procurement được sửa hợp đồng, nên PM leo thang để xin bổ sung các buổi thu thập lý do thiết kế trước khi đội rời đi.","Sai: đúng nếu cần hỗ trợ lâu dài, nhưng ở đây chỉ cần khoảng một tuần thu thập lý do thiết kế; gia hạn ba tháng giữ đội làm tham chiếu thường trực là chi phí không tương xứng.","Sai: đúng nếu đội vẫn liên lạc được sau bàn giao, nhưng ở đây họ chuyển sang khách hàng khác; câu hỏi gửi sau khi họ rời dễ không còn người nhớ lý do.","Sai: đúng nếu thiếu sót chỉ là định nghĩa của cài đặt, nhưng ở đây thiếu lý do chọn thiết kế; chú giải cài đặt và giá trị mặc định vẫn không trả lời vì sao."],exp:'Task P7, enabler "gather knowledge": thu thập tri thức khi nguồn còn sẵn, tập trung vào quyết định và lý do chứ không chỉ cấu hình. Khi việc đó vượt phạm vi hợp đồng và thẩm quyền của PM, PM leo thang cho người có quyền sửa hợp đồng trước khi đội rời đi.'},{id:"o297",n:297,t:0,origin:"original",eco:"P7",domain:"people",approach:"agile",tags:["agile","eco-2026","knowledge-sharing","psychological-safety"],type:"mc",q:"In retrospectives, a Scrum team of eight reveals that only two developers dare to modify the payment module, because a production incident last quarter led to public blame in a management meeting. A blameless review of that incident was held last month and its lessons were published. Other members still avoid the module, and a story touching it has slipped twice. Two members said they would try it if an expert worked beside them. What should the project manager do?",opts:["Ask the two experts to document the module in the wiki, then have the team read it before the next sprint","Pair each expert with a learner on payment stories, then revisit how safe it feels at each retrospective","Hold a blameless review of last quarter's incident with the team, then publish the lessons learned","Schedule a training session led by the experts, then have the others take payment stories from the next sprint"],ans:[1],why:["Sai: đúng nếu vấn đề là thiếu tài liệu, nhưng ở đây hai thành viên nói họ sẵn lòng thử nếu có chuyên gia ngồi cạnh; đọc wiki xong vẫn không ai dám sửa module.","Đúng: sự cố đã được xem xét không đổ lỗi nhưng nỗi sợ vẫn còn và hai thành viên sẵn lòng thử nếu có chuyên gia bên cạnh, nên PM sắp xếp ghép cặp trên story thật rồi theo dõi cảm giác an toàn ở mỗi retrospective.","Sai: đúng nếu chưa từng có buổi rà soát không đổ lỗi, nhưng ở đây buổi đó đã được tổ chức và bài học đã công bố; làm tiếp không thay đổi hành vi vì cần trải nghiệm an toàn khi làm việc với module.","Sai: đúng nếu đội thiếu kiến thức, nhưng ở đây vấn đề là tâm lý sợ bị đổ lỗi; yêu cầu nhận story ngay sau buổi đào tạo dễ lặp lại nỗi sợ."],exp:'Task P7, enabler "foster an environment for knowledge transfer": sau khi lỗi đã được xem xét không đổ lỗi, tri thức chỉ lan khi người ta thử làm cùng nhau trong môi trường an toàn. PM tạo điều kiện (ghép cặp, theo dõi sự an toàn) chứ không chỉ làm tài liệu hay đào tạo một lần.'},{id:"o298",n:298,t:0,origin:"original",eco:"P7",domain:"people",approach:"predictive",tags:["predictive","eco-2026","ai","verification","knowledge-capture"],type:"mc",q:"A predictive pipeline-construction project is recording interviews with a retiring welding inspector. An AI tool has already turned 30 recordings into procedure summaries, none yet published to the knowledge base. A reviewer checked three of them and found one with a preheat tolerance different from what the inspector said in the recording. What should the project manager do?",opts:["Ask the successor engineer to correct the tolerance value against the project specification","Publish the summaries with a banner stating that they are AI-generated and may contain errors","Hold publication of the summaries until the inspector can check each one against its recording","Re-run the AI tool with a stricter prompt on the recording with the wrong tolerance and compare results"],ans:[2],why:["Sai: kỹ sư kế nhiệm đối chiếu với specification là bước kiểm tra hữu ích, nhưng ở đây tri thức cần giữ là điều người thợ thực hiện thật, vốn có thể khác specification; chỉ người kiểm tra tại nguồn mới xác nhận được.","Sai: ghi chú nguồn AI là minh bạch, nhưng ở đây là thông số hàn liên quan an toàn và đã có một bản sai; cảnh báo chung không ngăn người dùng làm theo giá trị sai.","Đúng: một bản đã sai trong ba bản được kiểm tra và đây là tri thức an toàn, nên PM dừng việc công bố cho đến khi người thợ kiểm tra từng bản so với bản ghi âm gốc.","Sai: chạy lại AI với lời nhắc chặt hơn có thể giảm lỗi, nhưng ở đây chỉ sửa một bản; 29 bản kia vẫn chưa được kiểm chứng và AI vẫn có thể sai ở chỗ khác."],exp:'Task P7, enabler "gather knowledge", với AI làm bối cảnh: một lỗi trong mẫu kiểm tra cho thấy đầu ra chưa đáng tin, nên PM dừng bước rủi ro là công bố và đặt bước kiểm chứng bởi người có chuyên môn. AI tăng tốc ghi lại nhưng trách nhiệm kiểm chứng vẫn thuộc PM.'},{id:"o299",n:299,t:0,origin:"original",eco:"P7",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","lessons-learned","repository"],type:"mc",q:"An 18-month hybrid program collects lessons learned only at closure. Midway, two teams independently repeat the same vendor-onboarding mistake because the first team's experience was never shared, and the PMO has since found two other repeated mistakes, in test-data requests and access forms. The PMO asks how to prevent further repeats across the program. What should the project manager propose?",opts:["Hold the closing lessons-learned workshop earlier, in month twelve, then share the results with the teams","Ask the PMO to review each team's vendor onboarding, then report repeated mistakes to the sponsor","Create a vendor-onboarding checklist from the first team's experience, then require the other teams to use it","Capture lessons at each phase end plus each sprint review, then store them where all teams can search them"],ans:[3],why:["Sai: đúng nếu chỉ cần chia sẻ muộn hơn một lần, nhưng ở đây lỗi lặp ở nhiều mảng và xảy ra liên tục; một buổi duy nhất ở tháng mười hai vẫn để các đội lặp lỗi giữa các lần họp.","Sai: đúng nếu lỗi lặp do đội không tuân thủ quy trình, nhưng ở đây vấn đề là bài học chưa được chia sẻ; PMO phát hiện lỗi lặp sau khi xảy ra chưa ngăn được lần sau.","Sai: đúng nếu chỉ có đúng một bài học cần chia sẻ, nhưng ở đây PMO đã thấy thêm hai lỗi lặp ở test-data và access forms; checklist onboarding chỉ xử lý một bài học còn các bài khác vẫn lặp lại.","Đúng: chương trình chỉ thu thập bài học lúc đóng nên nhiều lỗi lặp lại giữa các đội, vì vậy PM đề xuất thu thập ở cuối mỗi giai đoạn và mỗi sprint review rồi lưu nơi mọi đội tìm được."],exp:'Task P7, enabler "gather knowledge": bài học cần được thu thập xuyên suốt và lưu ở nơi dễ tìm, không chỉ lúc đóng dự án. Bẫy: coi lessons learned là việc cuối dự án, hoặc xử lý từng lỗi riêng lẻ.'},{id:"o300",n:300,t:0,origin:"original",eco:"P7",domain:"people",approach:"predictive",tags:["predictive","eco-2026","distributed-teams","communities-of-practice"],type:"mc",q:"An engineering firm designs a power substation with teams in three countries under a predictive plan. Engineers say they upload their documents to the repository but do not know whom to ask about unwritten design practices in the other offices. Design reviews keep finding the same inconsistencies. What should the project manager do?",opts:["Set up cross-site technical exchange sessions and an expert directory so engineers know whom to ask","Set up a shared repository folder structure with naming rules so that design practices are easy to find","Add a design-practice checklist to each design review so that reviewers catch the known inconsistencies","Create a frequently-asked-questions page on the repository, with a coordinator to maintain it"],ans:[0],why:["Đúng: kỹ sư không biết hỏi ai về thực hành thiết kế ngầm ở các văn phòng khác, nên PM lập buổi trao đổi kỹ thuật định kỳ giữa các địa điểm và danh bạ chuyên gia.","Sai: cấu trúc thư mục và quy tắc đặt tên giúp tìm tài liệu, nhưng ở đây tri thức thiếu là thực hành chưa được viết ra; kỹ sư đã tải tài liệu lên mà vẫn không biết hỏi ai.","Sai: checklist trong review giúp phát hiện lỗi nhất quán đã biết, nhưng ở đây nó xử lý triệu chứng ở khâu cuối; thực hành ngầm vẫn không được chia sẻ giữa văn phòng nên lỗi mới vẫn xuất hiện.","Sai: trang hỏi đáp có người duy trì hữu ích cho câu hỏi lặp lại, nhưng ở đây tri thức ngầm khó viết thành câu trả lời sẵn; kỹ sư cần kênh hỏi trực tiếp người có kinh nghiệm."],exp:'Task P7, enabler "foster an environment for knowledge transfer": nhóm phân tán cần kênh để hỏi và chia sẻ tri thức ngầm, như cộng đồng thực hành và danh bạ chuyên gia, chứ không chỉ kho tài liệu.'},{id:"o301",n:301,t:0,origin:"original",eco:"P7",domain:"people",approach:"agile",tags:["agile","eco-2026","onboarding","working-agreement"],type:"mc",q:"A Scrum team will receive three new members at the start of the next sprint. The existing members worry about meeting the sprint goal while also helping them, and the team has estimated that onboarding will take about 20% of capacity in the first sprint. The product has a large wiki that is partly outdated. The next retrospective falls at the end of that first sprint. What should the project manager do?",opts:["Ask the team at the next retrospective how to handle onboarding, then update the working agreement","Rewrite the outdated wiki pages before the new members start, then ask the existing members to review them","Have the product owner explain the domain to the new members during sprint planning, then add notes to the wiki","Pair each new member with an onboarding buddy, then ask the team to forecast the sprint at 20% less capacity"],ans:[3],why:["Sai: đúng nếu còn một retrospective trước khi người mới đến, nhưng ở đây buổi retro kế tiếp rơi vào cuối sprint đầu của họ; bàn cách onboarding sau khi sprint đó đã chạy là quá muộn.","Sai: đúng nếu đội còn dư thời gian, nhưng ở đây các thành viên hiện tại đã kín việc cho sprint goal; viết lại wiki hữu ích lâu dài nhưng không đem lại người hướng dẫn trực tiếp ngay từ sprint đầu.","Sai: đúng nếu khoảng trống chính là hiểu lĩnh vực nghiệp vụ, nhưng ở đây người mới cần học cách làm việc trong code và quy trình của đội; một buổi nói trong sprint planning không đủ.","Đúng: đội đã ước tính onboarding tốn khoảng 20% công suất và sprint đầu của người mới bắt đầu ngay, nên PM giao buddy cho từng người mới và để đội dự báo sprint với công suất ít hơn 20% để thời gian ghép cặp không thành việc làm thêm."],exp:'Task P7, enabler "foster an environment for knowledge transfer", trong agile: khi chi phí onboarding đã được ước tính, PM hành động ngay bằng cách giao buddy và để đội dự báo sprint theo công suất thật. Chờ retrospective sau sprint hay viết lại wiki không giúp người mới ngay từ sprint đầu.'},{id:"o302",n:302,t:0,origin:"original",eco:"P7",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","ai","knowledge-base","content-ownership"],type:"mc",q:"A hybrid program lets new team members ask an AI assistant that answers from the project wiki. A new engineer followed the assistant's deployment steps and caused a failed release, because the wiki page was two years old and had never been retired. A quick check shows that several recently edited pages also hold outdated steps, and no wiki page has a named owner. What should the project manager do?",opts:["Give each wiki page an owner plus a refresh schedule, then retire pages that nobody has kept current","Restrict deployment rights to senior engineers, then test the assistant in a sandbox before widening access","Add a disclaimer to the assistant that answers may be out of date, then ask users to check each step","Ask the AI vendor to limit answers to pages edited in the last twelve months, then audit what remains"],ans:[0],why:["Đúng: sự cố đến từ trang wiki hai năm tuổi chưa được gỡ và nhiều trang sửa gần đây vẫn lỗi thời mà không ai làm chủ, nên PM giao chủ sở hữu và chu kỳ rà soát cho từng trang rồi gỡ trang chưa ai rà; công cụ AI chỉ tốt bằng tri thức nó dựa vào.","Sai: đúng nếu lỗi nằm ở hành vi của trợ lý, nhưng ở đây nguyên nhân là nội dung lỗi thời; người mới vẫn dựa vào wiki sai và senior sẽ bị quá tải bởi mọi lần triển khai.","Sai: đúng nếu không thể sửa nội dung trong thời gian ngắn, nhưng ở đây cảnh báo chung không chỉ ra trang nào lỗi thời; nội dung sai vẫn nằm đó và người mới vẫn có thể làm theo.","Sai: đúng nếu ngày sửa gần nhất phản ánh đúng độ tin cậy, nhưng ở đây nhiều trang sửa gần đây vẫn lỗi thời; không ai chịu trách nhiệm xác nhận nội dung đúng thì tri thức vẫn không đáng tin."],exp:'Task P7, enabler "foster an environment for knowledge transfer", với AI làm bối cảnh: công cụ AI chỉ tốt bằng tri thức nó dựa vào. PM đặt quyền sở hữu và chu kỳ rà soát cho nội dung thay vì bỏ công cụ, siết quyền hay chỉ thêm lời cảnh báo.'},{id:"o303",n:303,t:0,origin:"original",eco:"P7",domain:"people",approach:"predictive",tags:["predictive","eco-2026","lessons-learned","phase-gate"],type:"mc",q:'A predictive program requires teams to complete a lessons-learned template after each phase gate. A review shows the entries are generic, such as "improve communication", and nobody reads them. What should the project manager do?',opts:["Add required fields for owner, due date and cost impact to the template, then review entries at each gate","Set up an online knowledge repository and require each team to upload its template within a week of the gate","Facilitate a candid session after each gate and store specific actions where others can search","Have the PMO write the lessons from reports and meeting minutes on behalf of the teams"],ans:[2],why:["Sai: thêm trường bắt buộc làm mẫu cụ thể hơn, nhưng ở đây vấn đề là mục nhập chung chung và không ai đọc; thêm trường chỉ tăng thủ tục mà không tạo cuộc trao đổi tạo ra bài học thật.","Sai: kho tri thức trực tuyến giúp tìm lại, nhưng ở đây nội dung hiện tại đã chung chung; tải mẫu lên kho vẫn lưu những mục không dùng được và không ai đọc.","Đúng: mẫu biểu một mình không cho ra bài học, nên PM điều phối buổi trao đổi thẳng thắn sau mỗi phase gate và lưu hành động cụ thể ở nơi mọi người tìm được.","Sai: PMO tổng hợp từ báo cáo và biên bản nhanh và nhất quán, nhưng ở đây bài học thật nằm trong trải nghiệm của đội mà báo cáo không ghi; nhờ PMO viết thay làm đội mất sở hữu bài học."],exp:'Task P7, enabler "gather knowledge": mẫu biểu một mình không tạo ra bài học tốt; cần cuộc trao đổi thẳng thắn có người điều phối và nơi lưu để tìm lại được.'},{id:"o304",n:304,t:0,origin:"original",eco:"P7",domain:"people",approach:"agile",tags:["agile","eco-2026","bus-factor","pairing"],type:"mc",q:"Reviewing story history, a Scrum team finds that only one developer has worked on the billing integration, and she begins parental leave in six weeks. Several billing stories remain in the backlog. Two other developers have said they are willing to learn the module, and the product owner expects about four sprints of billing work. What should the project manager do?",opts:["Ask her to document the billing integration and hand it over during her last two weeks before leave","Map the billing code areas that only she understands, then rank them by risk to the roadmap","Hire a contractor with billing experience to cover the integration while she is on leave","Have two volunteers pair with her on billing stories now while the product owner sequences them"],ans:[3],why:["Sai: tài liệu bàn giao cuối cùng giữ lại được tri thức rõ ràng, nhưng ở đây còn sáu tuần và có hai người sẵn lòng học; tài liệu viết vội không thay được kinh nghiệm làm trên story thật.","Sai: lập bản đồ vùng mã chỉ cô hiểu giúp thấy rủi ro, nhưng ở đây lịch sử story đã cho thấy chỉ cô làm module này; thêm bước phân tích chỉ tiêu tốn vài tuần trong sáu tuần còn lại.","Sai: thuê người ngoài có kinh nghiệm billing là giải pháp có thể hợp lý, nhưng ở đây có hai developer sẵn lòng học và còn sáu tuần; thuê ngoài tốn kém, chậm và không xây năng lực trong đội.","Đúng: lịch sử cho thấy tri thức nằm ở một người và đã có hai người sẵn lòng, nên PM giao họ ghép cặp với cô trên story billing thật ngay từ bây giờ, còn product owner sắp thứ tự công việc."],exp:'Task P7, enabler "identify knowledge critical to the project" và "gather knowledge": khi dữ liệu đã chỉ ra tri thức nằm ở một người và có người sẵn lòng học, PM giao việc ghép cặp ngay trên công việc thật. Phân tích thêm hay tài liệu cuối cùng đều tốn thời gian của sáu tuần còn lại.'},{id:"o305",n:305,t:0,origin:"original",eco:"P7",domain:"people",approach:"predictive",tags:["predictive","eco-2026","trust","merger"],type:"mc",q:"After an acquisition, staff from the legacy company on a predictive transformation project are reluctant to share their process knowledge, fearing their roles will become redundant. HR has said role decisions cannot be made for another year, but the sponsor can approve a retention commitment. Last quarter the PM ran open knowledge forums and recognized sharing in team objectives; attendance was good, yet the notes stayed thin and generic, and staff said only a guarantee about their roles would change that. What should the project manager do?",opts:["Require legacy staff to complete detailed knowledge templates, then review them at the next gate","Escalate to the sponsor, then request a written retention commitment covering the handover","Pair each legacy employee with a newcomer for the handover, then track the hours in the schedule","Run low-risk knowledge forums for legacy staff, then recognize contributions in team objectives"],ans:[1],why:["Sai: đúng nếu họ sẵn lòng chia sẻ và chỉ thiếu cấu trúc, nhưng ở đây họ giữ tri thức vì sợ mất vai trò; ép điền mẫu chỉ tạo thêm ghi chú qua loa và làm niềm tin xấu đi.","Đúng: diễn đàn và ghi nhận đã thử mà ghi chú vẫn mỏng, nhân viên nói chỉ có đảm bảo về vai trò mới đổi được và chỉ sponsor mới có quyền cam kết giữ chân, nên PM leo thang lên sponsor để xin cam kết bằng văn bản cho người hoàn thành bàn giao.","Sai: đúng nếu nhân viên không lo mất việc, nhưng ở đây nỗi sợ còn nguyên; ghép người cũ với người sẽ thay họ khiến họ thấy mình bị thay thế và chia sẻ càng ít.","Sai: đúng nếu diễn đàn ít rủi ro chưa từng được thử, nhưng ở đây PM đã chạy và ghi nhận rồi mà ghi chú vẫn mỏng; làm lại đúng cách đó khi nỗi sợ chưa được xử lý không đổi kết quả."],exp:'Task P7, enabler "foster an environment for knowledge transfer": khi người ta giữ kiến thức vì sợ mất vai trò, trước hết dùng ghi nhận và diễn đàn ít rủi ro; nhưng khi những cách đó đã thử mà nỗi sợ vẫn còn và chỉ người có thẩm quyền mới xóa được, PM leo thang để xin cam kết. Ép buộc hay ghép cặp làm tăng cảm giác bị thay thế.'},{id:"o306",n:306,t:0,origin:"original",eco:"P7",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","transition","operations-handover"],type:"mc",q:"A hybrid product will move to an operations support team after release 3, which is four months away. The implementation team plans a single one-hour handover meeting with slides, and no support runbooks exist yet. The support team lead says they are not sure what they will need to run the product. What should the project manager do?",opts:["Ask the implementation team to draft support runbooks, then walk the support lead through them at the handover meeting","Interview the support team about what it needs to run the product, then plan shadowing sessions around those needs","Ask the sponsor to extend the implementation team's involvement for the first year, then route support questions to them","Ask the implementation team to expand the meeting to a half-day session, then add a live demo and a question round"],ans:[1],why:["Sai: đúng nếu đội hỗ trợ đã nói họ cần runbook, nhưng ở đây chính họ chưa biết cần gì; đội triển khai viết theo phỏng đoán có thể bỏ sót điều đội hỗ trợ thật sự cần.","Đúng: đội hỗ trợ chưa biết họ cần gì để vận hành và còn bốn tháng đến release 3, nên PM hỏi họ cần gì rồi lập kế hoạch shadowing xoay quanh các nhu cầu đó; chuyển giao thành công khi bên nhận làm được.","Sai: đúng nếu đội hỗ trợ không thể học kịp trong thời gian còn lại, nhưng ở đây còn bốn tháng; giữ đội triển khai một năm tạo phụ thuộc và đội hỗ trợ không có cơ hội tự vận hành.","Sai: đúng nếu đội hỗ trợ chỉ cần hiểu tổng quan sản phẩm, nhưng ở đây họ chưa biết cần gì để vận hành; buổi dài hơn vẫn là một lần giảng và xem demo không giống việc thực hành vận hành."],exp:'Task P7, enabler "foster an environment for knowledge transfer": chuyển giao thành công khi bên nhận làm được, bắt đầu từ việc hỏi họ cần gì. Họp một lần, viết runbook theo phỏng đoán hay kéo dài sự tham gia của đội cũ đều không đủ.'},{id:"o307",n:307,t:0,origin:"original",eco:"P8",domain:"people",approach:"predictive",tags:["predictive","eco-2026","sponsor-reporting","decision-focused"],type:"mc",q:"The sponsor of a predictive facilities-upgrade project tells the project manager that the 14-page monthly status report is too long and that she reads only the first page. Twice, she has missed issues that needed her decision. The report follows a PMO template used by four programs, which allows a customized front page. What should the project manager do?",opts:["Analyze the past six reports with the PMO analyst to find where the missed decisions sat, then restructure the report around those","Meet the PMO to ask whether the 14-page template can be shortened, then redesign it for all programs","Establish with her which decisions she must make, then rebuild the report around a one-page summary","Ask the PMO analyst to send her a short email alert whenever a decision is needed, then keep the monthly report as it is"],ans:[2],why:["Sai: phân tích sáu báo cáo gần nhất cùng PMO analyst để biết quyết định nằm ở đâu là đúng nếu chưa rõ vì sao bà bỏ lỡ, nhưng ở đây bà đã nói chỉ đọc trang đầu; điều còn thiếu là bà phải đưa ra những quyết định nào, và phân tích quá khứ không trả lời được.","Sai: đúng nếu mẫu là nguyên nhân chung của mọi chương trình, nhưng ở đây mẫu dùng cho bốn chương trình và đã cho phép trang đầu tùy chỉnh; người cần được phục vụ là sponsor nên sửa mẫu chung là sai tầm.","Đúng: sponsor chỉ đọc trang đầu và hai lần bỏ lỡ quyết định, còn mẫu PMO cho phép trang đầu tùy chỉnh, nên PM hỏi bà cần quyết định gì rồi tái cấu trúc báo cáo quanh bản tóm tắt một trang về các quyết định đó.","Sai: đúng nếu bà hài lòng với nội dung báo cáo, nhưng ở đây bà nói báo cáo quá dài và chưa ai biết bà cần xem gì; cảnh báo rời rạc tách quyết định khỏi bối cảnh tiến độ."],exp:'Task P8, enabler "create reports aligned with sponsor and stakeholder expectations": báo cáo tốt dẫn dắt quyết định. PM xác định sponsor cần quyết định gì và đưa lên đầu trong phạm vi mẫu cho phép, giữ chi tiết cho người cần.'},{id:"o308",n:308,t:0,origin:"original",eco:"P8",domain:"people",approach:"agile",tags:["agile","eco-2026","transparency","information-radiator"],type:"mc",q:"Stakeholders of an agile product keep messaging team members for status, interrupting developers several times a day. The product owner holds a sprint review every two weeks, but stakeholders say they cannot see progress in between. The product owner has said she has no spare time for more meetings, though the project manager can host a short weekly slot. The team's working agreement reserves the daily scrum for the developers. What should the project manager do?",opts:["Ask the product owner to hold a weekly stakeholder update, then keep the sprint review as it is","Route stakeholder questions through the product owner, then ask stakeholders to stop messaging the developers","Make the sprint board and burn-up chart visible to stakeholders, then host an open Q&A slot each week","Invite the stakeholders to the daily scrum, then use it to show progress each morning"],ans:[2],why:["Sai: đúng nếu product owner còn thời gian, nhưng ở đây bà đã nói không còn thời gian cho thêm cuộc họp; việc này dồn thêm cho một người.","Sai: đúng nếu product owner có dư năng lực, nhưng ở đây vấn đề là thiếu minh bạch giữa các lần review; chặn liên lạc và dồn câu hỏi lên người đã quá tải làm stakeholder bực hơn.","Đúng: stakeholder không thấy tiến độ giữa các lần review và product owner không có thời gian, nên PM mở bảng sprint cùng burn-up chart cho họ và tự tổ chức khung hỏi đáp mở hằng tuần, không làm gián đoạn đội.","Sai: đúng nếu working agreement cho phép khách mời tham dự, nhưng ở đây daily scrum dành cho developer lập kế hoạch ngày; họ dự sẽ biến nó thành họp báo cáo."],exp:'Task P8, enabler "promote transparency and collaboration": trong agile, minh bạch đạt được bằng information radiator luôn mở và một kênh trao đổi định kỳ do PM đảm nhận, thay vì báo cáo riêng, chặn liên lạc hay dồn việc cho product owner.'},{id:"o309",n:309,t:0,origin:"original",eco:"P8",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","ai","recording-consent","data-privacy"],type:"mc",q:"A hybrid program team uses an AI note-taker in all meetings. During a vendor negotiation session, the vendor's representative says she does not consent to the meeting being recorded and transcribed. The organization's policy requires consent from external participants for any recording. What should the project manager do?",opts:["Turn the AI note-taker off for this meeting and ask the program coordinator to take manual minutes for the vendor to review","Ask the vendor to put her objection in writing, then check with legal before deciding on the recording","Keep recording but restrict the transcript to the internal project team and the legal department, with access logged","Record only the sections that cover internal topics and switch off during the vendor's statements and questions"],ans:[0],why:["Đúng: chính sách yêu cầu đồng ý của bên ngoài và đại diện vendor đã nói không đồng ý, nên PM tắt công cụ AI cho buổi này và ghi biên bản thủ công.","Sai: xin văn bản và hỏi pháp lý đúng khi chính sách không rõ, nhưng ở đây chính sách đã nêu cần sự đồng ý và bà đã từ chối trực tiếp; vừa chờ pháp lý vừa tiếp tục ghi là vi phạm.","Sai: hạn chế quyền xem bản ghi giảm rủi ro lộ thông tin, nhưng ở đây vấn đề là việc ghi âm khi chưa có đồng ý; giới hạn truy cập không thay thế sự đồng ý của người bị ghi.","Sai: chỉ ghi các phần nội bộ nghe có vẻ hợp lý, nhưng ở đây buổi đàm phán trộn lẫn phát biểu của hai bên và bà không đồng ý bị ghi; tắt bật liên tục dễ ghi nhầm lời bà."],exp:'Task P8, enabler "define a communication strategy", với AI làm bối cảnh: chiến lược truyền thông gồm cả quy tắc ghi âm và quyền riêng tư. PM tuân theo chính sách đồng ý, dùng phương án thay thế và không đổ lỗi cho công cụ.'},{id:"o310",n:310,t:0,origin:"original",eco:"P8",domain:"people",approach:"predictive",tags:["predictive","eco-2026","communication-channel","field-crews"],type:"mc",q:"A predictive offshore wind-farm project sends a weekly email update to all stakeholders. Feedback from vessel crews shows they rarely read it because they have limited connectivity and work in shifts. A safety procedure change was missed last month. The PM has already surveyed the crews: they will attend pre-shift briefings, and the vessel masters have agreed to give five minutes for them. What should the project manager do?",opts:["Update the communications plan to put safety changes in pre-shift briefings, then record crew acknowledgement","Survey the crews on how they prefer to receive updates, then change the communications plan","Keep the weekly email, then require crew members to return a read receipt for each message","Post each update on the intranet portal, then send everyone a notification when it appears"],ans:[0],why:["Đúng: kênh phù hợp đã được khảo sát và các thuyền trưởng đã đồng ý dành thời gian, nên PM cập nhật kế hoạch truyền thông chuyển thay đổi an toàn sang buổi briefing đầu ca và ghi nhận xác nhận của thủy thủ.","Sai: đúng nếu PM chưa biết ưa thích của thủy thủ, nhưng ở đây khảo sát đã xong và các thuyền trưởng đã đồng ý dành năm phút; hỏi thêm khiến thay đổi an toàn tiếp tục bị bỏ lỡ.","Sai: đúng nếu kết nối ổn và thủy thủ chỉ quên đọc, nhưng ở đây họ ít đọc vì kết nối kém và làm theo ca; xác nhận đã đọc không làm họ nhận được thông tin an toàn.","Sai: đúng nếu thủy thủ đăng nhập từ xa được, nhưng ở đây kết nối hạn chế và làm theo ca là lý do họ không đọc email; chuyển sang cổng intranet vẫn cần họ đăng nhập từ xa."],exp:'Task P8, enabler "define a communication strategy": chiến lược chọn kênh theo người nhận và có xác nhận đã nhận. Thông tin an toàn bị bỏ lỡ cho thấy kênh sai, nên cập nhật kế hoạch dựa trên điều đã khảo sát chứ không chỉ nhắc lại hay khảo sát tiếp.'},{id:"o311",n:311,t:0,origin:"original",eco:"P8",domain:"people",approach:"agile",tags:["agile","eco-2026","feedback-loop","distributed-demo"],type:"mc",q:"A distributed agile team, with stakeholders across five time zones, records its sprint demo and shares the video. For three sprints, no stakeholder has commented. The product owner reads the silence as approval, but the project manager notices that few people have even opened the video, and nobody has asked the stakeholders how they would prefer to review the work. What should the project manager do?",opts:["Hold the demo live at a fixed time each sprint and record it for those who cannot attend","Add a short feedback form at the end of the video and remind stakeholders to complete it","Make written comments on each video mandatory for the stakeholders listed in the register for three sprints","Ask stakeholders which format suits them, then adapt the review so that feedback is easy to give"],ans:[3],why:["Sai: demo trực tiếp vào giờ cố định tăng tương tác, nhưng ở đây đội phân tán nhiều múi giờ và chưa biết họ ưa thích gì; chọn giờ và hình thức khi chưa hỏi có thể loại bỏ chính những người cần góp ý.","Sai: form phản hồi cuối video giảm công sức cho người xem, nhưng ở đây ít người còn mở video; thêm form vào nội dung không ai xem không tạo vòng phản hồi.","Sai: bắt buộc bình luận có thể tạo phản hồi hình thức, nhưng ở đây stakeholder chưa mở video; bắt buộc làm họ thêm việc và có thể cho bình luận qua loa thay vì phản hồi thật.","Đúng: sau ba sprint im lặng và ít người mở video, im lặng không phải là đồng ý, nên PM hỏi chính stakeholder họ muốn định dạng và thời điểm nào rồi điều chỉnh buổi review để dễ góp ý."],exp:'Task P8, enabler "establish a feedback loop": một kênh một chiều không phải vòng phản hồi. Khi không có phản hồi, PM hỏi chính người nhận và điều chỉnh định dạng, không suy diễn là đồng ý.'},{id:"o312",n:312,t:0,origin:"original",eco:"P8",domain:"people",approach:"predictive",tags:["predictive","eco-2026","governance","stage-gate"],type:"mc",q:"A predictive infrastructure program has stage-gate reviews that require an evidence package five days before each gate. Teams habitually submit it on the day of the gate, and the board has had to postpone twice. The PM has already confirmed with the board the exact evidence it requires and the format it prefers. Team leads say nobody is assigned to assemble the package, and the preparation work appears in no team's schedule. What should the project manager do next?",opts:["Add package-preparation milestones to each team's schedule and assign an owner for each package","Ask the board to confirm its evidence requirements and the format it prefers for the package","Request that the board relax the five-day deadline for teams with heavy workloads this quarter","Set up a shared checklist of required evidence that teams update before each gate, reviewed at the gate itself"],ans:[0],why:["Đúng: yêu cầu bằng chứng của hội đồng đã rõ, nên PM đưa mốc chuẩn bị gói vào lịch từng đội và giao người chịu trách nhiệm từng gói; đó là cách giúp đội đáp ứng hạn năm ngày.","Sai: xác nhận yêu cầu của hội đồng là bước đúng khi chưa rõ, nhưng ở đây PM đã xác nhận cả nội dung lẫn định dạng; hỏi lại không giải quyết việc các đội nộp trễ.","Sai: nới hạn cho đội đang bận có thể thông cảm, nhưng ở đây hội đồng đã hoãn hai lần vì nộp trễ; nới chuẩn sẽ làm quy trình quản trị yếu đi mà không sửa nguyên nhân là đội không lên lịch chuẩn bị.","Sai: danh mục kiểm tra bằng chứng giúp đội biết cần gì, nhưng ở đây yêu cầu đã rõ; vấn đề là không ai có lịch và người chịu trách nhiệm nên danh mục xem ở ngày gate vẫn đến quá muộn."],exp:'Task P8, enabler "support reporting and governance processes": khi PM đã biết rõ yêu cầu của hội đồng, bước đúng là đưa việc chuẩn bị vào lịch từng đội và giao người chịu trách nhiệm. Xác nhận lại, nới hạn hay chỉ lập danh mục kiểm tra không giải quyết nguyên nhân nộp trễ.'},{id:"o313",n:313,t:0,origin:"original",eco:"P8",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","integrated-reporting","hybrid-metrics"],type:"mc",q:"A hybrid program has a hardware team working to a Gantt chart and a software team using Scrum. Each reports in its own format, and the sponsor says she cannot see an integrated picture of progress. What should the project manager do?",opts:["Agree a single reporting format with the sponsor that shows milestones and iteration progress side by side","Ask the two team leads to agree a milestone summary page to add to their own reports and send both to the sponsor","Assess the sponsor's information needs from past questions with the PMO analyst, then build a shared dashboard from both tools","Require the software team to produce a Gantt chart for its sprints, then merge both teams' reports into one"],ans:[0],why:["Đúng: sponsor không thấy bức tranh tích hợp vì hai đội báo cáo hai định dạng, nên PM thống nhất với sponsor một định dạng chung đặt các mốc và tiến độ lặp cạnh nhau.","Sai: nhờ hai team lead thống nhất thêm trang tóm tắt mốc vào báo cáo của mỗi đội dễ làm, nhưng ở đây sponsor cần một góc nhìn chung; hai báo cáo vẫn do sponsor tự kết hợp và định dạng vẫn khác nhau.","Sai: phân tích nhu cầu thông tin của sponsor từ các câu hỏi cũ cùng PMO analyst rồi dựng dashboard nghe cẩn trọng, nhưng sponsor đã nói thẳng bà không thấy bức tranh tích hợp; định dạng cần được thống nhất với bà, không suy ra từ quá khứ.","Sai: ép đội phần mềm lập Gantt cho dễ hợp nhất, nhưng ở đây đội dùng Scrum và chart này không phản ánh đúng cách làm theo lặp; hợp nhất như vậy làm sai tiến độ thực tế."],exp:'Task P8, enabler "create reports aligned with sponsor expectations": trong hybrid, báo cáo cần tích hợp hai cách đo tiến độ trong một góc nhìn chung. PM chịu trách nhiệm tổng hợp và thống nhất định dạng với sponsor.'},{id:"o314",n:314,t:0,origin:"original",eco:"P8",domain:"people",approach:"predictive",tags:["predictive","eco-2026","transparency","bad-news","forecast"],type:"mc",q:"A predictive project's cost forecast shows a 12% overrun caused by a supplier price increase. The overrun exceeds the tolerance of both the project manager and the sponsor, so only the steering committee, which meets next week, can approve extra budget or accept a recovery plan. The project manager has a recovery option that would reduce the overrun to 5%, but it is not yet validated. How should the project manager proceed?",opts:["Report the 5% outcome as the forecast, then note that the recovery option is likely to be approved soon","Escalate the 12% forecast to the steering committee, then present the unvalidated option and decision needed","Brief the sponsor privately on the overrun, then agree with the sponsor how it appears in the committee pack","Ask the cost control lead to validate the recovery option this week, then report the forecast as 5% once it is confirmed"],ans:[1],why:["Sai: đúng nếu phương án phục hồi đã được duyệt, nhưng ở đây nó chưa được xác nhận; công bố 5% như dự báo thì steering committee ra quyết định trên số liệu chưa chắc chắn.","Đúng: mức vượt 12% nằm ngoài ngưỡng của PM và sponsor, chỉ steering committee được duyệt thêm ngân sách hoặc chấp nhận phương án, nên PM leo thang dự báo 12% kèm phương án chưa xác nhận, giả định và quyết định cần có.","Sai: đúng nếu mức vượt nằm trong ngưỡng sponsor tự quyết, nhưng ở đây committee mới là nơi quyết định; thỏa thuận cách trình bày với sponsor làm giảm minh bạch khi hội đồng cần thấy mức vượt thật.","Sai: nhờ cost control lead xác nhận phương án trong tuần nghe cẩn trọng, nhưng ngay cả khi được xác nhận, phương án phục hồi vẫn cần committee chấp nhận; báo 5% trước đó che mức vượt 12% mà committee cần thấy tuần tới."],exp:'Task P8, enabler "promote transparency and collaboration" cùng "support governance": khi vượt ngưỡng của PM và sponsor, PM leo thang lên cơ quan có thẩm quyền với tin xấu trung thực, kèm nguyên nhân, phương án và quyết định cần thiết. Bẫy: báo con số lạc quan hoặc trì hoãn.'},{id:"o315",n:315,t:0,origin:"original",eco:"P8",domain:"people",approach:"agile",tags:["agile","eco-2026","forecasting","executive-expectations"],type:"mc",q:"An executive asks an agile team to commit to a fixed release date because he needs to plan a launch event; he has said the event can shift by up to two weeks if he is told early enough. The team's velocity has varied between 22 and 34 points, and about 300 points remain in the backlog. What should the project manager do?",opts:["Ask the team to re-size the remaining backlog in smaller points, then fix the date from the new total","Give the executive the date at the optimistic end of the range, then ask the product owner to update it when velocity changes","Give the latest date in the range as a firm commitment, then ask the product owner to hold scope steady until release","Offer the executive a date range from the burn-up chart, using the velocity spread, and review it with the team at each sprint"],ans:[3],why:["Sai: đúng nếu việc ước lượng thô là nguồn bất định chính, nhưng ở đây vận tốc dao động 22–34 mới là nguồn chính; chia nhỏ ước lượng lại không giảm sự bất định đáng kể.","Sai: đúng nếu vận tốc ổn định, nhưng ở đây vận tốc dao động rộng; chỉ tin đầu lạc quan thì khả năng trễ cao và sếp mất niềm tin.","Sai: đúng nếu sự kiện không thể dời và cần cam kết cứng, nhưng ở đây sếp chấp nhận dời tối đa hai tuần nếu được báo sớm; ngày muộn nhất làm thành cam kết cứng trước dữ liệu dao động.","Đúng: sếp chấp nhận dời sự kiện hai tuần nếu được báo sớm và vận tốc dao động rộng, nên PM đưa khoảng ngày từ burn-up chart cùng độ phân tán vận tốc rồi cập nhật mỗi sprint."],exp:'Task P8, enabler "create reports aligned with sponsor and stakeholder expectations": với agile, PM chuyển nhu cầu của lãnh đạo thành dự báo theo khoảng, dựa trên dữ liệu và cập nhật thường xuyên, thay vì cam kết cứng hay giấu số liệu.'},{id:"o316",n:316,t:0,origin:"original",eco:"P8",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","ai","report-accuracy","human-review"],type:"mc",q:`A project manager on a program with phase gates and sprints uses an AI tool to draft the weekly executive summary from the issue tracker and the risk log. This week's draft, sent without review, said "no critical risks" although the log held one high risk. A field-mapping error was the cause. The sponsor has already forwarded the report, and its recipients may act on it this week. What should the project manager do now?`,opts:["Investigate with the tool vendor why the field mapping failed, then correct the sponsor on the findings","Ask the data team to fix the field mapping in the tool, then include the high risk in the report for next week","Withdraw the AI tool from reporting with the PMO lead, then revert to manual drafts for the rest of the program","Send a correction to the sponsor right away, then agree a human check of AI drafts with her before anything is sent"],ans:[3],why:["Sai: đúng nếu chưa biết nguyên nhân, nhưng ở đây lỗi ánh xạ trường đã rõ; điều tra với nhà cung cấp trước khi sửa sai khiến người nhận báo cáo tiếp tục dựa vào thông tin sai.","Sai: đúng nếu báo cáo chưa được chuyển tiếp và chưa ai dựa vào đó, nhưng ở đây sponsor đã chuyển tiếp và người khác có thể hành động trong tuần này; chỉ sửa công cụ không làm đúng lại thông tin đã gửi.","Sai: đúng nếu lỗi lặp lại nhiều lần, nhưng ở đây là một lỗi ánh xạ trường cùng việc thiếu bước kiểm tra của người; bỏ công cụ không xử lý bản báo cáo sai đã được chuyển tiếp.","Đúng: báo cáo sai đã được chuyển tiếp và nguyên nhân đã rõ, nên PM gửi đính chính cho sponsor ngay và thêm bước kiểm tra bởi người trước khi gửi các bản nháp AI; người chịu trách nhiệm cuối cùng vẫn là PM."],exp:'Task P8, enabler "create reports aligned with sponsor expectations", với AI làm bối cảnh: người chịu trách nhiệm cuối cùng của báo cáo vẫn là PM. Phản ứng đúng là sửa sai minh bạch ngay khi thông tin sai đã lan ra và thêm bước kiểm tra, không né trách nhiệm.'},{id:"o317",n:317,t:0,origin:"original",eco:"P8",domain:"people",approach:"predictive",tags:["predictive","eco-2026","communication-plan-review","feedback-loop"],type:"mc",q:"A predictive program's communication management plan is eight months old. Several stakeholders complain informally that they are copied on too many emails and meetings, without saying which ones. The plan has never been reviewed, nobody has asked whether it works, and the PM can update it without a baseline change. What should the project manager do?",opts:["Survey or interview stakeholders on what is useful, then update the communication plan with the communications owner","Raise a change request for the communication plan, then have the sponsor approve a revised distribution list","Direct each workstream lead to cut the distribution lists to the decision makers, then send everyone else a monthly digest","Ask the PMO to halve the number of status meetings, then watch whether the complaints decline over the next month"],ans:[0],why:["Đúng: kế hoạch truyền thông cũ tám tháng, chưa từng được rà soát và nhiều người than bị gửi quá nhiều mà không nói cụ thể, nên PM hỏi stakeholder điều gì hữu ích rồi cập nhật kế hoạch.","Sai: đúng nếu thay đổi làm đổi baseline hoặc vượt thẩm quyền của PM, nhưng ở đây PM tự cập nhật kế hoạch truyền thông được và chưa có đề xuất cụ thể; quy trình change request chỉ thêm thủ tục.","Sai: đúng nếu các bên đã nói ai cần gì, nhưng ở đây PM chưa hỏi nên có thể cắt nhầm người cần thông tin; bản tổng hợp hằng tháng thường đến quá trễ.","Sai: đúng nếu phàn nàn chỉ nhắm vào các cuộc họp trạng thái, nhưng ở đây họ phàn nàn cả email mà không nói cuộc nào; quan sát một tháng để xem có hiệu quả hay không thì kéo dài vấn đề."],exp:'Task P8, enabler "establish a feedback loop": kế hoạch truyền thông là tài liệu sống, cần phản hồi thường xuyên từ người nhận. PM hỏi, đo, rồi cập nhật trong phạm vi quyền của mình thay vì cắt giảm theo phỏng đoán.'}],a=[{id:"o209",n:209,t:0,origin:"original",eco:"R1",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","approach-selection","tailoring"],type:"mc",q:"A medical-device company is launching a wearable sensor and a companion mobile app. The sensor must pass regulatory testing on dates set by an external lab, while the app's features are still being discovered with clinicians through prototypes. The sponsor asks the project manager which development approach to recommend. The engineering leads have already rated the sensor as fixed-requirement and the app as high-uncertainty, and both must ship together as one product. What is the best recommendation?",opts:["Facilitate a tailoring workshop for the engineering leads to score uncertainty and cost of change per component, and record the scores in the tailoring plan","Plan stage gates on the lab's fixed dates for the sensor, sprints on clinician reviews for the app, joined by integration milestones","Create two separate projects, a predictive sensor project and an adaptive app project, each with its own charter and its own report to the sponsor","Baseline one predictive plan for the entire product, fixing the lab's test dates and the app scope in the project scope statement"],ans:[1],why:["Sai: workshop chấm điểm từng thành phần là đúng nếu chưa có đánh giá nào, nhưng đề bài đã nêu hai lead xếp cảm biến là yêu cầu cố định và ứng dụng là bất định cao; làm lại chỉ trì hoãn khuyến nghị mà sponsor đang chờ.","Đúng: cảm biến có mốc kiểm định cố định do phòng lab bên ngoài ấn định và thay đổi thiết kế rất tốn kém, nên hợp predictive với gate; ứng dụng còn đang khám phá cùng bác sĩ nên hợp lặp ngắn. Mốc tích hợp nối hai phần vì chúng ra mắt cùng nhau.","Sai: tách thành hai dự án riêng là hợp lý nếu hai sản phẩm độc lập với nhau, nhưng ở đây cảm biến và ứng dụng phải ra mắt cùng nhau như một sản phẩm; tách ra làm mất kiểm thử tích hợp và đầu mối chịu trách nhiệm chung.","Sai: một kế hoạch predictive cho toàn sản phẩm là đúng nếu cả hai phần đều có yêu cầu cố định, nhưng ở đây phạm vi ứng dụng còn đang khám phá cùng bác sĩ; khóa baseline sớm sẽ vỡ khi phản hồi thay đổi tính năng."],exp:"Task Process 1 (enabler: recommend a project management development approach). Khi một sản phẩm có phần ràng buộc cứng và phần còn khám phá, câu trả lời thường là hybrid được tailoring theo từng thành phần. Bẫy: chọn một cách tiếp cận cho toàn bộ sản phẩm hoặc chọn theo thói quen của tổ chức."},{id:"o318",n:318,t:0,origin:"original",eco:"R1",domain:"process",approach:"agile",tags:["agile","eco-2026","sustainability","critical-information","definition-of-done"],type:"mc",q:"A scrum team is building a fleet-routing tool for a city waste-collection contract. In sprint 3 the project manager learns that the city will score the final system on measurable fuel and emissions savings, yet nothing in the backlog or the definition of done mentions this. Two releases are already planned. The product owner and the city's contract manager have just confirmed in writing that the target is a 12 percent fuel saving, measured per route. What should the project manager do next?",opts:["Hold a clarification session with the product owner and the city to pin down the emissions target and how it will be measured","Record the city's scoring criterion in the risk register, assign an owner, and monitor it until the contract review with the city","Add a fuel-saving acceptance criterion to the affected stories and the definition of done, and plan measurement into the next sprint","Raise a change request with the city's contract office to add emissions reporting, since the backlog and the contract never mentioned it"],ans:[2],why:["Sai: làm rõ chỉ tiêu cùng product owner và thành phố là bước đúng khi chỉ tiêu còn mơ hồ, nhưng đề bài cho biết họ vừa xác nhận bằng văn bản mức 12 % và cách đo; họp thêm chỉ làm chậm việc đưa nó vào backlog.","Sai: risk register hợp lý cho điều chưa chắc xảy ra, nhưng tiêu chí chấm điểm của thành phố là yêu cầu đã biết, không phải rủi ro; để nó ở sổ rủi ro thì đội vẫn không xây và không kiểm thử theo nó.","Đúng: chỉ tiêu đã được xác nhận bằng văn bản nên không cần làm rõ thêm; hành động đúng là đưa nó vào tiêu chí chấp nhận và definition of done để đội xây và đo ngay trong sprint tới.","Sai: change request với thành phố là đúng khi yêu cầu nằm ngoài hợp đồng, nhưng ở đây chính thành phố chấm điểm theo chỉ tiêu này; việc còn thiếu nằm ở backlog của đội chứ không phải ở hợp đồng."],exp:"Task Process 1 (enabler: ensure value delivery). Khi yêu cầu giá trị đã được khách hàng và product owner xác nhận, PM không họp làm rõ thêm mà đưa nó vào backlog và definition of done để đội xây và đo được. Bẫy: coi yêu cầu đã biết là rủi ro, hoặc mở change request cho thứ vốn đã nằm trong tiêu chí chấm điểm."},{id:"o319",n:319,t:0,origin:"original",eco:"R1",domain:"process",approach:"predictive",tags:["predictive","eco-2026","sustainability","critical-information","baseline"],type:"mc",q:"A project to build a regional distribution center is in planning. The charter says nothing about sustainability, but the client's board has publicly committed to a green-building rating for all new sites. The scope and cost baselines are due for approval in three weeks. The client's sustainability lead has already confirmed in writing that the board expects at least the second-highest rating tier, with annual energy reporting. What should the project manager do?",opts:["Commission a consultant's feasibility study of the rating tier for this site, and update the baselines once the study reports back","Submit the baselines on time as chartered, and treat the rating as a change request if the client raises it afterwards","Ask the board to approve a sustainability reserve held outside the baselines, to be released once the design is final","Add the rating-tier requirements and energy reporting to the scope and cost baselines, and submit them for approval on schedule"],ans:[3],why:["Sai: nghiên cứu khả thi bằng tư vấn hợp lý nếu mức hạng còn để ngỏ, nhưng ban điều hành đã chốt mức hạng và sustainability lead đã xác nhận bằng văn bản; baseline phải duyệt sau ba tuần nên chờ nghiên cứu chỉ làm trễ.","Sai: xử lý yêu cầu phát sinh qua change request là đúng sau khi có baseline, nhưng ở đây yêu cầu đã biết trước hạn duyệt ba tuần; để nó thành change request là cố tình lập baseline thiếu.","Sai: quỹ dự phòng nằm ngoài baseline là công cụ hợp lệ cho rủi ro chưa biết, nhưng chi phí chứng nhận là phạm vi đã biết và phải nằm trong cost baseline mà ban điều hành duyệt.","Đúng: yêu cầu đã được xác nhận bằng văn bản và hạn duyệt baseline còn ba tuần, nên PM cùng người ước tính chi phí đưa mức hạng và báo cáo năng lượng vào phạm vi, chi phí rồi trình duyệt đúng hạn."],exp:"Task Process 2 (enabler: plan and manage scope). Yêu cầu bền vững đã được client xác nhận thì phải nằm trong scope và cost baseline trước khi duyệt; thêm sau bằng change request làm baseline sai ngay từ đầu. Bẫy: hỏi lại điều đã biết, hoặc đặt chi phí đã biết vào quỹ dự phòng ngoài baseline."},{id:"o320",n:320,t:0,origin:"original",eco:"R1",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","sustainability","critical-information","supplier-data"],type:"mc",q:"A consumer-electronics firm runs a hybrid project: hardware phases follow gates while the companion firmware is built in sprints. At the design gate, a retail partner asks for end-of-life recycling data on every component, which could change supplier choices already scheduled for purchase. Orders for long-lead parts are due in two weeks. What should the project manager do first?",opts:["Meet the retail partner and the procurement lead to size the recycling-data requirement against the supplier shortlist, before the long-lead orders are released","Release the long-lead orders to the current suppliers on the due dates, and write a recycling-data clause into each purchase contract with the procurement lead","Raise a change request with the retail partner pricing the recycling-data work as an addition to the signed scope, and place the orders after it is approved","Ask each current supplier to submit recycling data for its components, and place the orders if the data looks adequate to the hardware lead"],ans:[0],why:["Đúng: yêu cầu dữ liệu tái chế là thông tin quan trọng có thể đổi lựa chọn nhà cung cấp. Cần hiểu rõ nhu cầu của đối tác và tác động tới thiết kế, mua sắm, kế hoạch trước khi đặt hàng khó đảo ngược.","Sai: đặt hàng đúng hạn là đúng khi nhà cung cấp hiện tại chắc chắn đáp ứng, nhưng yêu cầu của đối tác có thể đổi lựa chọn nhà cung cấp; thêm điều khoản vào hợp đồng sau khi đã đặt chỉ vá sau khi quyết định đã bị khóa.","Sai: change request để tính phí là đúng sau khi biết khối lượng thêm, nhưng ở đây chưa ai đánh giá ảnh hưởng lên thiết kế và nhà cung cấp nên chưa thể định giá; gửi sớm chỉ tạo đề xuất không có căn cứ.","Sai: xin dữ liệu từ nhà cung cấp hiện tại hữu ích nếu yêu cầu của đối tác đã rõ, nhưng ở đây chưa biết đối tác cần mức dữ liệu nào cho linh kiện nào; số liệu của nhà cung cấp không cho biết có phải đổi nhà cung cấp hay không."],exp:"Task Process 1 (enabler: determine critical information requirements, e.g., sustainability). Hybrid: các quyết định phần cứng khó đảo ngược nên thông tin yêu cầu phải được thu thập trước cổng mua sắm. Bẫy: làm đúng lịch đặt hàng trong khi chưa biết yêu cầu, hoặc đẩy việc sang đội không liên quan."},{id:"o321",n:321,t:0,origin:"original",eco:"R1",domain:"process",approach:"agile",tags:["agile","eco-2026","ai","estimation","data-driven-decisions"],type:"mc",q:"A product team of eight plans to adopt an AI code assistant. The engineering director tells the project manager to cut the release forecast by 30 percent because the tool will double productivity, and cites only the vendor's brochure. The team has no data of its own with the tool, and the release date is shared with a customer who accepts a revised forecast after any sprint. What should the project manager do?",opts:["Apply the median productivity gain from published benchmarks for similar tools to the release forecast, and record the source with the team in the estimate basis","Run the tool for a few sprints, compare velocity and rework with earlier sprints, and update the release forecast from the measured results","Log the adoption in the risk register with the engineering director as owner, and keep the current forecast until the release ships","Agree a 15 percent forecast reduction with the engineering director as a compromise, and add a learning-curve buffer to the schedule"],ans:[1],why:["Sai: số liệu chuẩn bên ngoài hữu ích khi đội cần ước tính sơ bộ và chưa thể đo, nhưng ở đây khách hàng nhận dự báo sau mỗi sprint nên có thể đo thật; con số trung bình của đội khác không phản ánh đội này mà ngày phát hành thì chia sẻ với khách hàng.","Đúng: dự báo cần dựa trên dữ liệu thực tế của chính đội, và khách hàng chấp nhận dự báo điều chỉnh sau mỗi sprint nên có chỗ để kiểm chứng. Dùng công cụ vài sprint, đo velocity và mức rework rồi điều chỉnh; PM kiểm chứng lời hứa năng suất thay vì tin hay bác bỏ nó.","Sai: ghi rủi ro và giữ dự báo hợp lý nếu không cần điều chỉnh gì, nhưng giám đốc đã yêu cầu cắt và đội đang bắt đầu dùng công cụ; sổ rủi ro không tạo ra dữ liệu mà dự báo đang thiếu, và để đến sau khi phát hành là quá muộn.","Sai: thỏa hiệp 15 % trông cân bằng nhưng không có dữ liệu nào đỡ cho con số đó; đội chưa từng dùng công cụ, nên mọi mức cắt đều là phỏng đoán và rủi ro vẫn nằm trên ngày phát hành của khách hàng."],exp:"Task Process 1 (enabler: collect and analyze data to make informed project decisions; liên quan ước lượng effort). Công cụ AI là bối cảnh: dùng bằng chứng đo được để quyết định, kiểm chứng kết quả, thay vì tin tuyên bố hoặc bác bỏ công cụ. Bẫy: cam kết số liệu chưa kiểm chứng với khách hàng."},{id:"o322",n:322,t:0,origin:"original",eco:"R1",domain:"process",approach:"predictive",tags:["predictive","eco-2026","integrated-plan","dependencies"],type:"mc",q:"The planning team for a hospital wing renovation has produced the schedule, cost, procurement, and quality plans separately. Before the integrated baseline goes to the steering committee, the project manager notices that the procurement plan delivers imaging equipment eight weeks after the schedule shows installation starting. The equipment supplier and the installation contractor have both confirmed their dates are firm, and moving the installation start affects no contractual milestone. What is the best next step?",opts:["Escalate the eight-week gap to the steering committee, asking it to choose between expedited delivery and a later installation start","Submit the integrated baseline with a documented assumption that delivery will be expedited, and track it in the risk register","Re-sequence the installation to start after delivery, update the schedule and cost plans, and submit the integrated baseline","Ask the procurement lead to negotiate an expedited delivery with the supplier and add the premium to the cost baseline"],ans:[2],why:["Sai: leo thang cho steering committee là đúng nếu sắp xếp lại vượt quá thẩm quyền hoặc ảnh hưởng mốc hợp đồng, nhưng ở đây ngày đã chắc chắn và dời lắp đặt không đụng mốc nào; mang vấn đề đã có lời giải ra ủy ban chỉ làm chậm.","Sai: giả định có điều kiện cộng sổ rủi ro dùng được khi còn khả năng giao sớm hơn, nhưng ngày giao đã được nhà cung cấp xác nhận chắc chắn; xung đột này là chắc chắn, không phải rủi ro.","Đúng: hai bên đã xác nhận ngày chắc chắn và dời lắp đặt không đụng mốc hợp đồng, nên PM sắp xếp lại lắp đặt sau ngày giao, cập nhật tiến độ và chi phí liên quan rồi trình baseline tích hợp.","Sai: thương lượng giao nhanh là cách hợp lệ để nén tiến độ khi nhà cung cấp còn linh hoạt, nhưng ở đây nhà cung cấp đã xác nhận ngày không đổi; thêm phí vào baseline cho một việc không thể xảy ra là sai."],exp:"Task Process 1 (enabler: integrate planning activities). Khi các ngày đã được các bên xác nhận chắc chắn, PM giải quyết xung đột phụ thuộc bằng cách sắp xếp lại và cập nhật các kế hoạch liên quan trước khi trình baseline tích hợp. Bẫy: xác minh lại điều đã xác nhận, coi xung đột chắc chắn là rủi ro, hoặc mua nhanh một thứ nhà cung cấp đã nói không thể."},{id:"o323",n:323,t:0,origin:"original",eco:"R1",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","execution-strategy","phased-delivery"],type:"mc",q:"A bank is replacing its loan-origination system. Data migration and compliance sign-offs must follow a fixed sequence, while the customer-facing screens will be refined with user feedback. The sponsor wants visible value by year end, but full cutover cannot happen before the regulator's audit in spring, although the new screens could run for a pilot group alongside the old system. Which execution strategy should the project manager recommend?",opts:["Run a discovery sprint with branch managers to define what a pilot group needs from the screens before deciding the release plan","Complete migration and sign-offs in gated phases first, then run the new screens as a pilot after the regulator's audit","Deliver screens and migration together in two-week sprints, with audit evidence produced at the end of each sprint","Release the screens to a pilot group before year end, while migration and sign-offs follow gated phases to cutover"],ans:[3],why:["Sai: sprint khám phá cùng quản lý chi nhánh là đúng khi chưa biết nhóm thí điểm cần gì, nhưng đề bài đã nêu màn hình đã có thể chạy song song cho nhóm thí điểm; thêm khám phá chỉ lùi giá trị sponsor muốn thấy trước cuối năm.","Sai: làm tuần tự theo gate cho toàn bộ là hợp lý khi mọi phần đều cố định, nhưng ở đây màn hình cần tinh chỉnh theo phản hồi và có thể chạy thí điểm; chờ sau kiểm toán mùa xuân thì sponsor không thấy giá trị trước cuối năm.","Sai: sprint hai tuần là đúng cho phần màn hình, nhưng di chuyển dữ liệu và ký duyệt tuân thủ có thứ tự cố định theo quy định; ép chúng vào nhịp sprint làm lẫn cách làm với ràng buộc bên ngoài.","Đúng: chiến lược kết hợp vừa tôn trọng chuỗi bắt buộc của migration và cuộc kiểm toán mùa xuân, vừa mang lại giá trị sớm qua bản phát hành dần cho nhóm thí điểm."],exp:"Task Process 1 (enabler: recommend a project execution strategy). Chiến lược thực thi cân bằng ràng buộc cứng (quy định, thứ tự) với cơ hội giao giá trị sớm. Bẫy: chọn phương án tất cả hoặc không có gì, bỏ qua một trong hai ràng buộc."},{id:"o324",n:324,t:0,origin:"original",eco:"R1",domain:"process",approach:"predictive",tags:["predictive","eco-2026","estimation","bottom-up"],type:"mc",q:"A construction company is planning a new warehouse. The sponsor supplied a target budget based on a similar warehouse built five years ago. The WBS is now complete, but several work packages use a steel-framing method the company has never used before. The project manager must produce effort and resource estimates for the planning review in three weeks. What should the project manager do?",opts:["Ask the crew leads who will do the framing for bottom-up estimates of effort and resources, and cross-check them against the old warehouse figures","Estimate the framing packages parametrically from the old warehouse's cost per square meter, with the cost estimator adding the supplier's steel premium","Hold a three-point estimating session with the sponsor and finance to set optimistic, likely, and pessimistic figures for each framing package","Ask the steel-framing supplier to quote the framing packages, and have the procurement lead use those quotes as the effort and resource estimates"],ans:[0],why:["Đúng: gói công việc dùng phương pháp mới nên dữ liệu lịch sử chưa đủ; ước lượng từ dưới lên với người thực hiện sát thực tế hơn. Dữ liệu kho cũ chỉ dùng để đối chiếu, và chênh lệch lớn là điều cần giải thích với sponsor.","Sai: ước lượng theo tham số dựa trên dữ liệu lịch sử là phương pháp hợp lệ khi công việc giống trước đây, nhưng phương pháp khung thép là mới với công ty; chi phí mỗi m² của kho cũ không phản ánh nỗ lực của công việc này.","Sai: ước lượng ba điểm là kỹ thuật tốt, nhưng người dự phiên là sponsor và tài chính, không phải người sẽ làm; họ không biết thời gian thật của phương pháp mới nên con số lạc quan hay bi quan đều thiếu căn cứ.","Sai: báo giá nhà cung cấp là nguồn dữ liệu có ích cho chi phí vật tư, nhưng PM cần ước lượng nỗ lực và nguồn lực của chính đội công ty; báo giá không cho biết bao nhiêu giờ công và ai làm."],exp:"Task Process 1 (enabler: estimate work effort and resource requirements). Khi công việc mới, ưu tiên ước lượng bottom-up với người thực hiện; analogous/historical chỉ làm đối chiếu. Bẫy: để ngân sách mục tiêu quyết định ước lượng."},{id:"o325",n:325,t:0,origin:"original",eco:"R1",domain:"process",approach:"agile",tags:["agile","eco-2026","plan-maintenance","velocity","forecasting"],type:"mc",q:"After three sprints, a team's measured velocity is about 20 percent lower than the figure used in the release plan that stakeholders approved last quarter. The release plan is a forecast the team owns under its working agreement, and no change control board holds a baseline for it. The product owner still considers the next feature set essential, and the customer was told the release date is a target. What should the project manager do?",opts:["Run a retrospective to find the causes of the lower velocity, and hold the release forecast steady while the findings are written up for the sponsor","Escalate to the sponsor for funding of extra developers, to bring velocity back to the approved release plan figure","Update the forecast from the observed velocity, agree scope options with the product owner, share the revised date range with stakeholders","Open a change request with the change control board for the lower velocity, and route each later forecast update through that board's monthly meeting"],ans:[2],why:["Sai: retrospective để tìm nguyên nhân là thực hành tốt, nhưng đã có ba sprint dữ liệu đo được; forecast phải phản ánh số đo ngay và nguyên nhân có thể bàn song song, nên không cần giữ nguyên dự báo cũ trong lúc chờ.","Sai: thêm người là đúng nếu đây là dự án predictive với ngày cam kết cứng, nhưng khách hàng đã biết ngày phát hành chỉ là mục tiêu; người mới còn làm đội chậm đi vài sprint nên chưa cần trả tiền để giữ nguyên con số cũ.","Đúng: duy trì kế hoạch tích hợp nghĩa là cập nhật dự báo theo dữ liệu thực, cùng product owner xem lựa chọn về phạm vi và truyền thông minh bạch cho các bên, vì dự báo thuộc về đội và không có baseline nào khóa nó.","Sai: change request qua board là đúng nếu đây là dự án predictive có baseline phải đổi, nhưng ở đây forecast theo velocity thực tế là việc thường xuyên của đội và product owner; đưa mọi cập nhật qua board chỉ thêm thủ tục."],exp:"Task Process 1 (enabler: maintain the integrated project management plan). Kế hoạch là tài liệu sống; velocity đo được là bằng chứng để điều chỉnh forecast. Bẫy: giấu số liệu, ép đội làm nhiều hơn, hoặc áp thủ tục predictive vào việc cập nhật forecast."},{id:"o326",n:326,t:0,origin:"original",eco:"R1",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","data-driven-decisions","metrics"],type:"mc",q:"A hybrid program has a hardware team reporting earned value and a software team reporting burn-up charts. The steering committee must decide at the next review, in two weeks, whether to fund a three-month extension, and members say the two reports cannot be compared. The PMO says a common reporting standard needs a quarter to design. What should the project manager do?",opts:["Convert both teams' data into one view of progress against planned scope and value, and recommend on the extension from it","Ask the PMO to design a common reporting standard for hybrid programs, and bring the first comparable report to the committee's quarterly review","Ask the hardware lead to switch to burn-up charts from now on, so that both teams appear in one format at the committee's next review","Recommend the extension on the hardware scope using earned value, and attach the software team's burn-up chart as informational material"],ans:[0],why:["Đúng: hội đồng quyết định sau hai tuần nên PM quy các số liệu về cùng một góc nhìn (phạm vi và giá trị so với kế hoạch) rồi đưa khuyến nghị có căn cứ; chuẩn báo cáo dài hạn không kịp.","Sai: chuẩn báo cáo chung do PMO đặt là giải pháp tốt về lâu dài, và đúng nếu quyết định chưa gấp, nhưng ủy ban phải quyết định ở kỳ họp tới trong hai tuần; chuẩn mới không giúp có một bức tranh so sánh được cho quyết định này.","Sai: đổi định dạng của đội phần cứng là đúng nếu hai đội cùng loại công việc, nhưng ở đây dữ liệu quá khứ vẫn không so sánh được ngay và earned value phù hợp với việc có khối lượng cố định; kỳ họp tới vẫn không có một góc nhìn chung.","Sai: earned value chặt chẽ cho phần cứng và đúng nếu phần mềm không ảnh hưởng quyết định, nhưng bỏ số liệu phần mềm làm khuyến nghị chỉ nhìn một nửa chương trình; ủy ban cần tiến độ của cả hai đội."],exp:"Task Process 1 (enabler: collect and analyze data to make informed project decisions). Với hybrid, PM tích hợp các thước đo khác nhau thành bức tranh thống nhất trước khi quyết định. Bẫy: ép đồng bộ hóa công cụ hoặc đẩy phân tích cho người ra quyết định."},{id:"o327",n:327,t:0,origin:"original",eco:"R1",domain:"process",approach:"predictive",tags:["predictive","eco-2026","business-value","phase-gate","sunk-cost"],type:"mc",q:"At a phase gate on a customer-portal project, the consolidated plan shows a forecast 18 percent over budget and four months late. The sponsor mentions that a competitor has just launched a similar portal. The steering committee expects the project manager to recommend whether the project should continue. Finance has already re-forecast the cost to complete, and the product team has re-estimated the portal's benefit, which still exceeds the remaining cost. What should the project manager do?",opts:["Update the cost and schedule forecasts from current data and compare them with the business case before recommending anything","Recommend cancelling the project, as cost and schedule are outside the tolerances set in the approved baselines","Present continue, descope, and stop as three costed options and let the committee choose without a recommendation","Recommend continuing with a re-baselined budget and schedule, and ask the committee to approve the change request"],ans:[3],why:["Sai: cập nhật dự báo rồi so với business case là bước đúng khi chưa có số liệu, nhưng tài chính đã dự báo lại chi phí còn lại và đội sản phẩm đã ước lượng lại lợi ích; làm lại chỉ trì hoãn khuyến nghị ủy ban đang chờ.","Sai: vượt dung sai là tín hiệu để xem xét, và hủy dự án đúng khi lợi ích không còn bù chi phí, nhưng đề bài cho biết lợi ích vẫn lớn hơn chi phí còn lại; vượt baseline không tự nó là lý do dừng.","Sai: trình bày các lựa chọn có chi phí là thực hành tốt, nhưng ủy ban kỳ vọng PM đưa ra khuyến nghị có cơ sở; số liệu đã sẵn nên trình mà không khuyến nghị là né trách nhiệm của PM.","Đúng: số liệu đã cho thấy lợi ích còn lớn hơn chi phí còn lại, nên PM khuyến nghị tiếp tục kèm baseline mới và đề nghị ủy ban duyệt thay đổi."],exp:"Task Process 1 (enabler: ensure value delivery; manage changes). Khi dự báo và lợi ích đã được cập nhật và lợi ích vẫn lớn hơn chi phí còn lại, PM khuyến nghị rõ ràng và xin duyệt baseline mới thay vì phân tích lại. Bẫy: coi vượt dung sai là lý do hủy, hoặc né khuyến nghị bằng cách chỉ liệt kê lựa chọn."},{id:"o328",n:328,t:0,origin:"original",eco:"R1",domain:"process",approach:"agile",tags:["agile","eco-2026","complexity","scaling","dependencies"],type:"mc",q:"A retailer asks a project manager to lead a loyalty-platform initiative with six scrum teams across three locations. Several features cross team boundaries and the product owners hold different priorities. The first release is eight months away. Before sprint planning begins, what should the project manager assess first?",opts:["The cross-team dependencies and the coordination of product ownership, to size the coordination needed","Ask the six product owners to agree one prioritized backlog before any team starts sprint planning","Set up a scrum-of-scrums cadence and a shared dependency board across the three locations","Collect each team's capacity per sprint so that a firm release date can be committed to the retailer"],ans:[0],why:["Đúng: đánh giá nhu cầu, độ phức tạp và quy mô trước khi chọn cách điều phối. Số phụ thuộc chéo và cách phối hợp product ownership quyết định cần cơ chế nào như họp phối hợp giữa các đội.","Sai: một backlog ưu tiên chung là đích đúng của chương trình nhiều đội, nhưng chưa biết mức phụ thuộc và cách các product owner phối hợp thì chưa biết cần mức đồng bộ nào; bước đầu là đánh giá chứ không phải áp đặt một backlog.","Sai: scrum-of-scrums và bảng phụ thuộc là công cụ phối hợp hợp lý, nhưng chọn công cụ trước khi biết quy mô phối hợp cần thiết là đặt giải pháp trước vấn đề; cần đánh giá phụ thuộc trước.","Sai: năng lực mỗi đội cần cho việc lập kế hoạch, nhưng cam kết ngày phát hành chắc chắn khi còn tám tháng và nhiều tính năng xuyên đội là sớm; phụ thuộc giữa các đội mới quyết định ngày khả thi."],exp:"Task Process 1 (enabler: assess project needs, complexity, and magnitude). Quy mô lớn, nhiều đội: đánh giá phụ thuộc và cách điều phối trước, rồi mới chọn cấu trúc và cam kết. Bẫy: nhảy sang cam kết ngày giao hoặc thay đổi cấu trúc đội khi chưa phân tích."},{id:"o329",n:329,t:0,origin:"original",eco:"R1",domain:"process",approach:"predictive",tags:["predictive","eco-2026","execution-strategy","schedule-compression"],type:"mc",q:"A utility company's grid-upgrade project has a 20-month baseline. The sponsor wants the finish pulled forward by three months to meet a funding deadline. The schedule has many finish-to-start dependencies and relies on one shared specialist crew. The project manager has the network diagram and resource calendar. The project manager's own analysis shows that fast-tracking the two overlapping design packages and adding a second shift for the crew would recover three months. What should the project manager recommend?",opts:["Analyze compression options on the critical path with the network diagram and crew calendar before proposing anything to the sponsor","Ask the sponsor to seek an extension of the funding deadline, since the baseline duration reflects the real critical path","Put the fast-tracking of the two design packages and an extra crew shift through change control stating the cost and risk","Hire a second crew for the non-critical activities, to free the shared crew's time for the critical ones"],ans:[2],why:["Sai: phân tích các phương án nén tiến độ là bước đúng khi chưa có kết quả, nhưng PM đã tự phân tích và tìm ra tổ hợp fast-track cộng ca thứ hai thu hồi ba tháng; phân tích lại chỉ chậm thêm.","Sai: xin gia hạn hạn chót tài trợ là việc sponsor làm được và đôi khi đúng, nhưng sponsor đã yêu cầu rút ngắn và PM đã có phương án khả thi; chuyển trách nhiệm đi mà không trình phương án là bỏ qua việc của PM.","Đúng: PM đã có phương án rút ngắn ba tháng, nên đưa ra thay đổi baseline kèm chi phí và rủi ro cho sponsor duyệt vì nó đổi tiến độ đã được phê duyệt.","Sai: thêm đội cho việc không găng giải phóng nguồn lực đúng là có ích khi tải nhiều, nhưng nó không rút ngắn đường găng; muốn kết thúc sớm ba tháng phải nén chính các hoạt động găng."],exp:"Task Process 1 (enabler: manage project schedule; manage changes). Khi PM đã phân tích và có phương án nén đường găng khả thi, bước đúng là trình change request kèm chi phí và rủi ro để sponsor duyệt. Bẫy: phân tích lại điều đã có, đẩy việc cho sponsor, hoặc tối ưu việc không nằm trên đường găng."},{id:"o210",n:210,t:0,origin:"original",eco:"R2",domain:"process",approach:"predictive",tags:["predictive","eco-2026","scope-definition","requirements"],type:"mc",q:`A county government is procuring an online permit portal. The sponsor's one-line request is "make permits easier to get". The project manager has met the permit office, but planning staff, inspectors, and applicants have not been asked, and the developer contract is to be signed in six weeks. What should the project manager do next?`,opts:["Interview the permit office and the developer's analyst to write the scope statement, and let planning staff, inspectors, and applicants review it after signing",'Ask the sponsor to define "easier" in a one-page vision statement, and let the permit office write the requirements from it for the developer contract',"Gather requirements from the permit office, planning staff, inspectors, and applicants, then draft a scope statement with exclusions","Have the permit office survey applicants and rank the portal's features, and write the top-ranked ones into the scope statement for the contract"],ans:[2],why:["Sai: phỏng vấn văn phòng cấp phép và nhà phát triển rồi cho các nhóm khác góp ý sau khi ký là đúng nếu hợp đồng cho sửa phạm vi tự do, nhưng ở đây hợp đồng ký sau sáu tuần và ba nhóm chưa được hỏi; yêu cầu thiếu sẽ bị khóa vào hợp đồng.","Sai: nhờ sponsor viết tầm nhìn chi tiết hơn hữu ích nếu chưa ai biết hướng đi, nhưng sponsor không phải người dùng cổng; chi tiết yêu cầu phải đến từ các nhóm bị ảnh hưởng, và viết lại tầm nhìn không thay được việc hỏi họ.","Đúng: ba nhóm chưa được hỏi và hợp đồng ký sau sáu tuần, nên PM tổ chức các buổi lấy yêu cầu với cả bốn nhóm rồi soạn scope statement có phần loại trừ để sponsor xem xét trước khi ký.","Sai: khảo sát người nộp đơn là nguồn yêu cầu tốt, nhưng họ chỉ là một trong bốn nhóm; xếp hạng tính năng của họ chưa phải là phạm vi khi chưa có yêu cầu của nhân viên quy hoạch và thanh tra, và chưa ghi loại trừ."],exp:"Task Process 2 (enabler: define scope). Từ một yêu cầu mơ hồ, PM thu thập yêu cầu từ các nhóm bị ảnh hưởng rồi ghi phạm vi rõ ràng. Bẫy: để một nhóm hoặc nhà cung cấp quyết định phạm vi, hoặc chờ sponsor chi tiết hóa."},{id:"o330",n:330,t:0,origin:"original",eco:"R2",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","wbs","backlog","decomposition"],type:"mc",q:"A smart-building project combines sensor installation and wiring, which follow a signed bill of quantities, with a tenant dashboard whose feature list is still unknown and will be shaped by tenant feedback. The project manager is preparing the scope breakdown for the planning workshop. Which approach to decomposition is best?",opts:["Decompose the installation into WBS work packages, and hold the dashboard as epics that tenant feedback refines, in one baseline","Place all scope, wiring included, in one product backlog ordered by tenant value, with the product owner tracking installation items as backlog items","Decompose every deliverable, dashboard features among them, to work-package level in the WBS now with the team leads, and baseline the result","Run a tenant workshop to define each dashboard feature first, then build the WBS for the whole project from the outcome and baseline it"],ans:[0],why:["Đúng: phần lắp đặt có bill of quantities đã ký nên phân rã thành work package trong WBS; phần dashboard chưa biết tính năng nên để ở mức epic và tinh chỉnh dần với cư dân. Mỗi phần dùng công cụ phù hợp, cùng nằm trong một baseline.","Sai: backlog xếp theo giá trị cư dân là đúng nếu toàn bộ phạm vi còn chưa rõ, nhưng công việc lắp đặt đã có khối lượng cố định; đưa vào backlog làm mất cấu trúc cần cho kiểm soát chi phí.","Sai: phân rã đến work package là đúng nếu danh sách tính năng đã chốt, nhưng ở đây chưa biết tính năng dashboard; phân rã ngay sẽ tạo chi tiết giả và baseline phải sửa liên tục.","Sai: workshop với cư dân hữu ích để thu thập ý tưởng, nhưng phản hồi tới dần qua prototype nên không thể chốt mọi tính năng trong một buổi; lại bắt phần lắp đặt đã đủ rõ phải chờ mới có WBS."],exp:"Task Process 2 (enabler: break down scope). Hybrid: dùng WBS cho công việc ổn định và backlog/epic cho phần còn khám phá. Bẫy: phân rã chi tiết quá sớm, hoặc bỏ cấu trúc cho phần chưa rõ."},{id:"o331",n:331,t:0,origin:"original",eco:"R2",domain:"process",approach:"predictive",tags:["predictive","eco-2026","stakeholder-agreement","scope-baseline"],type:"mc",q:"On a plant-expansion project, the sponsor and engineering lead signed the scope statement. During a review, the maintenance manager, who will run the plant after handover, says two interfaces she depends on were never discussed with her. Detailed design starts next week. The maintenance manager and the sponsor have already agreed that the two interfaces are needed and worth the added cost, and the engineering lead has sized the effect on cost and schedule. What should the project manager do?",opts:["Meet the maintenance manager and the sponsor to walk through both interfaces, and record the agreed need in the stakeholder register before design begins","Start detailed design on the due date and raise a change request for the interfaces once design is far enough along to size the impact","Raise a change request including the engineering lead's impact analysis, adding the two interfaces to the affected baselines before design starts","Ask the engineering lead to include the two interfaces in the design and absorb the effort within the existing design budget"],ans:[2],why:["Sai: họp và ghi vào stakeholder register giúp lưu lại sự đồng thuận, nhưng sponsor và quản lý bảo trì đã đồng ý rồi; các baseline phạm vi, chi phí, tiến độ vẫn chưa đổi nên thiết kế sẽ chạy trên baseline cũ.","Sai: chờ thiết kế đi sâu mới đo tác động nghe hợp lý với yêu cầu mơ hồ, nhưng yêu cầu đã rõ, được đồng ý và đã có tính tác động; thiết kế chi tiết bắt đầu tuần sau nên thay đổi muộn làm làm lại.","Đúng: phạm vi đã được sponsor chấp thuận và tác động đã được tính, nên PM đưa thay đổi chính thức vào các baseline phạm vi, chi phí và tiến độ qua change request trước khi thiết kế chi tiết bắt đầu tuần sau.","Sai: nhờ trưởng kỹ thuật tự hấp thụ công việc tránh được thủ tục, nhưng phạm vi và chi phí đã được sponsor và kỹ sư ký; thêm việc ngoài kiểm soát thay đổi làm baseline sai và ngân sách thiết kế bị vượt."],exp:"Task Process 2 (enabler: manage scope changes). Khi thay đổi phạm vi đã được sponsor đồng ý, PM đưa vào baseline qua kiểm soát thay đổi trước khi bắt đầu giai đoạn bị ảnh hưởng. Bẫy: họp lại điều đã quyết, để muộn, hoặc hấp thụ công việc ngoài change control."},{id:"o332",n:332,t:0,origin:"original",eco:"R2",domain:"process",approach:"agile",tags:["agile","eco-2026","ai","epic-splitting","user-stories"],type:"mc",q:'A product owner adds an epic called "AI-powered customer replies" to the backlog for a support platform and ranks it first. The team says it is too large and vague to plan, and two developers disagree on what "done" would mean, including whether agents review AI drafts before sending. Release planning is next week. The team already chose the AI tool last sprint. What should the project manager facilitate?',opts:["A sizing session where the team estimates the whole epic in story points and records the figure for release planning","A story-splitting session in which the product owner and team slice the epic into small, testable stories","A scope ruling by the sponsor that fixes the epic's features and the draft-review policy before release planning","A time-boxed spike in which two developers evaluate the AI approach and report back before any stories are planned"],ans:[1],why:['Sai: ước lượng điểm story hữu ích cho các story đã rõ, nhưng epic này quá lớn và mơ hồ, và hai developer còn bất đồng về "xong"; điểm cho cả epic là con số không có nội dung đỡ nó.',"Đúng: epic quá lớn cần được tách thành các story nhỏ, kiểm thử được, kèm tiêu chí chấp nhận cụ thể như quy trình nhân viên duyệt bản nháp AI. Product owner và đội cùng làm là cách breakdown đúng.","Sai: sponsor có thể chốt chính sách rà soát bản nháp AI, nhưng cắt epic thành story kiểm thử được là việc của product owner và đội; sponsor chốt tính năng từ trên xuống bỏ qua cộng tác của nhóm.",'Sai: spike là kỹ thuật agile tốt khi chưa biết công nghệ, nhưng đội đã chọn công cụ AI từ sprint trước; vấn đề còn lại là epic quá lớn và "xong" chưa rõ, không phải bất định kỹ thuật.'],exp:"Task Process 2 (enabler: break down scope). AI chỉ là bối cảnh; phần kiểm tra là tách epic thành story nhỏ, có tiêu chí chấp nhận, gồm cả việc người kiểm chứng đầu ra AI. Bẫy: ước lượng khối lớn chưa rõ hoặc để PM viết đặc tả thay cho đội."},{id:"o333",n:333,t:0,origin:"original",eco:"R2",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","scope-definition","regulatory","mvp"],type:"mc",q:"A hybrid project to modernize a city's water-billing system has a legally fixed core: tariff rules and invoice formats mandated by the regulator. Around this core, the utility wants customer self-service features, with the first releases within six months, that will be prioritized as the project runs. The project manager is drafting the scope definition for planning. What should it contain?",opts:["A fixed scope for the regulated core, plus a backlog of self-service features reprioritized within a set limit on added effort","A traceability matrix tying each tariff rule and invoice format to its regulation, with the self-service features scheduled as a final phase","One fixed baseline covering the core and each self-service feature, signed by the regulator and the utility before planning ends","A scope statement for the system agreed with the regulator, with each self-service addition handled as a separate change request"],ans:[0],why:["Đúng: phạm vi hybrid gồm phần cố định cho lõi theo quy định và backlog ưu tiên cho tính năng tự phục vụ, với giới hạn rõ để kiểm soát chi phí và thời gian; tiện ích cũng nhận các bản tự phục vụ đầu tiên trong sáu tháng.","Sai: ma trận truy vết quy định là công cụ tốt cho lõi tuân thủ, và đúng nếu tính năng tự phục vụ có thể đợi, nhưng tiện ích muốn bản đầu trong sáu tháng; xếp vào giai đoạn cuối làm mất cơ hội ưu tiên dần trong lúc dự án chạy.","Sai: một baseline cố định cho cả tính năng tự phục vụ là đúng nếu mọi tính năng đã được xác định, nhưng ở đây chúng được ưu tiên liên tục; khóa sớm làm mọi điều chỉnh sau đó thành thay đổi và mất lợi thế linh hoạt.","Sai: chốt phạm vi cả hệ thống với cơ quan quản lý rồi thêm tính năng bằng change request hợp lý nếu chỉ có vài bổ sung, nhưng tính năng tự phục vụ được ưu tiên liên tục; mỗi lần thêm đều thành change request làm chậm và nặng thủ tục."],exp:"Task Process 2 (enabler: define scope). Hybrid: xác định phần không thương lượng được và phần linh hoạt, kèm ranh giới cho phần linh hoạt. Bẫy: coi toàn bộ là cố định hoặc toàn bộ là linh hoạt."},{id:"o334",n:334,t:0,origin:"original",eco:"R2",domain:"process",approach:"predictive",tags:["predictive","eco-2026","wbs","work-package","decomposition"],type:"mc",q:`A WBS for a data-center migration includes the work package "Migrate application servers", estimated at 14 weeks and assigned to a vendor. The vendor's lead admits it covers several unrelated applications and that progress cannot be measured until it ends; the package would still be accepted only as a whole at week 14, whatever schedule detail is added. The project manager is reviewing the WBS before baseline. What should the project manager do?`,opts:["Add a milestone at the 7-week mark, and check progress halfway through the package with the vendor","Keep the package as it is and track progress through the vendor's weekly status reports and invoices to date","Ask the vendor for a detailed 14-week schedule of the package and review it with the vendor's lead before the baseline","Ask the vendor's lead to split the package into smaller packages per application, each with an owner"],ans:[3],why:["Sai: một mốc ở tuần 7 giúp kiểm tra giữa kỳ nhưng không giải quyết gốc: gói gộp nhiều ứng dụng không liên quan và vẫn chỉ nghiệm thu một lần, nên vẫn khó giao việc và đo.","Sai: báo cáo hàng tuần và hóa đơn chỉ mô tả cảm nhận của nhà cung cấp, không đo tiến độ dựa trên sản phẩm bàn giao; gói vẫn mơ hồ và khó kiểm soát.","Sai: lịch chi tiết 14 tuần giúp thấy bên trong gói, nhưng gói vẫn chỉ được nghiệm thu một lần ở tuần 14 và gộp nhiều ứng dụng không liên quan; vấn đề là cấu trúc gói, nên cần tách gói chứ không phải xem thêm lịch.","Đúng: nhờ trưởng nhóm nhà cung cấp tách gói thành các gói nhỏ theo từng ứng dụng, mỗi gói có deliverable và một người chịu trách nhiệm, để đo và kiểm soát được; PM rà lại kết quả trước khi baseline. Làm cùng nhà cung cấp cũng giúp ước lượng sát thực tế."],exp:"Task Process 2 (enabler: break down scope). Work package phải đủ nhỏ để ước lượng, giao việc và đo lường. Bẫy: thêm cơ chế báo cáo thay vì sửa cấu trúc phân rã."},{id:"o335",n:335,t:0,origin:"original",eco:"R2",domain:"process",approach:"agile",tags:["agile","eco-2026","acceptance-criteria","stakeholder-agreement","sprint-review"],type:"mc",q:'In sprint reviews, the sales director often rejects stories that the product owner accepted, saying "that is not what I meant". The team reworks features each time. The sales director attends reviews but not refinement sessions, and no backlog item carries acceptance criteria that the director has seen before work starts. What should the project manager do?',opts:["Invite the sales director to refinement, and have the product owner write acceptance criteria with her before work starts","Ask the product owner to collect the sales director's written sign-off after each sprint review, and file it in the project records","Facilitate a retrospective with the team and the product owner on the rework, to find why stories keep being misread","Add the sales director as a required approver in the definition of done, and count no story as done before she approves it"],ans:[0],why:["Đúng: nguyên nhân là kỳ vọng chưa được thống nhất trước khi làm, vì giám đốc kinh doanh không dự refinement và chưa thấy tiêu chí nào. Mời họ vào refinement để cùng product owner thống nhất acceptance criteria thì giảm rework từ gốc.","Sai: chữ ký sau mỗi review là đúng nếu vấn đề là tranh cãi về việc ai đã chấp nhận, nhưng ở đây công việc đã làm sai kỳ vọng trước khi ký; chữ ký ghi nhận thái độ sau khi tốn công, không ngăn việc làm sai.","Sai: retrospective để tìm nguyên nhân là thực hành tốt và đúng nếu chưa rõ vì sao, nhưng đề bài đã cho thấy nguyên nhân: giám đốc không dự refinement nên kỳ vọng không được ghi lại trước khi làm; họp tìm nguyên nhân chỉ lặp điều này.","Sai: đưa người phê duyệt vào definition of done làm rõ ai chấp nhận, nhưng vẫn là cổng ở cuối; đội vẫn làm sai kỳ vọng rồi mới biết, nên rework tiếp diễn. Tiêu chí phải được thống nhất trước khi làm."],exp:"Task Process 2 (enabler: obtain stakeholder agreement on project scope). Trong agile, đồng thuận về phạm vi đến từ tiêu chí chấp nhận được thống nhất trước khi phát triển. Bẫy: xử lý ở cuối chu kỳ thay vì đầu chu kỳ."},{id:"o336",n:336,t:0,origin:"original",eco:"R2",domain:"process",approach:"predictive",tags:["predictive","eco-2026","scope-statement","exclusions","assumptions"],type:"mc",q:'A company intranet project has an approved scope statement listing six deliverables. During testing, the HR head expects a mobile app, saying "a modern intranet obviously includes one". The scope statement does not mention mobile either way, and the contract end date is close. What should the project manager have done during scope definition to avoid this?',opts:["Run a scope validation with the HR head and the sponsor at the start of testing, checking the deliverables against the scope statement","Created a requirements traceability matrix linking each of the six deliverables to its source requirement and its test","Listed explicit exclusions and assumptions in the scope statement and reviewed them with each stakeholder group","Obtained the sponsor's signature on the scope statement and placed it under change control before design started"],ans:[2],why:["Sai: xác nhận phạm vi với khách hàng là bước đúng, nhưng làm ở đầu giai đoạn kiểm thử là quá muộn để tránh hiểu lầm; câu hỏi hỏi điều lẽ ra phải làm ở bước xác định phạm vi.","Sai: ma trận truy vết giúp chứng minh sáu sản phẩm bàn giao đủ yêu cầu, nhưng nó chỉ truy vết những gì đã được liệt kê; ứng dụng di động chưa từng được nêu nên ma trận không bao giờ cho thấy khoảng trống này.","Đúng: nêu rõ loại trừ và giả định trong scope statement rồi rà soát với từng nhóm giúp phát hiện kỳ vọng ngầm như ứng dụng di động ngay từ đầu.","Sai: chữ ký của sponsor và đưa vào kiểm soát thay đổi là thực hành đúng, nhưng đề bài cho biết scope statement đã được duyệt; vấn đề là kỳ vọng ngầm của giám đốc nhân sự không được ghi, mà chữ ký không phát hiện ra."],exp:"Task Process 2 (enabler: define scope). Một scope statement tốt nêu cả những gì không nằm trong phạm vi và các giả định, được xem lại với các bên. Bẫy: dùng dự phòng hoặc mở rộng baseline để bù thiếu rõ ràng."},{id:"o337",n:337,t:0,origin:"original",eco:"R2",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","scope-agreement","vendor","interface"],type:"mc",q:"A hybrid project uses a fixed-price vendor to build a payment gateway while the in-house agile team builds the checkout experience around it. Both depend on an interface that is only partly specified, and each side interprets the open parts differently. Any interface change would affect the vendor's fixed price. Both teams have said they are willing to meet, and the contract permits joint scope sessions. What should the project manager do to reach agreement on scope?",opts:["Ask the contract manager to issue a clarification notice stating the in-house team's reading as the requirement, and meet the vendor's lead afterwards","Appoint the in-house architect as interface owner, with authority to settle the open points for both teams after consulting the vendor's lead","Record the open interface points as assumptions in the risk register with the project manager as owner, and revisit them with both leads at the next gate","Hold a joint session of the vendor and in-house teams to document the interface scope, acceptance criteria, and change handling"],ans:[3],why:["Sai: thông báo làm rõ chính thức là công cụ hợp đồng hợp lệ và đúng nếu văn bản hợp đồng đã rõ theo cách hiểu của công ty, nhưng ở đây phần giao diện mở và bên kia hiểu khác; gặp nhà cung cấp sau khi đã áp đặt một cách hiểu lên hợp đồng giá cố định sẽ gây tranh chấp về giá.","Sai: một người sở hữu giao diện là mô hình quản trị hợp lý trong nội bộ, nhưng nhà cung cấp theo hợp đồng giá cố định không chịu quyết định của kiến trúc sư công ty dù có được hỏi ý kiến; thay đổi giao diện ảnh hưởng giá nên cần thỏa thuận chung.","Sai: ghi giả định vào risk register hợp lý khi bất định không thể giải quyết ngay, nhưng ở đây hai bên sẵn sàng họp và hợp đồng cho phép; để mỗi đội làm theo cách hiểu riêng tới gate sau chắc chắn tạo lệch pha tốn kém.","Đúng: giao diện là điểm phụ thuộc chung và hai bên đã sẵn sàng họp, nên PM tổ chức buổi làm việc chung để thống nhất phạm vi, tiêu chí chấp nhận và cách xử lý thay đổi trước khi tiếp tục."],exp:"Task Process 2 (enabler: obtain stakeholder agreement on project scope). Hybrid có nhiều bên cùng làm; ranh giới phạm vi cần được thống nhất bằng cộng tác chứ không bằng áp đặt. Bẫy: chọn bên đúng thay vì làm rõ chung."},{id:"o338",n:338,t:0,origin:"original",eco:"R2",domain:"process",approach:"predictive",tags:["predictive","eco-2026","wbs-dictionary","subcontractor","scope-clarity"],type:"mc",q:'A subcontractor delivered the "site electrical" work package, but the inspector says it omitted temporary power for testing. The subcontractor says temporary power was never mentioned. The WBS names the package but has no WBS dictionary entries. What should the project manager do to prevent this on the remaining packages?',opts:["Require each subcontractor to submit a task list for the package owner's approval before it starts a work package","Write WBS dictionary entries for the remaining packages with each package owner, listing deliverables and acceptance criteria for review","Add a contract clause with the contract manager, making subcontractors responsible for anything an inspector considers part of their trade","Negotiate with the subcontractor and the inspector who pays for the temporary power, and record the agreement in the project records"],ans:[1],why:["Sai: danh sách việc do nhà thầu phụ lập cho thấy họ hiểu gì, nhưng phạm vi của gói phải do PM định nghĩa; nhà thầu phụ tự liệt kê sẽ lặp lại đúng lỗi thiếu điện tạm thời.","Đúng: WBS dictionary mô tả sản phẩm bàn giao, ranh giới và tiêu chí nghiệm thu; xem lại với từng chủ gói để phát hiện thiếu sót như điện tạm trước khi họ thi công.","Sai: Điều khoản bắt nhà thầu phụ chịu mọi thứ mà thanh tra cho là thuộc hạng mục của họ không làm rõ phạm vi, chỉ làm tăng tranh chấp và giá thầu; lỗi nằm ở chỗ định nghĩa thiếu chứ không phải ở thiếu điều khoản hợp đồng.","Sai: đàm phán chi phí điện tạm thời giải quyết vụ việc hiện tại là việc cần làm, nhưng câu hỏi là ngăn lỗi này ở các gói còn lại; không viết mô tả gói thì lỗi tương tự sẽ lặp lại."],exp:"Task Process 2 (enabler: break down scope). WBS cùng WBS dictionary tạo scope baseline; thiếu dictionary khiến ranh giới gói công việc mơ hồ. Bẫy: xử lý bằng hợp đồng hoặc họp thay vì định nghĩa rõ."},{id:"o339",n:339,t:0,origin:"original",eco:"R2",domain:"process",approach:"agile",tags:["agile","eco-2026","story-mapping","mvp","scope-definition"],type:"mc",q:"A startup sponsor wants the first release of a new booking app within four months, but the product owner and designers disagree about what that release must include. The backlog is a flat list of 80 items with no structure, and the team cannot tell what is essential. What should the project manager suggest?",opts:["Ask the product owner to rank the 80 items by value and cut the list at the four-month capacity line","Ask the team to size the 80 items and include whatever fits within four months of their capacity","Run a story-mapping workshop with the whole product group to select a minimum first release","Ask the sponsor to cut the backlog to 20 items with the board, then have the product owner refine the cut list"],ans:[2],why:["Sai: product owner xếp hạng theo giá trị là việc đúng của vai trò, nhưng đề bài nói product owner và designer bất đồng về nội dung; một người xếp hạng không giải quyết bất đồng và thiếu cái nhìn tổng thể về hành trình người dùng.","Sai: Chọn theo năng lực mà không xét giá trị có thể bỏ phần cốt lõi và đưa phần phụ vào; danh sách phẳng chưa cho biết thứ tự hành trình người dùng.","Đúng: bản đồ story cho thấy hành trình người dùng, từ đó chọn lát cắt nhỏ nhất mang giá trị đầu tiên với sự tham gia của product owner, nhà thiết kế và người dùng.","Sai: sponsor và ban lãnh đạo cắt bớt backlog dùng được để kiểm soát phạm vi, nhưng chọn 20 mục từ trên xuống bỏ qua product owner và designer, những người đang bất đồng; kết quả thiếu sự đồng thuận của nhóm làm việc."],exp:"Task Process 2 (enabler: define scope). Agile: dùng kỹ thuật cộng tác như story mapping để xác định lát cắt phát hành đầu. Bẫy: xếp theo năng lực hoặc để một vai trò quyết định thay cả nhóm."},{id:"o340",n:340,t:0,origin:"original",eco:"R2",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","rolling-wave","wbs","funder-reporting"],type:"mc",q:"A hybrid research-lab build includes construction milestones set by the funder and an instrument-control software component. The funder's grant terms require every deliverable to appear in the scope breakdown with an owner, but allow detail to be added as it becomes known. The software team says its features cannot be fully listed this early. How should the project manager present the breakdown?",opts:["Show both streams as epics and features in a backlog format, each under an owner, and attach the construction milestones as release targets","Show construction decomposed to work packages and software at summary level, each under an owner, decomposing further as features firm up","Require the software lead to list its features at work-package level now, each under an owner, and fit them into the funder's format this year","Agree with the funder that software deliverables are tracked in a separate plan under its own owner, outside the scope breakdown"],ans:[1],why:["Sai: định dạng backlog phù hợp cho phần mềm và đúng nếu nhà tài trợ chấp nhận cả hai dòng theo kiểu agile, nhưng họ đặt các mốc xây dựng và cần cấu trúc phân rã có chủ sở hữu; ép phần xây dựng vào epic làm mất kiểm soát khối lượng và mốc.","Đúng: điều khoản tài trợ cho phép bổ sung chi tiết khi biết thêm, nên phần xây dựng đã rõ được phân rã chi tiết và phần mềm ở mức tổng hợp có chủ sở hữu, phân rã dần (rolling wave) khi tính năng được làm rõ.","Sai: buộc liệt kê chi tiết đúng nếu tính năng phần mềm đã biết, nhưng ở đây chưa thể; danh sách chi tiết chưa biết là danh sách giả, sẽ phải sửa nhiều lần và không làm tăng độ tin cậy với nhà tài trợ.","Sai: kế hoạch riêng với người chịu trách nhiệm là cách hợp lệ để theo dõi phần mềm, nhưng điều khoản tài trợ yêu cầu mọi sản phẩm bàn giao nằm trong cùng một bản phân rã; loại phần mềm ra làm nhà tài trợ không thấy toàn bộ phạm vi."],exp:"Task Process 2 (enabler: break down scope). Hybrid cho phép mức chi tiết khác nhau cho phần rõ và phần chưa rõ; phân rã tăng dần khi thông tin đến. Bẫy: chi tiết hóa giả hoặc bỏ phần chưa rõ khỏi phạm vi."},{id:"o341",n:341,t:0,origin:"original",eco:"R2",domain:"process",approach:"predictive",tags:["predictive","eco-2026","requirements-validation","prototype","sign-off"],type:"mc",q:"Requirements for a hospital scheduling system were signed off by department heads from a 120-page document. During user acceptance testing, nurses say the screens do not match how they work, and several department heads admit they never read the whole document. What should the project manager have done to obtain real agreement on scope?",opts:["Run a formal requirements review in which each department head presented their section and the team recorded objections","Obtained sign-off from the CIO and the sponsor as well as the department heads, to widen the approval","Walked end users and heads through prototypes so that their understanding was confirmed before sign-off","Added a traceability matrix so that each signed requirement could be tested during acceptance"],ans:[2],why:["Sai: buổi rà soát chính thức nghe hợp lý, nhưng các trưởng khoa trình bày theo tài liệu 120 trang và y tá, người dùng thật, không tham gia; hiểu biết vẫn dựa trên văn bản chứ không phải trải nghiệm.","Sai: thêm chữ ký của CIO và sponsor mở rộng phê duyệt trên giấy, nhưng vấn đề là người dùng không hiểu hay đồng ý với màn hình; thêm người ký không xác nhận được điều đó.","Đúng: duyệt phạm vi cần sự hiểu thật. Dùng nguyên mẫu hoặc wireframe với cả trưởng khoa và người dùng cuối để họ phản hồi, rồi mới ký, giúp phát hiện sớm sai lệch.","Sai: ma trận truy vết giúp kiểm thử từng yêu cầu đã ký, nhưng nó giả định các yêu cầu đã đúng; vấn đề ở đây là yêu cầu không khớp cách y tá làm việc, và ma trận không phát hiện được điều đó."],exp:"Task Process 2 (enabler: obtain stakeholder agreement on project scope). Đồng thuận có ý nghĩa cần bằng chứng hiểu, dùng cách trực quan với đúng người. Bẫy: coi chữ ký là bằng chứng đồng thuận."},{id:"o211",n:211,t:0,origin:"original",eco:"R3",domain:"process",approach:"agile",tags:["agile","eco-2026","value-components","stakeholder-alignment"],type:"mc",q:"A hospital innovation group sponsors an app for patient discharge instructions. Doctors say value is a shorter discharge process, nurses say fewer callbacks, and finance wants fewer readmissions. The product owner has a long backlog but no agreed definition of value, and sprint 1 starts next week. The sponsor has said the groups must settle what value means among themselves. What should the project manager do?",opts:["Ask the product owner to run a prioritization workshop on the existing backlog using value points, then start sprint 1","Ask the sponsor to rank the three groups' views of value, and tell the other groups what was decided","Let the product owner pick the measure with the biggest financial effect and begin sprint 1 with that measure","Bring doctors, nurses, and finance together to settle the value components, then hand them to the product owner"],ans:[3],why:["Sai: workshop xếp thứ tự bằng điểm giá trị là kỹ thuật tốt, nhưng nó cần một định nghĩa giá trị chung để chấm điểm; ba nhóm đang hiểu giá trị khác nhau nên điểm số sẽ phản ánh nhóm nói to nhất.","Sai: sponsor đã nói các nhóm phải tự thống nhất ý nghĩa của giá trị; nhờ sponsor xếp hạng rồi thông báo là áp đặt, và các nhóm không đồng ý sẽ khó cam kết với kết quả. Đúng nếu sponsor chịu trách nhiệm chọn, nhưng ở đây thì không.","Sai: Chọn thước đo theo tác động tài chính lớn nhất bỏ qua góc nhìn bác sĩ và y tá, trong khi những người này sẽ dùng ứng dụng hằng ngày.","Đúng: xác định các thành phần giá trị cùng các bên chính trước khi thực thi. Thống nhất cách nhận biết từng giá trị, rồi product owner dùng làm cơ sở ưu tiên backlog."],exp:"Task Process 3 (enabler: identify value components with key stakeholders). Giá trị có nhiều thành phần theo từng nhóm; PM tạo điều kiện để họ thống nhất trước khi ưu tiên công việc. Bẫy: để một vai trò chọn giá trị thay các nhóm khác hoặc bắt đầu rồi tìm hiểu giá trị sau."},{id:"o342",n:342,t:0,origin:"original",eco:"R3",domain:"process",approach:"agile",tags:["agile","eco-2026","prioritization","stakeholder-feedback","backlog"],type:"mc",q:"After the second sprint review of an e-learning product, users strongly asked for an offline mode, while the top backlog item is a social feed favored by the marketing director. Analytics show 40 percent of learners study on commutes with no signal. The product charter gives the product owner authority over backlog order, and the product owner is unsure how to reorder. What should the project manager advise?",opts:["Advise the product owner to reorder the backlog on the user evidence, then explain the trade-off to the marketing director","Set up an A/B prototype test of offline mode and the social feed with a sample of learners, and reorder after two sprints of results","Escalate to the sponsor to rule between the marketing director and the user evidence, and pass the ruling to the product owner","Split the next sprint evenly between offline mode and the social feed, and revisit the split at the following sprint planning"],ans:[0],why:["Đúng: ưu tiên dựa trên giá trị và bằng chứng (40 % người học không có sóng, phản hồi mạnh). Product owner có quyền sắp xếp backlog theo điều lệ; PM hỗ trợ họ giải thích đánh đổi cho giám đốc marketing để giữ sự đồng thuận.","Sai: kiểm thử A/B là cách tốt để có bằng chứng khi chưa rõ, nhưng đã có phân tích cho thấy 40 % người học học khi không có sóng và người dùng yêu cầu rõ ràng; thêm hai sprint chỉ trì hoãn quyết định đã đủ dữ liệu.","Sai: sponsor có thể phân xử khi product owner không có quyền hoặc hai bên không thể thống nhất, nhưng thứ tự backlog thuộc về product owner theo điều lệ; chuyển việc lên sponsor khi bằng chứng đã sẵn làm mờ vai trò của họ.","Sai: chia đôi sprint đúng nếu hai tính năng có giá trị ngang nhau, nhưng bằng chứng nghiêng hẳn về chế độ ngoại tuyến; thỏa hiệp để làm hài lòng cả hai bên là ưu tiên theo chính trị, không theo giá trị, và cả hai tính năng bị chậm."],exp:"Task Process 3 (enabler: prioritize work based on value and stakeholder feedback). Ưu tiên theo giá trị và bằng chứng, giao tiếp rõ đánh đổi với bên có ảnh hưởng. Bẫy: để thẩm quyền hoặc cân bằng chính trị thay thế cho giá trị."},{id:"o343",n:343,t:0,origin:"original",eco:"R3",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","incremental-delivery","hybrid","release-planning"],type:"mc",q:"A logistics company is building a warehouse-management platform using stage gates for infrastructure and sprints for features. The plan delivers everything at a single go-live after 14 months. Operations says three modules (inbound scanning, labeling, dock scheduling) could run independently and would reduce errors right away. Operations and the team have already confirmed that the three modules do not depend on the rest of the platform. The sponsor has delegated release scheduling to the project manager within the approved budget and 14-month end date, and an early release changes neither scope nor cost. What should the project manager do?",opts:["Verify whether the three modules can ship independently, and hold the plan unchanged until operations documents the result","Schedule the three modules for release next quarter, and update the integrated plan and release schedule to show it","Release the three modules in the next sprint outside the gate process, to prove the platform's value quickly","Raise a change request for the early release of the three modules, for the steering committee to review at the next scheduled gate"],ans:[1],why:["Sai: kiểm tra tính độc lập là bước đúng khi chưa biết các mô-đun có độc lập không, nhưng vận hành và đội đã xác nhận ba mô-đun không phụ thuộc; làm lại việc xác nhận chỉ trì hoãn.","Đúng: tính độc lập đã được xác nhận, sponsor đã ủy quyền lịch phát hành cho PM và việc phát hành sớm không đổi phạm vi hay chi phí, nên PM lên kế hoạch phát hành sớm ba mô-đun và cập nhật kế hoạch tích hợp cùng lịch phát hành.","Sai: phát hành sớm đúng hướng, nhưng đưa ra ngoài quy trình gate và ngay sprint tới bỏ qua kiểm thử tích hợp, kế hoạch vận hành và đào tạo; kế hoạch cần cập nhật trước khi phát hành.","Sai: change request đúng thủ tục nếu việc phát hành sớm đổi phạm vi, chi phí, ngày kết thúc hoặc vượt thẩm quyền của PM, nhưng ở đây không có điều nào; chờ gate tiếp theo làm chậm một việc đã được xác nhận khả thi và nằm trong quyền của PM."],exp:"Task Process 3 (enabler: assess opportunities to deliver value incrementally). Khi tính độc lập của các mô-đun đã được xác nhận và thay đổi nằm trong quyền của PM, PM lên kế hoạch phát hành sớm và cập nhật kế hoạch tích hợp thay vì xác nhận lại. Bẫy: giữ big-bang, kiểm tra lại điều đã xác nhận, phát hành vượt quy trình, hoặc đưa việc trong quyền của mình qua change control."},{id:"o344",n:344,t:0,origin:"original",eco:"R3",domain:"process",approach:"predictive",tags:["predictive","eco-2026","business-case","benefits","value-review"],type:"mc",q:"A manufacturer approved a three-year ERP replacement on a business case promising a 12 percent inventory cost reduction. Eighteen months in, the company has sold its lowest-margin product line, which accounted for a third of the expected inventory savings. The project is on schedule and within budget. Finance and the sponsor have already recalculated the benefit at 8 percent, which is still above the remaining cost to complete. What should the project manager do?",opts:["Recalculate the benefits with the sponsor and compare them with the remaining cost before recommending continue, rescope, or stop","Recommend continuing with a revised business case and an 8 percent benefit target, and submit the change for approval","Complete the project and report the reduced benefits at closure as part of the final lessons learned review","Continue with the plan, as the project remains on schedule and within budget and the sponsor has not objected"],ans:[1],why:["Sai: tính lại lợi ích cùng sponsor là bước đúng khi chưa có số liệu, nhưng tài chính và sponsor đã tính lại ở mức 8 % và vẫn lớn hơn chi phí còn lại; tính lại chỉ trì hoãn khuyến nghị.","Đúng: lợi ích đã được tính lại và vẫn vượt chi phí còn lại, nên PM khuyến nghị tiếp tục với business case sửa đổi và mục tiêu 8 %, rồi trình thay đổi để được duyệt.","Sai: Chờ tới đóng dự án mới báo cáo là quá muộn để tác động; 18 tháng chi phí còn lại có thể đã được dùng cho kết quả giảm giá trị.","Sai: Đúng tiến độ và ngân sách chưa nói gì về giá trị kinh doanh; lợi ích mong đợi đã giảm nên cần xem lại."],exp:"Task Process 3 (enabler: examine the business value throughout the project). Khi lợi ích đã được tính lại và vẫn lớn hơn chi phí còn lại, PM khuyến nghị tiếp tục với business case sửa đổi và xin duyệt, thay vì tính lại. Bẫy: nhầm đúng tiến độ với còn giá trị, hoặc giấu thay đổi lợi ích tới khi đóng dự án."},{id:"o345",n:345,t:0,origin:"original",eco:"R3",domain:"process",approach:"predictive",tags:["predictive","eco-2026","ai","benefits-tracking","baseline-metrics"],type:"mc",q:"A bank's steering committee approved an AI transaction-screening project meant to cut false alerts by 25 percent. The plan has detailed technical milestones but no baseline for the current false-alert rate and no named owner for tracking benefits after go-live. Build is 40 percent complete. Naming a benefits owner in the business is a governance decision that belongs to the sponsor, and the project manager has no authority to appoint one. What should the project manager do?",opts:["Ask the vendor to run the tool in shadow mode on historical alerts with the bank's data team, and take its results as the false-alert baseline","Add benefit-tracking tasks to the operations team's backlog, for its product owner to pick up once the project is closed and handed over","Escalate to the sponsor, asking for a named benefit owner, plus an agreed baseline, metrics, and data sources for false alerts","Accept the accuracy figures reported by the vendor's tool as the benefit measure, and have the vendor's lead record them in the benefits register"],ans:[2],why:["Sai: chạy bóng trên dữ liệu cũ là cách hợp lý để thử mô hình, nhưng baseline cần là tỷ lệ cảnh báo giả hiện tại của ngân hàng; số của nhà cung cấp trên công cụ của chính họ không độc lập và vẫn chưa có chủ sở hữu theo dõi lợi ích.","Sai: chuyển sang đội vận hành sau khi dự án đóng là quá muộn để thu baseline, và trong thời gian triển khai vẫn không có chủ sở hữu; đúng nếu baseline đã có và chỉ cần người nhận bàn giao.","Đúng: chỉ định chủ sở hữu lợi ích là quyết định quản trị thuộc sponsor, PM không có quyền tự bổ nhiệm, nên PM leo thang và nhờ sponsor chỉ định người đó cùng thống nhất baseline false alert, thước đo và nguồn dữ liệu khi dự án còn chạy, vì sau đó sẽ không thu được baseline.","Sai: số liệu do chính công cụ AI báo cáo chưa được kiểm chứng độc lập; cần dữ liệu từ hệ thống của ngân hàng để đo lợi ích thật, và ghi vào benefits register không thay cho việc có chủ sở hữu."],exp:"Task Process 3 (enabler: verify a measurement system is in place to track benefits). AI là bối cảnh; điều cần có là hệ thống đo lợi ích với baseline, người sở hữu và dữ liệu độc lập với bên bán. Người sở hữu lợi ích do sponsor chỉ định nên PM leo thang. Bẫy: đo sau khi đã thay đổi hoặc tin số liệu của chính công cụ."},{id:"o346",n:346,t:0,origin:"original",eco:"R3",domain:"process",approach:"agile",tags:["agile","eco-2026","delivery-options","value-demonstration","mvp"],type:"mc",q:"A team building a customer-onboarding app is asked by the sponsor to show value to the board in six weeks. The full feature set needs four months. The board has already said it cares about shorter sign-up time, and manual document checks are the slowest step. The team could release a working identity-verification slice, show a clickable prototype of the full flow, or present a roadmap deck. Which option should the project manager recommend?",opts:["Present a clickable prototype of the entire onboarding flow, built with the designers, to show the board the complete product vision at the review","Present a roadmap deck with projected sign-up improvements, prepared with the product owner, and keep unfinished software out of the review","Release the working identity-verification slice to a small group of users, and report the measured sign-up time at the review","Interview the board members on what evidence of value they would accept, and choose what to show from their answers"],ans:[2],why:["Sai: nguyên mẫu cho thấy tầm nhìn và đúng nếu ban lãnh đạo muốn xem trải nghiệm, nhưng họ quan tâm thời gian đăng ký thực tế; nguyên mẫu không chứng minh giá trị bằng số đo thật.","Sai: slide dự báo đúng nếu chưa có gì chạy được, nhưng ở đây có thể giao một lát cắt thật; dự báo là giá trị trên giấy, ban lãnh đạo khó tin con số chưa từng đo.","Đúng: lát cắt xác minh danh tính giải quyết bước chậm nhất, chạy thật với nhóm nhỏ và đo được thời gian đăng ký, chứng minh giá trị đúng điều ban lãnh đạo quan tâm sau sáu tuần.","Sai: hỏi ban lãnh đạo cần bằng chứng nào là hợp lý khi chưa rõ họ quan tâm gì, nhưng đề bài đã nêu họ quan tâm thời gian đăng ký ngắn hơn và bước kiểm tra giấy tờ là chậm nhất; phỏng vấn thêm sẽ tốn thời gian trong sáu tuần."],exp:"Task Process 3 (enabler: evaluate delivery options to demonstrate value). Chọn phương án giao hàng cho bằng chứng thật và đo được gắn với điều mà bên liên quan quan tâm. Bẫy: nhầm minh họa hoặc dự báo với giá trị đã giao."},{id:"o347",n:347,t:0,origin:"original",eco:"R3",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","prioritization","hybrid","value-vs-risk"],type:"mc",q:"A hybrid project upgrading a retail chain's point-of-sale system combines fixed hardware rollout waves with software features chosen by store managers. Store managers rank faster returns handling highest, while the IT architect wants to build the reporting module first because it has no dependencies. Returns handling needs nothing from the hardware waves, and the reporting module would not shorten queues. The sponsor's goal is shorter queues. How should the project manager prioritize?",opts:["Alternate sprints between returns handling and the reporting module, and treat both items as equal in sprint planning","Ask the hardware rollout lead to rank the features by installation order, and follow that sequence in the sprints","Build the reporting module first, as it carries the least technical risk and gives the team a quick start","Prioritize returns handling in the backlog, and schedule the reporting module by its contribution to queue time"],ans:[3],why:["Sai: luân phiên là đúng nếu hai mục có giá trị ngang nhau, nhưng ở đây xử lý trả hàng gắn với mục tiêu hàng đợi còn báo cáo thì không; chia đều để công bằng giữa các bên là ưu tiên theo người, không theo giá trị.","Sai: thứ tự lắp đặt phần cứng đáng theo nếu tính năng phụ thuộc vào các đợt triển khai, nhưng ở đây xử lý trả hàng không cần gì từ phần cứng; người dẫn triển khai phần cứng cũng không sở hữu ưu tiên phần mềm.","Sai: rủi ro kỹ thuật thấp và không phụ thuộc là lý do hợp lý cho thứ tự xây dựng nếu giá trị tương đương, nhưng mục tiêu của sponsor là rút ngắn hàng đợi và mô-đun báo cáo không đóng góp trực tiếp.","Đúng: ưu tiên theo giá trị và phản hồi: xử lý trả hàng gắn với mục tiêu hàng đợi và được quản lý cửa hàng xếp hạng cao nhất; mô-đun báo cáo xếp theo đóng góp giá trị của nó."],exp:"Task Process 3 (enabler: prioritize work based on value and stakeholder feedback). Với hybrid, thứ tự công việc phần mềm vẫn do giá trị và phản hồi quyết định, không phải sự thuận tiện kỹ thuật. Bẫy: chọn theo rủi ro thấp hoặc theo công bằng giữa người."},{id:"o348",n:348,t:0,origin:"original",eco:"R3",domain:"process",approach:"predictive",tags:["predictive","eco-2026","incremental-delivery","phased-opening","cost-benefit"],type:"mc",q:"A highway authority is replacing a river bridge in two stages, and the plan opens the new bridge to traffic at completion in month 30. Traffic engineers note that after stage one the first two lanes could carry traffic and relieve a daily bottleneck, at some added temporary-works cost. Safety engineers and the authority have already approved opening two lanes after stage one, at a temporary-works cost within the contingency reserve. What should the project manager do?",opts:["Assess safety, cost, and schedule effects with the engineers and the authority before proposing a phased opening","Ask the contractor to open the two lanes after stage one and settle the temporary-works payment afterwards","Keep the single opening at month 30, since the approved baseline specifies that completion date for the traffic","Raise a change request to open the two lanes after stage one funded from the contingency reserve and update the schedule baseline"],ans:[3],why:["Sai: đánh giá an toàn, chi phí và tiến độ cùng kỹ sư là bước đúng khi chưa có chấp thuận, nhưng kỹ sư an toàn và cơ quan quản lý đã chấp thuận mở hai làn và chi phí nằm trong dự phòng; đánh giá lại chỉ trì hoãn lợi ích cho giao thông.","Sai: mở sớm đem lại lợi ích thật, nhưng giao nhà thầu mở làn trước khi có thay đổi được duyệt bỏ qua kiểm soát thay đổi và quyền quyết định về thanh toán; baseline và hợp đồng phải được cập nhật trước.","Sai: Baseline là cơ sở, không phải lý do bỏ qua cơ hội có giá trị; thay đổi hợp lý vẫn có thể được đề xuất qua quy trình.","Đúng: các chấp thuận về an toàn và chi phí đã có, nên PM trình thay đổi để mở hai làn sau giai đoạn một, dùng dự phòng và cập nhật baseline tiến độ."],exp:"Task Process 3 (enabler: assess opportunities to deliver value incrementally; manage changes). Khi an toàn và chi phí của việc mở sớm đã được chấp thuận, PM xử lý bằng change request cập nhật baseline thay vì đánh giá lại. Bẫy: đánh giá lại điều đã duyệt, mở sớm ngoài kiểm soát thay đổi, hoặc giữ baseline cũ mặc dù lợi ích rõ."},{id:"o349",n:349,t:0,origin:"original",eco:"R3",domain:"process",approach:"agile",tags:["agile","eco-2026","benefits-measurement","outcome-metrics","product-owner"],type:"mc",q:"A team delivered a self-service returns portal, and stakeholders call the release a success because all stories were accepted. The business case promised a 20 percent drop in support calls, but nobody is tracking calls and the product owner has moved on to the next epic. The support leads can supply call volumes for the last six months. What should the project manager do?",opts:["Run a customer survey with the support leads on the portal's usefulness, and report the satisfaction score each quarter as the measure of benefit","Add call volume, plus its six-month baseline, to the release's success criteria, then review the trend monthly with the support leads","Ask the product owner to add a portal-usage dashboard story to the backlog, and report weekly active users as the benefit measure","Close out the release in the project records with the sponsor's sign-off on the accepted stories, and report the delivery as a success for the business"],ans:[1],why:["Sai: khảo sát mức hài lòng là dữ liệu hữu ích về trải nghiệm và đúng nếu business case hứa tăng hài lòng, nhưng ở đây hứa giảm 20 % cuộc gọi hỗ trợ; hài lòng cao vẫn không cho biết số cuộc gọi có giảm hay không.","Đúng: đưa thước đo lượng cuộc gọi kèm baseline (đội hỗ trợ có số liệu sáu tháng) vào tiêu chí thành công của release và xem xu hướng cùng các trưởng nhóm hỗ trợ; đây là hệ thống đo lợi ích đúng với cam kết giảm 20 %.","Sai: số lượt dùng cổng cho biết hành vi và đúng nếu cam kết là tăng mức sử dụng, nhưng không trả lời liệu số cuộc gọi hỗ trợ có giảm; đo sai đại lượng lợi ích.","Sai: chấp nhận story đo kết quả đầu ra, không đo lợi ích; business case hứa giảm 20 % cuộc gọi nên đóng release sớm bỏ qua cam kết giá trị. Đúng chỉ khi business case chỉ hứa giao tính năng."],exp:"Task Process 3 (enabler: verify a measurement system is in place to track benefits). Giao deliverable không đồng nghĩa đạt lợi ích; cần thước đo bám sát lợi ích đã cam kết. Bẫy: dùng chỉ số đầu ra hoặc chỉ số hành vi thay cho chỉ số kết quả."},{id:"o350",n:350,t:0,origin:"original",eco:"R3",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","value-components","regulator","reporting"],type:"mc",q:"A utility is deploying smart meters under a fixed rollout contract, in a hybrid project that also builds a customer app in sprints. Engineering defines value as installed meter count, customer service as fewer billing disputes, and the regulator as accurate readings. The three groups have never compared their definitions, and reports so far track only meter counts. What should the project manager do?",opts:["Define the value components and measures with the three groups, and update the reports to cover each measure","Agree with the customer service lead to replace meter count with billing disputes as the single measure in the project reports","Ask the app's product owner to add a billing-dispute dashboard to the backlog, and keep the contract reporting based on meter count","Ask the regulator's liaison to decide which definition of value the project follows, and report against it from now on"],ans:[0],why:["Đúng: ba nhóm chưa từng so sánh định nghĩa nên PM xác định các thành phần giá trị cùng họ, rồi cập nhật báo cáo để theo dõi cả số lượng, tranh chấp hóa đơn và độ chính xác.","Sai: thay hoàn toàn bằng số tranh chấp hóa đơn là đúng nếu chỉ có bộ phận chăm sóc khách hàng quyết định giá trị, nhưng nó bỏ qua yêu cầu về độ chính xác của cơ quan quản lý và tiến độ lắp đặt đã cam kết trong hợp đồng.","Sai: bảng điều khiển tranh chấp hóa đơn giải quyết góc nhìn của chăm sóc khách hàng, nhưng báo cáo chính vẫn chỉ đo số đồng hồ; cơ quan quản lý không thấy độ chính xác được theo dõi và các nhóm chưa thống nhất định nghĩa giá trị.","Sai: để cơ quan quản lý chọn định nghĩa duy nhất là đúng nếu chỉ có tuân thủ quy định đáng kể, nhưng họ chỉ là một bên liên quan; cách này bỏ qua nhu cầu của khách hàng và kỹ thuật."],exp:"Task Process 3 (enabler: identify value components with key stakeholders). Giá trị đa chiều: PM tổng hợp quan điểm từ các nhóm thành bộ thước đo chung. Bẫy: chọn một thước đo dễ đo hoặc một nhóm duy nhất."},{id:"o351",n:351,t:0,origin:"original",eco:"R3",domain:"process",approach:"predictive",tags:["predictive","eco-2026","prioritization","budget-cut","value-for-cost"],type:"mc",q:"Midway through a plant-modernization project, the board cuts the remaining budget by 15 percent. Twelve work packages remain and the sponsor asks the project manager which to drop. Packages vary in cost, and stakeholders disagree about which matter most. The sponsor and key stakeholders have already agreed a ranking of the twelve packages by value against cost. What is the best approach?",opts:["Rank the packages with key stakeholders by value against cost before proposing which ones to drop","Apply an equal 15 percent reduction to each package, balancing the scope across the areas of the plant","Propose dropping the lowest-ranked packages until the 15 percent is recovered and raise a change request","Drop the most expensive packages first, as this recovers the 15 percent with the fewest cuts to the remaining scope"],ans:[2],why:["Sai: xếp hạng với các bên liên quan là đúng khi họ bất đồng, nhưng sponsor và các bên đã thống nhất thứ hạng theo giá trị so với chi phí; làm lại là lặp lại và trì hoãn việc cắt giảm hội đồng đã yêu cầu.","Sai: Cắt đều mọi gói có thể làm hỏng những gói không thể giảm quy mô mà vẫn dùng được; không dựa trên giá trị.","Đúng: thứ hạng đã được thống nhất, nên PM đề xuất bỏ các gói xếp thấp nhất cho đủ 15 % và trình change request kèm đánh đổi cho sponsor duyệt.","Sai: Gói đắt nhất chưa chắc ít giá trị nhất; cắt theo chi phí có thể loại bỏ phần mang lại lợi ích chính."],exp:"Task Process 2 (enabler: manage scope changes under budget cuts). Khi thứ hạng giá trị so với chi phí đã được các bên thống nhất, PM đề xuất cắt theo thứ hạng và trình change request kèm đánh đổi. Bẫy: xếp hạng lại điều đã đồng ý, cắt đều, hoặc cắt theo chi phí mà bỏ qua giá trị."},{id:"o352",n:352,t:0,origin:"original",eco:"R3",domain:"process",approach:"agile",tags:["agile","eco-2026","incremental-delivery","early-release","product-owner"],type:"mc",q:"A telecom company's team plans to release a new billing portal as one large launch after eight sprints. A support manager points out that account-balance viewing, built in sprint 2, would already remove about a third of customer calls. The product owner worries about releasing a partial portal. The product owner has agreed to a limited release of balance viewing once support confirms it can handle the extra calls, and support has confirmed it can. The two have also agreed the release criteria, based on call volume. What should the project manager do?",opts:["Discuss a limited early release of balance viewing with the product owner and settle the release criteria","Release balance viewing to a pilot group of customers in the next sprint, and track call volume against the agreed criteria","Ask the support manager to draft the release plan, as the support team will absorb the extra calls first","Release balance viewing to the customer base next sprint, as the support manager has already shown the benefit"],ans:[1],why:["Sai: bàn với product owner về phát hành giới hạn là bước đúng khi chưa có thỏa thuận, nhưng product owner đã đồng ý với điều kiện hỗ trợ xác nhận và hỗ trợ đã xác nhận; họp lại chỉ làm chậm lợi ích một phần ba cuộc gọi.","Đúng: các điều kiện đã được thỏa mãn, nên PM cùng đội phát hành chức năng xem số dư cho nhóm khách thí điểm ở sprint tới và theo dõi lượng cuộc gọi theo tiêu chí đã thống nhất.","Sai: Kế hoạch phát hành thuộc về product owner cùng đội; bộ phận hỗ trợ là bên liên quan cung cấp thông tin, không sở hữu quyết định.","Sai: phát hành rộng cho toàn bộ khách hàng ở sprint sau bỏ qua cơ hội học từ nhóm nhỏ và tăng rủi ro nếu có lỗi; product owner mới có quyền quyết định phát hành và tiêu chí."],exp:"Task Process 3 (enabler: assess opportunities to deliver value incrementally). Khi product owner và bộ phận hỗ trợ đã thống nhất điều kiện, đội phát hành giới hạn và đo kết quả thay vì bàn thêm. Bẫy: giữ big-bang, họp lại điều đã đồng ý, hoặc phát hành rộng mà không có nhóm thí điểm."},{id:"o353",n:353,t:0,origin:"original",eco:"R3",domain:"process",approach:"predictive",tags:["predictive","eco-2026","delivery-options","value-demonstration","public-sector"],type:"mc",q:"A municipality is building a flood-warning system on a 24-month plan. With the storm season starting in month 10, councillors ask whether the project can show useful results before then. The team sees two feasible early options: a sensor network in the highest-risk district, or a citywide public alert app using existing data feeds. The team's comparison, reviewed by the city's risk officer, shows the alert app can be live by month 8, while the sensor network cannot be certified before month 12. What should the project manager do?",opts:["Recommend the alert app for the storm season starting in month 10, and plan the sensor network as a later phase in the baseline","Commission an independent analysis of the two options from an outside consultant before any recommendation goes to the councillors","Recommend the sensor network as the engineers prefer it, and begin procurement of the sensors this quarter","Run a pilot of each option in the highest-risk district, and decide between them after the pilots report"],ans:[0],why:["Đúng: so sánh đã được cán bộ rủi ro của thành phố xem xét và cho thấy ứng dụng cảnh báo kịp tháng 8 còn mạng cảm biến chưa chứng nhận trước tháng 12, nên PM khuyến nghị ứng dụng cho mùa bão tháng 10 và đưa mạng cảm biến thành giai đoạn sau trong baseline 24 tháng.","Sai: phân tích độc lập từ tư vấn bên ngoài là bước đúng khi chưa có so sánh đáng tin, nhưng đội đã có so sánh được cán bộ rủi ro xem xét cho thấy chỉ ứng dụng kịp tháng 10; thuê thêm chỉ trì hoãn khuyến nghị trước mùa bão.","Sai: kỹ sư thích mạng cảm biến vì giảm rủi ro cao ở khu vực nguy hiểm, nhưng mạng này chưa thể chứng nhận trước tháng 12 nên không có ích cho mùa bão bắt đầu tháng 10.","Sai: thí điểm từng phương án là cách tốt để học khi chưa biết, nhưng mùa bão bắt đầu tháng 10 và so sánh đã cho thấy phương án nào kịp; chờ kết quả thí điểm làm mất mùa bão."],exp:"Task Process 3 (enabler: assess opportunities to deliver value incrementally). Khi so sánh đã được xem xét và cho thấy chỉ một phương án kịp mốc giá trị, PM khuyến nghị phương án đó và đặt phần còn lại vào giai đoạn sau trong baseline. Bẫy: làm lại phân tích đã có, chọn theo ý thích của kỹ sư, hoặc thí điểm quá muộn."},{id:"o212",n:212,t:0,origin:"original",eco:"R4",domain:"process",approach:"agile",tags:["agile","eco-2026","resource-planning","team-formation","capacity"],type:"mc",q:"A product owner needs a new scrum team to build a mobile loyalty app starting in six weeks. The available engineers are spread over three other products at about 30 percent each, and the payments and accessibility specialists are shared with other teams. Nobody has yet compared the backlog's skill needs with the people available, and the sponsor has not ranked this app above the other three products. The project manager is asked to propose how to staff the team. What should the project manager do first?",opts:["Open a sourcing request with the hiring manager for contractors in the payments and accessibility roles, and fill the other seats from the available engineers","Map the backlog's skill needs against the available people with the three functional managers, and secure dedicated capacity for the new team","Escalate to the sponsor to rank this app above the other three products and release the shared engineers to the new team","Ask the three product managers to nominate engineers for the team, and record the nominees' availability in the resource management plan"],ans:[1],why:["Sai: thuê ngoài là đúng nếu phân tích kỹ năng đã cho thấy nội bộ không có người làm thanh toán hay khả năng tiếp cận, nhưng ở đây chưa ai so sánh nhu cầu với người sẵn có; thuê trước khi biết thiếu gì là tốn kém và bỏ qua kiến thức sản phẩm.","Đúng: lập kế hoạch nguồn lực bắt đầu từ yêu cầu của công việc, tức là kỹ năng backlog cần. Đối chiếu với người sẵn có rồi thương lượng năng lực chuyên trách với các functional manager, vì chưa có phân tích nào làm cơ sở cho lựa chọn khác.","Sai: nhờ sponsor xếp ứng dụng này lên trên ba sản phẩm kia là đúng nếu việc đó đã được cân nhắc, nhưng đề bài nói sponsor chưa xếp hạng và chưa ai biết cần bao nhiêu người; leo thang sớm ảnh hưởng nặng tới các dự án khác khi chưa thương lượng ở cấp quản lý chức năng.","Sai: để các product manager đề cử người nhanh và ít xung đột, và hợp nếu danh sách kỹ năng đã được chốt, nhưng ở đây chưa so kỹ năng; chọn theo người sẵn sàng bỏ qua việc khớp kỹ năng thanh toán và khả năng tiếp cận."],exp:"Task Process 4 (enabler: define and plan resources based on requirements). Bắt đầu từ nhu cầu kỹ năng, sau đó mới đến nguồn cung và thương lượng. Bẫy: bố trí theo người sẵn có rồi hy vọng đội thích nghi, hoặc nhảy sang tuyển dụng."},{id:"o354",n:354,t:0,origin:"original",eco:"R4",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","resource-conflict","availability","hybrid"],type:"mc",q:"In a hybrid factory-automation project, the controls engineer is needed for gated commissioning work in week 12 and also for fortnightly sprint demonstrations of the operator interface. A new request has pushed commissioning into the same weeks as three demos. The demo calendar belongs to the product owner, who has declined to move the demos, and extra support can only be approved by the sponsor; the project manager can do neither alone. The engineer says both cannot be done well. What should the project manager do?",opts:["Tell the engineer to prioritize commissioning and drop the demos, as the gate dates are fixed by the contract","Ask the engineer to run both activities in parallel on the original dates, using a personal task schedule to keep each on track","Escalate to the sponsor with the engineer's workload data, asking for a decision to move the demos or fund extra support","Review both workloads with the engineer and the leads, then rearrange the demos or add support to remove the overload"],ans:[2],why:["Sai: bỏ các buổi demo là đúng nếu PM có thẩm quyền và demo ít giá trị, nhưng ở đây PM không sở hữu lịch demo; bỏ demo mà chưa thử phương án khác có thể làm mất phản hồi của người dùng giao diện.","Sai: lịch cá nhân không tạo thêm thời gian; kỹ sư đã nói không thể làm tốt cả hai việc, nên chỉ chuyển vấn đề sang chất lượng của cả hai. Đúng nếu xung đột chỉ nằm ở cách sắp xếp trong ngày, nhưng ở đây hai việc trùng nhau trong nhiều tuần.","Đúng: lịch demo thuộc product owner đã từ chối dời và hỗ trợ thêm chỉ sponsor duyệt được, nên PM không tự xử lý; PM leo thang kèm dữ liệu tải của kỹ sư và nhờ sponsor quyết định dời demo hoặc cấp thêm hỗ trợ.","Sai: xem tải rồi tự sắp xếp lại demo hoặc thêm hỗ trợ là đúng nếu PM kiểm soát lịch demo và ngân sách hỗ trợ, nhưng ở đây cả hai nằm ngoài quyền PM; tự làm là vượt thẩm quyền, cần quyết định của sponsor."],exp:"Task Process 4 (enabler: manage and optimize resource needs and availability). Xung đột nguồn lực: tối ưu trong thẩm quyền của PM trước, nhưng khi lịch và ngân sách nằm ngoài quyền thì PM leo thang kèm dữ liệu để người có thẩm quyền quyết định. Bẫy: hy sinh một cam kết, tự vượt quyền hoặc dùng làm thêm giờ."},{id:"o355",n:355,t:0,origin:"original",eco:"R4",domain:"process",approach:"predictive",tags:["predictive","eco-2026","resource-management-plan","wbs","estimating"],type:"mc",q:"A hospital is building a new emergency department over 28 months under a predictive plan. The WBS is approved and the project manager must prepare the resource management plan. The architect proposes reusing the last project's staffing level because this building is about the same size, although this one adds a trauma wing and a hybrid operating suite that the earlier WBS did not include. What should the project manager do?",opts:["Build the resource plan from the WBS work packages, listing the skills, headcount, and timing each package needs","Adopt the last project's staffing level as the resource baseline, with the architect reviewing it for overruns during construction","Ask each functional manager to nominate the staff they can spare, and fit the work packages to those people in the resource plan","Ask HR to benchmark staffing levels of similar hospital projects, and set the headcount in the plan from the benchmark median"],ans:[0],why:["Đúng: yêu cầu nguồn lực phải suy ra từ gói công việc và lịch trình của chính dự án này, gồm cả cánh chấn thương và phòng mổ hybrid: kỹ năng, số lượng, thời điểm; ghi vào resource management plan.","Sai: dùng lại mức nhân sự cũ đúng nếu hai công trình có phạm vi giống hệt, nhưng ở đây có thêm cánh chấn thương và phòng mổ hybrid; kế hoạch dựa trên giả định cùng quy mô bỏ qua khác biệt công việc và chỉ phát hiện thiếu khi đã chậm.","Sai: nhân sự mà các trưởng phòng ban có thể nhường là thông tin hữu ích cho bước thương lượng sau, nhưng kế hoạch bị điều chỉnh theo nguồn cung thay vì theo yêu cầu công việc.","Sai: dữ liệu chuẩn từ dự án tương tự là đầu vào hữu ích để đối chiếu, nhưng kế hoạch nguồn lực dự án này phải xuất phát từ các work package và tiến độ đã duyệt; headcount trung bình không cho biết kỹ năng và thời điểm cần."],exp:'Task Process 4 (enabler: define and plan resources based on requirements). Kế hoạch nguồn lực xuất phát từ WBS và lịch trình, không từ dự án cũ hay nguồn cung. Bẫy: nhận định "giống nhau" mà không phân tích.'},{id:"o356",n:356,t:0,origin:"original",eco:"R4",domain:"process",approach:"agile",tags:["agile","eco-2026","ai","tooling","data-protection","resource-planning"],type:"mc",q:"A scrum team asks to use a generative AI assistant to draft test cases. The company has no policy for such tools yet, and the product handles customers' personal health data. The product owner wants the tool in use by the next sprint. What should the project manager do first?",opts:["Let the team try the tool on real customer data in the next sprint, with the product owner reviewing the generated test cases afterward","Set the data-protection conditions for the tool with security and legal, and record them in the team's working rules before use","Let the product owner approve the tool for the team, and decide with the scrum master which sprint it starts in","Ask the product owner to document the tool's expected benefits and risks in a short business case for the sponsor to decide on"],ans:[1],why:["Sai: dùng dữ liệu sức khỏe thật để thử rồi mới xem lại có thể làm lộ dữ liệu nhạy cảm; hậu quả không thu hồi được và chưa có chính sách nào cho phép.","Đúng: công cụ AI là một nguồn lực phải đáp ứng yêu cầu bảo vệ dữ liệu sức khỏe. Cùng bộ phận bảo mật và pháp lý đặt điều kiện sử dụng trước khi đội bắt đầu; con người vẫn chịu trách nhiệm cuối cùng về kết quả kiểm thử.","Sai: product owner sở hữu backlog nên chọn sprint hợp lý, nhưng không có thẩm quyền quyết định về an toàn dữ liệu sức khỏe; việc này thuộc về bảo mật, pháp lý và quản trị tổ chức.","Sai: tài liệu lợi ích và rủi ro cho sponsor là thực hành tốt khi dùng công cụ mới, nhưng vấn đề trước mắt là dữ liệu sức khỏe cá nhân và chưa có chính sách; điều kiện bảo vệ dữ liệu phải được bảo mật và pháp lý đặt ra trước."],exp:"Task Process 4 (enabler: define and plan resources based on requirements). AI chỉ là bối cảnh: công cụ cũng là nguồn lực, cần xác định điều kiện sử dụng, nhất là với dữ liệu nhạy cảm, và vai trò chịu trách nhiệm cuối. Bẫy: thử trên dữ liệu thật hoặc cấm hoàn toàn."},{id:"o357",n:357,t:0,origin:"original",eco:"R4",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","shared-resources","hybrid","resource-leveling"],type:"mc",q:"Two streams of a hybrid product development share one environmental test chamber. The hardware stream has gated test slots booked, while the firmware stream's sprint plan needs chamber time for validation every two weeks. Both streams' results are required at the next gate review, and next month the chamber is overbooked by about 30 percent. The two stream leads have compared their needs and cannot agree; neither will give up slots. The project manager can neither rank the streams nor fund more chamber capacity, since both decisions sit with the sponsor. What should the project manager do?",opts:["Reduce the firmware stream's validation to the free slots, and record the lower coverage as accepted in the test plan","Give the hardware stream priority as its slots were booked first, and let the firmware team find alternatives","Bring both leads together to compare chamber needs, and level the bookings or rent added capacity within the stream budgets","Escalate to the sponsor with both streams' chamber needs, and ask for a ruling on priority or funding for added capacity"],ans:[3],why:["Sai: giảm kiểm chứng của firmware xuống mức vừa với slot trống và ghi nhận chấp nhận là hạ chất lượng ngầm khi gate cần kết quả của cả hai dòng. Việc cắt độ bao phủ phải là quyết định có chủ đích của người có thẩm quyền, không phải kết quả mặc định của lịch quá tải.","Sai: slot phần cứng được đặt trước, nhưng gate tiếp theo cần kết quả của cả hai dòng; cho phần cứng ưu tiên tuyệt đối thì firmware thiếu bằng chứng kiểm chứng và chính gate đó có thể bị trượt. Thứ tự đặt chỗ không thay cho quyết định ưu tiên của người có quyền.","Sai: họp lại để san lịch hay thuê thêm năng lực trong ngân sách từng dòng là đúng nếu hai trưởng nhóm chưa so nhu cầu hoặc còn quỹ để dùng, nhưng ở đây họ đã so và không thống nhất; họp thêm một vòng chỉ lặp lại tranh chấp.","Đúng: phòng thử là nguồn lực dùng chung bị quá tải khoảng 30 % và hai trưởng nhóm đã không thống nhất; xếp ưu tiên giữa hai dòng và cấp vốn thêm năng lực đều thuộc sponsor, nên PM leo thang kèm nhu cầu của cả hai dòng và nhờ sponsor quyết định."],exp:"Task Process 4 (enabler: manage and optimize resource needs and availability). Nguồn lực dùng chung bị quá tải: PM thử phân tích nhu cầu và san tải trong quyền của mình; khi các trưởng nhóm đã không thống nhất và quyết định ưu tiên hoặc cấp vốn thuộc sponsor thì PM leo thang kèm dữ liệu. Bẫy: mặc định dòng đặt chỗ trước thắng, hoặc cắt âm thầm độ bao phủ kiểm thử."},{id:"o358",n:358,t:0,origin:"original",eco:"R4",domain:"process",approach:"predictive",tags:["predictive","eco-2026","vendor-staff","critical-path","availability"],type:"mc",q:"Eleven months into a predictive ERP rollout, a vendor's lead data-migration consultant is reassigned to another client. The migration work packages are on the critical path and begin in four weeks. The contract allows the vendor to substitute staff with equivalent skills. The vendor has shared the replacement's CV, and the project's technical lead has confirmed the replacement meets the package requirements. What should the project manager do next?",opts:["Check the replacement's qualifications against the package needs with the technical lead before accepting","Move the project's own analyst onto the migration work and release the vendor from that work package now","Accept the replacement, and agree a two-week handover with the departing consultant before the migration packages start","Invoke the contract's key-personnel clause to require the original consultant to stay until the migration packages finish"],ans:[2],why:["Sai: kiểm tra năng lực người thay thế với trưởng kỹ thuật là bước đúng khi chưa có đánh giá, nhưng trưởng kỹ thuật đã xác nhận người thay đáp ứng yêu cầu gói; kiểm tra lại chỉ lặp việc đã làm trong khi gói găng bắt đầu sau bốn tuần.","Sai: Tự chuyển công việc sang nhân viên nội bộ chưa chắc đã có chuyên môn migration, lại thay đổi cấu trúc hợp đồng và giải phóng nhà cung cấp khỏi gói đường găng mà chưa phân tích hay trao đổi với họ. Phương án này chỉ hợp lý nếu đã đánh giá rằng người thay thế của nhà cung cấp không đạt.","Đúng: hợp đồng cho phép thay thế tương đương và người thay đã được xác nhận đạt yêu cầu, nên PM chấp nhận và sắp xếp hai tuần bàn giao trước khi gói đường găng bắt đầu.","Sai: điều khoản nhân sự chủ chốt giữ người ban đầu là công cụ hợp lệ khi hợp đồng nêu tên người, nhưng ở đây hợp đồng cho phép thay bằng nhân sự tương đương; viện dẫn nó dễ gây xung đột mà không có căn cứ."],exp:"Task Process 4 (enabler: manage and optimize resource needs and availability). Khi người thay thế đã được xác nhận đạt yêu cầu và hợp đồng cho phép, PM chấp nhận và quản lý chuyển giao để giảm rủi ro trên đường găng. Bẫy: kiểm tra lại điều đã xác nhận, đối đầu với nhà cung cấp, hoặc chuyển việc sang nội bộ không đủ chuyên môn."},{id:"o359",n:359,t:0,origin:"original",eco:"R4",domain:"process",approach:"agile",tags:["agile","eco-2026","bottleneck","cross-skilling","team-capacity"],type:"mc",q:`Three sprints in, a scrum team's stories keep stalling at "ready for test" because the single QA engineer cannot keep up with eight developers. The team wants two more QA engineers, but the sponsor has confirmed the budget is fixed for the year. Several developers have said they would like to learn test automation. What should the project manager do?`,opts:["Move testing of the stories into a stabilization phase at the end of the release, agreed with the product owner, to keep sprints flowing","Help the team cross-skill developers into test automation with the QA engineer coaching, then check the effect on flow at the next review","Escalate to the sponsor with the queue data and request the two additional QA engineers that the team asked for, citing the delay","Ask the QA engineer to work extra hours to test faster, and clear the queue of stories waiting for test within the next sprint"],ans:[1],why:["Sai: dồn kiểm thử về cuối release là đúng nếu sản phẩm vốn có giai đoạn ổn định bắt buộc, nhưng ở đây nó tạo khối lượng lớn muộn và phát hiện lỗi chậm, đi ngược nguyên tắc kiểm thử liên tục.","Đúng: tối ưu nguồn lực bằng cách tăng kỹ năng chéo (developer đã muốn học test tự động) với QA hướng dẫn rồi theo dõi luồng công việc ở buổi review. Ngân sách đã cố định nên đây là cách dùng năng lực sẵn có.","Sai: leo thang xin thêm hai người là đúng nếu ngân sách còn dư hoặc đã thử tối ưu mà chưa đủ, nhưng ở đây sponsor đã xác nhận ngân sách cố định; điểm nghẽn rõ ràng nhưng giải quyết bắt đầu từ cách đội làm việc.","Sai: giục QA làm nhanh hơn chỉ che triệu chứng, QA kiệt sức và chất lượng giảm, còn nguyên nhân là tám developer chỉ có một người kiểm thử thì vẫn còn. Hàng chờ sẽ đầy lại ngay sau đợt dồn việc."],exp:"Task Process 4 (enabler: manage and optimize resource needs and availability). Điểm nghẽn trong đội agile: tối ưu năng lực sẵn có bằng cross-skilling trước khi xin thêm nguồn lực. Bẫy: tăng người hoặc giờ làm mà không xử lý cấu trúc."},{id:"o360",n:360,t:0,origin:"original",eco:"R4",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","seasonal-availability","hybrid","planning"],type:"mc",q:"A hybrid project to develop crop-monitoring equipment needs field testers who are agronomy staff available only during the two-month harvest window each year, which opens in four months. The software sprints that support testing are not yet planned. The agronomy managers have already confirmed the testers' availability for the harvest window. What should the project manager do?",opts:["Confirm with the agronomy managers that the testers can attend the harvest window before planning any sprints","Plan the sprints at the usual cadence, and ask the testers to join whenever a sprint finishes with a usable build","Plan to use the project team's own engineers as the field testers, rather than the agronomy staff","Schedule the software increments backward from the harvest window, so a usable build is ready for the testers on their first day"],ans:[3],why:["Sai: xác nhận khả năng sẵn sàng với quản lý nông học là bước đúng khi chưa chắc, nhưng họ đã xác nhận; việc còn lại là lập tiến độ sprint theo cửa sổ chứ không phải hỏi lại.","Sai: nhịp sprint thông thường hợp lý với phần mềm không bị ràng buộc bên ngoài, nhưng tester nông học chỉ có hai tháng mỗi năm; để họ vào khi build sẵn sàng có thể bỏ lỡ cửa sổ và mất cả năm.","Sai: dùng kỹ sư dự án làm tester là phương án hợp lệ khi không có chuyên gia, nhưng tester cần kiến thức nông học thực địa mà kỹ sư không có; kết quả thử nghiệm sẽ kém giá trị.","Đúng: tính sẵn sàng của tester đã được xác nhận và cửa sổ chỉ hai tháng mỗi năm, nên PM lập tiến độ lùi từ cửa sổ thu hoạch để bản build dùng được sẵn sàng ngày đầu."],exp:"Task Process 4 (enabler: plan and manage resource availability). Khi nguồn lực khan hiếm đã được xác nhận sẵn sàng trong một cửa sổ, PM lập kế hoạch lùi từ cửa sổ đó thay vì hỏi lại. Bẫy: xác nhận lại điều đã biết, lập nhịp sprint không gắn với cửa sổ, hoặc thay người bằng nhân sự thiếu chuyên môn."},{id:"o361",n:361,t:0,origin:"original",eco:"R4",domain:"process",approach:"predictive",tags:["predictive","eco-2026","resource-leveling","over-allocation","change-control"],type:"mc",q:"The resource histogram for a bridge-rehabilitation project shows the welding crew over-allocated by 40 percent for six weeks, because two critical activities were scheduled in parallel. The crew's availability cannot be increased and the schedule is baselined. The scheduler's analysis shows that delaying the activity with eight days of float by its full float still leaves the crew 25 percent over-allocated for three weeks, and that only a second shift removes the overload. The extra shift costs more than the project manager may approve alone. What should the project manager do?",opts:["Level the crew by delaying the activity with float by eight days, and update the schedule to show the new dates","Add a second welding shift on the activity with float, and raise a change request for the extra cost","Cut one of the two parallel activities from the plan, and bring the histogram within the crew's capacity","Keep the crew on both activities and absorb the overload for six weeks, as the baseline dates matter most"],ans:[1],why:["Sai: san tải bằng cách dời hoạt động có float là cách sửa thông thường và đúng nếu float đủ xóa chồng lấn, nhưng phân tích cho thấy dời hết tám ngày vẫn còn quá tải 25 % trong ba tuần; chỉ ca thứ hai mới xóa được quá tải.","Đúng: phân tích đã chỉ ra ca thứ hai là cách duy nhất xóa quá tải, chi phí vượt quyền duyệt của PM và baseline đã được duyệt, nên PM thêm ca cho hoạt động còn float và trình change request cho phần chi phí phát sinh.","Sai: cắt một hoạt động găng ra khỏi kế hoạch là thay đổi phạm vi mà không có phê duyệt, trong khi công việc đó vẫn cần được làm; histogram trông ổn nhưng dự án thì thiếu một phần việc.","Sai: giữ cả hai hoạt động với quá tải 40 % trong sáu tuần là ép đội, gây rủi ro an toàn và chất lượng hàn, không bền vững. Đúng nếu quá tải chỉ vài ngày, nhưng ở đây kéo dài sáu tuần."],exp:"Task Process 4 (enabler: manage and optimize resource needs and availability; manage changes). Khi phân tích đã chỉ ra phương án duy nhất khả thi, PM thực hiện nó và đưa phần chi phí qua change control vì baseline đã duyệt và chi phí vượt quyền. Bẫy: dời việc khi float không đủ, cắt việc, hoặc ép đội chịu quá tải."},{id:"o362",n:362,t:0,origin:"original",eco:"R4",domain:"process",approach:"predictive",tags:["predictive","eco-2026","virtual-team","resource-calendar","time-zones"],type:"mc",q:"A predictive software-integration project is staffed by teams in Poland, India, and Brazil. The resource plan lists names and rates but not working-hour overlap or who must attend each design review. Reviews keep being rescheduled, and the leads in all three countries say they would commit to fixed overlap windows if the plan named them. What should the project manager add to the resource plan?",opts:["Resource calendars showing each location's hours and overlap, plus the roles required at each review, confirmed by the leads","A team-charter section on communication norms, including a rule to record each review for later viewing by absent members","Extra review meetings spread across the day, giving each member a chance to attend one of several repeated sessions","A rule that members adopt the headquarters' working hours during review weeks, whatever their local time zone"],ans:[0],why:["Đúng: bổ sung resource calendar với giờ làm việc, khung giờ chồng lấn và vai trò bắt buộc ở từng buổi review, được các trưởng nhóm xác nhận. Khi kế hoạch nêu rõ, họ cam kết khung giờ cố định và lịch review ổn định thay vì phải xếp lại liên tục.","Sai: quy ước giao tiếp và ghi hình buổi review là thực hành tốt cho đội phân tán và đúng nếu vấn đề là người vắng không nắm nội dung, nhưng ở đây kế hoạch không có giờ chồng lấn và người cần dự; các buổi review vẫn bị dời lịch.","Sai: thêm buổi họp rải trong ngày hợp lý nếu chỉ cần mỗi người nghe được một lần, nhưng review thiết kế cần các vai trò chủ chốt cùng có mặt; thêm họp tăng tải họp cho cả ba địa điểm mà kế hoạch vẫn không nói ai phải dự buổi nào.","Sai: theo giờ trụ sở trong các tuần review có thể chấp nhận được nếu trụ sở trùng giờ với mọi nơi, nhưng ở đây ảnh hưởng giấc ngủ của thành viên ở Ấn Độ hay Brazil và không giải quyết gốc rễ là kế hoạch thiếu thông tin về lịch làm việc và người bắt buộc phải dự."],exp:"Task Process 4 (enabler: define and plan resources based on requirements). Kế hoạch nguồn lực cho đội phân tán cần lịch làm việc và vai trò bắt buộc, không chỉ tên và đơn giá. Bẫy: áp giờ làm hoặc thêm họp thay vì lập kế hoạch lịch."},{id:"o363",n:363,t:0,origin:"original",eco:"R4",domain:"process",approach:"agile",tags:["agile","eco-2026","product-owner-availability","agile","impediment"],type:"mc",q:"The product owner of a scrum team also runs a sales region and has attended only half of the refinement sessions. Developers now wait days for answers, and two sprints ended with unfinished work for that reason. The sponsor values the product owner's market knowledge. Only the sponsor can change the product owner's sales duties; the project manager cannot. What should the project manager do?",opts:["Work with the team to take fewer stories per sprint, and report the lower velocity until the product owner's time frees up","Escalate to the sponsor with the missed-refinement and unfinished-sprint data, asking for protected time or a proxy","Appoint a business analyst as product owner instead, as she has more time to spare for the team's daily questions","Let the developers answer their own questions about requirements, and keep the sprints finishing on time as planned"],ans:[1],why:["Sai: giảm số story mỗi sprint là đúng nếu thiếu thời gian chỉ là tạm thời và đã có kế hoạch giải quyết, nhưng ở đây nó chỉ thích nghi với vấn đề: velocity giảm dài hạn còn nguyên nhân là product owner thiếu thời gian thì vẫn còn.","Đúng: product owner là nguồn lực then chốt nhưng không đủ thời gian, và chỉ sponsor mới thay đổi được nhiệm vụ bán hàng của họ. PM leo thang kèm số liệu refinement bị bỏ lỡ và sprint dang dở, nhờ sponsor bảo đảm thời gian chuyên trách hoặc cử người đại diện (proxy), mà vẫn giữ kiến thức thị trường mà sponsor coi trọng.","Sai: thay product owner làm mất kiến thức thị trường mà sponsor coi trọng, và việc bổ nhiệm vai trò này cũng không thuộc quyền PM. Business analyst có thể làm proxy hữu ích, nhưng không có thẩm quyền ưu tiên giá trị.","Sai: để developer tự trả lời các câu hỏi về yêu cầu là bỏ qua thẩm quyền của product owner; sprint có thể kết thúc đúng hạn nhưng sản phẩm có thể đi sai hướng giá trị."],exp:"Task Process 4 (enabler: manage and optimize resource needs and availability). Sự sẵn sàng của product owner là một nguồn lực quan trọng; khi chỉ sponsor mới đổi được nhiệm vụ của họ thì PM leo thang kèm số liệu. Bẫy: đội tự quyết, thay người hoặc giảm tải chỉ để thích nghi."},{id:"o364",n:364,t:0,origin:"original",eco:"R4",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","idle-resources","hybrid","resource-optimization"],type:"mc",q:"In a hybrid project, six system testers will be idle for five weeks while the build team finishes a gated design phase, and the company does not want to carry the cost. The sprint-based test phase afterward needs all six at once. A functional manager offers to reassign them to another project now, but that project's end date is not firm and these testers already know the product. The functional manager has confirmed the six testers can be recalled on two weeks' notice, and the test lead says enough test-preparation work exists to keep them busy. What should the project manager do?",opts:["Accept the offer now and ask the other project to return the same six people when the test phase begins","Review the test-preparation backlog with the test lead to see whether enough work exists for the six testers","Keep the testers idle on the project so that the six are guaranteed to be available when the phase starts","Assign the six testers to the test-preparation work for the five weeks, and agree a recall date with the functional manager"],ans:[3],why:["Sai: cho mượn tạm là cách dùng nguồn lực hợp lý khi không có việc, nhưng dự án kia chưa có ngày kết thúc chắc chắn và người này đã biết sản phẩm; mất họ có thể không lấy lại được, trong khi đã có việc chuẩn bị kiểm thử cho họ.","Sai: rà soát backlog chuẩn bị kiểm thử là bước đúng khi chưa biết có việc không, nhưng trưởng nhóm kiểm thử đã xác nhận có đủ việc; rà soát lại chỉ lặp điều đã biết.","Sai: Giữ nhàn rỗi năm tuần tốn chi phí không cần thiết và không tối ưu nguồn lực, trong khi công ty đã nói không muốn gánh khoản này; nó chỉ bảo đảm được việc có mặt chứ không tạo ra giá trị nào.","Đúng: đã có đủ việc chuẩn bị kiểm thử và người quản lý chức năng đồng ý gọi lại sau hai tuần, nên PM giao việc cho sáu tester và thống nhất ngày gọi lại để họ sẵn sàng khi giai đoạn bắt đầu."],exp:"Task Process 4 (enabler: manage and optimize resource needs and availability). Khi đã có việc phù hợp cho nguồn lực chờ, PM giao việc và thống nhất lịch gọi lại thay vì cho mượn hoặc để rảnh. Bẫy: để nhân sự rảnh, thả họ hẳn, hoặc cho mượn mà không đảm bảo quay lại."},{id:"o213",n:213,t:0,origin:"original",eco:"R5",domain:"process",approach:"predictive",tags:["predictive","eco-2026","contract-type","fixed-price","construction"],type:"mc",q:"A transit agency needs a pump station built from a complete design package. Drawings, specifications, and quantities are final, the site has been thoroughly surveyed, and the agency wants cost certainty for its board. The project manager is asked which contract type to use for the construction. What should be recommended?",opts:["Cost plus fixed fee, which lets the agency follow the contractor's actual costs and share the savings that appear","Time and materials with a not-to-exceed ceiling, because it lets the contractor adjust to field conditions as they arise","Firm fixed price, because the scope is fully defined and the agency wants cost certainty for the board","Cost plus award fee, with performance bonuses to motivate the contractor to finish ahead of the planned schedule"],ans:[2],why:["Sai: Cost-plus chuyển rủi ro chi phí cho bên mua, trong khi phạm vi đã rõ và hội đồng muốn chắc chắn về chi phí; hợp đồng này hợp khi phạm vi chưa xác định.","Sai: T&M có trần phù hợp khi phạm vi chưa rõ; ở đây thiết kế và khối lượng đã chốt nên loại này chuyển rủi ro quản lý chi phí về phía cơ quan mà không cần thiết.","Đúng: phạm vi hoàn toàn rõ và khách hàng cần chắc chắn chi phí nên firm fixed price chuyển rủi ro chi phí sang nhà thầu, hợp lý nhất cho công trình có thiết kế hoàn chỉnh.","Sai: Thưởng theo hiệu suất không giải quyết yêu cầu chắc chắn chi phí, và tạo thêm chi phí quản lý đánh giá; cũng nằm trong nhóm cost-reimbursable."],exp:"Task Process 5 (enabler: select preferred contract types). Quy tắc nhớ: phạm vi rõ thì giá cố định; phạm vi chưa rõ hoặc cần linh hoạt thì T&M hoặc cost-reimbursable. Bẫy: chọn theo khả năng theo dõi chi phí thay vì theo mức độ rõ của phạm vi."},{id:"o365",n:365,t:0,origin:"original",eco:"R5",domain:"process",approach:"predictive",tags:["predictive","eco-2026","make-or-buy","procurement-planning","strategic-capability"],type:"mc",q:"A manufacturer's project needs a specialized sensor-calibration capability. The company has two engineers who could learn it in about five months, and three vendors offer calibration services. The schedule has no float on this work, and the capability will be needed on future projects as well. Nobody has yet compared the make and buy options. What should the project manager do as part of procurement planning?",opts:["Select the vendor with the lowest quoted price with the procurement lead, and contract the calibration work this week, given the schedule has no float","Collect budgetary quotes from the three vendors with the procurement lead, and compare them on price before deciding whether to buy","Train the two engineers over the next five months to build the calibration skill in-house, with their manager planning cover for their other work","Have the engineering manager run a make-or-buy analysis of cost, schedule, risk, and long-term need, recorded in the procurement plan"],ans:[3],why:["Sai: chọn nhà cung cấp giá thấp nhất ngay là đúng nếu đã quyết định mua và chỉ còn so giá, nhưng ở đây chưa so phương án tự làm; giá không phải yếu tố duy nhất và bỏ qua nhu cầu dài hạn cùng rủi ro nhà cung cấp.","Sai: thu báo giá và so theo giá là bước hữu ích khi đã quyết định mua, nhưng ở đây chưa ai so phương án tự làm với mua; chỉ so giá bỏ qua tiến độ không float, rủi ro và nhu cầu dài hạn của năng lực này.","Sai: đào tạo nội bộ có lợi cho các dự án sau và đúng nếu lịch còn float, nhưng ở đây mất khoảng năm tháng trong khi lịch không có float; lựa chọn này chưa được so sánh với các lựa chọn khác và không kịp cho việc này.","Đúng: chưa ai so sánh tự làm và mua, nên PM cùng quản lý kỹ thuật chạy phân tích make-or-buy cân nhắc chi phí, tiến độ, rủi ro và nhu cầu dài hạn, rồi ghi quyết định vào procurement plan; lịch không float và nhu cầu tương lai đều được đưa vào."],exp:"Task Process 5 (enabler: plan procurement). Quyết định tự làm hay mua là bước đầu của lập kế hoạch mua sắm, dựa trên phân tích nhiều yếu tố. Bẫy: chọn theo một yếu tố, hoặc phát RFP trước khi quyết định có cần mua."},{id:"o366",n:366,t:0,origin:"original",eco:"R5",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","delivery-solution","hybrid-contract","procurement-strategy"],type:"mc",q:"A hospital group needs a patient portal built by an outside firm. The security and integration components are well specified, while patient-facing features need continuous refinement with clinicians. Legal wants a contract that protects the budget, and the vendor prefers to work iteratively. How should the project manager structure the procurement?",opts:["Use an open time-and-materials contract for the whole portal, with sprint scope set each sprint by the vendor's lead and the product owner","Fix the price of the specified security and integration components, and cap the iterative work on patient features","Ask legal to draft a fixed-price contract for the whole portal, with a change-order schedule for clinician-driven refinements","Use a single fixed-price contract for the entire portal, with legal approving each clinician-driven change before the vendor builds it"],ans:[1],why:["Sai: T&M mở cho cả portal đúng nếu toàn bộ còn chưa rõ, nhưng ở đây bộ phận pháp lý cần bảo vệ ngân sách và phần bảo mật, tích hợp đã đặc tả rõ không cần linh hoạt đến vậy.","Đúng: giá cố định cho các thành phần đã đặc tả giúp bảo vệ ngân sách, còn phần tính năng bệnh nhân cần tinh chỉnh với bác sĩ được làm theo vòng lặp trong một khoản có trần. Cách này cân bằng yêu cầu của bộ phận pháp lý và cách làm việc lặp của nhà cung cấp.","Sai: hợp đồng giá cố định kèm lịch change order bảo vệ ngân sách, và đúng nếu thay đổi hiếm, nhưng tính năng hướng bệnh nhân cần tinh chỉnh liên tục nên mỗi thay đổi thành một change order; bên bán muốn làm lặp và quy trình sẽ bị cản trở.","Sai: một hợp đồng giá cố định cho cả portal đúng nếu mọi thành phần đã đặc tả, nhưng ở đây tính năng bệnh nhân còn tiến hóa; dù pháp lý duyệt từng thay đổi, mọi điều chỉnh vẫn thành change order, gây tranh chấp và làm nhà cung cấp không làm lặp được."],exp:"Task Process 5 (enabler: develop a delivery solution). Hybrid: chọn cơ chế mua sắm khác nhau cho phần ổn định và phần tiến hóa, vẫn trong một hợp đồng thống nhất. Bẫy: chọn một loại hợp đồng cho mọi thứ."},{id:"o367",n:367,t:0,origin:"original",eco:"R5",domain:"process",approach:"agile",tags:["agile","eco-2026","vendor-management","definition-of-done","working-agreement"],type:"mc",q:"A vendor team under a time-and-materials contract works inside a company's scrum process. Over three sprints, the vendor's stories were accepted only after rework, and the vendor says its definition of done differs from the company's. The contract does not mention a definition of done, and the two sides have never compared their definitions in writing; the contract permits joint working agreements. What should the project manager do?",opts:["Have the product owner and scrum master audit the vendor's stories from the three sprints to classify the causes of rework, and decide next steps","Agree a shared definition of done with the vendor team and the product owner, and review story quality at each sprint review","Invoke the contract's termination clause with legal's support, and replace the vendor team with another supplier","Ask the vendor's account manager for a corrective plan to review monthly, and leave the team's working practices to the vendor"],ans:[1],why:['Sai: rà soát nguyên nhân rework cùng product owner hữu ích khi chưa ai biết vì sao story bị làm lại, nhưng ở đây nhà cung cấp đã nói hai bên dùng hai định nghĩa "xong" khác nhau và chưa ai so sánh; việc cần làm là thống nhất định nghĩa chứ không phải phân tích thêm.','Đúng: gốc vấn đề là hai bên chưa so sánh định nghĩa "xong" và hợp đồng cho phép thỏa thuận làm việc chung. Thống nhất definition of done với nhóm nhà cung cấp và product owner rồi rà soát chất lượng mỗi sprint là quản lý nhà cung cấp theo cộng tác; nên ghi lại thỏa thuận để cả hai bên cùng dựa vào.','Sai: chấm dứt hợp đồng là đúng nếu nhà cung cấp từ chối sửa dù đã làm rõ kỳ vọng, nhưng ở đây nguyên nhân là hai định nghĩa "xong" khác nhau và chưa ai thử làm rõ; đây là biện pháp cực đoan.','Sai: kế hoạch khắc phục từ quản lý tài khoản đúng nếu lỗi nằm ở năng lực nhà cung cấp, nhưng ở đây nó không đổi cách hai đội làm việc hằng sprint; đội vẫn không có chuẩn "xong" chung.'],exp:"Task Process 5 (enabler: manage suppliers and contracts). Trong agile, nhà cung cấp làm việc như một phần của đội; kỳ vọng chất lượng cần được thống nhất công khai. Bẫy: nhảy sang chế tài hoặc để vấn đề chất lượng kéo dài."},{id:"o368",n:368,t:0,origin:"original",eco:"R5",domain:"process",approach:"predictive",tags:["predictive","eco-2026","ai","ai-vendor","procurement-requirements","data-governance"],type:"mc",q:"A retailer plans to buy an AI-based demand-forecasting service from an outside vendor under a predictive plan. Past sales data will be sent to the vendor's cloud, and store managers will use the forecasts for ordering. The vendor's accuracy figures come from its own tests on other customers' data. The project manager is drafting the procurement package. What should the requirements make sure to include?",opts:["Terms on data handling and ownership, a test of forecast accuracy on the retailer's own sales data, and an accountable owner","A requirement that bidders document their model design and training data sources, ranked in the evaluation matrix","An acceptance clause based on the vendor's published accuracy figures, with payment released on delivery","A liability clause making the vendor responsible for ordering decisions taken from its forecasts, whatever the retailer's own checks"],ans:[0],why:["Đúng: yêu cầu mua dịch vụ AI cần điều khoản dữ liệu, cách kiểm chứng độ chính xác bằng dữ liệu bán hàng của chính mình, và người chịu trách nhiệm cuối cùng bên mua. Số liệu của nhà cung cấp đến từ dữ liệu khách hàng khác và trách nhiệm quyết định đặt hàng không thể chuyển hết cho AI hay nhà cung cấp.","Sai: tài liệu hóa thiết kế mô hình và nguồn dữ liệu huấn luyện đúng nếu cần so sánh kỹ thuật hoặc kiểm tra thiên lệch, nhưng đó không thay cho điều khoản dữ liệu và kiểm chứng độ chính xác trên dữ liệu của người mua; chấm điểm thuật toán không đảm bảo kết quả trong bối cảnh cửa hàng.","Sai: số liệu quảng bá của nhà cung cấp đến từ dữ liệu khách hàng khác nên không phải bằng chứng độc lập; nghiệm thu và trả tiền khi giao phải dựa trên kết quả đo bằng dữ liệu của chính khách hàng.","Sai: điều khoản chuyển toàn bộ trách nhiệm cho nhà cung cấp là không thực tế; người quyết định đặt hàng vẫn là cửa hàng, và nhà cung cấp hiếm chấp nhận. Đúng chỉ khi cửa hàng không có cách kiểm tra nào."],exp:"Task Process 5 (enabler: plan procurement). Bối cảnh AI chỉ là nền: yêu cầu mua sắm phải bảo vệ dữ liệu, cho phép kiểm chứng đầu ra độc lập và giữ người chịu trách nhiệm cuối cùng. Bẫy: tin số liệu của bên bán hoặc tin rằng có thể chuyển hết trách nhiệm."},{id:"o369",n:369,t:0,origin:"original",eco:"R5",domain:"process",approach:"predictive",tags:["predictive","eco-2026","vendor-performance","inspection","corrective-action"],type:"mc",q:'A vendor building a warehouse conveyor system has missed two consecutive milestones by a week each. Its monthly reports say progress is "on track". The contract includes performance reporting, a right to inspect, and a clause for corrective action plans. The project manager is preparing a performance review. An inspection last week confirmed both delays and found the conveyor integration three weeks behind, not one. What should the project manager do?',opts:["Inspect the deliverables and progress against the contract milestones before requiring a corrective plan","Meet the vendor's account manager to agree revised milestone dates, and update the baseline to match","Switch to the runner-up from the original bid evaluation and re-baseline the remaining schedule","Issue a formal notice invoking the corrective-action clause, and require a recovery plan from the vendor within two weeks"],ans:[3],why:["Sai: kiểm tra sản phẩm và tiến độ là bước đúng khi chưa có bằng chứng, nhưng đợt kiểm tra tuần trước đã xác nhận cả hai lần trễ và độ trễ tích hợp là ba tuần; kiểm tra lại chỉ làm chậm phản ứng.","Sai: thỏa thuận mốc mới có thể đúng khi nhà cung cấp trễ vì lý do khách quan, nhưng báo cáo hằng tháng nói đúng tiến độ trong khi thực tế trễ ba tuần; chấp nhận mốc mới mà chưa buộc kế hoạch khắc phục bỏ qua quyền của hợp đồng.","Sai: Thay nhà cung cấp là biện pháp lớn, tốn kém và mất thời gian chuyển giao, trong khi hợp đồng còn các công cụ nhẹ hơn là kiểm tra và kế hoạch khắc phục chưa được dùng.","Đúng: đợt kiểm tra đã xác nhận trễ ba tuần và hợp đồng có điều khoản kế hoạch khắc phục, nên PM gửi thông báo chính thức và yêu cầu kế hoạch phục hồi trong hạn."],exp:"Task Process 5 (enabler: manage suppliers and contracts). Khi kiểm tra đã xác nhận nhà cung cấp trễ, PM dùng điều khoản hợp đồng để yêu cầu kế hoạch khắc phục thay vì kiểm tra lại hoặc chấp nhận mốc mới. Bẫy: tin báo cáo của nhà cung cấp, điều chỉnh mốc ngay, hoặc đổi nhà cung cấp quá sớm."},{id:"o370",n:370,t:0,origin:"original",eco:"R5",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","negotiation-strategy","sole-source","hybrid"],type:"mc",q:"A hybrid program depends on a sole-source supplier of a specialized sensor. The supplier has announced a 20 percent price rise at renewal in six weeks. The hardware phase is fixed and its design is frozen, so a redesigned part would trigger rework, and delivery quantities are fairly predictable for the next 18 months. No negotiation objectives or limits have been written down yet. The project manager is asked to prepare for negotiations. What should the project manager do first?",opts:["Accept the 20 percent rise at renewal through the procurement lead, and secure the sole source through the 18-month delivery plan","Have the procurement lead open with a counter-offer 20 percent below the current price, and hold that position through the renewal talks","Prepare the program's priorities, alternatives, and acceptable ranges with the procurement lead, and learn the supplier's interests","Escalate to the sponsor to approve a redesign around a competing supplier's part, and use its quote as an alternative in the talks"],ans:[2],why:["Sai: chấp nhận ngay là đúng nếu mọi lựa chọn khác đã được thử và hết đòn bẩy, nhưng ở đây chương trình có số lượng dự đoán được 18 tháng và các điều khoản khác có thể thương lượng; chấp nhận từ đầu bỏ phí đòn bẩy đó.","Sai: đề nghị thấp hơn 20 % rồi giữ nguyên lập trường dễ làm căng quan hệ với nhà cung cấp duy nhất và thất bại; đúng nếu chương trình có phương án thay thế mạnh, nhưng PM chưa viết ra mục tiêu và giới hạn của mình.","Đúng: chưa có mục tiêu hay giới hạn nào được viết ra, nên bước đầu là xác định chiến lược đàm phán: ưu tiên, lựa chọn thay thế và khoảng chấp nhận được của mình, cùng lợi ích của nhà cung cấp, rồi mới chọn cách tiếp cận.","Sai: báo giá cho linh kiện thiết kế lại có thể trở thành đòn bẩy, nhưng thiết kế phần cứng đã đóng băng nên thiết kế lại kéo theo làm lại và chưa chắc khả thi; xin sponsor duyệt thiết kế lại khi chưa xác định ưu tiên và khoảng chấp nhận được là leo thang quá sớm."],exp:"Task Process 5 (enabler: determine a negotiation strategy). Chuẩn bị đàm phán: mục tiêu, giới hạn, phương án thay thế và lợi ích của đối tác, rồi mới chọn chiến thuật. Bẫy: nhượng bộ sớm hoặc áp lập trường cứng."},{id:"o371",n:371,t:0,origin:"original",eco:"R5",domain:"process",approach:"agile",tags:["agile","eco-2026","contract-type","agile-contracting","time-and-materials"],type:"mc",q:"A company wants an outside team to build a customer-facing web application using its agile process. The product vision is clear but the features will emerge from user feedback, and the company wants to stop funding if early releases fall short. Procurement proposes a fixed-price contract with a full feature list, and the product owner worries that it will block changes. Which contract approach should the project manager recommend?",opts:["A time-and-materials contract with a budget ceiling, incremental delivery, and a right to stop, reviewed by the product owner each sprint","Separate fixed-price contracts for each feature, each priced and signed with procurement before development of that feature starts","A cost-plus contract with no ceiling on spend, reviewed each quarter by the vendor's lead and the product owner","A fixed-price contract with a complete feature list, and changes handled through the vendor's change order process"],ans:[0],why:["Đúng: đội chỉ có tầm nhìn, tính năng hình thành theo phản hồi và công ty muốn dừng được nếu bản đầu kém, nên cần T&M hoặc theo năng lực có trần ngân sách, giao theo từng phần và quyền dừng sau mỗi vòng lặp.","Sai: từng hợp đồng giá cố định theo tính năng đúng nếu tính năng đã biết trước, nhưng ở đây chúng hình thành theo phản hồi; thêm chi phí quản lý và không ứng phó được với thay đổi.","Sai: cost-plus không có trần là đúng nếu công việc không thể ước lượng và bên mua chấp nhận rủi ro chi phí, nhưng ở đây công ty muốn kiểm soát; nhà cung cấp cũng không có động lực giao sớm hay giữ gọn phạm vi vì làm lâu hơn được trả nhiều hơn.","Sai: giá cố định với danh sách tính năng đầy đủ đúng nếu yêu cầu đã chốt, nhưng ở đây sản phẩm cần thay đổi theo phản hồi; mỗi thay đổi thành change order chậm và tốn kém, và công ty không có quyền dừng sớm."],exp:"Task Process 5 (enabler: select preferred contract types). Phạm vi tiến hóa thì chọn hợp đồng linh hoạt nhưng kiểm soát được: trần ngân sách, giao theo vòng, quyền dừng. Bẫy: giữ giá cố định theo thói quen mua sắm hoặc thả nổi chi phí."},{id:"o372",n:372,t:0,origin:"original",eco:"R5",domain:"process",approach:"predictive",tags:["predictive","eco-2026","acceptance","final-payment","closing-procurement"],type:"mc",q:"A contractor has announced completion of a data-center cooling installation and submitted its final invoice. The contract makes the final payment and the 10 percent retention due on acceptance, which requires a performance test against the acceptance criteria. The project manager's team notes that the performance test has not been run. What should the project manager do?",opts:["Pay the invoice on the contractor's report of completion, and schedule the performance test for the early warranty period","Schedule the performance test with the contractor, verify the results against the criteria, and hold payment pending acceptance","Reject the invoice, and notify the contractor in writing through the contract manager that it is in breach of the completion terms","Have the contractor run the performance test in the next two weeks, and pay the invoice less the retention while the test is pending"],ans:[1],why:["Sai: trả tiền theo lời báo hoàn thành là đúng nếu hợp đồng cho thanh toán theo mốc báo cáo, nhưng ở đây nghiệm thu cần performance test; trả trước rồi dời kiểm thử sang bảo hành làm mất đòn bẩy hợp đồng và lỗi phát hiện sau sẽ khó đòi.","Đúng: hợp đồng gắn thanh toán cuối và tiền giữ lại với nghiệm thu, nên PM sắp xếp chạy performance test, xác minh kết quả theo tiêu chí và giữ khoản thanh toán cuối cùng cùng retention trong lúc đó.","Sai: từ chối hóa đơn và tuyên bố vi phạm là đúng nếu kiểm thử đã chạy và không đạt, nhưng ở đây kiểm thử chưa chạy; kết luận sớm khi nhà thầu có thể vẫn đáp ứng tiêu chí là tạo tranh chấp không cần thiết.","Sai: thanh toán trừ khoản giữ lại là cách bảo vệ một phần, nhưng điều kiện chấp nhận gồm bài kiểm tra hiệu năng chưa chạy; thanh toán gần hết trước khi nghiệm thu mất đòn bẩy nếu bài kiểm tra không đạt."],exp:"Task Process 5 (enabler: verify that the objectives of the procurement agreement are met). Nghiệm thu theo tiêu chí hợp đồng, xác minh bằng kiểm thử, rồi mới thanh toán cuối. Bẫy: coi lời báo hoàn thành là bằng chứng, trả trước nghiệm thu, hoặc kết luận vi phạm trước khi kiểm thử."},{id:"o373",n:373,t:0,origin:"original",eco:"R5",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","negotiation","supplier-shortage","win-win"],type:"mc",q:"During a hybrid project, a supplier of embedded controllers asks to renegotiate delivery dates because of a component shortage. Hardware gates and sprint demos both depend on the controllers, and the supplier wants a price increase for expedited parts. No position on dates or price has been agreed yet. In the negotiation meeting, what should the project manager do?",opts:["Accept the price increase on the spot through the procurement lead, and ask the supplier to give the project's order priority in return","Explore the supplier's constraints, share the critical project dates, and seek trade-offs that both sides can accept in the meeting","Have the procurement lead hold to the original dates and price, and cite the contract's penalty clause to press the supplier","Leave the negotiation to the procurement department, and join afterwards to confirm the technical dates and quantities"],ans:[1],why:["Sai: đồng ý tăng giá nhanh chóng đúng nếu đã có cam kết ưu tiên bằng văn bản, nhưng ở đây chưa có; nhà cung cấp có thể vẫn ưu tiên khách khác và dự án mất đòn bẩy.","Đúng: tham gia đàm phán bằng cách hiểu ràng buộc và lợi ích của nhà cung cấp, chia sẻ mốc quan trọng của dự án, và tìm đánh đổi (ví dụ lô nhỏ ưu tiên, điều chỉnh giá) để cả hai đều được bảo vệ.","Sai: dùng điều khoản phạt để gây sức ép đúng nếu nhà cung cấp cố tình vi phạm, nhưng ở đây họ gặp thiếu linh kiện thực sự; gây sức ép làm hỏng quan hệ và không giải quyết việc thiếu hàng.","Sai: giao hoàn toàn cho bộ phận mua sắm hợp lý nếu việc chỉ là giá, nhưng PM nắm các mốc phụ thuộc quan trọng của gate và demo; chỉ xác nhận ngày sau khi điều khoản đã được thương lượng là quá muộn."],exp:"Task Process 5 (enabler: participate in agreement negotiations). Đàm phán hiệu quả dựa trên lợi ích hai bên, không chỉ vị thế; PM mang kiến thức về các phụ thuộc tới bàn đàm phán. Bẫy: gây áp lực bằng phạt hoặc nhượng bộ vội vàng."},{id:"o374",n:374,t:0,origin:"original",eco:"R5",domain:"process",approach:"agile",tags:["agile","eco-2026","procurement-strategy","framework-agreement","scaling"],type:"mc",q:"An agile program expects to scale from two to eight teams over a year, depending on funding releases each quarter. The company needs outside developers but cannot predict exact numbers. A new tender takes about ten weeks, and each funding decision arrives only two weeks before the quarter starts. Procurement asks the project manager for a strategy. Which strategy best fits?",opts:["Ask HR to hire each team's engineers one at a time as permanent employees, and drop outside vendors from the plan altogether","Sign a one-year fixed contract for eight teams, securing the chosen vendor's capacity through procurement for the year","Run a new competitive tender each quarter with procurement, and buy the number of teams needed in that quarter's budget","Set up a framework agreement at pre-set rates with procurement, with teams called off as each quarter's funding is confirmed"],ans:[3],why:["Sai: tuyển nhân viên chính thức từng người đúng nếu nhu cầu ổn định nhiều năm, nhưng ở đây nhu cầu thay đổi theo quý; tuyển dụng chậm và tạo cam kết dài hạn không phù hợp.","Sai: cam kết cả năm cho tám đội đúng nếu tài trợ đã chắc chắn, nhưng ở đây tiền chỉ được giải phóng theo quý; công ty phải trả cho năng lực không dùng đến nếu tiền không về.","Sai: đấu thầu mỗi quý đúng nếu thời gian đấu thầu ngắn, nhưng một lần đấu thầu mất khoảng mười tuần còn quyết định tài trợ đến chỉ hai tuần trước quý; đội khởi động trễ và phải thương lượng lại điều khoản mỗi lần.","Đúng: thỏa thuận khung với giá và điều khoản định sẵn cho phép gọi thêm đội ngay khi tài trợ được xác nhận, phù hợp nhu cầu biến động và thời gian đấu thầu dài."],exp:"Task Process 5 (enabler: plan and manage the procurement strategy). Nhu cầu biến động cần chiến lược mua sắm linh hoạt như framework agreement. Bẫy: cam kết đầy đủ hoặc làm lại thủ tục mỗi lần."},{id:"o375",n:375,t:0,origin:"original",eco:"R5",domain:"process",approach:"predictive",tags:["predictive","eco-2026","change-orders","claims","contract-administration"],type:"mc",q:"A vendor installing network equipment submits an invoice for extra work, saying a site engineer verbally asked for it three weeks ago. The contract requires written change orders approved by the project manager, and none exists. The site engineer is reachable, and the claims procedure allows 30 days to respond. The vendor's contact is pressing for payment. What should the project manager do first?",opts:["Verify the verbal request with the site engineer, and review the claim against the contract's procedure within the 30 days","Escalate to the sponsor to settle the matter with the vendor's executives, and avoid a formal dispute over the claim","Pay the invoice now on the finance lead's approval, and remind the vendor to use written change orders next time","Reject the claim by email through the contract manager, and refer the vendor to the dispute-resolution clause of the contract"],ans:[0],why:["Đúng: PM xác minh sự việc với kỹ sư hiện trường (còn liên lạc được và còn thời hạn trả lời), đối chiếu hợp đồng rồi xử lý qua thủ tục thay đổi/khiếu nại. Cách này công bằng với cả hai bên nếu yêu cầu miệng có thật, và vẫn giữ nguyên tắc hợp đồng đòi change order bằng văn bản.","Sai: leo thang lên sponsor để giải quyết với lãnh đạo nhà thầu đúng nếu PM hết thẩm quyền hoặc thủ tục khiếu nại thất bại, nhưng ở đây PM có thẩm quyền và quy trình hợp đồng còn thời hạn để xử lý trước.","Sai: thanh toán khi không có change order phá vỡ quy trình kiểm soát thay đổi và tạo tiền lệ để nhà thầu bỏ qua điều khoản; giữ quan hệ không thay cho xác minh.","Sai: từ chối bằng email đúng nếu đã xác minh không có yêu cầu nào, nhưng ở đây việc kiểm tra còn chưa làm; từ chối khi yêu cầu miệng của kỹ sư hiện trường có thể có thật sẽ tạo tranh chấp không cần thiết."],exp:"Task Process 5 (enabler: manage suppliers and contracts). Xử lý khiếu nại bằng thủ tục hợp đồng: kiểm tra sự thật, đối chiếu điều khoản, ghi nhận. Bẫy: trả để giữ quan hệ, từ chối vội hoặc leo thang sớm."}],o=[{id:"o214",n:214,t:0,origin:"original",eco:"R6",domain:"process",approach:"predictive",tags:["predictive","eco-2026","funding","estimate-gap"],type:"mc",q:"A construction project is managed with an approved scope and a predictive plan. The sponsor allocated $2.8 million, but the project manager's bottom-up estimate from the work packages, including a risk-based contingency, comes to $3.1 million. The work package owners have already reviewed their estimates. The sponsor has not yet seen the figures. What should the project manager do first?",opts:["Prepare a scope-reduction change request with the work package owners to fit the $2.8 million, and submit it to the change control board","Propose to the sponsor, with the finance controller, funding of $2.8 million now and the remainder at the next phase gate, and log the gap as a risk","Have the work package owners and the cost estimator re-estimate their packages with the team to confirm the $3.1 million figure","Escalate the $300,000 gap to the sponsor together with the bottom-up estimate basis and the contingency logic, before committing to any figure or cut"],ans:[3],why:["Sai: một change request lên change control board dùng cho baseline đã được duyệt, còn ở đây sponsor chưa biết có chênh lệch. Sẽ đúng nếu ngân sách đã là baseline, nhưng ở đây chủ sở hữu vốn phải thấy khoảng chênh $300.000 trước.","Sai: đề xuất cách cấp vốn khi sponsor chưa thấy cơ sở ước tính và khoảng chênh là đưa lời giải trước dữ kiện. Sẽ đúng nếu sponsor đã xem số liệu và đang chọn cách cấp vốn.","Sai: đây là bước đánh giá đã xong, vì đề nói các work package owner đã soát ước tính của họ. Ước tính lại sẽ đúng nếu có nghi ngờ về số liệu, nhưng ở đây vấn đề là chênh với nguồn vốn.","Đúng: nhu cầu từ bottom-up ($3,1 triệu) lệch $300.000 so với nguồn vốn được cấp, và sponsor chưa thấy số liệu. PM đưa khoảng chênh cùng cơ sở ước tính lên sponsor trước khi cam kết bất kỳ con số nào; việc chọn phương án (giảm scope, tăng vốn) làm tiếp cùng sponsor."],exp:'Task R6, enabler "Analyze project financial needs": so sánh nhu cầu ước tính từ dưới lên với nguồn vốn được cấp và đưa chênh lệch ra cho người sở hữu vốn. Quy tắc nhớ: số liệu minh bạch trước, lựa chọn (scope, vốn, tiến độ) sau. Bẫy: cắt contingency hoặc xin tiền muộn để "cho đẹp" ngân sách.'},{id:"o215",n:215,t:0,origin:"original",eco:"R7",domain:"process",approach:"agile",tags:["agile","eco-2026","quality-requirements","definition-of-done","accessibility"],type:"mc",q:"A government agency is building a public benefits portal in two-week sprints. The definition of done covers functional acceptance criteria only. In the last review, citizens using screen readers could not complete the forms, and pages slowed down at peak hours. A workshop after the review already gathered the accessibility needs from citizens and the performance targets from the compliance office. The product owner says nobody mentioned these needs earlier. What should the project manager do?",opts:["Update the definition of done with the workshop's accessibility and performance criteria, and have the team apply it to every story from the next sprint","Add the workshop's accessibility and performance criteria to a release acceptance checklist owned by the product owner, and test against it in the final sprint","Ask the team and the compliance office to assess the accessibility and performance defects in the delivered stories before deciding what the definition of done should contain","Add the workshop's criteria to the product backlog as non-functional stories owned by the product owner, and keep the definition of done as the team wrote it"],ans:[0],why:["Đúng: nhu cầu accessibility và performance đã được thu thập trong workshop, nên bước cần làm là đưa chúng vào definition of done để mọi story từ sprint sau đều được kiểm tra theo cùng chuẩn.","Sai: checklist chấp nhận ở cuối chỉ chặn lỗi sau khi các story đã được tính là done. Sẽ đúng nếu dự án chỉ có một cổng chấp nhận trước khi phát hành, nhưng ở đây đội giao theo sprint và DoD là chuẩn duy nhất áp dụng cho từng story.","Sai: workshop sau review đã thu thập đủ nhu cầu accessibility và performance, nên đánh giá lại khoảng trống trên các story đã giao là lặp lại việc đã xong. Sẽ đúng nếu chưa có tiêu chí nào được thu thập, nhưng ở đây tiêu chí đã có mà DoD chưa chứa.","Sai: story phi chức năng trong product backlog nhưng definition of done vẫn như cũ thì các story khác tiếp tục được tính là done mà không kiểm accessibility hay performance. Sẽ đúng nếu đây là việc một lần, nhưng ở đây tiêu chí thiếu trong DoD."],exp:'Task R7, enabler "Gather quality requirements for project deliverables". Yêu cầu quality phi chức năng (accessibility, hiệu năng) phải đi vào definition of done và acceptance criteria thì mới được kiểm ở mọi sprint. Khi nhu cầu đã được thu thập, hành động đúng là cập nhật DoD và áp dụng ngay, không họp lại hay vá riêng lẻ. Bẫy: sửa lỗi sau khi phát hành thay vì sửa tiêu chí.'},{id:"o216",n:216,t:0,origin:"original",eco:"R8",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","schedule-approach","master-schedule"],type:"mc",q:"A hybrid project will install a robotic sorting line and its control software. The installation has fixed dates set by a building lease and crane availability, while the software scope is expected to evolve with warehouse feedback. The project manager is asked to prepare the schedule. What should the project manager do?",opts:["Run installation and software on one four-week sprint cadence, with the installation work broken into backlog items","Plan fixed-date installation as milestones in the master schedule and software as time-boxed iterations","Hold a scheduling workshop with the installer, and software lead to agree dependencies before choosing a method for each part","Build a critical path network for the installation and carry the software as one summary task with a single end date"],ans:[1],why:["Sai: nhịp sprint hợp với phần phần mềm đang thay đổi, nhưng ngày cẩu và hợp đồng thuê mặt bằng không điều chỉnh theo sprint. Sẽ đúng nếu cả hai phần đều linh hoạt, nhưng ở đây lắp đặt có ngày cố định.","Đúng: phần lắp đặt có ngày cố định nên đặt làm milestone trong master schedule; phần phần mềm còn thay đổi nên lập kế hoạch theo iteration có time-box, đóng góp vào milestone đó. Đây là tailoring đúng cho hybrid.","Sai: đề đã nêu rõ phần lắp đặt có ngày cố định và phần mềm thay đổi, nên chưa cần workshop để chọn phương pháp. Họp xác định dependency hợp lý ở bước sau, nhưng không thay thế việc chọn cách lập lịch.","Sai: đường găng cho lắp đặt là đúng, nhưng gói phần mềm thành một task với một ngày kết thúc không cho thấy các iteration và làm mất khả năng điều chỉnh khi phản hồi của kho đổi scope."],exp:'Task R8, enabler "Prepare a schedule based on the selected development approach". Lịch phải theo cách tiếp cận của từng phần: milestone và dependency cố định cho phần dự đoán, iteration/time-box cho phần thích nghi, rồi tích hợp bằng master schedule. Bẫy: một cách lập lịch cho mọi thứ.'},{id:"o217",n:217,t:0,origin:"original",eco:"R9",domain:"process",approach:"agile",tags:["agile","eco-2026","metrics","outcome-measures"],type:"mc",q:"A product organization asks its new agile team to report velocity and the number of stories closed to executives each month, and plans to compare teams using these numbers. The sponsor's stated goals are faster time to market and higher customer retention. The sponsor and product owner have already named lead time and 90-day customer retention as the measures that show those goals. How should the project manager develop the project metrics?",opts:["Report velocity and stories closed as requested, and add lead time and retention as extra columns in the same team comparison table the executives asked for","Hold a workshop with the executives to define what progress on time to market, and retention means before choosing any measures","Make lead time and 90-day retention the primary metrics, show velocity only as a planning aid, and drop the comparison between teams","Adopt the standard metric set the PMO publishes for all agile teams, so reporting stays consistent across the organization"],ans:[2],why:['Sai: thêm cột vẫn giữ việc so sánh đội bằng velocity, khuyến khích "thổi" điểm và che mất mục tiêu của sponsor. Sẽ ổn nếu chỉ dùng velocity để lập kế hoạch cho từng đội, nhưng ở đây nó bị dùng để so sánh.',"Sai: sponsor và product owner đã nêu rõ lead time và retention, nên việc xác định thế nào là tiến độ đã xong. Họp lại sẽ đúng nếu mục tiêu còn mơ hồ.","Đúng: chỉ số phải truy được về mục tiêu mà sponsor đã nêu. Đặt lead time và retention làm chỉ số chính, dùng velocity chỉ để lập kế hoạch, bỏ so sánh giữa các đội.","Sai: bộ chỉ số chuẩn của PMO giúp nhất quán nhưng không gắn với mục tiêu time to market và retention của sponsor này. Sẽ hợp lý nếu PMO quy định bộ chỉ số bắt buộc, nhưng đề không nói vậy."],exp:'Task R9, enabler "Develop project metrics, analysis, and reconciliation". Chỉ số phải truy được về mục tiêu và quyết định cần đưa ra. Khi sponsor đã nêu chỉ số, PM áp dụng chúng làm chỉ số chính và dùng velocity đúng mục đích (lập kế hoạch của đội), không dùng để so sánh đội. Bẫy: giữ chỉ số có sẵn và thêm cột.'},{id:"o218",n:218,t:0,origin:"original",eco:"R10",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","closure-criteria","phase-exit"],type:"mc",q:'A hybrid project built a pilot system in phase one and is about to enter phase two. The charter says the pilot must be "accepted". In a workshop last week the sponsor, customer and team agreed that acceptance means the sprint scope is done and the pilot passes a performance test; the signed workshop minutes record this. The team considers phase one finished because all sprints ended, while the performance test has not yet run. What should the project manager do?',opts:["Hold the phase gate now with the sponsor on the completed sprints, and move the performance test into the phase-two plan as an accepted risk","Run the performance test against the criteria in the signed minutes, then hold the phase gate with the sponsor before phase two starts","Ask the customer's operations manager to run the performance test and sign off phase one in the sponsor's place at the gate review","Ask the sponsor and the customer to confirm the acceptance criteria in writing, and plan the performance test after the confirmation arrives"],ans:[1],why:["Sai: hoàn tất sprint chỉ là xong hoạt động, trong khi tiêu chí đã thống nhất gồm cả performance test. Đẩy test sang phase hai và để sponsor nhận rủi ro sẽ đúng nếu tiêu chí cho phép, nhưng ở đây tiêu chí đóng phase đã nêu rõ test.","Đúng: tiêu chí đã được các bên thống nhất và nằm trong biên bản ký, nên bước cần làm là chạy performance test theo tiêu chí đó rồi họp phase gate cùng sponsor trước khi vào phase hai.","Sai: operations manager là một bên liên quan, nhưng sign-off thay mặt sponsor vượt thẩm quyền của họ. Sẽ đúng nếu sponsor ủy quyền bằng văn bản, nhưng đề không nói vậy.",'Sai: biên bản workshop đã ký ghi rõ ý nghĩa của "accepted", nên xin sponsor và khách hàng xác nhận lại bằng văn bản là lặp lại việc đã xong. Sẽ đúng nếu tiêu chí chỉ được thống nhất miệng, nhưng ở đây đã có văn bản.'],exp:'Task R10, enabler "Determine criteria to successfully close the project or phase". Tiêu chí đóng phase đã được các bên thống nhất thì PM ghi lại thành exit criteria, thực hiện kiểm tra còn thiếu rồi đánh giá ở phase gate. Quy tắc nhớ: xong là so với tiêu chí đã thống nhất, không phải hết hoạt động. Bẫy: coi hết sprint là xong phase.'},{id:"o376",n:376,t:0,origin:"original",eco:"R6",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","contingency","emv"],type:"mc",q:"A hybrid program combines a predictive hardware installation with agile control software. The hardware team's register lists three open threats: a delivery delay (30% probability, $80,000 impact), a site access restriction (20%, $150,000) and a permit rework (50%, $40,000). The sponsor asks how much contingency reserve to include in the cost baseline for these identified risks. What should the project manager propose?",opts:["Include $74,000 as contingency reserve inside the cost baseline, controlled by the project manager and drawn down through the risk register","Include $74,000 as management reserve outside the cost baseline, held by the sponsor and released through change control","Include $104,000 as contingency reserve inside the cost baseline, the expected value of the three threats plus a 40% buffer set by the project manager","Include $150,000 as contingency reserve inside the cost baseline, sized to the largest single threat in the register and approved by the sponsor"],ans:[0],why:["Đúng: EMV = 0,3×80.000 + 0,2×150.000 + 0,5×40.000 = 24.000 + 30.000 + 20.000 = $74.000. Dự phòng cho rủi ro đã nhận diện là contingency reserve và nằm trong cost baseline.","Sai: số $74.000 đúng nhưng loại dự phòng sai: management reserve dành cho unknown-unknowns, nằm ngoài baseline. Rủi ro đã nằm trong register thì dùng contingency. Sẽ đúng nếu rủi ro chưa được nhận diện.","Sai: EMV đã phản ánh xác suất của ba rủi ro; cộng thêm 40% buffer là con số tùy ý, không có cơ sở phân tích. Buffer chỉ hợp lý nếu có đánh giá độ bất định riêng của ước tính.","Sai: dự phòng cho đúng một rủi ro lớn nhất bỏ qua hai rủi ro còn lại và xác suất. Cách này đúng cho một sự kiện hiếm cực lớn, nhưng ở đây ba rủi ro đều đã có xác suất."],exp:'Task R6, enabler "Quantify risk and contingency financial allocations". EMV = xác suất × tác động, cộng các rủi ro đã nhận diện thì ra contingency reserve đưa vào cost baseline. Phân biệt: contingency reserve (known-unknowns, trong baseline) và management reserve (unknown-unknowns, ngoài baseline). Bẫy: đúng số nhưng sai loại reserve.'},{id:"o377",n:377,t:0,origin:"original",eco:"R6",domain:"process",approach:"predictive",tags:["predictive","eco-2026","spend-tracking","earned-value"],type:"mc",q:"A pipeline construction project has an approved cost baseline of $4.5 million and 40 work packages. During planning, the finance partner asks how the project manager will track spend against progress, because some packages run for several months before any deliverable is finished. What should the project manager define in the cost management plan?",opts:["Reviews of work package spend against budget at deliverable acceptance, with a variance threshold of 5% of the package budget","A weekly check by finance of purchase orders and invoices against each package budget, plus a monthly total for the sponsor","Progress on each package measured as hours used divided by hours budgeted, with variance thresholds that trigger a review","Rules for measuring earned value on each work package, plus variance thresholds that trigger a review"],ans:[3],why:["Sai: kiểm tra khi deliverable được chấp nhận là hợp lý cho package ngắn, nhưng ở đây có package chạy nhiều tháng chưa có deliverable nên sai lệch bị che trong thời gian dài.","Sai: so sánh hóa đơn với ngân sách package chỉ cho biết đã tiêu bao nhiêu, không cho biết công việc đạt đến đâu. Finance hỏi cách theo dõi chi tiêu so với tiến độ, không chỉ so với ngân sách.",'Sai: giờ đã dùng chia giờ ngân sách đo công sức tiêu thụ, không đo công việc đã hoàn thành; package làm chậm cũng hiện ra là "đúng tiến độ" khi giờ tăng. Cách này đúng chỉ khi tiến độ tỷ lệ với giờ công.',"Đúng: chi tiêu chỉ có ý nghĩa khi so với giá trị công việc đã hoàn thành. Với package kéo dài nhiều tháng cần quy tắc đo earned value (ví dụ milestone có trọng số) và ngưỡng variance định sẵn trong cost management plan."],exp:'Task R6, enabler "Plan spend tracking throughout the project life cycle". Cost management plan phải nêu phương pháp đo (earned value, quy tắc tính tiến độ cho từng loại package), tần suất và ngưỡng variance. Bẫy: nhầm theo dõi chi tiêu (actual cost) với theo dõi hiệu quả chi tiêu (so với giá trị làm ra).'},{id:"o378",n:378,t:0,origin:"original",eco:"R6",domain:"process",approach:"agile",tags:["agile","eco-2026","financial-reporting","funding-envelope"],type:"mc",q:"A product team is funded in quarterly increments and delivers working software every two weeks. The finance director is used to reports showing percent complete against a fixed plan and is confused by the team's burn-up chart. She has already told the project manager that she needs monthly spend against the quarterly funding and a list of what was delivered. The sponsor wants confidence about spend. What should the project manager do to plan financial reporting?",opts:["Build a monthly finance report pairing spend against quarterly funding with the value delivered","Meet the finance director to learn which figures she needs, and how often before any report is designed","Convert the backlog into a work breakdown structure, and report percent complete in the finance format","Send the burn-up chart and sprint review notes to finance every sprint, with a short guide on how to read them"],ans:[0],why:["Đúng: finance director đã nêu rõ cô cần spend theo tháng so với vốn từng quý và danh sách sản phẩm đã giao. Báo cáo ghép hai thứ này đáp ứng đúng nhu cầu và vẫn hợp với cách làm agile.","Sai: nhu cầu của finance director đã được nói rõ, nên họp để tìm hiểu lại là lặp lại bước đã xong. Sẽ đúng nếu chưa biết cô cần gì.","Sai: ép backlog thành WBS để tính percent complete làm mất tính thích nghi của agile và tạo cảm giác chính xác giả; backlog sẽ đổi mỗi sprint. Sẽ đúng ở dự án predictive.","Sai: gửi burn-up kèm hướng dẫn giúp minh bạch nhưng bắt finance tự diễn giải, trong khi cô đã nói cần spend so với vốn quý. Báo cáo cần theo định dạng người đọc yêu cầu."],exp:'Task R6, enabler "Plan financial reporting". Báo cáo tài chính thỏa thuận nội dung, tần suất, định dạng với người đọc. Khi finance đã nêu nhu cầu, PM dựng báo cáo ngay, gắn chi tiêu với giá trị đã giao thay vì dùng mẫu predictive hay gửi biểu đồ nội bộ. Bẫy: áp mẫu của một phương pháp lên phương pháp khác.'},{id:"o379",n:379,t:0,origin:"original",eco:"R6",domain:"process",approach:"predictive",tags:["predictive","eco-2026","currency-risk","finance-forecast"],type:"mc",q:"A predictive plant upgrade will run for 20 months. About 40% of the equipment cost is contracted in euros and paid in four milestone payments, while the project budget and reporting are in U.S. dollars. The euro has been volatile and the contracts have no currency clauses. Finance has quantified the exposure at about $380,000 for a 10% move and has compared hedging with accepting the exposure; it recommends forward contracts. Treasury policy allows forwards only when the sponsor approves the hedging cost. What should the project manager do?",opts:["Commission treasury to run a hedging comparison for the four euro payments, and report to the project manager before any approval is requested","Reforecast the cost baseline each month at the latest exchange rate, and report the difference to the steering committee as a currency variance","Escalate the exposure and finance's recommended forwards to the sponsor for approval of the hedging cost, and record the response in the risk register","Instruct the vendor through the contracts team to invoice the remaining payments in dollars at the proposal-date rate, and log it in the risk register"],ans:[2],why:["Sai: mức phơi nhiễm đã được lượng hóa và finance đã so sánh hedging với chấp nhận rủi ro, nên yêu cầu treasury phân tích lại là lặp lại việc đã xong. Sẽ đúng nếu chưa có khuyến nghị, nhưng ở đây cần quyết định của sponsor.","Sai: đổi baseline mỗi tháng theo tỷ giá làm baseline mất vai trò mốc so sánh; baseline chỉ đổi qua change control. Cách này biến rủi ro dự báo được thành variance sau sự việc.","Đúng: finance đã lượng hóa phơi nhiễm và khuyến nghị forward contract, còn chính sách treasury yêu cầu sponsor duyệt chi phí hedging. PM escalate đề xuất lên sponsor rồi ghi biện pháp vào risk register.","Sai: hợp đồng không có điều khoản tiền tệ nên nhà cung cấp không có nghĩa vụ đổi sang đô la theo tỷ giá cũ. Sẽ khả thi nếu hợp đồng có điều khoản đó, nhưng ở đây không có."],exp:'Task R6, enabler "Anticipate future finance challenges". Mức phơi nhiễm tỷ giá đã được lượng hóa và finance đã so sánh phương án; chính sách treasury đặt quyền duyệt chi phí hedging ở sponsor, nên PM escalate đề xuất lên sponsor rồi ghi biện pháp vào risk register. Quy tắc nhớ: baseline chỉ đổi qua change control, không đổi theo thị trường.'},{id:"o380",n:380,t:0,origin:"original",eco:"R6",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","evm","eac","governance"],type:"mc",q:"A hybrid project has a budget at completion of $1,200,000. Status shows earned value of $400,000, actual cost of $480,000 and planned value of $450,000. The steering committee requires its review of any forecast overrun above 10%. The cause is a vendor day rate that will stay higher for the rest of the contract, so the cost performance seen so far will continue. What should the project manager do next?",opts:["Forecast an estimate at completion of $1,280,000, adding the remaining budget to the actual cost, and report it in the next update","Report the $80,000 cost variance to the steering committee and have it decide how the forecast should be built","Forecast an estimate at completion of $1,440,000 using BAC divided by CPI, and take it to the steering committee now","Forecast $1,440,000 using BAC divided by CPI, and agree a recovery plan with the vendor before telling the steering committee"],ans:[2],why:["Sai: $1.280.000 = AC + (BAC − EV) chỉ đúng khi sai lệch là bất thường, sẽ không lặp lại. Ở đây giá cao còn kéo dài nên số này thấp hơn thực tế và còn nằm dưới ngưỡng 10%.","Sai: variance chỉ mô tả quá khứ; dự báo là việc của PM. Đẩy việc dự báo cho ủy ban làm mất giá trị phân tích mà PM phải mang tới.","Đúng: CPI = 400.000/480.000 = 0,83; nguyên nhân (giá nhân công) kéo dài nên EAC = BAC/CPI = $1.440.000, vượt baseline 20% (> 10%) nên PM đưa lên steering committee theo ngưỡng đã thống nhất.","Sai: số $1.440.000 đúng, nhưng dự báo vượt 20% > ngưỡng 10% nên phải đưa lên steering committee ngay. Thương lượng với vendor trước là sai thứ tự; kế hoạch phục hồi có thể làm tiếp cùng ủy ban."],exp:'Task R6, enabler "Monitor financial variations and work with the governance process". Chọn công thức EAC theo nguyên nhân: sai lệch kéo dài thì EAC = BAC/CPI; sai lệch một lần thì EAC = AC + (BAC − EV). Sau đó so với ngưỡng governance và báo cáo đúng người. Bẫy: dùng công thức "bất thường" khi nguyên nhân vẫn còn.'},{id:"o381",n:381,t:0,origin:"original",eco:"R6",domain:"process",approach:"agile",tags:["agile","eco-2026","management-reserve","governance"],type:"mc",q:"An agile team building a patient portal has a funding envelope with a contingency reserve of $40,000, already allocated to risks on the register. A newly published data-privacy rule adds work estimated at $90,000, and it was not on the risk register. The sponsor holds a $150,000 management reserve intended for unplanned work. What should the project manager do?",opts:["Require the product owner to place the privacy work in the backlog and absorb the $90,000 within the envelope","Draw the $40,000 contingency and ask the sponsor for the remaining $50,000 from the management reserve","Assess the new rule's effect on the risk register with the team, before touching any reserve this quarter","Request $90,000 from the management reserve through governance and update the funding envelope and the backlog"],ans:[3],why:["Sai: product owner quản lý thứ tự backlog, nhưng nguồn tiền cho việc mới ngoài kế hoạch là việc của sponsor và governance. Sẽ đúng nếu envelope còn dư, nhưng ở đây việc $90.000 vượt xa reserve.","Sai: $40.000 contingency đã được phân bổ cho rủi ro trong register; lấy dùng cho việc khác làm mất khả năng ứng phó khi các rủi ro đó xảy ra. Việc mới là unknown-unknown nên dùng management reserve.","Sai: đề đã cho ước tính $90.000 và nói rõ rủi ro chưa nằm trong register, nên bước đánh giá đã có. Cập nhật register là việc tốt nhưng không thay thế việc xin nguồn tiền.","Đúng: yêu cầu mới không có trong risk register là unknown-unknown, nguồn đúng là management reserve do sponsor giữ. Phải xin qua governance, rồi cập nhật funding envelope và backlog."],exp:'Task R6, enabler "Manage financial reserves". Contingency reserve (trong baseline) cho rủi ro đã nhận diện; management reserve (ngoài baseline) cho việc không lường trước và chỉ giải ngân qua governance. Quy tắc nhớ: đúng loại reserve, đúng người duyệt, rồi cập nhật tài liệu.'},{id:"o382",n:382,t:0,origin:"original",eco:"R6",domain:"process",approach:"predictive",tags:["predictive","eco-2026","cash-flow","funding-limit"],type:"mc",q:"A software migration has a time-phased cost baseline totaling $3.6 million. The funding agreement releases money in four equal quarterly tranches of $900,000. The cumulative spend plan shows $1.4 million needed by the end of the first quarter, because the signed license contract requires full prepayment. The contract fixes both the scope and the license purchase. The project manager has just completed the budget. What should the project manager do?",opts:["Move the license prepayment into the second quarter of the cost baseline so that the first quarter fits the $900,000 tranche, and note it in the baseline log","Escalate to the vendor's account manager a request for license installments, and update the cost baseline when the vendor agrees to them","Escalate the $500,000 first-quarter gap to the sponsor, bringing the reconciled spend plan, and ask for an advance of the second tranche or a schedule change","Reduce first-quarter scope by $500,000 through the change control board, and reconcile the spend plan with the tranche once the scope change is approved"],ans:[2],why:["Sai: chuyển khoản trả trước sang quý 2 trong baseline làm baseline không còn phản ánh khi nào thật sự chi tiền. Dòng tiền thiếu vẫn xảy ra ở quý 1.","Sai: đàm phán trả góp là lựa chọn hợp lệ nếu hợp đồng cho phép, nhưng hợp đồng đã ký yêu cầu trả trước đủ nên PM không thể giả định nhà cung cấp đồng ý.","Đúng: $1,4 triệu − $0,9 triệu = $500.000 thiếu ở quý 1. Đây là chênh lệch giữa chi tiêu lũy kế và lịch giải ngân; sponsor sở hữu nguồn vốn nên PM escalate để quyết định lịch giải ngân.","Sai: giảm scope qua CCB đúng nếu scope còn linh hoạt, nhưng hợp đồng cố định cả scope lẫn khoản mua license. Cắt scope không xử lý được khoản trả trước đã ký."],exp:'Task R6, enabler "Analyze project financial needs". Nhu cầu tài chính gồm cả thời điểm cần tiền: so sánh cumulative spend với funding limit để phát hiện tuần/quý thiếu vốn khi còn lập kế hoạch. Bẫy: lập baseline "đẹp" rồi chờ thiếu tiền thật mới báo.'},{id:"o383",n:383,t:0,origin:"original",eco:"R6",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","ai","forecast-validation"],type:"mc",q:"A hybrid project uses an AI forecasting tool that reads timesheets and invoices. It now predicts a 12% cost overrun, while the project manager's bottom-up estimate to complete implies 3%. The team has already checked the tool's inputs and traced the gap to eight weeks of timesheets that are missing from the tool's source data. The finance partner has already seen the AI figure on a shared dashboard. How should the project manager handle this?",opts:["Ask the AI vendor to review the model's assumptions and correct its 12% overrun prediction for the project","Complete the missing timesheets in the source data, re-run the forecast, and brief finance on the reconciled figure","Publish both the 3% and 12% figures with a note on the data gap, and leave the tool's input as it is","Test the tool's inputs and assumptions against the bottom-up estimate, before deciding which figure to give finance this week"],ans:[1],why:["Sai: lỗi nằm ở dữ liệu timesheet của dự án, không phải mô hình của vendor. Hỏi vendor sẽ hợp lý nếu dữ liệu đầu vào đầy đủ nhưng dự báo vẫn lệch.","Đúng: nguyên nhân đã được tìm ra là thiếu tám tuần timesheet. PM bổ sung dữ liệu, chạy lại dự báo và báo finance con số đã được đối chiếu.","Sai: công bố cả hai số và ghi chú minh bạch, nhưng không sửa dữ liệu nên chênh lệch vẫn còn và finance vẫn phải tự chọn số. Sẽ đủ nếu không sửa được dữ liệu.","Sai: bước kiểm tra đầu vào và giả định đã được đội làm xong và đã ra nguyên nhân. Làm lại sẽ đúng nếu chưa biết vì sao có chênh lệch."],exp:'Task R6, enabler "Anticipate future finance challenges", với AI là bối cảnh. Dự báo tài chính do PM chịu trách nhiệm; khi nguyên nhân chênh lệch đã tìm ra (thiếu dữ liệu nguồn), PM sửa dữ liệu, chạy lại và báo finance số đã đối chiếu. Quy tắc nhớ: kiểm chứng đầu ra AI, sửa tại nguồn, giữ minh bạch.'},{id:"o384",n:384,t:0,origin:"original",eco:"R6",domain:"process",approach:"agile",tags:["agile","eco-2026","contingency","velocity","funding-envelope"],type:"mc",q:"A product team has a backlog of 360 story points. Its velocity has varied between 24 and 36 points per sprint and averages 30. Each two-week sprint costs $50,000, and the budget is built on average velocity. The sponsor wants a funding reserve that covers the slowest velocity observed. How much contingency should the project manager request?",opts:["$100,000, which funds two extra sprints for a team that runs 10% below its average velocity of 30 points per sprint","$750,000, which is the complete cost of delivering the backlog at the slowest observed velocity of 24 points per sprint","$240,000, which funds the 12-point spread between the fastest and slowest sprints as 40% of the $600,000 budget","$150,000, which funds three extra sprints: the 15 needed at 24 points per sprint, less the 12 planned at 30 points"],ans:[3],why:["Sai: hai sprint thêm hợp với đội chậm hơn 10% so với trung bình (27 điểm, cần 14 sprint), nhưng sponsor yêu cầu phủ velocity thấp nhất đã thấy là 24 điểm (cần 15 sprint).","Sai: $750.000 là tổng chi phí ở velocity thấp nhất, trong đó $600.000 đã nằm trong ngân sách. Contingency chỉ là phần chênh.","Sai: độ chênh 12 điểm không phải tỷ lệ dự phòng; 40% ngân sách không dựa trên số sprint thật sự cần thêm. Cách tính đúng là tính số sprint ở velocity thấp nhất.","Đúng: 360/30 = 12 sprint ($600.000); ở velocity thấp nhất 360/24 = 15 sprint ($750.000). Chênh 3 sprint × $50.000 = $150.000 là contingency."],exp:'Task R6, enabler "Quantify risk and contingency financial allocations" trong bối cảnh agile. Dự phòng tính từ độ biến thiên velocity: số sprint ở kịch bản xấu trừ số sprint kế hoạch, nhân chi phí mỗi sprint. Bẫy: nhầm tổng chi phí kịch bản xấu với phần dự phòng cần thêm.'},{id:"o385",n:385,t:0,origin:"original",eco:"R6",domain:"process",approach:"predictive",tags:["predictive","eco-2026","evm","tcpi"],type:"mc",q:"Partway through a predictive project with a budget at completion of $600,000, planned value is $200,000, earned value is $150,000 and actual cost is $180,000. The sponsor asks what cost efficiency the team must achieve on the remaining work to still finish within the original budget. What should the project manager report?",opts:["The team must earn about $1.13 of value per dollar spent, found by dividing the remaining work by the remaining planned value","The team must earn about $0.83 of value per dollar spent, which is the cost performance achieved so far","The team must earn about $1.07 of value per dollar spent, shown by the to-complete performance index","The team must earn about $1.00 of value per dollar spent, because the original baseline assumed full cost efficiency"],ans:[2],why:["Sai: 1,13 = 450/400 dùng planned value còn lại (600 − 200) làm mẫu số, trong khi chi phí thực tế đã là $180.000. Mẫu số phải là ngân sách còn lại (BAC − AC).","Sai: 0,83 là CPI hiện tại (150/180), mô tả hiệu quả đã đạt, không phải hiệu quả cần có từ nay.","Đúng: TCPI = (BAC − EV)/(BAC − AC) = (600 − 150)/(600 − 180) = 450/420 ≈ 1,07. Đội phải làm ra $1,07 giá trị trên mỗi đô la còn lại để giữ trong BAC.","Sai: baseline giả định hiệu quả 1,0 từ đầu, nhưng thực tế CPI chỉ 0,83. Để giữ trong BAC, đội phải làm tốt hơn mức 1,0 trên phần còn lại."],exp:'Task R6, enabler "Monitor financial variations and work with the governance process". TCPI theo BAC = (BAC − EV)/(BAC − AC): TCPI lớn hơn 1 nghĩa là phần còn lại phải làm hiệu quả hơn kế hoạch; so với CPI hiện tại để đánh giá mục tiêu có khả thi không rồi báo cho governance. Bẫy: nhầm CPI, SPI và TCPI.'},{id:"o386",n:386,t:0,origin:"original",eco:"R6",domain:"process",approach:"predictive",tags:["predictive","eco-2026","variance","change-control","thresholds"],type:"mc",q:"A predictive project has a $5 million cost baseline. Governance rules let the project manager approve forecast variances up to 5% of the baseline; anything larger goes to the change control board. Because of a design correction accepted by the customer in writing, the forecast now exceeds the baseline by $400,000, and no management reserve has been released. The impact analysis and options were completed last week. What should the project manager do?",opts:["Ask the sponsor to release management reserve for the $400,000 variance, and update the cost baseline once the work is finished","Take the $400,000 variance to the steering committee for approval, with the sponsor chairing the meeting and the customer's written acceptance attached to the paper","Prepare an impact analysis of alternative corrections for the $400,000 variance, and send the variance to governance once the options are compared","Escalate the $400,000 forecast variance, 8% of the baseline, to the change control board, bringing the completed impact analysis and the written acceptance"],ans:[3],why:["Sai: reserve cũng phải qua quy trình change/governance, và baseline chỉ được cập nhật sau khi thay đổi đã được duyệt, không phải sau khi làm xong.","Sai: steering committee quan trọng nhưng quy tắc governance đặt thay đổi vượt 5% baseline ở change control board. Sẽ đúng nếu quy tắc nêu steering committee, nhưng ở đây là CCB.","Sai: impact analysis và các phương án đã hoàn thành tuần trước, nên làm lại là lặp lại bước đã xong. Sẽ đúng nếu thay đổi chưa được phân tích.","Đúng: $400.000/$5 triệu = 8% > ngưỡng 5% của PM. Phân tích tác động đã xong, nên bước cần làm là trình change request kèm phân tích lên change control board."],exp:'Task R6, enabler "Monitor financial variations and work with the governance process". Biết ngưỡng thẩm quyền, tính đúng tỷ lệ variance (8%), rồi đi qua đường escalation đã định: change request lên CCB khi phân tích đã xong. Quy tắc nhớ: đúng người có thẩm quyền, đúng thứ tự, không làm lại bước đã có.'},{id:"o387",n:387,t:0,origin:"original",eco:"R7",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","quality-plan","test-strategy"],type:"mc",q:"A hybrid project delivers a connected medical scale: hardware assembled in batches and firmware released in two-week iterations. The sponsor asks the project manager to plan the quality processes and tools. The quality objectives and defect metrics were agreed with the sponsor last month. Earlier projects used one inspection checklist for everything and missed firmware regression defects. What should the project manager do?",opts:["Apply the agile team's automated regression approach to the whole product in the quality management plan, and retire the hardware inspection step","Hold a quality workshop with the hardware and firmware leads to set the defect metrics, then choose sampling for hardware and regression tests for firmware","Choose quality methods per component in the quality management plan: sampling inspection for hardware batches and automated regression tests for firmware","Extend the existing inspection checklist with firmware items in the quality management plan, and have the quality team apply it at each hardware batch and each firmware release"],ans:[2],why:["Sai: áp tự động hóa kiểu agile cho cả dự án rồi bỏ bước inspection thì phần cứng không được kiểm: lô vật lý cần inspection và sampling. Một quy trình cho tất cả chỉ tiện về hình thức.","Sai: mục tiêu chất lượng và chỉ số lỗi đã được thống nhất với sponsor tháng trước, nên workshop để đặt lại chỉ số là lặp lại bước đã xong dù hướng chọn công cụ đúng. Sẽ đúng nếu mục tiêu chưa được chốt.","Đúng: quality plan phải chọn công cụ theo bản chất từng thành phần: lấy mẫu kiểm tra cho lô phần cứng, regression tự động cho firmware lặp lại. Bài học dự án trước chính là một checklist cho mọi thứ.","Sai: mở rộng checklist cũ lặp lại cách làm đã bỏ sót lỗi regression; một danh sách kiểm tra thủ công cho cả hai loại không bắt được hồi quy của firmware phát hành mỗi hai tuần."],exp:'Task R7, enabler "Plan quality processes and tools". Quality management plan chọn kỹ thuật và công cụ phù hợp từng loại deliverable (sampling, kiểm tra, test tự động, review) cùng chỉ số đo. Trong hybrid, tailoring theo thành phần là điểm chính. Bẫy: một quy trình đồng nhất cho mọi thành phần.'},{id:"o388",n:388,t:0,origin:"original",eco:"R7",domain:"process",approach:"agile",tags:["agile","eco-2026","ai","quality-assurance","test-coverage"],type:"mc",q:"A scrum team adopted an AI tool that generates test cases and reports a 98% pass rate every sprint. After release, customers report defects in a scenario that the generated tests never covered. The quality plan says each sprint's tests must verify the acceptance criteria. The testers have already compared the generated tests with the acceptance criteria and found three uncovered scenarios. What should the project manager do next?",opts:["Compare the generated tests against the acceptance criteria to find which scenarios are not covered","Get the AI vendor to raise the coverage of the generated tests, and re-run the same sprint tests to confirm in the next sprint","Raise the required pass rate in the quality plan from 98% to 100% before any sprint is released","Create tests for the three uncovered scenarios in the suite, and require human sign-off on generated tests every sprint"],ans:[3],why:["Sai: việc đối chiếu test với acceptance criteria đã được tester làm xong và đã chỉ ra ba kịch bản thiếu. Làm lại sẽ đúng nếu chưa biết thiếu kịch bản nào.","Sai: ba kịch bản thiếu đã được tester xác định, nhưng yêu cầu vendor tăng coverage chung không nhắm vào chúng và không gắn với acceptance criteria của đội. Sẽ đúng nếu thiếu hụt nằm ở công cụ chứ không ở bộ test của đội.","Sai: nâng pass rate lên 100% không giải quyết vấn đề vì các test hiện có vẫn đạt; lỗi nằm ở kịch bản chưa được test. Pass rate chỉ có nghĩa khi độ phủ đủ.","Đúng: ba kịch bản thiếu đã xác định, nên bổ sung test cho chúng và đặt bước người duyệt mỗi sprint để kế hoạch chất lượng thực sự kiểm chứng acceptance criteria."],exp:'Task R7, enabler "Execute a quality management plan", với AI là bối cảnh. Khi khoảng trống độ phủ đã được xác định, hành động đúng là bổ sung test và đặt bước người duyệt đầu ra AI, không đo lại hay nâng chỉ tiêu pass rate. Bẫy: tin vào pass rate thay vì độ phủ so với yêu cầu.'},{id:"o389",n:389,t:0,origin:"original",eco:"R7",domain:"process",approach:"predictive",tags:["predictive","eco-2026","regulatory-compliance","traceability"],type:"mc",q:"A predictive project is building an infusion pump under a medical-device regulator. The auditor will need traceable evidence that each requirement was verified. The quality plan describes testing but not the format or storage of records, and the test team is two weeks from starting verification. Compliance has already approved the evidence format and storage location. What should the project manager do?",opts:["Map each regulatory requirement to a test case, and have the test team record every result in the approved format and location from the first test","Meet compliance and the test lead to settle the evidence format and storage location, and approve the start of verification only afterward","Let the test team run verification first, then have the quality lead assemble the records afterward in the order of the regulator's checklist","Engage an external auditor, reporting to compliance, to certify the whole evidence package after verification ends and before it goes to the regulator"],ans:[0],why:["Đúng: compliance đã duyệt định dạng và nơi lưu, nên PM ánh xạ từng yêu cầu quy định sang một test và ghi kết quả đúng định dạng trước khi verification bắt đầu để có bằng chứng truy vết.","Sai: định dạng và nơi lưu bằng chứng đã được compliance duyệt, nên họp lại là lặp lại bước đã xong. Sẽ đúng nếu compliance chưa chốt.","Sai: chạy verification rồi mới gom hồ sơ thì bằng chứng có thể không được ghi đủ; test không có bản ghi truy vết được coi như chưa làm. Sắp theo checklist chỉ sắp xếp, không tạo ra bằng chứng đã mất.","Sai: thuê auditor ngoài sau khi test kết thúc là quá muộn để sửa thiếu sót bằng chứng. Sẽ hữu ích nếu bằng chứng đã được ghi từ đầu và cần xác nhận độc lập."],exp:'Task R7, enabler "Help ensure regulatory compliance". Khi định dạng bằng chứng đã được compliance duyệt, PM ánh xạ yêu cầu quy định sang test và bắt đầu ghi bằng chứng theo định dạng đó từ lần test đầu. Quy tắc nhớ: bằng chứng được thiết kế trước, không gom sau.'},{id:"o390",n:390,t:0,origin:"original",eco:"R7",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","cost-of-quality","prevention"],type:"mc",q:"A hybrid project reviews its cost of quality after the second release. Prevention (training and design reviews) cost $40,000, appraisal (testing and inspections) $60,000, internal failure (rework before release) $90,000 and external failure (warranty and support) $150,000. Root-cause notes trace most of these failures to unclear requirements and design errors. The sponsor wants to cut quality spending. What should the project manager conclude from the data?",opts:["Appraisal is the best lever, because testing from $60,000 to $120,000 would catch the $150,000 of external failures before release","Nonconformance costs of $240,000 exceed conformance costs of $100,000, so more prevention should lower the total","The $90,000 internal failure cost is the main target, so the team should speed up rework and shorten the rework cycle","The $40,000 prevention budget should be cut, as failures stayed high even after the training and design reviews"],ans:[1],why:["Sai: tăng thẩm định bắt lỗi sớm hơn nhưng không ngăn lỗi; ghi chú nguyên nhân cho thấy lỗi bắt nguồn từ yêu cầu và thiết kế chưa rõ. Sẽ đúng nếu lỗi sinh ra ở khâu làm ra sản phẩm.","Đúng: cost of conformance = 40.000 + 60.000 = $100.000; cost of nonconformance = 90.000 + 150.000 = $240.000. Chi phí lỗi gấp 2,4 lần chi phí tuân thủ và phần lớn lỗi bắt nguồn từ yêu cầu, thiết kế chưa rõ, nên đầu tư phòng ngừa thêm thường giảm tổng chi phí.","Sai: rút ngắn chu kỳ làm lại giảm một phần chi phí lỗi nội bộ, nhưng không chạm vào lỗi bắt nguồn từ yêu cầu và thiết kế, và chi phí lỗi ngoại vi $150.000 vẫn còn.","Sai: lỗi vẫn cao vì phòng ngừa chưa nhắm vào nguyên nhân gốc là yêu cầu và thiết kế; cắt $40.000 sẽ làm chi phí lỗi tăng thêm. Cắt chỉ đúng nếu phòng ngừa đã nhắm đúng mà vẫn không hiệu quả."],exp:'Task R7, enabler "Manage cost of quality (CoQ)". CoQ = cost of conformance (prevention + appraisal) + cost of nonconformance (internal + external failure). Khi chi phí lỗi lớn hơn nhiều, đầu tư phòng ngừa thường có lợi hơn. Bẫy: cắt chi phí chất lượng chỉ vì thấy tổng lớn.'},{id:"o391",n:391,t:0,origin:"original",eco:"R7",domain:"process",approach:"agile",tags:["agile","eco-2026","continuous-improvement","retrospective"],type:"mc",q:"In three consecutive retrospectives, a team named slow code reviews as its biggest impediment and agreed on actions, but nothing has changed and velocity is flat. Team members now call the retrospective a talking shop. In the last retrospective the team voted code-review turnaround as the single issue to fix and agreed on a target of one working day. What should the project manager do?",opts:["Add a root-cause analysis item to the backlog, owned by the tech lead, and defer the one-day turnaround action until the analysis reports at the next sprint review","Add the one-day turnaround action to the backlog and have the scrum master replace the retrospective with a monthly anonymous survey","Add the one-day review turnaround action to the sprint backlog, name a team member as its owner, and show the measure at each sprint review","Ask the functional manager to set and own the review turnaround target, with violations reported to the team lead at each sprint review"],ans:[2],why:["Sai: đội đã bỏ phiếu chọn đúng một vấn đề và đã có chỉ tiêu một ngày, nên bước tìm nguyên nhân đã xong. Sẽ đúng nếu đội chưa biết vấn đề nào cần xử lý, nhưng ở đây hoãn hành động chỉ kéo dài tình trạng nói mà không làm.","Sai: hành động có vào backlog, nhưng thay retrospective bằng khảo sát ẩn danh không giải quyết khâu theo dõi hành động. Sẽ đúng nếu đội ngại nói công khai, nhưng ở đây đội đã nói rõ vấn đề.","Đúng: hành động đã được chọn và có chỉ tiêu, nên cần một người sở hữu trong đội và đưa vào backlog để theo dõi như công việc khác, rồi cho thấy kết quả ở mỗi sprint review.","Sai: functional manager đặt chỉ tiêu và báo cáo vi phạm từ bên ngoài đi ngược với tự quản của đội. Sẽ đúng nếu vấn đề nằm ngoài quyền của đội, nhưng ở đây đội đã tự chọn chỉ tiêu và có thể tự sở hữu giải pháp."],exp:'Task R7, enabler "Implement continuous improvement". Retrospective chỉ có giá trị khi dẫn tới hành động: ít mục, có người chịu trách nhiệm, đo được, nằm trong backlog. Khi đội đã chọn mục tiêu và chỉ tiêu, PM đưa nó vào backlog với owner thay vì họp thêm. Bẫy: đổi hình thức họp thay vì giải quyết khâu theo dõi hành động.'},{id:"o392",n:392,t:0,origin:"original",eco:"R7",domain:"process",approach:"predictive",tags:["predictive","eco-2026","sustainability","cost-of-quality","waste"],type:"mc",q:"A predictive project manufactures aluminum housings. Final inspection scrap is 6%, and each scrapped unit adds disposal cost and the energy used to remelt it. The quality plan tracks only inspection and rework costs, while the charter commits to cutting waste and emissions. Finance has already costed the scrap, disposal and remelt energy at $140,000 a year. A process-control upgrade would cost $90,000 and is expected to remove most of that scrap. How should the project manager proceed?",opts:["Weigh the upgrade against the inspection and rework savings the quality plan tracks, since the plan defines cost of quality that way","Approve the upgrade for its payback under a year on the full cost of quality, and add scrap and energy to the plan","Raise the final inspection sampling rate to catch more scrap early, which costs less than the upgrade","Have finance model the upgrade's savings in more detail over another quarter, before any decision is made"],ans:[1],why:["Sai: kế hoạch chất lượng chỉ tính kiểm tra và làm lại nên bỏ qua chi phí phế phẩm, xử lý và năng lượng mà finance đã tính ($140.000 một năm), và đánh giá thấp lợi ích. Sẽ đúng nếu không có số liệu phế phẩm và cam kết trong charter.","Đúng: finance đã tính chi phí phế phẩm, xử lý và năng lượng $140.000 một năm, nên $90.000 hoàn vốn dưới một năm và phù hợp cam kết trong charter. PM phê duyệt và bổ sung các chi phí này vào kế hoạch chất lượng.","Sai: tăng lấy mẫu kiểm tra chỉ phát hiện phế phẩm sớm hơn chút, không làm giảm tỷ lệ 6%, và vẫn không giải quyết nguyên nhân.","Sai: finance đã tính chi phí $140.000 mỗi năm và khoản đầu tư $90.000, nên cơ sở quyết định đã đủ. Mô hình hóa thêm sẽ đúng nếu số liệu còn thiếu hoặc chưa đáng tin."],exp:'Task R7, enabler "Manage cost of quality (CoQ) and sustainability". Chi phí chất lượng gồm cả tác động môi trường của lỗi (phế phẩm, chất thải, năng lượng) khi dự án cam kết bền vững. Khi phân tích đầy đủ đã có và cho kết quả hoàn vốn rõ, PM quyết định và cập nhật kế hoạch chất lượng. Bẫy: chỉ dùng định nghĩa CoQ hẹp trong kế hoạch.'},{id:"o393",n:393,t:0,origin:"original",eco:"R7",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","sustainability","cost-of-quality","test-strategy"],type:"mc",q:"A hybrid project to deliver smart thermostats plans destructive durability tests on 200 units from each hardware batch. The tests consume costly materials, and the resulting waste conflicts with the company's sustainability policy, which the charter cites. The firmware team uses simulations validated against past results. Quality and compliance have already confirmed that 30 units per batch plus the validated simulation meet the regulatory requirements. What should the project manager do?",opts:["Run a pilot comparing 30-unit samples with the 200-unit results on three batches before changing the test plan this quarter","Keep the 200-unit tests and send the spent materials to a certified recycler to meet the sustainability policy","Cut the sample to 20 units per batch, and update the test plan to match the sustainability policy","Update the test plan to 30 units per batch plus the validated simulation, and issue it through the change process"],ans:[3],why:["Sai: quality và compliance đã xác nhận mẫu 30 đơn vị cộng mô phỏng đạt yêu cầu, nên không cần chạy pilot so sánh nữa. Pilot sẽ đúng nếu chưa có xác nhận.","Sai: tái chế vật liệu giảm tác động nhưng vẫn tạo ra lượng chất thải lớn nhất, trong khi đã có cách đạt yêu cầu với mẫu nhỏ hơn. Tái chế sẽ đúng nếu không thể giảm mẫu.","Sai: mẫu 20 đơn vị chưa được quality và compliance xác nhận; chỉ con số 30 đã được chứng minh đạt yêu cầu. Chính sách bền vững không thay thế yêu cầu chất lượng.","Đúng: việc cân đối chi phí thẩm định với tác động môi trường đã được quality và compliance xác nhận. PM cập nhật test plan sang 30 đơn vị cộng mô phỏng và ban hành qua quy trình thay đổi."],exp:'Task R7, enabler "Manage cost of quality (CoQ) and sustainability". Chi phí thẩm định có hệ quả môi trường; khi chuyên gia đã xác nhận cách giảm mẫu vẫn đạt yêu cầu, PM cập nhật kế hoạch và ban hành qua quy trình thay đổi thay vì kiểm tra lại. Bẫy: hy sinh một mục tiêu cho mục tiêu kia mà không có bằng chứng.'},{id:"o394",n:394,t:0,origin:"original",eco:"R7",domain:"process",approach:"predictive",tags:["predictive","eco-2026","control-chart","quality-review"],type:"mc",q:"A predictive bottling project tracks fill volume on a control chart. For nine consecutive samples, the measurements have been above the mean line, but every point is inside the control limits and the product meets specification. The quality manager says the process is in control. What should the project manager do?",opts:["Have the quality manager recalculate the control limits from the last nine samples and approve the new limits for the control chart","Investigate the nine-point run above the mean with the quality manager, and correct the assignable cause before the process drifts further","Double the sampling frequency on the bottling line with the line supervisor, and act only when a point crosses a control limit","Have the quality manager confirm the capability index against the customer requirement, and leave the control chart unchanged until then"],ans:[1],why:["Sai: tính lại control limit từ dữ liệu đang lệch che mất chính tín hiệu; giới hạn nên được tính lại sau khi đã tìm ra và xử lý nguyên nhân. Sẽ đúng nếu quá trình đã thay đổi có chủ đích, nhưng đề không nói vậy.","Đúng: chín điểm liên tiếp cùng một phía đường trung bình là mẫu hình phi ngẫu nhiên dù chưa vượt giới hạn; cần truy ra nguyên nhân gán được trước khi quá trình ra khỏi kiểm soát.","Sai: lấy mẫu dày hơn là hợp lý để theo dõi, nhưng chỉ hành động khi điểm vượt giới hạn là bỏ qua quy tắc chuỗi cùng phía, tín hiệu cảnh báo sớm nhất. Sẽ đúng nếu chuỗi chưa đủ dài để coi là mẫu hình.","Sai: đề đã nói sản phẩm đạt specification, nên năng lực đáp ứng khách hàng đã rõ. Sẽ đúng nếu có nghi ngờ về specification, nhưng ở đây vấn đề là tín hiệu lệch của quá trình mà chỉ số năng lực không cho thấy."],exp:'Task R7, enabler "Conduct ongoing quality reviews". Đọc control chart: ngoài việc điểm vượt giới hạn, các mẫu hình như chuỗi bảy điểm cùng phía, xu hướng tăng/giảm đều cần điều tra. Control limits (khả năng quá trình) khác specification limits (yêu cầu khách hàng). Bẫy: nhầm "trong giới hạn" với "ổn định".'},{id:"o395",n:395,t:0,origin:"original",eco:"R7",domain:"process",approach:"agile",tags:["agile","eco-2026","sustainability","cost-of-quality","test-pipeline"],type:"mc",q:"A team's pipeline runs the full 4-hour regression suite on every code commit, about 60 times a day. Cloud costs and energy use have tripled, and the product's charter includes a carbon-reduction goal. Developers say the suite finds real defects but long waits slow delivery. The team has already measured that 90% of the defects are caught by 15-minute unit and smoke tests. What should the project manager do?",opts:["Facilitate the removal of the slowest quarter of the regression tests from the pipeline, and track build time and energy use each sprint","Facilitate running the 15-minute unit and smoke tests on every commit with the full suite nightly, and track escaped defects each sprint","Facilitate a move of the pipeline to a cheaper cloud tier with the infrastructure lead, keeping the full suite on each commit, and track cost each sprint","Facilitate a review of test cost and defect yield by test type before the pipeline schedule changes, and track the findings in the backlog"],ans:[1],why:["Sai: bỏ một phần bộ test vĩnh viễn làm mất các test có thể bắt lỗi thật; developer nói bộ test tìm ra lỗi thật. Dữ liệu đã cho thấy cách giảm mà không bỏ test.","Đúng: dữ liệu cho thấy 90% lỗi được bắt bởi test 15 phút, nên chạy chúng mỗi commit, dời bộ đầy đủ sang chạy đêm và theo dõi lỗi thoát để giảm chi phí, năng lượng mà không giảm chất lượng.","Sai: rẻ hơn mỗi giờ nhưng vẫn chạy 60 lần/ngày thì mức tiêu thụ không đổi, mục tiêu giảm carbon và thời gian chờ đều không giải quyết. Sẽ đúng nếu chỉ cần giảm chi phí tiền tệ.","Sai: đội đã đo hiệu quả bắt lỗi theo từng loại test (90% từ test 15 phút), nên bước phân tích đã xong. Sẽ đúng nếu chưa có dữ liệu defect yield."],exp:'Task R7, enabler "Manage cost of quality (CoQ) and sustainability". Chi phí thẩm định tự động cũng có chi phí tài chính và môi trường. Khi dữ liệu defect yield đã có, đội tái cấu trúc tần suất kiểm thử (nhanh mỗi commit, đầy đủ mỗi đêm) và theo dõi lỗi thoát. Quy tắc nhớ: tối ưu theo dữ liệu, không cắt kiểm thử tùy tiện.'},{id:"o396",n:396,t:0,origin:"original",eco:"R7",domain:"process",approach:"predictive",tags:["predictive","eco-2026","continuous-improvement","pdca"],type:"mc",q:"A predictive project piloted a revised inspection checklist on one production line. Defects per 100 units fell from 8 to 5 during the four-week pilot, as the quality plan targeted. The other three lines still use the old checklist. What should the project manager do next?",opts:["Roll out the revised checklist to all four lines under the quality management plan, with training for the other three lines and ongoing defect measurement","Extend the pilot on the first line for four more weeks, with the quality manager reviewing the data weekly, and decide on rollout when the extension ends","Ask the supervisors of the other three lines to adopt the revised checklist when each is ready, and have the quality manager review defect counts at project closure","Set a new target of 2 defects per 100 units with the quality manager, and run the next pilot toward it on the same production line"],ans:[0],why:["Đúng: chu trình plan-do-check-act: pilot đã đạt mục tiêu (check), bước tiếp theo là act: chuẩn hóa, cập nhật kế hoạch, đào tạo và tiếp tục đo để duy trì kết quả.","Sai: pilot đã đạt chỉ tiêu mà kế hoạch đặt ra trong bốn tuần, nên bước check đã xong; kéo dài và soát hàng tuần chỉ trì hoãn bước act. Sẽ đúng nếu kết quả dao động hoặc chưa đủ dữ liệu.","Sai: để từng giám sát tự áp dụng làm ba dây chuyền dùng cách kiểm tra khác nhau và không cập nhật quality management plan. Chuẩn hóa là việc của quality plan.","Sai: đặt mục tiêu mới trên cùng dây chuyền bỏ lỡ lợi ích đã chứng minh cho ba dây chuyền còn lại. Mục tiêu 2 lỗi chỉ hợp lý sau khi đã chuẩn hóa mức hiện tại."],exp:'Task R7, enabler "Implement continuous improvement". PDCA: khi bước check xác nhận cải tiến đạt kết quả, bước act là chuẩn hóa, cập nhật quality management plan, đào tạo, rồi đo tiếp. Quy tắc nhớ: cải tiến đã chứng minh phải được áp dụng ngay và ghi vào quy trình, không chờ cuối dự án.'},{id:"o397",n:397,t:0,origin:"original",eco:"R7",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","regulatory-compliance","definition-of-done"],type:"mc",q:"A hybrid project updates software at a regulated energy utility. The software teams release every two weeks, but the regulator requires documented safety verification before any change reaches the control room. Compliance staff review packages at the end of each month, and two releases have been held back. Compliance has now agreed to review complete packages within five working days. What should the project manager do?",opts:["Add safety evidence to each sprint's definition of done, owned by the quality lead, and pass the complete packages to the five-day compliance review","Assign a compliance liaison to work with the teams on each release's package, and keep the compliance review at month end for all releases","Meet compliance and the quality lead to negotiate a review cadence faster than five days, and change team practices only after that agreement","Move the software teams to monthly releases, with the release manager sending each month's changes to compliance as one package at month end"],ans:[0],why:["Đúng: compliance đã đồng ý rà soát trong năm ngày làm việc, nên đưa bằng chứng an toàn vào definition of done và gửi gói đầy đủ mỗi sprint để release không bị nghẽn cuối tháng.","Sai: người liên lạc giúp chuẩn bị gói tốt hơn, nhưng giữ rà soát cuối tháng bỏ qua thỏa thuận năm ngày và vẫn giữ các release bị kẹt. Sẽ đúng nếu compliance không đổi lịch.","Sai: nhịp rà soát đã được thỏa thuận (năm ngày làm việc), nên đàm phán lại là lặp lại bước đã xong. Sẽ đúng nếu compliance chưa đồng ý.","Sai: chuyển sang phát hành hàng tháng giữ bằng chứng ở cuối nhưng bỏ phản hồi nhanh hai tuần mà tổ chức cần; xử lý triệu chứng thay vì nguyên nhân."],exp:'Task R7, enabler "Help ensure regulatory compliance". Trong hybrid, yêu cầu quy định được chuyển thành tiêu chí hoàn thành (DoD) và cadence làm việc với compliance. Khi nhịp đã được thỏa thuận, PM áp dụng ngay vào DoD và quy trình gửi gói mỗi sprint. Bẫy: phát hành trước, bù hồ sơ sau, hoặc đàm phán lại điều đã đồng ý.'},{id:"o398",n:398,t:0,origin:"original",eco:"R8",domain:"process",approach:"agile",tags:["agile","eco-2026","velocity","release-forecast","historical-data"],type:"mc",q:"A product owner needs a release date for a 240-point backlog. The team's velocity in its last five sprints was 28, 32, 30, 26 and 34 points, and scope is stable. Sprints last two weeks, and a partial sprint counts as a whole sprint. Which forecast should the project manager give?",opts:["Seven to nine sprints, from the highest recent velocity of 34 points and the average of 30, given to the product owner as a range and refreshed each sprint","Eight sprints, from the average velocity of 30 points, given to the product owner as the forecast and refreshed each sprint in the release plan","Ten sprints, from the lowest recent velocity of 26 points, given to the product owner as the committed release date in the release plan","Eight to ten sprints, from the highest and lowest recent velocities, given to the product owner as a range and refreshed each sprint"],ans:[3],why:["Sai: 240/34 ≈ 7,06 nhưng một sprint dở dang tính là một sprint nên cận dưới là 8 chứ không phải 7, và 240/26 ≈ 9,2 → 10 nên cận trên là 10 chứ không phải 9. Sẽ đúng nếu lấy khoảng từ các velocity quan sát, nhưng ở đây làm tròn sai.","Sai: 240/30 = 8 sprint là điểm giữa và cập nhật mỗi sprint là đúng, nhưng một con số duy nhất che khoảng velocity 26–34 mà product owner cần thấy. Sẽ đúng nếu velocity không dao động.","Sai: 240/26 ≈ 9,2 → 10 sprint chỉ là cận trên của khoảng; lấy velocity thấp nhất làm ngày cam kết che đi phần còn lại của biến thiên 26–34 điểm mà product owner cần thấy.","Đúng: 240/34 ≈ 7,1 → 8 sprint; 240/26 ≈ 9,2 → 10 sprint. Dùng dữ liệu velocity lịch sử, đưa khoảng 8–10 sprint và cập nhật mỗi sprint."],exp:'Task R8, enabler "Utilize benchmarks and historical data" (agile). Dự báo release từ velocity lịch sử: tổng điểm chia velocity cao nhất và thấp nhất, làm tròn lên số sprint, trình bày thành khoảng và cập nhật liên tục. Bẫy: cam kết một ngày duy nhất từ giá trị trung bình, hoặc quên làm tròn lên.'},{id:"o399",n:399,t:0,origin:"original",eco:"R8",domain:"process",approach:"predictive",tags:["predictive","eco-2026","critical-path","schedule-compression"],type:"mc",q:"A predictive project network has these activities (durations in days): A 4 (no predecessor); B 6 (after A); C 3 (after A); D 5 (after B and C); E 4 (after C); F 2 (after D and E). The sponsor asks the project manager to shorten the 17-day schedule by 2 days. Crashing costs $3,000 per day on activity B and $1,000 per day on C and on E; no other activity can be shortened. Which action achieves this at the lowest cost?",opts:["Crash activity B by 2 days at $3,000 per day, a total of $6,000, and leave every other activity at its planned duration","Crash activity C by 2 days at $1,000 per day, a total of $2,000, and leave every other activity at its planned duration","Crash activities C and E by 1 day each at $1,000 per day, a total of $2,000, and leave every other activity at its planned duration","Crash activity B by 2 days at $3,000 per day and activity C by 2 days at $1,000 per day, a total of $8,000, with no other activity changed"],ans:[0],why:["Đúng: A-B-D-F = 4+6+5+2 = 17 ngày là critical path. Rút B 2 ngày (tổng $6.000) còn 15 ngày; hai path kia là 14 và 13 nên dự án rút đúng 2 ngày, với chi phí thấp nhất trong các phương án đạt mục tiêu.","Sai: C chỉ nằm trên path A-C-D-F (14 ngày) với float 3 ngày; rút C 2 ngày chỉ tốn $2.000 nhưng critical path A-B-D-F vẫn 17 ngày. Sẽ đúng nếu path của C là path dài nhất.","Sai: rút C và E mỗi cái 1 ngày làm A-C-D-F còn 13 và A-C-E-F còn 11, nhưng A-B-D-F vẫn 17 ngày. Sẽ đúng nếu cả C và E nằm trên critical path.","Sai: rút B 2 ngày đã đưa dự án xuống 15 ngày; rút thêm C 2 ngày (A-C-D-F còn 12) không rút ngắn thêm gì mà tốn thêm $2.000, tổng $8.000. Sẽ đúng nếu A-C-D-F cũng là critical path."],exp:'Task R8, enabler "Create a project schedule". Chỉ rút ngắn activity trên critical path mới rút ngắn dự án (crashing); activity rẻ nhất chưa chắc là activity đúng. Cần xem path khác có trở thành critical không (rút 3 ngày thì A-B-D-F và A-C-D-F cùng 14). Bẫy: chọn activity theo chi phí hoặc số phụ thuộc thay vì theo critical path.'},{id:"o400",n:400,t:0,origin:"original",eco:"R8",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","coordination","operations","shared-resources"],type:"mc",q:"A hybrid ERP upgrade has a predictive data-center cutover and agile configuration sprints. The cutover is planned for the last weekend of December. Operations has just announced a year-end freeze on infrastructure changes, and another project plans to use the same network engineers that weekend. Operations has offered the first weekend of January, when the network engineers are free, and the other project manager has agreed to keep the engineers for the December weekend. The schedule was published a week ago, and the change plan lets the project manager move a cutover by up to two weeks if go-live is unaffected, which is the case here. What should the project manager do?",opts:["Move the cutover to the first weekend of January, update the schedule and tell the stakeholders, the vendors and the team","Confer with operations and the other project manager to compare cutover windows, and engineer availability","Bring the sponsor in to decide which of the two projects keeps the network engineers and the weekend","Keep the December date, and have operations grant an exception as the schedule is already published"],ans:[0],why:["Đúng: vận hành đã đề xuất cuối tuần đầu tháng Một và PM dự án kia đồng ý giữ kỹ sư cho cuối tuần tháng Mười Hai. PM chuyển cutover, cập nhật lịch và báo các bên liên quan.","Sai: hai bên đã đạt thỏa thuận nên họp lại là lặp lại bước phối hợp đã xong. Sẽ đúng nếu vẫn chưa có cửa sổ chấp nhận được.","Sai: leo thang lên sponsor chỉ cần khi hai bên không đạt thỏa thuận; ở đây thỏa thuận đã có.","Sai: lịch đã công bố không tạo ra quyền ưu tiên so với freeze của vận hành; xin ngoại lệ khi đã có cửa sổ khác là bắt vận hành nhường."],exp:'Task R8, enabler "Coordinate with other projects and operations". Lịch dự án nằm trong bối cảnh tổ chức. Khi phối hợp đã cho ra thỏa thuận, PM thực hiện: dời cutover, cập nhật lịch và thông báo. Bẫy: họp lại điều đã thống nhất hoặc leo thang sponsor khi không cần.'},{id:"o401",n:401,t:0,origin:"original",eco:"R8",domain:"process",approach:"predictive",tags:["predictive","eco-2026","schedule-baseline","change-control"],type:"mc",q:"A predictive project's approved schedule baseline shows delivery in 30 weeks. A key supplier's delivery slipped by three weeks, and the forecast end date is now week 33. The sponsor, who dislikes variance reports, suggests re-baselining so that status shows the project on track. What should the project manager do?",opts:["Claim compensation from the supplier under the contract, and report the original end date until the claim is settled","Report the three-week variance, and have the sponsor approve crashing later activities to recover all three weeks","Keep the baseline, report the three-week variance, and work out recovery options first","Re-baseline the end date to week 33 as the sponsor suggests, and use the new baseline for status reporting"],ans:[2],why:["Sai: đòi bồi thường theo hợp đồng là quyền hợp lệ, nhưng báo ngày cũ cho đến khi giải quyết là cung cấp thông tin sai cho stakeholder. Sẽ đúng nếu báo cáo variance rõ ràng song song.","Sai: báo variance là đúng nhưng đề xuất rút ngắn (crash) để lấy lại cả ba tuần trước khi phân tích phương án phục hồi là nhảy tới giải pháp; crash tốn chi phí và có thể không khả thi.","Đúng: baseline là mốc để đo sai lệch, không đổi để làm đẹp báo cáo. Giữ baseline, báo cáo variance 3 tuần, phân tích phương án phục hồi, và chỉ đổi baseline qua change request được duyệt.","Sai: quyền của sponsor không biến việc re-baseline chỉ để xóa variance thành hợp lệ; baseline chỉ đổi khi có thay đổi được duyệt, và sai lệch cần được nhìn thấy."],exp:'Task R8, enabler "Baseline a project schedule". Baseline được duyệt là chuẩn so sánh; thay đổi qua change control khi có thay đổi phạm vi/ràng buộc hợp lệ, không để xóa variance. Quy tắc nhớ: báo cáo trung thực, phân tích phục hồi, rồi mới xét change request. Bẫy: "re-baseline cho đẹp".'},{id:"o402",n:402,t:0,origin:"original",eco:"R8",domain:"process",approach:"agile",tags:["agile","eco-2026","burn-up","scope-growth","schedule-variance"],type:"mc",q:"A release plan targets 20 sprints. After sprint 8, the burn-up chart shows 190 points completed, while the scope line has risen from 500 to 560 points because stakeholders keep adding items. Velocity is steady at about 24 points per sprint. The release date is in jeopardy. What should the project manager do?",opts:["Add two experienced developers to the team now, forecast velocity of about 31 points per sprint, and keep the release at sprint 20 for the stakeholders","Show stakeholders the burn-up trend with a forecast of about 24 sprints, and ask the product owner to reprioritize the added items or agree a new release date","Hold the new forecast back until sprint 10, then show the stakeholders the burn-up trend with two more sprints of velocity data","Tell stakeholders the release stays at sprint 20 and that further additions go to a later release, then freeze the scope line at 560 points"],ans:[1],why:["Sai: thêm người giữa chừng thường làm giảm tốc độ ngắn hạn (ramp-up, giao tiếp) và không giải quyết scope tăng. Sẽ đúng nếu đội có thể ramp-up nhanh và đã có dữ liệu cho thấy vậy.","Đúng: còn lại 560 − 190 = 370 điểm; 370/24 ≈ 15,4 → 16 sprint, tổng 8 + 16 = 24 sprint. Dữ liệu burn-up cho thấy scope tăng; PM minh bạch xu hướng để PO và stakeholder quyết định ưu tiên hoặc ngày.","Sai: chờ thêm hai sprint dữ liệu khi release đã bị đe dọa và xu hướng đã rõ chỉ làm stakeholder biết muộn. Sẽ đúng nếu velocity dao động mạnh và chưa có xu hướng.","Sai: dù chốt scope ở 560 điểm, còn lại 560 − 190 = 370 điểm; ở 24 điểm/sprint cần 16 sprint, tổng 24 sprint, nên không giữ được sprint 20. Sẽ đúng nếu velocity đủ cao hoặc scope bị cắt xuống."],exp:'Task R8, enabler "Analyze schedule variation". Với burn-up, so điểm hoàn thành với đường scope: scope tăng nên ngày release lùi dù velocity ổn định. PM giúp stakeholder nhìn xu hướng và chọn đánh đổi (scope, ngày, nguồn lực). Quy tắc nhớ: dữ liệu rõ ràng, quyết định thuộc về người sở hữu sản phẩm.'},{id:"o403",n:403,t:0,origin:"original",eco:"R8",domain:"process",approach:"predictive",tags:["predictive","eco-2026","spi","critical-path","schedule-forecast"],type:"mc",q:"A predictive building project reports a schedule performance index of 1.03 because landscaping and interior mock-ups were finished early. However, the foundation curing on the critical path is six days late and has no float to absorb the delay. The sponsor reads the index, concludes that the project is ahead of schedule, and will present that status to the board in three days. The foundation contractor says a recovery plan will take two weeks. What should the project manager do?",opts:["Calculate the cost performance index with the team, show the sponsor that budget is the better indicator of health, and let the sponsor present the status","Open a change request to extend the schedule baseline by six days for the foundation delay, and give the board the revised baseline","Ask the foundation contractor for a recovery plan, and explain the late activity to the sponsor when the plan arrives, before forecasting a new end date","Escalate the six-day critical-path delay to the sponsor before the board meets, bringing an end-date forecast from the critical path and its float"],ans:[3],why:["Sai: CPI đo chi phí chứ không đo tiến độ; không giải quyết việc SPI che đi activity critical đang trễ. Sẽ hữu ích khi hỏi về sức khỏe chi phí, không phải ngày hoàn thành.","Sai: change request kéo dài baseline 6 ngày sẽ xóa variance mà chưa có dự báo hay phân tích phục hồi, và sponsor vẫn hiểu sai SPI. Baseline chỉ đổi khi có thay đổi được duyệt.","Sai: kế hoạch phục hồi của nhà thầu cần, nhưng nó mất hai tuần còn board họp sau ba ngày; chờ nó thì sponsor đã trình trạng thái sai. Sẽ đúng nếu kỳ họp board còn xa.","Đúng: SPI cộng gộp mọi công việc theo giá trị nên việc sớm ở nhánh phụ che việc trễ ở critical path. Board họp sau ba ngày, nên PM escalate cho sponsor trước đó với dự báo ngày kết thúc theo critical path và float còn lại."],exp:'Task R8, enabler "Analyze schedule variation". SPI chỉ là chỉ số tổng hợp; khi đánh giá tiến độ phải xem critical path và float của từng activity. Một delay trên critical path không float trực tiếp dời ngày kết thúc. Sponsor sắp trình board, nên PM phải escalate trước kỳ họp với dự báo từ critical path thay vì chờ kế hoạch phục hồi. Bẫy: tin vào SPI trên 1,0 hoặc trì hoãn hành động.'},{id:"o404",n:404,t:0,origin:"original",eco:"R8",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","pert","three-point-estimate"],type:"mc",q:"A hybrid project uses three-point estimating for fixed-scope hardware tasks and story points for software. For the hardware calibration task, engineers give an optimistic estimate of 10 days, a most likely estimate of 14 days and a pessimistic estimate of 24 days. The PMO standard for these tasks uses the beta (PERT) weighting for expected duration, and any buffer is held in the project's contingency, not in task durations. Which duration should the project manager enter in the schedule?",opts:["16 days, the simple average (O + M + P) / 3 of the three estimates, entered as the expected duration of the task","14 days, the most likely estimate (M), entered as the expected duration with the extra 10 days to the pessimistic value held in contingency","15 days, the weighted average (O + 4M + P) / 6 of the three estimates, entered as the expected duration of the task","17 days, the weighted average plus one standard deviation (P − O) / 6, entered as the expected duration with a built-in buffer"],ans:[2],why:["Sai: 16 = (10 + 14 + 24)/3 là trung bình cộng triangular, không phải trọng số beta mà chuẩn PMO yêu cầu. Sẽ đúng nếu PMO quy định triangular.","Sai: 14 ngày là giá trị most likely, bỏ qua việc phân phối lệch về phía pessimistic (24 ngày) kéo kỳ vọng lên.","Đúng: (10 + 4×14 + 24)/6 = 90/6 = 15 ngày. Công thức PERT trọng số giá trị most likely gấp bốn lần, đúng theo chuẩn PMO.","Sai: 15 + (24 − 10)/6 ≈ 17 ngày; cộng độ lệch chuẩn là buffer, nhưng đề nói buffer nằm ở contingency của dự án chứ không trong thời lượng task. Sẽ đúng nếu PMO yêu cầu buffer trong task."],exp:'Task R8, enabler "Estimate project tasks (milestones, dependencies, story points)". Hybrid dùng ước tính ba điểm cho phần dự đoán: PERT = (O + 4M + P)/6; còn story points cho phần thích nghi. Bẫy: nhầm giữa PERT, triangular (O + M + P)/3 và trung điểm.'},{id:"o405",n:405,t:0,origin:"original",eco:"R8",domain:"process",approach:"agile",tags:["agile","eco-2026","dependencies","cross-team"],type:"mc",q:"Three agile teams build one mobile app. Team B needs an API from team A that is planned for sprint 6, but team B's feature is scheduled for sprint 5. Each team plans its own sprints, and no one has looked across the backlogs. The dependency surfaced during sprint 4. The three product owners meet weekly and can reorder their backlogs. What should the project manager do?",opts:["Escalate the sequencing conflict between teams A and B to the sponsor, and ask for a ruling on which team's plan takes precedence","Gather the teams and product owners to resequence the dependent items across the backlogs and track the dependency on a board","Ask team B to build a temporary API of its own, and keep its sprint 5 commitment to the product owner for this sprint","Add the dependency to the shared risk log under a named owner, and review it at the sprint 5 planning meeting"],ans:[1],why:["Sai: các product owner họp hàng tuần và tự sắp xếp lại backlog được, nên xin sponsor phán quyết là leo thang quá sớm cho việc điều phối thường ngày. Sẽ đúng nếu các product owner không thống nhất được.","Đúng: phụ thuộc giữa các đội cần được xử lý bằng lập kế hoạch liên đội: sắp xếp lại thứ tự item phụ thuộc và theo dõi dependency công khai để không lặp lại bất ngờ.","Sai: API tạm của team B là công việc làm lại, có thể lệch với API của team A, và giữ cam kết sprint 5 không giải quyết việc không ai nhìn qua các backlog. Sẽ đúng nếu sprint 6 của team A không thể dời.","Sai: đưa dependency vào risk log chung là tốt, nhưng xem xét ở sprint 5 planning là muộn vì tính năng của team B đã nằm trong sprint 5 và phụ thuộc chưa được giải quyết. Cần sắp xếp lại ngay trong sprint 4."],exp:'Task R8, enabler "Coordinate with other projects and operations" (nhiều đội agile). Dependency giữa đội được quản lý bằng release/cross-team planning, scrum of scrums, bảng dependency chung. Quy tắc nhớ: phối hợp trực tiếp trước, leo thang sau. Bẫy: để mỗi đội lập kế hoạch riêng.'},{id:"o406",n:406,t:0,origin:"original",eco:"R8",domain:"process",approach:"predictive",tags:["predictive","eco-2026","historical-data","analogous-estimate"],type:"mc",q:"A predictive project must install point-of-sale systems in retail stores. The PMO's records show 14 earlier installs averaging 90 days, ranging from 70 to 130; their duration did not track the number of stores and was driven by network setup. The new project covers two more regions and a newer payment terminal that none of the earlier projects used. The sponsor needs a duration estimate for the schedule this week, and a pilot install with the new terminal would take about six weeks. What should the project manager do?",opts:["Ask the installation leads to adjust the 90-day average for the new regions and terminal, and validate the result before the sponsor sees it","Use 130 days, the longest earlier duration, as the estimate for the schedule, and record the new terminal and regions as risks in the risk register","Run a pilot install with the new terminal in one store, and give the sponsor an estimate once the pilot reports its results to the PMO","Build a parametric estimate of days per store from the 14 earlier installs, and apply the rate to the stores in the two new regions of the project"],ans:[0],why:["Đúng: dữ liệu lịch sử là điểm xuất phát tốt nhưng dự án mới khác (thêm vùng, thiết bị mới). Điều chỉnh theo khác biệt cùng người lắp đặt rồi kiểm chứng trước khi đưa cho sponsor.","Sai: lấy giá trị dài nhất là đệm tùy tiện không dựa trên phân tích khác biệt của dự án này. Sẽ đúng nếu mọi dự án trước đều bị thu hẹp tương tự, nhưng ở đây cần điều chỉnh theo hai khác biệt.","Sai: pilot cho terminal mới hữu ích nhưng mất khoảng sáu tuần, trong khi sponsor cần ước tính trong tuần này. Sẽ đúng nếu không có dữ liệu lịch sử hoặc hạn chót còn xa, nhưng ở đây có 14 lần lắp.","Sai: ước tính tham số (ngày mỗi cửa hàng) cần mối quan hệ giữa số cửa hàng và thời lượng, mà dữ liệu cho thấy thời lượng không theo số cửa hàng. Nó còn bỏ qua terminal mới."],exp:'Task R8, enabler "Utilize benchmarks and historical data". Ước tính tương tự (analogous) dựa trên dữ liệu lịch sử, điều chỉnh theo khác biệt và xác nhận với những người thực hiện. Ước tính tham số chỉ hợp lý khi có quan hệ thống kê giữa biến và thời lượng; ở đây thời lượng không theo số cửa hàng. Bẫy: coi trung bình lịch sử là cam kết, hoặc bỏ nó đi vì dự án "khác".'},{id:"o407",n:407,t:0,origin:"original",eco:"R8",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","schedule-recovery","crashing","fast-tracking"],type:"mc",q:"A hybrid project is three weeks behind on its predictive installation phase, which feeds agile configuration work. The sponsor asks the project manager to recover the three weeks. The team has costed both options: overtime on the critical path recovers the three weeks for $60,000, while overlapping the design review with installation risks about two weeks of rework. The sponsor has told the project manager to pick the option that protects the end date, and any change to the cost baseline goes to the change control board. What should the project manager do?",opts:["Present the crashing and fast-tracking options to the sponsor with the team's cost and rework figures, and ask her to choose","Overlap the design review with installation to recover the three weeks, and absorb the rework risk in the agile configuration backlog","Raise a change request to the change control board for $60,000 of critical path overtime, and keep the design review before installation","Ask the agile configuration team to shorten its sprints with the product owner to absorb the three weeks, and keep the installation plan as it is"],ans:[2],why:["Sai: sponsor đã giao PM chọn phương án bảo vệ ngày kết thúc và đội đã tính xong chi phí, rủi ro của cả hai phương án ($60.000 và khoảng hai tuần làm lại), nên hỏi lại sponsor chọn là lặp lại quyết định đã giao. Sẽ đúng nếu sponsor chưa nêu ưu tiên.","Sai: fast tracking tạo rủi ro làm lại khoảng hai tuần, tức gần bằng thời gian muốn lấy lại, và đẩy rủi ro sang phần agile. Sẽ đúng nếu rủi ro làm lại nhỏ hơn.","Đúng: sponsor giao PM chọn phương án bảo vệ ngày kết thúc, và overtime trên critical path lấy lại đủ ba tuần với $60.000 mà không gây làm lại. Thay đổi baseline chi phí đi qua change control.","Sai: rút ngắn sprint của đội agile không bù được trễ ở giai đoạn lắp đặt dự đoán, và chỉ chuyển áp lực sang nhóm khác. Sẽ đúng nếu trễ nằm ở phần agile."],exp:'Task R8, enabler "Analyze schedule variation" (gồm đề xuất phục hồi). Nén tiến độ bằng crashing (thêm nguồn lực/chi phí) hoặc fast tracking (chồng chéo, tăng rủi ro). Khi đã có số liệu và ưu tiên của sponsor, PM chọn phương án phù hợp và trình qua change control. Bẫy: phân tích lại điều đã có hoặc fast track khi rủi ro làm lại lớn.'},{id:"o408",n:408,t:0,origin:"original",eco:"R8",domain:"process",approach:"predictive",tags:["predictive","eco-2026","ai","schedule-validation","baseline"],type:"mc",q:"A predictive project manager used an AI scheduling assistant trained on the company's past projects to draft the schedule for a data-center build. It produced a 14-month network with durations and dependencies. Two senior engineers say the commissioning sequence looks wrong, but they have not yet reviewed the rest of the draft or marked what is out of order. The sponsor wants a baseline by Friday, and the engineers can finish a review by Thursday. What should the project manager do?",opts:["Ask the engineers to reorder the commissioning steps by Wednesday, update the network, and take the result to the sponsor for baseline approval on Friday","Have both engineers review the full draft against dependencies and calendars by Thursday, correct the errors, and take the baseline to the sponsor on Friday","Ask the AI vendor and the engineers to validate the tool's output on two past projects before the draft is used for any schedule baseline","Baseline the AI draft on Friday as the sponsor requested, and log the engineers' commissioning concern in the risk register for later review"],ans:[1],why:["Sai: sửa riêng trình tự commissioning thì phần còn lại của bản nháp AI vẫn chưa ai rà soát, trong khi các kỹ sư có thể rà cả mạng trước thứ Năm. Sẽ đúng nếu chỉ có đúng một chỗ nghi ngờ và phần còn lại đã được kiểm.","Đúng: AI cho bản nháp, PM chịu trách nhiệm. Các kỹ sư mới nghi ngờ một chỗ và có thể rà soát xong thứ Năm, nên PM xác minh cả mạng với họ, sửa lỗi tìm được rồi trình baseline thứ Sáu.","Sai: kiểm chứng công cụ trên hai dự án cũ là cẩn thận nhưng không kịp thứ Sáu, trong khi bản nháp này có thể được rà soát trực tiếp trước thứ Năm. Sẽ đúng nếu không có hạn chót và công cụ mới được đưa vào.","Sai: baseline một lịch đã bị nghi sai trình tự rồi ghi vào risk register là đưa lỗi đã biết vào baseline. Sẽ đúng nếu không còn thời gian rà soát, nhưng ở đây còn đến thứ Năm."],exp:'Task R8, enabler "Create a project schedule" (trước "Baseline a project schedule"), với AI là bối cảnh. Đầu ra của AI chỉ là bản nháp: PM chịu trách nhiệm xác minh với chuyên gia trước khi baseline. Khi chuyên gia mới nghi ngờ một chỗ và còn kịp rà soát trước thứ Sáu, PM xác minh cả mạng lịch rồi mới baseline. Bẫy: để áp lực thời hạn quyết định hoặc baseline lịch đã biết sai.'},{id:"o409",n:409,t:0,origin:"original",eco:"R9",domain:"process",approach:"agile",tags:["agile","eco-2026","ai","dashboard","reconciliation"],type:"mc",q:"An AI tool connected to the team's work tracker produces a status dashboard for the sponsor saying the release is on track with 95% confidence. The sprint board, however, shows five blocked stories, and two team members say they have not updated their tickets for a week. The sponsor will read the dashboard in the morning. What should the project manager do?",opts:["Brief the sponsor on the five blocked stories from the sprint board with the scrum master, and leave the dashboard published as it is","Reconcile the dashboard with the sprint board, correct the data, and tell the sponsor how reliable the figure is before the morning","Have the scrum master ask the team to update their tickets tonight and rerun the dashboard, which will correct the confidence level","Ask the AI tool's vendor and the data owner to review how the confidence figure is calculated before the dashboard is used for further reports"],ans:[1],why:["Sai: báo năm story bị chặn là tốt, nhưng dashboard vẫn công bố mức tin cậy 95% dựa trên dữ liệu cũ, làm sponsor nhận hai thông điệp mâu thuẫn. Sẽ đúng nếu dashboard chỉ là tài liệu phụ.","Đúng: dashboard dựa trên dữ liệu cũ (ticket không cập nhật một tuần) nên kết luận không đáng tin. PM đối chiếu với bảng sprint, sửa dữ liệu rồi nói rõ mức tin cậy cho sponsor.","Sai: cập nhật ticket và chạy lại là cần, nhưng chưa đối chiếu với bảng sprint hay nói cho sponsor biết độ tin cậy, và sponsor sẽ đọc vào sáng mai. Số chạy lại cũng cần được kiểm chứng.","Sai: vấn đề là dữ liệu ticket không được cập nhật chứ không phải cách tính của công cụ; hỏi vendor là nhầm chủ thể và không kịp trước sáng mai."],exp:'Task R9, enabler "Develop project metrics, analysis, and reconciliation", với AI là bối cảnh. Đối chiếu (reconcile) số liệu tự động với nguồn thực tế trước khi truyền đạt; PM chịu trách nhiệm cuối cùng về tính chính xác của báo cáo. Bẫy: tin vào con số AI vì có độ tin cậy cao.'},{id:"o410",n:410,t:0,origin:"original",eco:"R9",domain:"process",approach:"predictive",tags:["predictive","eco-2026","artifact-tailoring","pmo"],type:"mc",q:"The PMO template for a predictive project lists 18 required artifacts. The project is a three-month internal server refresh with a $120,000 budget, one vendor and a low-risk profile. The PMO's tailoring guide allows a short-form set of eight artifacts for projects under $250,000 that the PMO classifies as low-risk; this project has not been classified yet. The project manager has limited time and thinks half of the template adds no value here. What should the project manager do?",opts:["Create the 18 artifacts in the PMO template as required, and have the sponsor mark the ones that add little value as not applicable at closure","Choose the eight artifacts the team finds most useful with the sponsor, and tell the PMO which ones at the next governance review","Ask the sponsor to waive ten artifacts of the PMO template in writing, and record the waiver in the project management plan","Ask the PMO to classify the project's risk, then apply the eight-artifact short-form set if it is low-risk and record the tailoring decision"],ans:[3],why:["Sai: làm đủ 18 artifact cho dự án nhỏ, rủi ro thấp là lãng phí thời gian; template là điểm xuất phát, không bắt buộc áp dụng toàn bộ. Sẽ đúng nếu PMO không có hướng dẫn tailoring.","Sai: tự chọn theo ý đội và báo PMO sau bỏ qua danh sách PMO đã quy định và có thể bỏ nhầm artifact mà governance đòi hỏi. Sẽ đúng nếu PMO giao quyền chọn cho đội.","Sai: sponsor không sở hữu template của PMO; miễn trừ bằng văn bản từ sponsor không thay cho việc PMO phân loại dự án. Sẽ đúng nếu hướng dẫn tailoring không tồn tại và sponsor có quyền miễn trừ.","Đúng: hướng dẫn tailoring chỉ áp dụng cho dự án được PMO xếp loại rủi ro thấp, mà dự án này chưa được phân loại. PM nhờ PMO phân loại trước, rồi dùng bộ tám artifact và ghi quyết định vào project management plan."],exp:'Task R9, enabler "Identify and tailor needed artifacts". Tailoring artifact dựa trên quy mô, rủi ro và yêu cầu của tổ chức; hướng dẫn của PMO cho bộ rút gọn với dự án được PMO xếp loại rủi ro thấp, nên PM xác nhận phân loại với PMO trước, rồi áp dụng bộ rút gọn và ghi quyết định. Quy tắc nhớ: đủ để kiểm soát, không thừa; dùng đúng hướng dẫn tailoring sẵn có.'},{id:"o411",n:411,t:0,origin:"original",eco:"R9",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","artifact-maintenance","risk-register"],type:"mc",q:"At a phase-gate review, auditors find that a hybrid project's risk register was last updated three months ago, although sprint reviews have raised several new risks and a few have already become issues. The sprint teams say the register belongs to the project manager. What should the project manager do?",opts:["Ask the sprint teams to track risks on their boards and review the boards each month, replacing the central register","Hold a risk identification workshop with all teams to rebuild the register from scratch, before the next gate","Update the register before the next gate and keep it as the project manager's own working document","Assign owners and a review cadence for the register and add update triggers to sprint reviews"],ans:[3],why:["Sai: bảng sprint tốt cho đội nhưng bỏ register trung tâm làm mất cái nhìn tổng thể cho governance và rủi ro liên đội. Sẽ đúng nếu dự án chỉ có một đội.","Sai: các rủi ro mới đã được nêu trong sprint review, nên vấn đề là bảo trì register chứ không phải thiếu nhận diện; dựng lại từ đầu không tạo ra người sở hữu hay nhịp cập nhật.","Sai: tự cập nhật trước mỗi gate lặp lại vấn đề: PM làm một mình, register vẫn lệch thực tế giữa các lần cập nhật.","Đúng: artifact được cập nhật khi có người sở hữu, nhịp rà soát và trigger gắn vào quy trình sẵn có (ví dụ sprint review), nên nó theo kịp thực tế."],exp:'Task R9, enabler "Help ensure artifacts are created, reviewed, updated, and documented". Artifact chỉ có giá trị khi được cập nhật: phân quyền sở hữu, nhịp review, trigger cập nhật gắn với nghi thức hiện có. Bẫy: coi tài liệu là việc riêng của PM.'},{id:"o412",n:412,t:0,origin:"original",eco:"R9",domain:"process",approach:"agile",tags:["agile","eco-2026","status-communication","sponsor"],type:"mc",q:"A sponsor travels often, never attends sprint reviews, and says the status emails are too long to read. Recent increments have shifted priorities twice, and the sponsor was surprised both times. In a call this week the sponsor said a five-line message each Friday, plus a phone call for any priority change, would work. The project manager needs to communicate project status. What should the project manager do?",opts:["Push the sponsor to attend sprint reviews in person, as they are the agile form of reporting for this project","Send the sponsor a five-line message each Friday on progress, risks and decisions needed, and phone about any priority change","Meet the sponsor to find out which status information, and channel work best before sending anything","Post a link to the team's live dashboard and expect the sponsor to check it whenever a decision is needed"],ans:[1],why:["Sai: sprint review là hình thức báo cáo agile, nhưng sponsor đi công tác thường xuyên và đã nói cách khác phù hợp. Sẽ đúng nếu sponsor có thể tham dự.","Đúng: sponsor đã nêu rõ cách nhận thông tin: năm dòng mỗi thứ Sáu và điện thoại khi ưu tiên đổi. PM làm đúng như vậy, bao gồm tiến độ, rủi ro chính và quyết định cần sponsor.","Sai: nhu cầu của sponsor đã được nói rõ trong cuộc gọi tuần này, nên họp để tìm hiểu lại là lặp lại bước đã xong. Sẽ đúng nếu chưa biết sponsor cần gì.","Sai: chỉ đăng liên kết là thụ động; sponsor đã bị bất ngờ hai lần vì không nhận thông tin đúng thời điểm và đã nói muốn tin nhắn ngắn."],exp:'Task R9, enabler "Communicate project status". Tailor nội dung, độ dài, kênh và nhịp theo người nhận, ưu tiên điều họ cần quyết định. Khi người nhận đã nêu nhu cầu, PM làm theo thay vì hỏi lại. Bẫy: gửi thêm thông tin hoặc phụ thuộc vào kênh sponsor không dùng.'},{id:"o413",n:413,t:0,origin:"original",eco:"R9",domain:"process",approach:"predictive",tags:["predictive","eco-2026","evm","etc"],type:"mc",q:"The budget at completion of a predictive project is $1,000,000. At the status date, earned value is $450,000 and actual cost is $500,000. The overrun comes from a material price increase that will continue to affect the remaining work. The sponsor asks for the estimate to complete. What should the project manager report?",opts:["$550,000, the budget at completion minus the earned value, treating the price rise as a one-time event","About $611,000, using the current cost performance index for the remaining work","About $1,111,000, the forecast of the total cost at completion at current cost performance","About $1,050,000, the forecast of total cost at completion if the overrun does not recur"],ans:[1],why:["Sai: $550.000 = BAC − EV là ETC khi sai lệch là một lần và không tái diễn. Ở đây giá vật liệu còn tăng nên công thức này thấp hơn thực tế.","Đúng: CPI = 450/500 = 0,9; EAC = 1.000.000/0,9 ≈ $1.111.000; ETC = EAC − AC ≈ $611.000. Giá vật liệu tiếp tục tăng nên dùng hiệu suất hiện tại.","Sai: $1.111.000 là EAC (tổng chi phí khi hoàn thành) theo CPI hiện tại, không phải ETC (chi phí còn lại); phải trừ chi phí đã tiêu $500.000.","Sai: $1.050.000 = AC + (BAC − EV) là EAC khi sai lệch không lặp lại, và cũng là tổng chứ không phải chi phí còn lại. Sai hai lần: sai công thức và sai đại lượng."],exp:'Task R9, enabler "Assess current progress". EAC = BAC/CPI khi sai lệch sẽ tiếp diễn; ETC = EAC − AC. Cẩn thận phân biệt tiền còn lại (BAC − AC), ETC (còn phải tiêu) và EAC (tổng). Bẫy: trả lời EAC khi hỏi ETC.'},{id:"o414",n:414,t:0,origin:"original",eco:"R9",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","artifact-access","accessibility"],type:"mc",q:"A hybrid project's dashboards and requirement documents sit in a tool that the offshore vendor team cannot open from their network and that the product owner, who uses a screen reader, finds hard to navigate. Decisions are being made on outdated copies sent by email. IT has confirmed that the vendor can reach the tool through an approved VPN and that the tool exports screen-reader-friendly documents. What should the project manager do?",opts:["Shift the artifacts to the vendor's preferred tool, and have the vendor team lead help the product owner adapt to it over time","Keep the tool as it is, and have the document owner email accessible exports to the vendor and the product owner after each change, with version numbers","Meet the vendor team and the product owner to find out what each can open, and then agree the access and the formats","Give the vendor team role-based access through the approved VPN and publish the tool's accessible exports as the single source for both groups"],ans:[3],why:["Sai: chuyển sang công cụ của nhà cung cấp vẫn để product owner không dùng được; bài toán là khả năng tiếp cận chứ không phải sở thích công cụ. Sẽ đúng nếu cả hai nhóm đều dùng tốt công cụ đó.","Sai: gửi bản xuất qua email sau mỗi thay đổi vẫn tạo nhiều bản sao rời rạc và bản cũ vẫn lưu hành; không có nguồn sự thật duy nhất. Sẽ đúng nếu chỉ cần gửi một lần.","Sai: IT đã xác nhận cách vendor truy cập (VPN) và định dạng xuất đọc được bằng screen reader, nên khảo sát lại là lặp lại bước tìm hiểu đã xong. Sẽ đúng nếu chưa rõ mỗi nhóm mở được gì.","Đúng: các rào cản đã rõ, nên PM cấu hình quyền theo vai trò qua VPN đã duyệt và đăng bản xuất dễ tiếp cận vào kho chung làm nguồn duy nhất."],exp:'Task R9, enabler "Help ensure accessibility of artifacts". Accessibility vừa là truy cập được (quyền, mạng, công cụ) vừa là đọc/dùng được (định dạng cho người dùng có nhu cầu đặc biệt), trong khi vẫn kiểm soát theo vai trò. Khi rào cản đã rõ, PM cấu hình ngay thay vì khảo sát lại. Bẫy: sửa bằng email hoặc mở quyền rộng.'},{id:"o415",n:415,t:0,origin:"original",eco:"R9",domain:"process",approach:"agile",tags:["agile","eco-2026","cumulative-flow","wip-limits","bottleneck"],type:"mc",q:'The cumulative flow diagram of a team shows the "In test" band widening for four sprints while "In development" and "Done" stay flat. Developers keep pulling new stories, and testers say they are overloaded. In the stand-up the team has already agreed that testing is the bottleneck and proposed a limit of four stories in test. The sprint goal is at risk. What should the project manager do?',opts:["Support the team's limit of four stories in test, and have developers help with testing until the queue is under the limit","Direct the developers to hold new stories until the test queue is empty, then review the board at the end of the sprint","Add a second tester to the sprint for its remaining days, and keep the team's current way of pulling new work","Review the diagram with the team to confirm where the bottleneck is before changing how work is pulled"],ans:[0],why:["Đúng: đội đã tự xác định điểm nghẽn ở kiểm thử và đề xuất giới hạn bốn story. PM hỗ trợ áp dụng WIP limit và để dev giúp kiểm thử đến khi hàng đợi giảm.","Sai: ra lệnh từ trên xuống bỏ qua việc đội tự quản và giải pháp WIP limit mà đội đã đề xuất. Sẽ đúng nếu đội không đồng ý với giải pháp.","Sai: thêm tester có thể giúp nhưng nếu dev tiếp tục kéo việc không giới hạn thì hàng đợi vẫn dài ra; chưa đụng đến hành vi gây nghẽn.","Sai: đội đã xác nhận điểm nghẽn trong stand-up, nên xem lại biểu đồ là lặp lại bước chẩn đoán đã xong. Sẽ đúng nếu chưa chắc nghẽn ở đâu."],exp:'Task R9, enabler "Assess current progress" (chỉ số agile). Cumulative flow diagram cho thấy hàng đợi và điểm nghẽn; khi đội đã đọc dữ liệu và đề xuất WIP limit, PM hỗ trợ áp dụng và chia sẻ việc kiểm thử. Quy tắc nhớ: dữ liệu dòng chảy dẫn tới thay đổi hành vi của đội.'},{id:"o416",n:416,t:0,origin:"original",eco:"R9",domain:"process",approach:"predictive",tags:["predictive","eco-2026","percent-complete","reconciliation","subcontractor"],type:"mc",q:"A subcontractor's monthly report says a predictive system integration package is 70% complete. The project manager's earned value figures, based on accepted milestones, put it at 52%. The subcontractor is paid by percent complete, and the discrepancy is worth about $60,000 this month. The contract does not say how percent complete is measured. What should the project manager do?",opts:["Pay on the project's 52% figure now, and have the contracts manager settle the $60,000 difference after the next milestone is accepted","Pay on the subcontractor's 70% figure, and adjust the next payment if the accepted milestones do not reach that level of progress","Agree with the subcontractor and the contracts manager how percent complete is measured, then verify the figure against accepted deliverables","Have the subcontractor resubmit the report using the project's milestone definition, and pay on the resubmitted figure"],ans:[2],why:["Sai: trả theo 52% trước là thận trọng, nhưng hợp đồng không định nghĩa cách đo percent complete nên con số 52% của dự án cũng chưa được hai bên công nhận. Sẽ đúng nếu hợp đồng đã chọn milestone làm cơ sở trả tiền.","Sai: trả theo 70% trước rồi điều chỉnh sau là trả $60.000 chưa kiểm chứng, khó thu hồi nếu số liệu sai.","Đúng: hai số đo khác nhau về định nghĩa và hợp đồng không quy định. PM cùng nhà thầu thống nhất cách đo, rồi kiểm chứng với deliverable đã nghiệm thu trước khi thanh toán hoặc báo cáo.","Sai: ép nộp lại theo định nghĩa của dự án khi hợp đồng không quy định cách đo là áp đặt một định nghĩa một chiều lên nhà thầu. Phải thống nhất định nghĩa và đối chiếu với deliverable trước."],exp:'Task R9, enabler "Measure, analyze, and update project metrics". Khi hai nguồn số liệu lệch nhau, đối chiếu định nghĩa và phương pháp đo, rồi kiểm chứng bằng deliverable. Quy tắc nhớ: xác minh trước, thanh toán và báo cáo sau. Bẫy: chọn một con số hoặc lấy trung bình.'},{id:"o417",n:417,t:0,origin:"original",eco:"R9",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","integrated-reporting","rag-status"],type:"mc",q:'The steering committee of a hybrid program receives a milestone report for the hardware stream and a sprint burn-up for the software stream. Members say they cannot tell whether the program is healthy, and each stream uses a different rule for "red" status. The two stream leads and the committee chair agreed last week on common red, amber and green rules. What should the project manager do?',opts:["Require the software stream to report in milestone format, and use the same method in both streams","Hold a workshop with both streams and the committee to agree common RAG criteria before building any view","Publish one integrated status view that applies the agreed RAG rules to both streams' own measures","Keep both reports as they are and add a short narrative summary written by the project manager"],ans:[2],why:["Sai: ép luồng phần mềm sang báo cáo milestone bỏ mất giá trị của burn-up và tính thích nghi của agile. Sẽ đúng nếu cả hai luồng đều predictive.","Sai: tiêu chí RAG chung đã được hai trưởng luồng và chủ tịch ủy ban thống nhất tuần trước, nên workshop lặp lại bước đã xong. Sẽ đúng nếu chưa có thỏa thuận.","Đúng: tiêu chí đã thống nhất, nên PM dựng một bức tranh chung áp dụng cùng quy tắc RAG cho cả hai luồng, vẫn dùng thước đo riêng của từng luồng.",'Sai: thêm tóm tắt vẫn giữ hai quy tắc "đỏ" khác nhau nên người đọc phải tin diễn giải của PM; chưa sửa gốc vấn đề.'],exp:'Task R9, enabler "Communicate project status" (hybrid). Tích hợp thông tin từ các phương pháp khác nhau bằng tiêu chí chung được thống nhất với người nhận, nhưng vẫn giữ phương pháp đo phù hợp với từng luồng. Khi tiêu chí đã thống nhất, PM áp dụng ngay. Bẫy: ép một định dạng hoặc chỉ thêm tóm tắt.'},{id:"o418",n:418,t:0,origin:"original",eco:"R9",domain:"process",approach:"predictive",tags:["predictive","eco-2026","artifact-effectiveness","communications"],type:"mc",q:"Late in a predictive project, the project manager notices that the weekly status report, the action log and a detailed issue register take four hours a week to maintain. A quick poll shows that stakeholders rely on the one-page summary and the issue register, that nobody uses the action log, and that the action log is often out of date. What should the project manager do?",opts:["Survey the stakeholders on which artifacts they use before changing anything in the communications plan","Retire the action log, move its open items into the issue register, and keep the one-page summary","Retire the detailed issue register and the action log, and rely on the one-page summary alone","Assign a team member to keep the action log current each week, and leave all three artifacts in place"],ans:[1],why:["Sai: cuộc khảo sát nhanh đã cho biết stakeholder dùng artifact nào, nên khảo sát lại là lặp lại bước đã xong. Sẽ đúng nếu kết quả khảo sát còn mơ hồ.","Đúng: stakeholder không dùng action log, nên bỏ nó và chuyển các mục còn mở sang issue register mà họ dựa vào, giữ bản tóm tắt một trang để giảm công sức duy trì.","Sai: stakeholder dựa vào issue register, nên bỏ cả register làm mất công cụ quản lý issue mà họ cần. Chỉ đúng nếu register cũng không ai dùng.","Sai: duy trì action log mỗi tuần tăng chi phí cho thứ không ai dùng, trong khi gốc vấn đề là artifact không có giá trị với người đọc."],exp:'Task R9, enabler "Continually assess the effectiveness of artifact management". Định kỳ đánh giá artifact: ai dùng, có giá trị không, chi phí duy trì bao nhiêu, rồi tinh gọn. Khi dữ liệu đã cho thấy artifact nào không dùng, PM bỏ hoặc gộp ngay và giữ phần stakeholder dựa vào.'},{id:"o419",n:419,t:0,origin:"original",eco:"R9",domain:"process",approach:"agile",tags:["agile","eco-2026","ai","confidential-information","artifact-review"],type:"mc",q:"A team uses an AI note-taker to summarize stand-ups and retrospectives, and posts the summaries in the shared project space where the client can read them. One summary blames a supplier's delay on a named engineer and includes an unreleased pricing figure. The engineer says the statement is wrong. What should the project manager do?",opts:["Edit the summary with the scrum master to remove the engineer's name and the pricing figure, and keep the AI tool's current settings as they are","Withdraw the summary from the shared space, correct it with the engineer, and require a human reviewer for AI notes that touch sensitive content","Ask the engineer to post a clarification in the shared space, and leave the original summary in place with a note added by the project manager","Ask the AI vendor to add a filter for names and prices, and re-post the corrected summary with the vendor after the filter is installed"],ans:[1],why:["Sai: xóa tên và giá chỉ sửa một lần; không thêm bước người duyệt hay quy tắc nên lỗi tương tự lặp lại. Sẽ đủ nếu đây chỉ là lỗi hiếm không do quy trình.","Đúng: artifact phải được tạo, kiểm tra và ghi nhận đúng. Gỡ bản tóm tắt sai, sửa lại và đặt quy tắc người duyệt AI cùng cách xử lý thông tin nhạy cảm trước khi đăng.","Sai: để bản sai tồn tại và nhờ kỹ sư đính chính đẩy gánh nặng cho người bị nêu tên; thông tin nhạy cảm vẫn còn hiển thị cho khách hàng.","Sai: bộ lọc của vendor có thể hỗ trợ sau này, nhưng bản tóm tắt sai và giá chưa công bố vẫn hiển thị cho khách hàng trong lúc chờ. PM phải gỡ ngay và đặt quy tắc duyệt của người."],exp:'Task R9, enabler "Help ensure artifacts are created, reviewed, updated, and documented", với AI là bối cảnh. Nội dung do AI tạo vẫn là artifact của dự án: cần người duyệt chịu trách nhiệm, kiểm soát thông tin nhạy cảm và quy tắc rõ trước khi chia sẻ ra ngoài đội. Bẫy: sửa một lần mà không sửa quy trình.'},{id:"o420",n:420,t:0,origin:"original",eco:"R10",domain:"process",approach:"predictive",tags:["predictive","eco-2026","formal-acceptance","sign-off"],type:"mc",q:'A customer representative tells the project manager by phone that the delivered pumping station "looks fine". The contract requires written acceptance against defined acceptance criteria, and the final payment depends on it. Both parties walked the site against the acceptance criteria yesterday; the two minor punch-list items were fixed this morning, and the customer representative inspected both fixes and found nothing further. The team wants to demobilize. What should the project manager do?',opts:["Obtain the customer's signature on the written acceptance form with the closed punch-list attached, before the team demobilizes","Record the customer's phone call as the acceptance in the project file, and begin the closing activities","Invoice the final payment on the phone confirmation, and attach the signed acceptance form when it arrives","Walk the site with the customer's technical lead to re-check each acceptance criterion, then obtain the written acceptance"],ans:[0],why:["Đúng: hợp đồng đòi chấp nhận bằng văn bản; hai punch-list đã sửa và đại diện khách hàng đã kiểm lại, các bên đã đi kiểm tra theo tiêu chí. PM gửi mẫu chấp nhận kèm punch-list đã đóng để khách ký trước khi giải phóng đội.","Sai: lời nói qua điện thoại không phải chấp nhận chính thức theo hợp đồng và không có giá trị chứng cứ. Sẽ đúng nếu hợp đồng cho phép chấp nhận bằng lời.","Sai: xuất hóa đơn trước khi có chữ ký vi phạm điều kiện thanh toán và gây tranh chấp. Sẽ đúng nếu hợp đồng cho phép thanh toán theo xác nhận miệng.","Sai: hai bên đã đi kiểm tra theo tiêu chí hôm qua và đại diện khách hàng đã xem hai mục vừa sửa mà không có ý kiến thêm, nên đi kiểm lại là lặp lại. Sẽ đúng nếu có thay đổi sau lần kiểm tra."],exp:'Task R10, enabler "Obtain project stakeholder approval of project completion". Chấp nhận chính thức, bằng văn bản, theo tiêu chí đã thống nhất, từ người có thẩm quyền. Khi việc kiểm tra và punch-list đã xong, PM xin chữ ký ngay rồi mới giải phóng đội. Xác nhận miệng không đủ.'},{id:"o421",n:421,t:0,origin:"original",eco:"R10",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","transition","operational-readiness"],type:"mc",q:"A hybrid project delivers a new warehouse management system. The software passed its final sprint review, and the sponsor wants closure next week. The operations team has not seen the system, has no runbooks, and the night-shift staff were not trained. Operations has agreed a transition plan: runbooks by Wednesday, night-shift training on Thursday, and four weeks of support after go-live. What should the project manager do?",opts:["Carry out the agreed transition plan of runbooks, night-shift training and four weeks of support, and close once operations signs off","Hand the runbooks to the operations manager and keep the delivery team available for questions throughout the first month","Close the project next week as the sponsor requested, and have the operations manager run the transition plan afterward","Convene operations and the night-shift leads to define what transition support they need, before starting any transition work"],ans:[0],why:["Đúng: kế hoạch chuyển giao đã được vận hành đồng ý, nên PM thực hiện nó (runbook, đào tạo ca đêm, giai đoạn hỗ trợ) và chỉ đóng khi vận hành xác nhận sẵn sàng.","Sai: giao tài liệu rồi để câu hỏi tự đến là chuyển giao thụ động; không đảm bảo ca đêm đủ năng lực dù kế hoạch chuyển giao đã được thỏa thuận.","Sai: đóng dự án trước rồi để operations tự chạy kế hoạch bỏ đội phát triển đi trước khi vận hành sẵn sàng. Sẽ đúng nếu operations đã xác nhận sẵn sàng.","Sai: nhu cầu hỗ trợ đã được thỏa thuận trong kế hoạch chuyển giao, nên họp lại là lặp lại bước đã xong. Sẽ đúng nếu operations chưa tham gia."],exp:'Task R10, enabler "Validate readiness for transition (e.g., to operations team or next phase)". Chuyển giao gồm nhận thức, đào tạo, tài liệu vận hành và hỗ trợ, và bên nhận xác nhận sẵn sàng. Khi kế hoạch đã thỏa thuận, PM thực hiện và đóng sau khi bên nhận xác nhận. Bẫy: coi "đã qua sprint review" là sẵn sàng vận hành.'},{id:"o422",n:422,t:0,origin:"original",eco:"R10",domain:"process",approach:"agile",tags:["agile","eco-2026","lessons-learned","retrospective"],type:"mc",q:"After the final release of a customer portal, the team learns it will be reassigned next week. The sponsor says a closing report is optional because the product continues under a different team. Some agile practices that worked well have never been recorded, and the organization requires lessons learned from the whole team to be kept in its lessons repository. What should the project manager do?",opts:["Hand the product history and sprint notes to the next team, and ask it to run a retrospective and record the lessons once it starts work","Hold a final retrospective with the whole team before reassignment, and record the lessons in the organization's repository","Ask each team member to send personal notes on the practices that worked, and have the scrum master compile them in the shared team folder","Interview the team members one by one, write a lessons summary from the interviews, and send it to the sponsor"],ans:[1],why:["Sai: đội kế tiếp không có ngữ cảnh về những thực hành đã làm và đội cũ đã tách ra, nên bài học sẽ thiếu. Sẽ đúng nếu cùng đội tiếp tục.","Đúng: tổ chức yêu cầu bài học của cả đội được lưu trong lessons repository. Retrospective cuối với cả đội ghi nhận thực hành tốt thành lessons learned trước khi đội giải tán.","Sai: ghi chú cá nhân gom vào thư mục đội không được thảo luận chung và không vào repository của tổ chức. Sẽ đúng nếu tổ chức chỉ cần ghi chú nội bộ của đội.","Sai: phỏng vấn riêng từng người tạo một bản tóm tắt qua góc nhìn của PM, không có thảo luận chung và gửi sponsor chứ không vào repository mà tổ chức yêu cầu. Sẽ đúng nếu tổ chức chỉ cần báo cáo cho sponsor."],exp:'Task R10, enabler "Conclude activities to close the project or phase (e.g., final lessons learned, retrospectives, ...)". Closure agile vẫn cần retrospective cuối và lessons learned được lưu vào OPAs. Bẫy: coi sản phẩm tiếp tục là lý do bỏ hoạt động đóng, hoặc ghi chú rời rạc.'},{id:"o423",n:423,t:0,origin:"original",eco:"R10",domain:"process",approach:"predictive",tags:["predictive","eco-2026","procurement-closure","contract-claims"],type:"mc",q:"A predictive project's main contractor has completed all work and the customer has accepted it. The contractor still claims $85,000 for extra work that the project manager says was out of scope, and the final invoice is unpaid. The contract requires disputed claims to go through its mediation step. The sponsor asks to close the project this month. What should the project manager do?",opts:["Take the $85,000 claim through the contract's mediation step, settle the final invoice according to the outcome, and close the contract","Ask the sponsor to approve paying the $85,000 claim from contingency, as the customer has accepted the work, and close the contract","Ask the legal department to review the claim and the contract before the project manager decides on mediation, and keep the project open meanwhile","Have the customer confirm in writing that the extra work was out of scope, then reject the claim with the contracts manager and pay the final invoice"],ans:[0],why:["Đúng: đóng procurement cần giải quyết claim theo cơ chế tranh chấp của hợp đồng, thanh toán hóa đơn cuối theo kết quả giải quyết (không mặc nhiên trả claim) và đóng hợp đồng chính thức, trước khi đóng dự án.","Sai: trả $85.000 cho công việc PM cho là ngoài phạm vi, chỉ vì khách đã nghiệm thu, là chi trả không có cơ sở hợp đồng dù sponsor phê duyệt. Sẽ đúng nếu có change order được duyệt cho công việc đó.","Sai: hợp đồng đã quy định claim tranh chấp đi qua hòa giải, nên không còn quyết định nào để luật sư soát trước; giữ dự án mở chờ chỉ kéo dài thêm. Sẽ đúng nếu hợp đồng không quy định bước nào.","Sai: xác nhận bằng văn bản của khách hàng hữu ích làm bằng chứng, nhưng hợp đồng yêu cầu claim tranh chấp đi qua bước hòa giải; đơn phương bác bỏ claim bỏ qua bước đó."],exp:'Task R10, enabler "Conclude activities to close the project or phase (procurement, financials, resources)". Đóng hợp đồng gồm xác minh hoàn tất, giải quyết claim theo điều khoản hợp đồng, thanh toán cuối, lưu hồ sơ. Quy tắc nhớ: không đóng dự án khi hợp đồng còn mở. Bẫy: trả cho nhanh hoặc dùng thanh toán để gây áp lực.'},{id:"o424",n:424,t:0,origin:"original",eco:"R10",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","early-termination","closure"],type:"mc",q:'Midway through a hybrid product development, the sponsor cancels the project because the company dropped the market. Two sprints are in progress, a hardware supplier holds a purchase order that carries a cancellation fee unless it is settled under its terms, and team members expect to be reassigned. The sponsor tells the project manager to stop and "just move on". What should the project manager do?',opts:["Escalate the supplier's purchase order and the open sprints to the sponsor's office, and release the team after the wind-down","Cancel the supplier's purchase order and release the team at once, then prepare the formal closure report when the steering committee meets","Finish the two sprints in progress with the product owner to give the abandoned work a finished state, then close the project with a closure report","Close the project formally despite the cancellation: record its status, settle the supplier's order, release the team and capture lessons"],ans:[3],why:["Sai: chuyển đơn hàng của nhà cung cấp và hai sprint dở dang cho văn phòng sponsor rồi giải phóng đội thì không ai ghi nhận trạng thái, hợp đồng và bài học. Sẽ đúng nếu sponsor giao chính thức việc đóng dự án cho văn phòng, nhưng ở đây PM vẫn chịu trách nhiệm đóng.","Sai: hủy PO ngay khi đơn có phí hủy nếu không xử lý theo điều khoản sẽ phát sinh chi phí, và giải phóng đội trước khi ghi nhận trạng thái làm mất thông tin cho báo cáo đóng. Sẽ đúng nếu hợp đồng cho phép hủy không phí.","Sai: hoàn thành hai sprint tiêu tốn thêm ngân sách cho một sản phẩm đã bị hủy; sponsor đã quyết định dừng.","Đúng: dự án hủy giữa chừng vẫn phải đóng: ghi lại trạng thái, giải quyết hợp đồng và PO, giải phóng nhân sự và thu thập bài học."],exp:'Task R10, enabler "Conclude activities to close the project or phase". Cả khi dự án bị chấm dứt sớm vẫn thực hiện đóng: trạng thái, hợp đồng, tài chính, nguồn lực và lessons learned. Quy tắc nhớ: mọi dự án đều đóng chính thức, kể cả bị hủy.'},{id:"o425",n:425,t:0,origin:"original",eco:"R10",domain:"process",approach:"predictive",tags:["predictive","eco-2026","phase-gate","exit-criteria"],type:"mc",q:"A predictive project is at the gate between construction and commissioning. The exit criteria agreed in the project plan require zero open severity-1 defects, and the plan names a gate review board as the owner of gate decisions. One severity-1 defect remains, with a fix planned in three weeks. The construction team has finished everything else, and the sponsor wants to start commissioning now. What should the project manager do?",opts:["Take the unmet criterion and the fix options to the gate review board, and ask it for a documented decision before commissioning starts","Escalate to the sponsor for a written waiver of the severity-1 criterion, and record the waiver in the project plan before commissioning","Start commissioning with the commissioning lead on the systems the defect does not affect, and take the defect to the board when the fix arrives","Re-run the severity assessment of the defect with the test lead to confirm that it is really severity 1, and decide on the gate afterward"],ans:[0],why:["Đúng: tiêu chí thoát chưa đạt thì PM không tự quyết. Trình người có thẩm quyền ở gate với các phương án (sửa trước, hoặc chấp nhận có điều kiện) và có quyết định bằng văn bản.","Sai: kế hoạch đặt quyền quyết định gate ở gate review board, không phải sponsor riêng lẻ, nên sponsor tự miễn tiêu chí là vượt quyền. Sẽ đúng nếu kế hoạch ghi sponsor là người ra quyết định gate.","Sai: chia nhỏ commissioning là một lựa chọn có thể được xét, nhưng phải do gate review board quyết định, trước khi bắt đầu chứ không sau khi lỗi được sửa.","Sai: đề đã nói defect còn mở là severity-1, nên đánh giá lại mức độ là lặp lại bước đã xong. Sẽ đúng nếu mức độ bị tranh cãi."],exp:'Task R10, enabler "Determine criteria to successfully close the project or phase". Tiêu chí thoát phase được thống nhất trước; khi chưa đạt, PM minh bạch về khoảng cách, đưa phương án và để người có thẩm quyền ra quyết định có ghi chép. Bẫy: sửa tiêu chí hoặc tự hoãn.'},{id:"o426",n:426,t:0,origin:"original",eco:"R10",domain:"process",approach:"agile",tags:["agile","eco-2026","handover","sustaining-team","knowledge-transfer"],type:"mc",q:"A scrum team has built an internal analytics product for 14 months and is being disbanded. A small sustaining team will own it from next month. The sustaining team has attended only demos and has never changed the code. The definition of done is met for every story. What should the project manager do?",opts:["Record the handover in the closing report and rely on the definition of done as the proof that the sustaining team is ready to take over","Extend the delivery team's assignment by one month, and release it when the sustaining team's manager reports confidence in the handover","Plan pairing and shadowing with the sustaining team on real stories, and agree handover criteria that they confirm before the delivery team exits","Run a two-day handover workshop where the delivery team walks through the code, and have the sustaining team sign a checklist before the team disbands"],ans:[2],why:["Sai: definition of done chứng minh từng story hoàn thành, nhưng đề nêu đội duy trì chỉ mới dự demo và chưa từng sửa code, nên ghi vào báo cáo không chứng minh họ vận hành được. Sẽ đúng nếu họ đã từng làm việc trên mã nguồn.","Sai: kéo dài một tháng giữ chi phí nhưng tiêu chí sẵn sàng dựa vào cảm nhận của quản lý chứ không phải việc đội duy trì thực sự làm được. Cần tiêu chí do họ xác nhận.","Đúng: đội duy trì chưa từng sửa code nên cần cùng làm (pairing, shadowing) và tiêu chí bàn giao do chính họ xác nhận trước khi đội phát triển rời đi.","Sai: workshop hai ngày kèm checklist ký giúp nắm tổng quan, nhưng đội duy trì chưa từng sửa code; chỉ nghe và ký không cho thấy họ tự thay đổi được code. Sẽ đúng nếu họ đã từng làm việc trên mã nguồn."],exp:'Task R10, enabler "Validate readiness for transition". Với đội chuyển giao, bằng chứng sẵn sàng là bên nhận làm được việc, không chỉ nhận tài liệu: pairing, shadowing và tiêu chí do bên nhận xác nhận. Bẫy: nhầm DoD (sản phẩm xong) với sẵn sàng bàn giao.'},{id:"o427",n:427,t:0,origin:"original",eco:"R10",domain:"process",approach:"predictive",tags:["predictive","eco-2026","financial-closure","cost-accounts"],type:"mc",q:"After its deliverables were accepted, a predictive project still shows $42,000 unspent in the finance report. Two purchase orders remain open, one for software licenses that were never needed, and some time charges are still posting to the project's cost code. Company policy requires unspent funds to be returned at closure. The sponsor wants the project closed in a week. What should the project manager do?",opts:["Propose to the sponsor that the $42,000 funds post-implementation improvements to the delivered system, and close the project afterward","Keep the cost code open for three months with finance to catch late charges, and hold the closing report until they are included in the final cost","Close the project as the sponsor requested, and ask finance to clear the open purchase orders and the leftover budget after the closing report","Cancel the unneeded purchase orders with procurement, block the cost code, reconcile final costs with finance and return the $42,000 per policy"],ans:[3],why:["Sai: sponsor có thể có nhu cầu cải tiến, nhưng chính sách yêu cầu hoàn vốn chưa dùng khi đóng dự án; dùng tiếp cần một khoản ngân sách mới. Sẽ đúng nếu chính sách cho phép giữ lại.","Sai: giữ cost code ba tháng là kéo dài đóng dự án không cần thiết khi PO mở có thể xử lý ngay; chi phí muộn có thể xử lý qua quy trình riêng.","Sai: đóng dự án và để finance dọn sau để lại PO mở và cost code còn nhận chi phí; số liệu cuối dự án không chính xác.","Đúng: đóng tài chính gồm hủy PO không cần, khóa mã chi phí, đối chiếu chi phí cuối và hoàn lại vốn chưa dùng theo chính sách; làm được trong một tuần."],exp:'Task R10, enabler "Conclude activities to close the project or phase (financials)". Đóng tài chính: xử lý PO mở, ngừng ghi chi phí, đối chiếu và báo cáo chi phí cuối, trả vốn chưa dùng theo chính sách. Quy tắc nhớ: dự án chưa xong về tài chính khi sổ còn nhận chi phí.'},{id:"o428",n:428,t:0,origin:"original",eco:"R10",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","ai","lessons-learned","verification"],type:"mc",q:"At the end of a hybrid project, the project manager asked an AI assistant to draft the final report and lessons learned from the tickets, chat history and meeting notes. The draft credits the project's success to a process change that the team says did not happen, and cites a lesson from a different project. The project manager has already checked every statement in the draft against the records and with the team, and found only these two errors. What should the project manager do?",opts:["Prompt the AI assistant to revise the draft using the team's corrections and then submit the revised version","Publish the draft to the lessons learned repository, and label it clearly as AI-generated","Check the draft statement by statement against the records and with the team before correcting anything","Correct the two errors, and have a named person sign off the report before it goes into the lessons learned repository"],ans:[3],why:["Sai: bảo AI sửa theo ý đội vẫn là tin vào đầu ra chưa được người đối chiếu với hồ sơ; có thể thêm lỗi mới.","Sai: gắn nhãn AI không sửa nội dung sai; bài học sai đưa vào kho tri thức sẽ dẫn dắt dự án sau.","Sai: việc đối chiếu từng câu với hồ sơ và đội đã làm xong và chỉ ra hai lỗi. Làm lại sẽ đúng nếu chưa kiểm tra toàn bộ bản nháp.","Đúng: hai lỗi đã được xác định sau khi kiểm tra toàn bộ, nên PM sửa chúng và nhờ một người cụ thể ký duyệt trước khi đưa vào kho bài học của tổ chức."],exp:'Task R10, enabler "Conclude activities to close the project or phase (final lessons learned)", với AI là bối cảnh. AI soạn nháp, người kiểm chứng và chịu trách nhiệm. Khi việc đối chiếu đã xong, PM sửa lỗi và có người ký duyệt trước khi công bố vào tài sản tổ chức.'},{id:"o429",n:429,t:0,origin:"original",eco:"R10",domain:"process",approach:"agile",tags:["agile","eco-2026","closure-criteria","value-delivered"],type:"mc",q:"An agile project's backlog never empties because stakeholders keep adding ideas. The product vision and success measures were met two releases ago, but the team continues to build low-value features and the budget is nearly used. The product owner wants to keep going, and the sponsor has confirmed that the vision is achieved, that further spend is not justified, and that the project should close this month. What should the project manager do?",opts:["Continue until the backlog is empty, as agile projects end when the backlog items are done and accepted","Ask the product owner to compare the delivered releases with the vision and success measures before deciding whether to close","Close the project, hand the remaining backlog to the product owner as the ongoing product backlog, and record the final results","Ask the product owner to prioritize the backlog, and fund a final release of the highest-value items before closing the project"],ans:[2],why:["Sai: backlog agile là danh sách mở, hầu như không bao giờ cạn; chờ hết backlog là tiếp tục chi tiền cho tính năng giá trị thấp. Sẽ đúng nếu mục tiêu sản phẩm chưa đạt.","Sai: vision và thước đo đã đạt từ hai release trước và sponsor đã xác nhận, nên bước đối chiếu đã xong. Sẽ đúng nếu chưa rõ mục tiêu đã đạt chưa.","Đúng: mục tiêu đã đạt và sponsor xác nhận không nên chi thêm, nên PM đóng dự án, chuyển backlog còn lại cho product owner làm backlog sản phẩm và ghi kết quả cuối.","Sai: một release cuối cho các mục giá trị cao nghe hợp lý, nhưng giá trị mục tiêu đã đạt và sponsor xác nhận chi thêm không có cơ sở; ngân sách gần hết."],exp:'Task R10, enabler "Determine criteria to successfully close the project or phase" (agile). Đóng theo giá trị: vision và success measures đạt thì dừng đầu tư thêm; backlog còn lại chuyển cho sản phẩm vận hành. Khi sponsor đã xác nhận, PM đóng và bàn giao. Bẫy: coi backlog rỗng là điều kiện kết thúc.'},{id:"o430",n:430,t:0,origin:"original",eco:"R10",domain:"process",approach:"predictive",tags:["predictive","eco-2026","acceptance","change-control","stakeholder-approval"],type:"mc",q:"All baseline scope of a predictive project has been delivered, and the sponsor has signed the completion certificate. At the final review, the end-user department objects to a report layout and says it will not accept the system. The layout matches the approved requirements, and the acceptance plan names the sponsor as approver. Closure is planned for Friday. What should the project manager do?",opts:["Escalate the department's objection to the steering committee, and defer closure until the committee rules on the layout and on the department's refusal","Change the layout before closing the project, and have the end-user department confirm the change before Friday's closure","Walk the department through the layout against the approved requirements, then route any new layout wish through change control and close on Friday","Hold closure until the end-user department's manager also signs the completion certificate, and move the closure to the following Friday"],ans:[2],why:["Sai: steering committee là diễn đàn hợp lệ cho tranh chấp lớn, nhưng kế hoạch nghiệm thu đã đặt sponsor là người phê duyệt và bố cục khớp yêu cầu đã duyệt. Sẽ đúng nếu yêu cầu bị tranh cãi.","Sai: sửa trước khi đóng là thay đổi ngoài baseline mà chưa qua change control; có thể phát sinh chi phí và tiền lệ.","Đúng: bố cục khớp yêu cầu đã duyệt và sponsor là người phê duyệt theo kế hoạch nghiệm thu. PM giải thích với bộ phận từng điểm so với yêu cầu, đưa mong muốn mới qua change control và đóng theo lịch.","Sai: kế hoạch nghiệm thu đã xác định người phê duyệt; đòi mọi stakeholder đều ký là đặt điều kiện ngoài thỏa thuận."],exp:'Task R10, enabler "Obtain project stakeholder approval of project completion". Nghiệm thu theo kế hoạch: tiêu chí đã duyệt và người có thẩm quyền phê duyệt. Yêu cầu mới sau baseline đi qua change control. Quy tắc nhớ: tôn trọng stakeholder bằng cách giải thích và có kênh chính thức, không bằng thay đổi ngầm.'}],c=[{id:"o219",n:219,t:0,origin:"original",eco:"B1",domain:"business",approach:"predictive",tags:["predictive","eco-2026","governance","escalation"],type:"mc",q:"A project manager is starting a 14-month data center build for a regional bank. The charter is approved and the steering committee will meet monthly, but the draft governance plan says only that “significant variances will be escalated.” The bank’s financial policy requires executive approval for any cost overrun above 5 percent of the approved budget and says nothing about schedule. The steering committee must approve the governance plan before the build starts. What should the project manager do to complete the plan?",opts:["Apply the bank’s 5 percent cost rule to schedule slips as well, and ask the committee to approve the plan with that rule","Set measurable cost and schedule thresholds, using 5 percent for cost, and put them to the steering committee for approval","Name the sponsor as the person who judges which variances reach the steering committee, and record that rule in the plan","Take over the thresholds used on the bank’s last data center project from the PMO library, and enter them in the plan for committee approval"],ans:[1],why:["Sai: đúng nếu chính sách ngân hàng cũng nêu ngưỡng tiến độ, nhưng chính sách chỉ nói về chi phí 5%; áp ngưỡng chi phí cho tiến độ là suy diễn nên plan vẫn thiếu ngưỡng schedule do bên có thẩm quyền đặt.","Đúng: chính sách chỉ có ngưỡng chi phí 5% còn tiến độ chưa có ngưỡng, nên PM cùng PMO đặt ngưỡng đo được cho cả hai, lấy 5% làm mốc chi phí; steering committee phải duyệt governance plan trước khi build bắt đầu.","Sai: đúng nếu sponsor được ủy quyền tự phán đoán từng trường hợp, nhưng ở đây plan cần tiêu chí đo được để ai cũng biết khi nào phải leo thang; giao cho một người thì ngưỡng vẫn mơ hồ như câu «significant variances».","Sai: ngưỡng của dự án data center trước trong thư viện PMO là OPA hữu ích, đúng nếu cùng quy mô và cùng chính sách tài chính, nhưng ở đây chưa đối chiếu với mốc 5% hiện hành nên có thể lệch."],exp:"B1 kiểm tra enabler về escalation paths and thresholds. Governance plan phải nói rõ ai quyết gì và khi nào vấn đề được đẩy lên, dựa trên OPA như chính sách tài chính. Quy tắc nhớ: ngưỡng phải đo được, khớp chính sách và được cấp có thẩm quyền đồng ý trước khi cần dùng."},{id:"o220",n:220,t:0,origin:"original",eco:"B2",domain:"business",approach:"agile",tags:["agile","eco-2026","compliance","sustainability","backlog"],type:"mc",q:"A scrum team is building a cloud analytics platform. The company’s sustainability policy requires projects to track and report the energy use of their cloud workloads, but the product backlog contains only customer-facing features and nobody has mentioned the policy. The sustainability office has confirmed that the policy covers this product and that its requirements are mandatory, not tradable against feature value. Release planning is next week. What should the project manager do?",opts:["Let the product owner weigh the policy work against customer features, so that it is placed where its value ranks in the backlog","Have the sustainability office confirm which products the policy covers, then bring the result to release planning","Add energy tracking to the backlog with the product owner and to the definition of done, as a compliance requirement","Let the sustainability office compile the energy figures from the cloud provider’s invoices, and share them quarterly"],ans:[2],why:["Sai: đúng nếu chính sách là tùy chọn có thể đánh đổi với giá trị tính năng, nhưng sustainability office đã xác nhận đây là yêu cầu bắt buộc; xếp theo giá trị có thể đẩy nó xuống cuối backlog và không bao giờ làm.","Sai: đúng nếu chưa rõ chính sách có áp dụng cho sản phẩm này không, nhưng sustainability office đã xác nhận phạm vi rồi; bước xác nhận đã xong nên làm lại chỉ trì hoãn việc đưa yêu cầu vào backlog.","Đúng: chính sách bắt buộc đã được xác nhận nhưng backlog chưa có gì; PM cùng product owner đưa việc theo dõi năng lượng vào backlog và vào definition of done để yêu cầu tuân thủ được làm và kiểm tra mỗi sprint.","Sai: đúng nếu chỉ cần số liệu hóa đơn tổng, nhưng chính sách yêu cầu dự án theo dõi và báo cáo năng lượng của workload; hóa đơn quý không nằm trong backlog nên đội không đo hay kiểm tra được."],exp:"B2 kiểm tra enabler confirm compliance requirements, trong đó sustainability được ECO nêu cùng security và regulatory. Với agile, yêu cầu bắt buộc đã xác nhận được đưa vào backlog cùng product owner và vào tiêu chí definition of done. Quy tắc nhớ: yêu cầu tuân thủ phải hiện trong backlog thì mới được làm."},{id:"o221",n:221,t:0,origin:"original",eco:"B3",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","change-control","hybrid-scope"],type:"mc",q:"On a hybrid smart-lock project, hardware scope is baselined and controlled by a change control board, while firmware is managed from a product backlog. A marketing director asks to add a fingerprint sensor, which would change the housing design and require new firmware stories. The team has already sized the firmware work and the housing supplier has quoted the tooling cost. What should the project manager do?",opts:["Add the firmware stories to the backlog and tell the change control board about the housing impact once the sprint ends","Meet the product owner and the marketing director, agree that the sensor is in scope, and then update the baselines","Ask the team to size the firmware work and get a tooling quote from the housing supplier, so that the change request carries figures","Submit a change request for the housing impact to the board, then work with the product owner on the backlog"],ans:[3],why:["Sai: firmware đi qua backlog là đúng kênh, nhưng cảm biến vân tay đổi thiết kế vỏ, thuộc phạm vi đã baseline do CCB kiểm soát. Báo CCB sau khi sprint kết thúc là đảo thứ tự và vi phạm kiểm soát thay đổi.","Sai: họp với product owner và giám đốc marketing để thống nhất phạm vi không thay thế phê duyệt của CCB. Cập nhật baseline mà chưa có quyết định của CCB là bỏ qua kênh có thẩm quyền.","Sai: ước lượng firmware và báo giá khuôn vỏ là phần của phân tích tác động, nhưng stem cho biết đội đã ước lượng và nhà cung cấp đã báo giá. Làm lại không thêm thông tin; việc còn lại là trình CCB phần vỏ.","Đúng: phần cứng đã có baseline nên phải qua change request và CCB. Phần firmware thay đổi trong backlog do product owner sắp xếp, sau khi quyết định của CCB đã rõ."],exp:"B3 kiểm tra execute the change control process trong dự án hybrid. Phần predictive đi qua CCB và baseline, phần agile đi qua product owner và backlog. Quy tắc nhớ: mỗi loại thay đổi đi theo kênh có thẩm quyền của nó; thay đổi chạm cả hai phía thì làm CCB trước rồi mới cập nhật backlog."},{id:"o222",n:222,t:0,origin:"original",eco:"B4",domain:"business",approach:"agile",tags:["agile","eco-2026","impediments","prioritization"],type:"mc",q:"On day four of a sprint, the team’s impediment board lists six items: slow build servers, a pending security approval, no test data for one story, an unclear acceptance criterion, an expired license for a design tool, and a missing access right. The sprint goal depends mainly on one story, which is blocked by the missing test data and the unclear acceptance criterion; the security approval, the license and the access right sit with other departments. What should the project manager do?",opts:["Meet the team and agree that it resolves the six items itself, since a self-organizing team manages its own blockers","Clear the items in the order they were logged on the board, so each reporter sees their own item handled in turn","Escalate the security approval, the license and the access right to the sponsor as a group and ask for one decision","Rank the items by effect on the sprint goal and clear the biggest blockers first while keeping the rest visible"],ans:[3],why:["Sai: đội tự tổ chức tự xử lý trở ngại trong tầm của mình, nhưng ba mục cần phòng ban khác (phê duyệt bảo mật, license, quyền truy cập) vượt quyền của đội. PM phải hỗ trợ, không để đội tự gánh.","Sai: xử lý theo thứ tự ghi nhận nghe công bằng, nhưng sprint goal phụ thuộc vào một story bị chặn bởi test data và tiêu chí chấp nhận. Thứ tự ghi nhận không phản ánh tác động lên sprint goal.","Sai: leo thang ba mục ngoài đội lên sponsor có thể cần, nhưng chúng không chặn story chính của sprint goal. Làm vậy xử lý trở ngại phụ trước và bỏ sót test data cùng tiêu chí chấp nhận.","Đúng: PM đánh giá tác động của từng trở ngại lên sprint goal, ưu tiên cái ảnh hưởng nhiều nhất (ví dụ cái chặn story chủ chốt) và giữ mọi mục hiển thị trên board để theo dõi tiếp."],exp:"B4 kiểm tra enabler prioritize and highlight impediments. Đánh giá tác động lên sprint goal trước, rồi xử lý theo mức ảnh hưởng và giữ mọi mục minh bạch. Quy tắc nhớ: ưu tiên theo tác động chứ không theo thứ tự đến, và chỉ leo thang sau khi PM đã thử tháo gỡ."},{id:"o431",n:431,t:0,origin:"original",eco:"B1",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","success-metrics","reporting"],type:"mc",q:"A company is rolling out an ERP upgrade. The core finance modules follow a predictive plan with monthly earned value reports, while the mobile app team works in two-week sprints and reports velocity and burndown. At the first steering committee meeting, the sponsor says she cannot tell whether the overall initiative is succeeding. What should the project manager do?",opts:["Get the PMO analyst to merge both report sets into one dashboard, and walk the sponsor through it before each steering committee meeting","Ask the finance lead and the mobile product owner to explain their reports to the sponsor, and agree with her which figures she should watch","Convert the sprint data into earned value figures with the PMO, so that the steering committee reads one method for both teams","Define shared outcome metrics and one reporting cadence that both teams feed, agreed with the sponsor and the product owner"],ans:[3],why:["Sai: đúng nếu sponsor chỉ thiếu một màn hình gộp các số đang có, nhưng ở đây hai bộ số đo bằng thước khác nhau (earned value và velocity) nên dashboard gộp vẫn không cho biết initiative có thành công hay không.","Sai: đúng nếu sponsor chỉ chưa hiểu cách đọc từng báo cáo, nhưng ở đây vấn đề là chưa có chỉ số kết quả chung; giải thích hai báo cáo vẫn để bà tự ghép hai bức tranh.","Sai: đúng nếu cả hai đội cùng chạy predictive, nhưng ở đây đội mobile làm sprint và báo velocity, burndown; ép sang earned value làm sai bản chất công việc của đội và không đo được kết quả.","Đúng: sponsor không biết initiative có thành công không vì hai bên đo bằng hai thước khác nhau; chỉ số kết quả chung cộng một nhịp báo cáo giữ phương pháp riêng của từng đội mà vẫn cho một bức tranh."],exp:"B1 kiểm tra enabler define success metrics và reporting trong governance. Với hybrid, PM tailor để mỗi phần giữ phương pháp riêng nhưng thống nhất chỉ số kết quả và nhịp báo cáo. Quy tắc nhớ: sponsor cần một bức tranh chung, không phải hai bộ báo cáo song song."},{id:"o432",n:432,t:0,origin:"original",eco:"B1",domain:"business",approach:"predictive",tags:["predictive","eco-2026","opa","governance-structure"],type:"mc",q:"A project manager has just been assigned a two-year grid modernization project at a utility. The company has a PMO with a governance template, an approval matrix by contract value, a code of conduct, and a lessons learned repository. The sponsor asks for the governance structure within two weeks. What should the project manager do first?",opts:["Meet the sponsor to fix who sits on the steering committee, then have the PMO lead fit the governance template around those people","Adopt the PMO governance template as issued with its approval matrix, and ask the PMO lead to sign off the unchanged result","Ask peers at two other utilities for their governance structures through a professional network, and propose the stronger one to the sponsor","Tailor the PMO governance template to the size, risk and contract values of this two-year project, and take it to the sponsor for review"],ans:[3],why:["Sai: đúng nếu công ty chưa có tài sản governance nào, nhưng ở đây PMO đã có template, và chọn người trước rồi viết luật quanh họ bỏ qua OPA sẵn có và quy mô, rủi ro của dự án.","Sai: đúng nếu dự án có quy mô và rủi ro điển hình của công ty, nhưng đây là dự án lưới điện 2 năm với giá trị hợp đồng riêng nên dùng nguyên template mà không tailor sẽ không khớp.","Sai: đúng nếu công ty không có PMO hay template, nhưng ở đây tài sản tổ chức đã sẵn; mô hình của hai công ty khác không theo chính sách, approval matrix hay code of conduct của công ty này.","Đúng: PMO đã có governance template, approval matrix, code of conduct và lessons learned, nên PM bắt đầu từ template và tailor theo quy mô, rủi ro, giá trị hợp đồng rồi mới trình sponsor."],exp:"B1 kiểm tra enabler describe and establish the structure, rules, procedures, reporting, ethics and policies through OPAs. Quy tắc nhớ: bắt đầu từ tài sản của tổ chức, rồi tailor theo quy mô và rủi ro; đừng dựng mô hình riêng khi tổ chức đã có sẵn."},{id:"o433",n:433,t:0,origin:"original",eco:"B1",domain:"business",approach:"agile",tags:["agile","eco-2026","ai","governance","working-agreement"],type:"mc",q:"A self-organizing scrum team of eight at an insurance company wants to use a generative AI assistant to draft user stories and test cases. The company has a data classification policy but no guidance on AI tools, and the product owner supports the idea. The company’s security team owns decisions about which tools may touch company data. Several team members have already started trying it. What should the project manager do?",opts:["Write acceptable AI use into the working agreement based on the data policy and input from the security team","Make the product owner the approver of each AI-assisted story and test case, before it enters the sprint","Escalate the question to the PMO, so that it writes an AI standard for the company’s projects","Have the team draft its own rules for the tool at the next retrospective, since choosing how to work is within its authority"],ans:[0],why:["Đúng: quy tắc dùng AI là một phần governance và ethics, nên xây trên OPA hiện có (chính sách phân loại dữ liệu) với đại diện bảo mật tham gia. Đưa vào working agreement giúp đội tuân thủ mà vẫn tự tổ chức.","Sai: product owner duyệt đầu ra là kiểm soát chất lượng hợp lý, nhưng rủi ro chính là dữ liệu nào được đưa vào công cụ. Duyệt sau khi story đã tạo không ngăn dữ liệu nhạy cảm bị nhập ngay từ đầu.","Sai: chuyển cho PMO viết chuẩn AI chung cho mọi dự án mất nhiều thời gian trong khi nhiều thành viên đã dùng công cụ. Đúng nếu cần chuẩn toàn công ty, nhưng đội cần ranh giới rõ ngay trong working agreement.","Sai: đội tự quyết cách làm việc là đúng với quy trình, nhưng quyết định công cụ nào được chạm dữ liệu công ty thuộc security team. Đội tự đặt luật bỏ qua người có thẩm quyền về dữ liệu."],exp:"B1 kiểm tra việc thiết lập rules, policies và ethics qua OPA, ở đây với bối cảnh AI. PM không cấm tràn lan cũng không để mặc: cùng đội, product owner và bộ phận bảo mật đặt ranh giới rõ, rồi ghi vào working agreement. Người dùng AI vẫn chịu trách nhiệm về đầu ra."},{id:"o434",n:434,t:0,origin:"original",eco:"B1",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","success-metrics","benefits"],type:"mc",q:"At the start of a hybrid initiative to launch a customer portal, the sponsor describes success as “on time and within budget.” The head of sales says success means 30 percent of existing customers using the portal within six months. The program office wants one set of success metrics in the governance plan. What should the project manager do?",opts:["Record the delivery metrics in the governance plan as the sponsor described them, and let the head of sales track adoption in the sales reports","Include both definitions in the plan as the sponsor and the head of sales wrote them, and let each of them judge success their own way","Get the sponsor and head of sales to approve one set of measurable criteria covering delivery and the 30 percent adoption target","Review adoption results from earlier portal launches with the sales analyst to find a realistic target, then add that figure to the plan"],ans:[2],why:["Sai: đúng nếu chỉ một bên định nghĩa thành công, nhưng ở đây cả sponsor lẫn head of sales đều có lý và program office cần một bộ metrics; để adoption ngoài plan thì governance không đo được lợi ích.","Sai: đúng nếu hai bên chấp nhận được hai cách đánh giá riêng, nhưng ở đây program office cần một bộ metrics duy nhất; hai định nghĩa viết nguyên văn vẫn chưa đo được và sẽ gây tranh cãi khi báo cáo.","Đúng: hai bên liên quan mô tả thành công khác nhau và cả hai đều có lý, nên PM soạn một bộ tiêu chí đo được gồm giao hàng và adoption rồi để cả hai duyệt; đó là một metrics duy nhất cho governance plan.","Sai: đúng nếu head of sales chưa nêu mục tiêu, nhưng ở đây 30% trong 6 tháng đã được nêu ra; vấn đề là hai định nghĩa khác nhau chứ không phải thiếu số liệu lịch sử để chọn target."],exp:"B1 kiểm tra enabler define success metrics. Hai bên liên quan mô tả thành công khác nhau thì PM không chọn giúp một bên; PM soạn tiêu chí đo được cho cả kết quả giao hàng lẫn lợi ích và để họ cùng duyệt. Quy tắc nhớ: thống nhất định nghĩa thành công trước khi thực thi."},{id:"o435",n:435,t:0,origin:"original",eco:"B1",domain:"business",approach:"predictive",tags:["predictive","eco-2026","escalation","governance"],type:"mc",q:"A construction project’s governance plan states that schedule delays over two weeks go from the project manager to the steering committee, which then informs the sponsor. A regulatory approval for a pipeline crossing is now three weeks late. The site lead, worried about the deadline, emailed the sponsor directly and copied no one. What should the project manager do?",opts:["Brief the sponsor directly on the slip since she already knows about it, and send the steering committee a note for the record","Meet the site lead to agree a recovery plan for the crossing, and report to the steering committee if the plan fails","Take the delay to the steering committee through the defined path, backed by data, and remind the team of the thresholds","Analyze with the site lead how the three-week slip affects the critical path, before choosing the escalation route"],ans:[2],why:["Sai: sponsor đã biết, nhưng governance plan đặt steering committee ở giữa đường escalation. Chỉ gửi ghi chú cho steering committee sau khi báo trực tiếp sponsor là đi tắt đường đã thống nhất.","Sai: kế hoạch phục hồi cùng site lead là việc có ích, nhưng ngưỡng hai tuần đã bị vượt (ba tuần). Plan yêu cầu escalate khi vượt ngưỡng, không đợi đến khi kế hoạch phục hồi thất bại.","Đúng: chậm hơn hai tuần là vượt ngưỡng, nên vấn đề phải đi theo đường escalation đã định cùng dữ liệu tác động. Nhắc lại đường đi và ngưỡng giúp đội tránh bỏ qua cấp trung gian về sau.","Sai: phân tích ảnh hưởng đến đường găng cùng site lead là việc có ích, nhưng governance plan đã định sẵn đường escalation theo ngưỡng hai tuần và độ trễ ba tuần đã vượt. PM không cần phân tích để biết phải đi đường nào."],exp:"B1 kiểm tra enabler outline governance escalation paths and thresholds. Khi ngưỡng đã bị vượt và có người đi tắt, PM đưa vấn đề đúng đường đã thống nhất và củng cố quy tắc. Quy tắc nhớ: tuân thủ đường escalation, và dạy đội hiểu vì sao nó tồn tại."},{id:"o436",n:436,t:0,origin:"original",eco:"B1",domain:"business",approach:"agile",tags:["agile","eco-2026","tailoring","stage-gate"],type:"mc",q:"A product company has six scrum teams. The PMO requires a stage-gate package of detailed requirement documents and a baselined plan before funding each quarter. The teams plan in detail only the next release and review working increments every sprint. The PMO head has said she is open to tailoring the gates if the control objectives stay intact. Quarterly funding is now at risk. What is the best way to set up governance?",opts:["Produce the detailed gate package each quarter alongside the sprint work, and ask the PMO head to confirm it satisfies the funding rules","Propose with the six product owners that quarterly gate reviews be replaced by sprint review notes shared with the PMO","Add a quarterly release-forecast report from each product owner next to the detailed gate documents, and let the PMO head fund from both","Tailor the gates for the six teams, so that funding decisions rest on increment reviews, release forecasts and metrics the PMO head accepts"],ans:[3],why:["Sai: đúng nếu PMO không chịu tailor gate, nhưng ở đây trưởng PMO đã sẵn sàng tailor miễn là mục tiêu kiểm soát còn nguyên; làm gói tài liệu chi tiết song song là lãng phí và giữ nguyên quy trình cũ.","Sai: đúng nếu quarterly gate không phục vụ mục tiêu kiểm soát nào, nhưng ở đây PMO cần giữ control objective; bỏ gate và chỉ gửi sprint review notes khiến quyết định tài trợ mất căn cứ.","Sai: đúng nếu PMO không thể đổi gate document, nhưng ở đây PMO sẵn sàng tailor; thêm báo cáo song song với tài liệu chi tiết tạo hai lớp việc và không giải quyết rủi ro funding.","Đúng: trưởng PMO sẵn sàng tailor gate nếu control objective còn nguyên, nên PM cùng PMO đổi bằng chứng sang increment review, release forecast và metrics đã thống nhất; funding giữ được mà không viết tài liệu thừa."],exp:"B1 kiểm tra tailoring governance theo cách tiếp cận. PM làm việc với PMO để giữ mục tiêu kiểm soát nhưng đổi bằng chứng và nhịp phù hợp với agile. Quy tắc nhớ: governance phục vụ phương pháp, không bắt phương pháp chạy theo giấy tờ."},{id:"o437",n:437,t:0,origin:"original",eco:"B1",domain:"business",approach:"predictive",tags:["predictive","eco-2026","ethics","conflict-of-interest"],type:"mc",q:"A project manager is establishing governance for a hospital construction project that will place more than 40 purchase orders with equipment suppliers. The company’s code of conduct and conflict-of-interest policy exist but are not mentioned in the draft governance plan (the ethics office has already confirmed that they apply to the team and the bidders), and two team members have friends working at bidding suppliers. What should the project manager do?",opts:["Add the company’s code of conduct plus its conflict-of-interest rules to the governance plan and brief the team on them","Ask procurement to brief the bid evaluators on the conflict-of-interest rules, since it runs the bidding for the project","Ask the ethics office to confirm that the conflict-of-interest policy applies to the team members and the bidders","Hold a team session on the professional code of conduct and trust each member to apply it to bidding situations"],ans:[0],why:["Đúng: ethics và policies là một phần của governance và đã có sẵn trong OPA. PM đưa chúng vào governance plan và truyền thông cho đội, kể cả thủ tục khai báo xung đột lợi ích, trước khi hơn 40 đơn mua sắm được đặt.","Sai: procurement briefing người chấm thầu là việc tốt, nhưng hai thành viên có bạn ở nhà thầu lại là thành viên đội dự án, không nằm trong nhóm chấm thầu. Quy tắc phải nằm trong governance plan để cả đội biết.","Sai: xác nhận phạm vi áp dụng của chính sách là hợp lý nếu còn nghi ngờ, nhưng ethics office đã xác nhận chính sách áp dụng cho đội và nhà thầu. Việc còn thiếu là đưa nó vào governance plan và truyền thông.","Sai: buổi họp về bộ quy tắc nghề nghiệp có ích, nhưng để mỗi người tự áp dụng thì plan vẫn không nêu chính sách của công ty hay thủ tục khai báo xung đột lợi ích. Phải ghi vào plan và truyền thông."],exp:"B1 kiểm tra enabler ethics và policies thông qua OPA. Khi chính sách tổ chức đã có, PM tích hợp và truyền thông chúng ngay trong governance plan, nhất là trước giai đoạn mua sắm có rủi ro xung đột lợi ích. Quy tắc nhớ: dùng OPA có sẵn và làm cho mọi người biết."},{id:"o438",n:438,t:0,origin:"original",eco:"B1",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","decision-rights","hybrid-governance"],type:"mc",q:"A hybrid software and device project for a medical company has two bodies: a product council that prioritizes the backlog every sprint, and a change control board that manages baselined hardware scope. Last month both groups claimed authority over a sensor feature, and the team waited two weeks for direction. What should the project manager do?",opts:["Convene both bodies in a joint session to settle the sensor feature, and record the outcome in the change log","Draft a decision-rights table saying who decides what and when a decision moves up, and get both chairs to sign it","Have the sponsor merge the two bodies into one weekly forum that reviews backlog and baseline decisions together","Look into the sensor dispute with both chairs to find out which body acted first, and let that body’s decision stand"],ans:[1],why:["Sai: đúng nếu đây là tranh chấp đơn lẻ, nhưng ở đây hai cơ quan cùng nhận quyền trên một feature và đội đã chờ hai tuần; giải quyết riêng feature cảm biến thì lần sau vẫn xảy ra lại.","Đúng: hai cơ quan cùng nhận quyền và đội chờ hai tuần, nên lỗi nằm ở cấu trúc; bảng decision rights nói rõ cơ quan nào quyết gì và khi nào chuyển cấp, được cả hai ký, sửa gốc của vấn đề.","Sai: đúng nếu hai cơ quan trùng chức năng hoàn toàn, nhưng ở đây product council xếp backlog mỗi sprint còn change control board quản scope baseline phần cứng; gộp lại làm mất tính chuyên trách của từng bên.","Sai: đúng nếu quyền được xác định theo ai hành động trước, nhưng ở đây không có quy tắc đó; tìm bên đi trước hay bên có lý hơn chỉ xử lý vụ này và để lại khoảng trống về decision rights."],exp:"B1 kiểm tra enabler structure, rules và procedures của governance. Trong hybrid, nhiều cơ quan quyết định cùng tồn tại; PM cùng chủ tọa hai bên làm rõ decision rights và ngưỡng chuyển cấp rồi lấy chữ ký. Quy tắc nhớ: sửa cấu trúc, đừng chỉ xử lý một vụ việc."},{id:"o439",n:439,t:0,origin:"original",eco:"B1",domain:"business",approach:"predictive",tags:["predictive","eco-2026","opa","approval-matrix","confirm-first"],type:"mc",q:"A project manager inherits a 20-month infrastructure project at the end of its second phase. The approved governance plan refers to an approval matrix that lets the project manager authorize purchases up to a limit. Last week the company issued a new matrix that halves that limit. The memo applies it to active projects from the issue date “except contracts signed under the old matrix” and names the PMO as the owner of any question about its scope. The main contracts were signed under the old matrix, but a purchase between the two limits, planned for next month, is a new order outside them. What should the project manager do first?",opts:["Revise the governance plan to the halved limit, tell the team to follow it from the issue date, and note the change in the plan history","Keep the approved plan’s limit through the phase gate, and adopt the new matrix in the plan revision that follows it","Apply the halved limit to next month’s purchase in practice, and keep the approved plan text unchanged for audit purposes","Ask the PMO to rule whether the memo’s exception reaches next month’s purchase, then update the governance plan to match its answer"],ans:[3],why:["Sai: đúng nếu đơn mua nằm ngoài ngoại lệ chắc chắn, nhưng ở đây chưa rõ ngoại lệ có bao trùm đơn hàng mới này không; sửa plan theo hạn mức mới khi chưa xác nhận có thể làm sai quy định.","Sai: đúng nếu đơn mua thuộc các hợp đồng ký theo ma trận cũ, nhưng đây là order mới ngoài hợp đồng chính và memo giao PMO giải thích phạm vi; giữ hạn mức cũ là giả định ngoại lệ áp dụng.","Sai: đúng nếu plan không cần phản ánh việc làm thực tế, nhưng làm khác plan đã duyệt tạo lệch giữa tài liệu và thực tế, và vẫn chưa biết hạn mức nào đúng; kiểm toán sẽ thấy ngay chỗ lệch này.","Đúng: memo giao PMO quyền giải thích phạm vi và đơn mua này nằm ngoài hợp đồng chính nên chưa rõ ngoại lệ có áp dụng; PM hỏi PMO trước, rồi mới cập nhật governance plan theo câu trả lời."],exp:"B1 kiểm tra việc xác lập và cập nhật rules, procedures qua OPA. Khi ma trận phê duyệt đổi nhưng memo có ngoại lệ mơ hồ và giao PMO giải thích, PM hỏi PMO trước rồi mới sửa governance plan và truyền thông. Quy tắc nhớ: chưa rõ chính sách có áp dụng thì xác nhận với chủ sở hữu trước, đừng sửa plan hay làm trái plan theo phỏng đoán."},{id:"o440",n:440,t:0,origin:"original",eco:"B2",domain:"business",approach:"agile",tags:["agile","eco-2026","compliance","definition-of-done"],type:"mc",q:"A scrum team is building a card payment feature and releases every sprint. Auditors will later ask for evidence that security and data-handling requirements were met in each release. The compliance officer has already confirmed the list of requirements, and the team has no separate QA group. At the sprint review the team shows working features, but nobody can show how compliance was checked; the definition of done lists only code review and passing tests. What should the project manager do?",opts:["Engage an outside testing group to run a compliance test cycle before each release, and have the compliance officer file the results as audit evidence","Go through the requirements with the compliance officer and list them in a release checklist that the product owner signs for each release","Appoint a compliance champion on the team to review each story against the requirements before the release goes out","Add the compliance criteria to the definition of done, and have the team check each increment against them within the sprint"],ans:[3],why:["Sai: đúng nếu đội có QA group riêng cần kiểm thử bổ sung, nhưng ở đây kiểm thử ngoài trước mỗi release là kiểm tra bù cuối và không nhúng tuân thủ vào công việc từng sprint.","Sai: đúng nếu danh sách yêu cầu chưa được xác nhận, nhưng compliance officer đã xác nhận rồi; checklist ký lúc release vẫn kiểm tra bù ở cuối, không tạo bằng chứng trong từng sprint.","Sai: đúng nếu đội có người chuyên trách đủ thời gian cho mọi story, nhưng ở đây đội không có QA group; một champion duyệt trước release vẫn là kiểm tra cuối và không để lại tiêu chí trong definition of done.","Đúng: definition of done chỉ có code review và test pass nên thiếu tiêu chí tuân thủ; đưa tiêu chí vào DoD và kiểm tra từng increment trong sprint tạo bằng chứng cho auditor ở mỗi release."],exp:"B2 kiểm tra enabler measure the extent to which the project is in compliance, trong bối cảnh agile. Cách làm: nhúng tiêu chí tuân thủ vào definition of done và công khai kết quả ở sprint review. Quy tắc nhớ: tuân thủ được xây vào công việc từng sprint, không kiểm tra bù cuối cùng."},{id:"o441",n:441,t:0,origin:"original",eco:"B2",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","ai","data-privacy","compliance","escalation"],type:"mc",q:"On a hybrid CRM migration, analysts under deadline pressure pasted real customer records, including names and addresses, into a public generative AI chatbot to speed up data mapping. A team lead noticed and told the project manager. The company’s privacy policy requires any suspected exposure of customer data to be reported to the security team, which owns the incident procedure. What should the project manager do first?",opts:["Escalate the exposure to the security team and the privacy officer under the incident procedure, and pause AI use on the migration","Go through the pasted records with the analysts to count the customers affected, then decide whether the exposure needs reporting","Draft a data-handling guideline for AI tools with the team and the security team’s review, and apply it from the next mapping task","Ask the AI vendor to confirm how the pasted customer records are stored, and to delete them from its systems now"],ans:[0],why:["Đúng: chính sách quyền riêng tư yêu cầu báo mọi nghi ngờ lộ dữ liệu cho security team, đơn vị sở hữu incident procedure; PM leo thang ngay và tạm dừng AI trên dự án để dừng tiếp tục rò rỉ.","Sai: đúng nếu chính sách chỉ yêu cầu báo khi đã xác nhận có rò rỉ, nhưng ở đây chính sách yêu cầu báo cả khi nghi ngờ (suspected exposure), nên không được chờ đánh giá mức độ rồi mới quyết định báo.","Sai: đúng nếu chưa có vi phạm nào xảy ra, nhưng ở đây dữ liệu khách hàng đã được dán vào công cụ công khai; hướng dẫn cho lần sau không thay được việc báo sự cố hiện tại.","Sai: đúng nếu security team đã xử lý sự cố và chỉ còn việc với nhà cung cấp, nhưng ở đây sự cố chưa được báo; liên hệ vendor trước khi security team vào cuộc bỏ qua incident procedure."],exp:"B2 kiểm tra enabler determine potential threats to compliance và determine the necessary approach and action. AI chỉ là bối cảnh: dữ liệu khách hàng đưa vào công cụ ngoài vi phạm chính sách quyền riêng tư. Quy tắc nhớ: báo ngay cho bên sở hữu quy trình sự cố (security, privacy), tạm dừng hành vi, rồi mới tính chuyện hướng dẫn cho tương lai."},{id:"o442",n:442,t:0,origin:"original",eco:"B2",domain:"business",approach:"predictive",tags:["predictive","eco-2026","compliance","sustainability","planning"],type:"mc",q:"A project to expand a food-processing plant is in the planning phase. The company’s sustainability policy sets a water-recycling target and requires annual reporting by every capital project. The draft plans contain no activities, measures or reporting for it, and the main contractor says it is not in the draft contract, which is still open for negotiation. What should the project manager do?",opts:["Get the sustainability office to plan a closure audit of water use, and record the result in the annual report","Write the recycling target, activities, measures and annual reporting into the plans, and ask procurement to add them to the contract","Invite the main contractor to propose its own recycling approach in the negotiation, and add it to the contract if the sponsor judges it adequate","Ask the sustainability office to confirm whether the target applies to expansion projects before any planning starts"],ans:[1],why:["Sai: đúng nếu kế hoạch đã có hoạt động tái chế và chỉ cần kiểm tra kết quả, nhưng ở đây draft plan chưa có hoạt động, thước đo hay báo cáo nào; kiểm toán lúc đóng dự án quá muộn để thiết kế vào kế hoạch.","Đúng: chính sách yêu cầu mọi capital project có mục tiêu tái chế nước và báo cáo hằng năm, còn hợp đồng chính chưa ký; PM đưa yêu cầu vào các plan và nhờ procurement thêm vào hợp đồng khi còn thương lượng được.","Sai: đúng nếu chính sách để nhà thầu tự đặt mục tiêu, nhưng ở đây công ty đã đặt target; để nhà thầu đề xuất cách làm riêng và chờ sponsor đánh giá có thể không đạt mục tiêu của chính sách.","Sai: đúng nếu chính sách chỉ áp dụng cho một số loại dự án, nhưng ở đây chính sách yêu cầu mọi capital project và dự án mở rộng nhà máy là capital project; hỏi lại phạm vi chỉ làm chậm việc lập kế hoạch."],exp:"B2 kiểm tra enabler confirm project compliance requirements; ECO nêu sustainability cùng security, health and safety và regulatory. Ở giai đoạn lập kế hoạch, yêu cầu của chính sách nội bộ là compliance và được viết vào plan và hợp đồng khi còn thương lượng. Quy tắc nhớ: đưa yêu cầu tuân thủ vào kế hoạch sớm, khi hợp đồng còn mở."},{id:"o443",n:443,t:0,origin:"original",eco:"B2",domain:"business",approach:"agile",tags:["agile","eco-2026","compliance","threats","spike"],type:"mc",q:"An agile team plans to adopt a new open-source library to speed up a feature due in three sprints. Another team mentions that the library’s license terms are unusual and may conflict with the company’s rules on distributing the product. The product owner wants a quick decision. What should the project manager do?",opts:["Have the product owner compare the library with two alternatives on delivery speed and cost, then pick one","Add a spike for the developers to measure the library’s performance and fit, and decide when the sprint ends","Adopt the library to protect the date, and ask legal to look at the license once the feature is complete","Ask legal and compliance to review the license, and add a spike to the backlog to assess its fit before adopting"],ans:[3],why:["Sai: đúng nếu mối lo chỉ là tốc độ và chi phí, nhưng ở đây lo ngại là giấy phép có thể xung đột quy định phân phối của công ty; so sánh thư viện không trả lời được câu hỏi tuân thủ.","Sai: đúng nếu mối lo là hiệu năng hay độ phù hợp kỹ thuật, nhưng ở đây vấn đề là điều khoản giấy phép; spike kỹ thuật thuần túy không do legal đánh giá nên không loại được rủi ro tuân thủ.","Sai: đúng nếu giấy phép chắc chắn không ràng buộc, nhưng ở đây giấy phép lạ và có thể xung đột; dùng trước rồi nhờ legal xem sau khi xong feature để rủi ro tuân thủ đã nằm trong sản phẩm.","Đúng: có dấu hiệu rủi ro tuân thủ nên PM nhờ legal và compliance rà giấy phép, đồng thời đưa spike vào backlog để đánh giá độ phù hợp; quyết định thư viện chỉ chốt sau khi có thông tin."],exp:"B2 kiểm tra enabler determine potential threats to compliance trong agile. PM nhận diện rủi ro tuân thủ sớm và dùng spike để có thông tin trước khi cam kết. Quy tắc nhớ: gặp dấu hiệu rủi ro tuân thủ thì phân tích với chuyên gia trước, rồi mới ra quyết định công nghệ."},{id:"o444",n:444,t:0,origin:"original",eco:"B2",domain:"business",approach:"predictive",tags:["predictive","eco-2026","compliance","noncompliance-consequences"],type:"mc",q:"A chemical storage facility is two weeks from planned commissioning. A mandatory safety inspection will take three more weeks to schedule and complete. The sponsor, under pressure from a customer contract, tells the project manager to skip the inspection and says she will accept responsibility for the decision. What should the project manager do?",opts:["Sound out the inspection body informally on whether the step can be shortened, and proceed on its answer if it agrees to a shorter inspection","Have the facility operations manager schedule the inspection after commissioning as a post-launch activity, so that the facility starts on time","Raise the instruction with the PMO director and the compliance officer, and let the PMO decide whether the inspection stays in the plan","Have the compliance officer list what noncompliance could cost in fines, shutdown and liability, then present the options to the sponsor"],ans:[3],why:["Sai: đúng nếu quy định cho phép rút ngắn thanh tra, nhưng thanh tra an toàn bắt buộc không được rút gọn theo ý kiến không chính thức; làm theo câu trả lời đó vẫn là bỏ qua bước bắt buộc.","Sai: đúng nếu quy định cho phép vận hành thử trước khi thanh tra, nhưng ở đây thanh tra là bắt buộc trước khi đưa vào sử dụng; ghi nó là hoạt động sau launch tức là vận hành khi chưa được kiểm tra.","Sai: đúng nếu PMO là cấp có quyền quyết định tuân thủ, nhưng chuyển vụ việc cho PMO để họ quyết định bỏ qua việc PM phải làm rõ hậu quả cụ thể và đưa phương án cho người có thẩm quyền, tức sponsor.","Đúng: sponsor muốn bỏ qua bước bắt buộc và nhận trách nhiệm, nên PM làm rõ cùng compliance officer hậu quả (phạt, đóng cửa, trách nhiệm pháp lý) rồi đưa phương án để sponsor quyết định đúng thông tin."],exp:"B2 kiểm tra enabler analyze the consequences of noncompliance. Khi có áp lực bỏ qua một bước bắt buộc, PM làm rõ hậu quả cụ thể rồi trình phương án để người có thẩm quyền quyết định đúng thông tin. Quy tắc nhớ: yêu cầu an toàn bắt buộc không được đánh đổi để giữ tiến độ."},{id:"o445",n:445,t:0,origin:"original",eco:"B2",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","compliance","sustainability","measurement"],type:"mc",q:"A hybrid product-packaging project uses a predictive plan for supply contracts and sprints for design. The company’s sustainability policy requires at least 80 percent of packaging components to be recyclable. After four sprints, the sustainability officer finds that new designs use a material that does not qualify. No one tracked the share, so the current figure is unknown, including for the components in the supply contracts. What should the project manager do?",opts:["Get the contract managers to collect supplier certificates of recyclability for each component, so that the policy counts as met","Define a measure for the recyclable share, and report it to the sustainability officer at every sprint review and phase gate","Add a recyclability gate to the predictive plan, owned by the procurement lead, and leave the design sprints as they are","Rework the non-qualifying designs with the sustainability officer, and check the share at the final gate audit"],ans:[1],why:["Sai: đúng nếu chứng nhận của nhà cung cấp chứng minh đủ tỷ lệ 80%, nhưng chứng nhận từng linh kiện không cho biết tỷ lệ tổng và không đo gì trong các sprint thiết kế đang chạy.","Đúng: chưa ai theo dõi tỷ lệ nên không biết mình đang cách mục tiêu 80% bao xa; PM định nghĩa thước đo cùng sustainability officer và báo ở mỗi sprint review lẫn phase gate cho cả hai phần của hybrid.","Sai: đúng nếu vấn đề chỉ nằm ở hợp đồng cung ứng, nhưng ở đây thiết kế mới cũng dùng vật liệu không đạt; gate chỉ ở phần predictive để các sprint thiết kế không được đo.","Sai: đúng nếu đã biết tỷ lệ hiện tại, nhưng ở đây chưa ai đo; sửa các thiết kế bị phát hiện mà không đo tỷ lệ và chỉ kiểm lại ở gate cuối là phát hiện muộn, có thể còn thiết kế sai khác."],exp:"B2 kiểm tra enabler measure the extent to which the project is in compliance, với sustainability là loại yêu cầu tuân thủ. Khi chưa ai đo tỷ lệ, hybrid cần một chỉ số dùng chung cho cả sprint và phase gate trước khi sửa từng thiết kế. Quy tắc nhớ: đo định kỳ trong quá trình, không đợi kiểm toán cuối."},{id:"o446",n:446,t:0,origin:"original",eco:"B2",domain:"business",approach:"agile",tags:["agile","eco-2026","compliance","security","release"],type:"mc",q:"During sprint 9, a security scan shows that a login feature stores credentials in a way that breaks the company’s security standard, which is a compliance requirement for the product; the standard does not allow waivers for credential storage. The product owner wants the feature released next week because the customer is waiting. The team estimates the fix at three days. What should the project manager do?",opts:["Put the fix at the top of the backlog with the product owner, then release once the code passes the security scan","Re-scan and assess with the security team how severe the weakness is before deciding where to place the fix","Release next week with the credential handling flagged as a known issue, and have the team patch it in the following sprint","Ask the security team to issue a time-limited risk waiver for the breach, so that the release can keep the customer’s date"],ans:[0],why:["Đúng: tiêu chuẩn bảo mật là yêu cầu tuân thủ và không cho waiver với lưu credential; fix ba ngày được đặt đầu backlog cùng product owner và release khi pass scan, chỉ trễ ba ngày.","Sai: đúng nếu tiêu chuẩn cho phép tùy mức độ nghiêm trọng, nhưng ở đây tiêu chuẩn không cho waiver với lưu credential; đánh giá mức độ nặng nhẹ không đổi việc phải sửa trước release.","Sai: đúng nếu lỗi chỉ là chất lượng thông thường, nhưng ở đây đây là vi phạm yêu cầu tuân thủ; release kèm lỗi đã biết là phát hành sản phẩm không tuân thủ rồi mới vá.","Sai: đúng nếu tiêu chuẩn cho phép waiver tạm thời, nhưng ở đây tiêu chuẩn nói rõ không có waiver với lưu credential; xin waiver là tìm đường vòng quanh một yêu cầu bắt buộc."],exp:"B2 kiểm tra enabler determine the necessary approach and action(s) to address compliance needs. Với agile, sửa lỗi tuân thủ được ưu tiên trong backlog cùng product owner và release khi đạt Definition of Done. Quy tắc nhớ: không vá sau những gì là điều kiện tuân thủ."},{id:"o447",n:447,t:0,origin:"original",eco:"B2",domain:"business",approach:"predictive",tags:["predictive","eco-2026","compliance","classification","sustainability"],type:"mc",q:"A logistics warehouse project has received a list of requirements from the legal team and the sustainability office: fire-code approvals, worker safety rules, security of the warehouse management system, and a company carbon-reporting policy. Both offices have confirmed in writing that every item is mandatory. The items sit in a single spreadsheet with no owners or verification methods. What should the project manager do?",opts:["Rank the items by the fine each one carries, assign an owner to each from the top of that ranking, and track them in the compliance register","Have the legal team and the sustainability office rank which items are binding, and add only the binding ones to the plan","Hand the whole list to the legal team to track as owner of every item, with a monthly status report to the project manager","Classify the items into categories such as safety, security, regulatory and sustainability, and assign each an owner and a verification method"],ans:[3],why:["Sai: đúng nếu chỉ một số mục bắt buộc và cần chọn mục ưu tiên, nhưng cả hai bên đã xác nhận mọi mục đều bắt buộc; xếp theo mức phạt đề cao một số mục và bỏ bước phân loại để gán owner phù hợp.","Sai: đúng nếu chưa rõ mục nào bắt buộc, nhưng hai văn phòng đã xác nhận bằng văn bản rằng mọi mục đều bắt buộc; hỏi lại để lọc chỉ làm chậm và có thể loại mất yêu cầu cần tuân thủ.","Sai: đúng nếu legal là chuyên gia phù hợp cho mọi nhóm, nhưng an toàn, bảo mật hệ thống và carbon reporting cần owner và cách kiểm tra khác nhau; giao hết cho legal thì không ai chịu trách nhiệm đúng chuyên môn.","Đúng: mọi mục đều đã được xác nhận bắt buộc nhưng chưa có owner hay cách xác minh; phân loại theo safety, security, regulatory, sustainability giúp gán owner và verification method phù hợp cho từng nhóm."],exp:"B2 kiểm tra enabler classify compliance categories. Phân loại giúp gán chủ sở hữu và phương pháp xác minh phù hợp cho từng nhóm, kể cả sustainability. Quy tắc nhớ: phân loại trước, rồi gán owner và cách kiểm tra."},{id:"o448",n:448,t:0,origin:"original",eco:"B2",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","compliance","traceability","regulatory"],type:"mc",q:"A hybrid project develops an infusion-pump device. Hardware follows a baselined plan, while the software team delivers sprint increments. Regulatory auditors will require traceability from each requirement to design, tests and approvals. The software team’s backlog items are not linked to hardware requirements. What should the project manager do?",opts:["Get the quality lead to review a sample of finished backlog items each month, and report the traceability gaps to the steering committee","Agree with the QA department that it builds the traceability matrix from the finished records during final audit preparation","Ask the regulatory affairs lead to list the auditors’ traceability expectations, then plan a documentation sprint before integration","Link each requirement to backlog items, tests and approvals as the work goes, and have the hardware lead and product owner keep the links current"],ans:[3],why:["Sai: đúng nếu liên kết đã được tạo trong lúc làm và chỉ cần soát chất lượng, nhưng ở đây backlog item chưa gắn với yêu cầu phần cứng; soát mẫu hằng tháng chỉ phát hiện lỗ hổng chứ không tạo truy vết.","Sai: đúng nếu dữ liệu đủ để dựng lại truy vết về sau, nhưng ở đây backlog chưa liên kết yêu cầu nên dựng ma trận từ hồ sơ cuối lúc chuẩn bị audit là bù muộn và dễ thiếu liên kết.","Sai: đúng nếu chưa biết kỳ vọng của auditor, nhưng đề đã nêu rõ họ yêu cầu truy vết từ yêu cầu đến design, test và approval; liệt kê lại rồi mới làm sprint tài liệu là trì hoãn việc cần làm ngay.","Đúng: auditor cần truy vết liên tục từ yêu cầu đến design, test và approval, còn backlog chưa gắn với yêu cầu phần cứng; PM cùng hai bên liên kết khi công việc diễn ra, giữ phương pháp riêng của từng nhóm."],exp:"B2 kiểm tra enabler use methods to support compliance. Với thiết bị y tế hybrid, truy vết yêu cầu và review định kỳ là công cụ chính. Quy tắc nhớ: tailor cách làm để vẫn tạo bằng chứng tuân thủ liên tục."},{id:"o449",n:449,t:0,origin:"original",eco:"B3",domain:"business",approach:"predictive",tags:["predictive","eco-2026","change-control","baseline"],type:"mc",q:"The change control board approved a change adding a second inspection station to a bottling line. The contractor is ready to start. The contractor’s quotation already lists the added cost, the extra work packages and the new dependencies, but the approved baselines do not yet include them. What should the project manager do next?",opts:["Return to the board with the updated work breakdown structure, for a second approval before work begins","Analyze the added cost, work packages and dependencies with the contractor before updating the baselines","Revise the baselines and project documents to include the change, and direct the team and contractor to do the work","Start the work now to match the contractor’s readiness, and update the baselines at the next phase review"],ans:[2],why:["Sai: quay lại CCB xin duyệt lần hai đúng nếu phạm vi thay đổi so với lần đã duyệt, nhưng ở đây thay đổi đã được duyệt. Việc còn lại là cập nhật baseline cho khớp và triển khai.","Sai: phân tích chi phí, work package và phụ thuộc cùng nhà thầu là đúng nếu chưa có số liệu, nhưng báo giá của nhà thầu đã liệt kê đầy đủ. Việc còn lại là cập nhật baseline và giao việc.","Đúng: sau khi CCB duyệt, PM cập nhật baseline và tài liệu (WBS, lịch, chi phí, phụ thuộc) rồi chỉ đạo thực hiện. Như vậy công việc thay đổi nằm trong kế hoạch được kiểm soát.","Sai: nhà thầu sẵn sàng và CCB đã duyệt, nhưng bắt đầu trước khi cập nhật baseline làm chi phí và tiến độ thực tế không còn so được với baseline. Phải cập nhật baseline trước khi giao việc."],exp:"B3 kiểm tra enabler implement approved changes to the project và update project documentation. Sau khi duyệt: cập nhật baseline, tài liệu, rồi thực hiện và thông báo. Quy tắc nhớ: duyệt, cập nhật kế hoạch, làm việc, truyền thông, không làm trước baseline."},{id:"o450",n:450,t:0,origin:"original",eco:"B3",domain:"business",approach:"agile",tags:["agile","eco-2026","change-control","product-owner"],type:"mc",q:"Midway through a sprint, a business director messages a developer directly and asks for an extra report to be added “quickly.” The director is a stakeholder, not the product owner, and the product owner is available today. The developer tells the project manager. The sprint goal is at risk if scope grows, and the team’s working agreement says that backlog changes go through the product owner. What should the project manager do?",opts:["Have the developer build the report as a small task between stories, and tell the product owner at the next sprint review","Agree with the developer to add the report to the sprint and move the lowest-value story out of it","Get the team to analyze the effect of the report on the sprint goal and present the result to the director for a decision","Ask the director to take the request to the product owner, who ranks it in the backlog against the sprint goal"],ans:[3],why:["Sai: đúng nếu product owner đã duyệt việc thêm báo cáo, nhưng ở đây yêu cầu đi thẳng từ director đến developer, không qua product owner; làm xen kẽ vẫn bỏ qua working agreement và làm rủi ro sprint goal.","Sai: đúng nếu product owner đã đồng ý đổi sprint backlog, nhưng đổi nội dung sprint là việc đội cùng product owner quyết; PM và developer tự thêm báo cáo rồi bỏ story thấp nhất là vượt quyền.","Sai: đúng nếu director là người ra quyết định về backlog, nhưng director là stakeholder, không phải product owner, nên không có quyền quyết; phân tích tác động rồi để director chốt đi sai kênh.","Đúng: working agreement ghi mọi thay đổi backlog đi qua product owner và hôm nay product owner có mặt; director đưa yêu cầu đến product owner để xếp thứ tự so với sprint goal."],exp:"B3 kiểm tra execute the change control process trong agile. Kênh chuẩn là product owner với backlog, theo working agreement của đội. Quy tắc nhớ: yêu cầu mới thành backlog item do product owner ưu tiên; không chen vào sprint đang chạy khi chưa qua người đó."},{id:"o451",n:451,t:0,origin:"original",eco:"B3",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","change-control","communication"],type:"mc",q:"Four change requests have been waiting on a hybrid project’s change control board for three weeks. The agile team and a supplier are both holding work that depends on the outcome and are asking about the status. The impact analyses for two of the requests are not finished. The board chair says the next meeting is in ten days. The change management plan lets the chair call an extra session on request, and the two open impact analyses can be finished within three days. What should the project manager do?",opts:["Request an extra board session from the chair this week, and have the two open impact analyses finished before it","Let the agile team and the supplier start the low-risk changes now, on the expectation that the board will approve them","Ask the sponsor to approve the four requests in place of the board and restart the dependent work","Publish a status update with the expected decision date for each of the four requests and confirm the dates with the chair"],ans:[0],why:["Đúng: change management plan cho phép chủ tịch gọi phiên họp thêm và hai phân tích tác động làm xong trong ba ngày. Họp sớm với phân tích đầy đủ mở lại công việc đang bị giữ, thay vì chờ mười ngày.","Sai: bắt đầu thay đổi rủi ro thấp khi CCB chưa duyệt là làm trước khi có thẩm quyền, kể cả khi dự đoán đúng. Hai phân tích tác động còn dở nên mức rủi ro thực chưa được xác nhận.","Sai: sponsor có quyền cao nhưng quyết định thay đổi baseline thuộc CCB theo kế hoạch quản lý thay đổi. Sponsor duyệt thay CCB bỏ qua quy trình và để lại tiền lệ xấu.","Sai: công khai trạng thái và ngày dự kiến là truyền thông tốt và đúng nếu không còn cách nào nhanh hơn, nhưng ở đây chủ tịch có thể gọi họp thêm. Chỉ cập nhật trạng thái vẫn để công việc bị giữ mười ngày."],exp:"B3 kiểm tra enabler communicate the status of proposed changes và execute the change control process. Khi nhiều thay đổi chờ lâu và công việc phụ thuộc bị giữ, PM dùng cơ chế sẵn có trong change management plan để CCB họp sớm với phân tích tác động đầy đủ. Công khai trạng thái vẫn cần, nhưng chưa đủ. Quy tắc nhớ: đi đúng kênh nhưng rút ngắn thời gian bằng cơ chế được phép."},{id:"o452",n:452,t:0,origin:"original",eco:"B3",domain:"business",approach:"predictive",tags:["predictive","eco-2026","change-control","impact-analysis"],type:"mc",q:"A senior stakeholder asks the project manager of a software implementation to add single sign-on with a second identity provider. The scope, schedule and cost baselines were approved eight weeks ago. The change management plan requires every change request to carry its impact analysis, and the board returns incomplete requests. What should the project manager do first?",opts:["Log the request in the change log and take it to the board marked “impact to be determined” for early review","Analyze the effect on scope, schedule, cost, risk and quality with the team, then take a request with that analysis to the board","Send the request to the sponsor for endorsement of the second identity provider before any analysis of its effects begins","Request a quotation from the identity-provider vendor, and take it to the board as the cost impact of this change request"],ans:[1],why:["Sai: đúng nếu hội đồng chấp nhận request chưa đủ phân tích, nhưng change management plan yêu cầu mỗi request kèm impact analysis và hội đồng trả lại hồ sơ thiếu; ghi “impact to be determined” sẽ bị trả lại.","Đúng: baseline đã duyệt nên mọi thay đổi phải qua change control, và board trả lại request thiếu phân tích; PM trước hết phân tích tác động lên phạm vi, tiến độ, chi phí, rủi ro, chất lượng rồi mới trình.","Sai: đúng nếu sponsor là người phê duyệt thay đổi, nhưng sponsor đồng ý khi chưa biết tác động thì duyệt trước khi có thông tin; board vẫn yêu cầu impact analysis đầy đủ.","Sai: đúng nếu chi phí là tác động duy nhất, nhưng báo giá của vendor chỉ là một phần chi phí; thay đổi còn tác động phạm vi, tiến độ, rủi ro, chất lượng nên request vẫn thiếu phân tích."],exp:"B3 kiểm tra enabler execute the change control process trong dự án predictive. Thứ tự đúng: ghi nhận yêu cầu, phân tích tác động, trình CCB, rồi thực hiện nếu được duyệt. Quy tắc nhớ: phân tích trước khi trình; không phê duyệt ngoài quy trình."},{id:"o453",n:453,t:0,origin:"original",eco:"B3",domain:"business",approach:"agile",tags:["agile","eco-2026","documentation","roadmap","communication"],type:"mc",q:"After a sprint review, the product owner reprioritized the backlog and moved two large epics out of the next release. Stakeholders still hold the roadmap and release date published a month ago, and several of them are planning launch activities around that date. What should the project manager do?",opts:["Update the roadmap and release forecast to match the product owner’s new priorities, then tell the stakeholders planning launches","Share the link to the reprioritized backlog with the stakeholders, and let them work out the effect on the release date","Ask the product owner to confirm the new release scope at the next sprint planning, then update the roadmap","Have the scrum master record the reprioritization and its reasons in the retrospective notes, for the team to learn from"],ans:[0],why:["Đúng: product owner đã chuyển hai epic lớn ra khỏi bản phát hành sau sprint review và các stakeholder đang lên kế hoạch ra mắt theo ngày cũ; PM cập nhật roadmap, release forecast rồi báo ngay cho họ.","Sai: đúng nếu stakeholder có kỹ năng đọc backlog và dự báo release, nhưng ở đây họ đang giữ roadmap cũ và tự suy ra ngày mới là chuyển việc cập nhật tài liệu sang người không nắm velocity của đội.","Sai: đúng nếu product owner chưa chốt phạm vi, nhưng product owner đã sắp xếp lại backlog sau sprint review; chờ đến sprint planning tiếp theo làm stakeholder tiếp tục lên kế hoạch ra mắt theo ngày cũ.","Sai: đúng nếu mục tiêu chỉ là học hỏi của đội, nhưng ở đây vấn đề là người ngoài đội đang giữ thông tin cũ; ghi vào retrospective notes không cập nhật roadmap hay báo cho người bị ảnh hưởng."],exp:"B3 kiểm tra enabler update project documentation to reflect changes, trong bối cảnh agile (roadmap, release forecast). Quy tắc nhớ: sau khi ưu tiên thay đổi thì cập nhật tài liệu cùng product owner và thông báo ngay cho người bị ảnh hưởng."},{id:"o454",n:454,t:0,origin:"original",eco:"B3",domain:"business",approach:"predictive",tags:["predictive","eco-2026","change-control","procurement","contract"],type:"mc",q:"The change control board approved a scope increase that adds 300 access-control readers to a fixed-price contract with a security integrator. The integrator’s site manager says the crew can start next week and offers to “sort out the paperwork later.” What should the project manager do?",opts:["Ask procurement to process a contract amendment under the change procedure, and release the integrator’s start only after it is signed","Authorize the integrator to start with a signed work instruction, and have procurement negotiate the amendment price while the crew works","Update the project baselines and issue a work instruction, as the board’s approval is enough authority to proceed","Get the integrator’s site manager to confirm in writing that the extra readers fall inside the fixed price, and start the crew once it does"],ans:[0],why:["Đúng: board chỉ duyệt phạm vi, còn hợp đồng giá cố định phải được sửa bằng amendment qua thủ tục thay đổi; PM nhờ procurement xử lý và chỉ cho nhà thầu bắt đầu sau khi ký.","Sai: đúng nếu hợp đồng cho phép work instruction trước khi thống nhất giá, nhưng ở đây hợp đồng giá cố định; cho bắt đầu khi giá chưa chốt làm mất đòn bẩy thương lượng và phát sinh cam kết ngoài hợp đồng.","Sai: đúng nếu quyền duyệt của board đã bao gồm hợp đồng, nhưng board duyệt phạm vi chứ không sửa hợp đồng; cập nhật baseline và ra lệnh làm việc mà chưa có amendment là hành động ngoài thủ tục.","Sai: đúng nếu 300 đầu đọc đã nằm trong hợp đồng, nhưng đây là phạm vi tăng thêm vào hợp đồng giá cố định nên không thể nằm trong giá hiện có; xác nhận bằng văn bản không thay được amendment."],exp:"B3 kiểm tra enabler implement approved changes to the project khi thay đổi chạm hợp đồng. Thay đổi đã duyệt vẫn phải đi qua thủ tục hợp đồng. Quy tắc nhớ: CCB duyệt phạm vi, procurement sửa hợp đồng, rồi mới triển khai."},{id:"o455",n:455,t:0,origin:"original",eco:"B3",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","ai","change-control","impact-analysis"],type:"mc",q:"On a hybrid logistics platform project, a business analyst used a generative AI tool to draft the impact analysis for a change request. It states that the change adds only two days of effort. The lead architect believes the change affects three interfaces and will take much longer. The change control board meets tomorrow. What should the project manager do?",opts:["Ask the analyst to rerun the AI analysis with more detailed prompts, and submit the result if it looks more realistic","Discard the AI draft and have the lead architect write the analysis by hand for tomorrow’s board meeting","Submit the AI analysis with the architect’s concerns attached, so that the board weighs both figures at the meeting","Check the draft with the lead architect against the team’s own estimates and data, then correct it before the board sees it"],ans:[3],why:["Sai: đúng nếu công cụ AI là nguồn đáng tin sau khi chỉnh prompt, nhưng chạy lại chỉ là thử vận may; kết quả trông thực tế hơn vẫn chưa được kiểm chứng bằng dữ liệu của đội.","Sai: đúng nếu bản AI không có giá trị nào, nhưng bỏ hẳn là lãng phí và một mình kiến trúc sư viết tay trong một ngày cũng chưa được kiểm tra đối chiếu với ước lượng của đội.","Sai: đúng nếu hội đồng cần thấy mọi quan điểm trước khi chọn, nhưng ở đây impact analysis phải là bản đáng tin; nộp hai con số mâu thuẫn bắt board tự phân xử khi PM chưa kiểm chứng.","Đúng: con người chịu trách nhiệm cuối cùng cho đầu ra AI; PM cùng kiến trúc sư đối chiếu bản nháp với ước lượng và dữ liệu của đội rồi sửa trước khi board họp ngày mai."],exp:"B3 kiểm tra enabler execute the change control process; AI chỉ là bối cảnh. Impact analysis trình CCB phải đáng tin, và con người chịu trách nhiệm cuối cùng cho đầu ra AI. Quy tắc nhớ: dùng AI để nhanh hơn, nhưng kiểm chứng trước khi dùng làm căn cứ quyết định."},{id:"o456",n:456,t:0,origin:"original",eco:"B3",domain:"business",approach:"predictive",tags:["predictive","eco-2026","change-control","emergency-change","escalation"],type:"mc",q:"A manufacturing execution system is in production when testers find a defect that can cause a safety interlock to fail; the safety engineer has rated it critical. The change control board meets only on the first Monday of each month, which is 18 days away. The change management plan includes an urgent-change procedure under which the board chair, as authorized delegate, can approve a fix within 24 hours. What should the project manager do?",opts:["Escalate the defect under the urgent-change procedure to the board chair for an immediate decision on the fix","Apply operational restrictions on the line as a precaution and bring the fix to the monthly board meeting for approval","Have the team implement the fix under the project manager’s authority and ask the board to ratify it at its next meeting","Review the defect with the testers to confirm its severity, then decide whether the urgent procedure is justified"],ans:[0],why:["Đúng: plan có thủ tục khẩn cấp và board chair được ủy quyền duyệt trong 24 giờ. PM leo thang lên đúng người có quyền để quyết nhanh mà vẫn được kiểm soát, phù hợp lỗi an toàn đã được đánh giá nghiêm trọng.","Sai: hạn chế vận hành là biện pháp tạm thời tốt, nhưng mười tám ngày với lỗi có thể làm hỏng khóa an toàn là quá dài. Plan đã có thủ tục khẩn cấp để quyết trong 24 giờ.","Sai: triển khai bản vá rồi xin CCB hợp thức hóa đảo ngược thứ tự phê duyệt; PM không có thẩm quyền tự duyệt. Thủ tục khẩn cấp cho phép quyết nhanh nhưng vẫn do người có quyền quyết.","Sai: đúng nếu mức độ lỗi chưa rõ, nhưng safety engineer đã đánh giá lỗi là nghiêm trọng và plan có sẵn thủ tục khẩn cấp. Không cần thêm bước xác nhận trước khi dùng thủ tục."],exp:"B3 kiểm tra enabler execute the change control process cho trường hợp khẩn cấp. Quy trình khẩn cấp là một phần của change management plan; PM leo thang lên người được ủy quyền thay vì bỏ qua hay chờ họp định kỳ. Quy tắc nhớ: nhanh nhưng vẫn qua đúng người có quyền."},{id:"o457",n:457,t:0,origin:"original",eco:"B3",domain:"business",approach:"agile",tags:["agile","eco-2026","change-control","product-owner-sync"],type:"mc",q:"Three scrum teams in one program share an order API. Team A’s product owner wants to change the API’s response format to support a new feature. Teams B and C have stories planned that use the current format. The program has no change control board for the backlog; teams coordinate through a weekly product owner sync. What should the project manager do?",opts:["Have the architect analyze the effect of the new format on teams B and C, and publish a recommendation for team A’s product owner to follow","Ask team A’s product owner to take the change to the weekly product owner sync, where the affected teams assess it","Get the PMO to set up a program change control board to approve each API change before teams alter backlogs or sprint plans","Ask team A’s product owner to schedule the change in its own backlog, and tell teams B and C at the next sync"],ans:[1],why:["Sai: đúng nếu việc đổi định dạng chỉ là vấn đề kỹ thuật thuần túy, nhưng ở đây tác động đến backlog và kế hoạch của đội B, C nên cần chính các product owner bị ảnh hưởng cùng bàn; kiến trúc sư không quyết thay họ.","Đúng: chương trình phối hợp qua buổi product owner sync hằng tuần và không có change control board cho backlog; product owner đội A đưa thay đổi ra đó để các đội bị ảnh hưởng đánh giá trước khi làm.","Sai: đúng nếu chương trình đã dùng change control board cho backlog, nhưng ở đây cơ chế đang dùng là product owner sync; lập hội đồng mới tạo lớp thủ tục không cần thiết cho thay đổi giữa các đội agile.","Sai: đúng nếu đội B và C không dùng định dạng hiện tại, nhưng họ có story đang dùng nó; sắp xếp trong backlog riêng rồi chỉ báo sau tại sync lần tới để hai đội phát hiện thay đổi khi đã quá muộn."],exp:"B3 kiểm tra enabler execute the change control process trong agile ở quy mô nhiều đội. Kênh đúng là cơ chế phối hợp giữa các product owner, không phải CCB cho backlog. Quy tắc nhớ: thay đổi ảnh hưởng chéo đội thì cùng các bên bị ảnh hưởng bàn trước khi làm."},{id:"o458",n:458,t:0,origin:"original",eco:"B4",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","issue-management","risk-to-issue"],type:"mc",q:"A hybrid project’s risk register includes “key supplier delivers the control units late,” with a planned response of using an alternate supplier at higher cost, which the sponsor approved when the risk was registered. This morning the supplier confirmed in writing that delivery will be three weeks late. The agile team’s integration sprints are scheduled around the original date. What should the project manager do?",opts:["Set the risk probability to its maximum in the register, and keep the integration sprints on their original dates","Assess with the agile team how the late units change the sprint plan, and choose a response after that","Move it from the risk register to the issue log and trigger the planned response using the alternate supplier","Report the late delivery to the sponsor, and trigger the alternate-supplier response once she confirms it"],ans:[2],why:["Sai: nâng xác suất lên mức cao nhất vẫn coi sự kiện là khả năng, trong khi nhà cung cấp đã xác nhận bằng văn bản sẽ giao trễ ba tuần. Đó đã là issue, và các sprint tích hợp theo ngày cũ không còn khả thi.","Sai: đánh giá ảnh hưởng đến kế hoạch sprint cùng đội agile là cần, nhưng response đã được lập kế hoạch và sự kiện đã xảy ra. Chọn lại response sau khi đánh giá làm chậm việc kích hoạt phương án đã có.","Đúng: nhà cung cấp đã xác nhận bằng văn bản nên rủi ro đã xảy ra và trở thành issue. PM ghi vào issue log và kích hoạt phương án đã lên kế hoạch (nhà cung cấp thay thế), rồi điều chỉnh các sprint tích hợp theo ngày giao mới.","Sai: báo cho sponsor là đúng, nhưng sponsor đã duyệt response nhà cung cấp thay thế khi đăng ký rủi ro. Chờ xác nhận lần nữa trước khi kích hoạt chỉ làm mất thời gian."],exp:"B4 kiểm tra enabler recognize when a risk becomes an issue. Dấu hiệu: sự kiện đã xảy ra hoặc chắc chắn xảy ra. Khi đó PM chuyển sang issue log, dùng response đã lên kế hoạch và hợp tác với các bên. Quy tắc nhớ: risk còn là khả năng, issue là sự thật."},{id:"o459",n:459,t:0,origin:"original",eco:"B4",domain:"business",approach:"predictive",tags:["predictive","eco-2026","issue-management","collaboration","shared-resources"],type:"mc",q:"A project’s validation tests need a climate chamber shared with another project in the same company. Both projects booked the same four weeks. The other project manager says her booking was made first. The chamber manager is neutral. Slipping the tests would delay this project’s phase gate. The chamber calendar shows free days inside the four weeks, and an external chamber would cost more than the contingency reserve holds. What should the project manager do?",opts:["Meet the other project manager and the chamber manager to look for a schedule that suits both projects","Ask the PMO director to rule on which project has priority for the chamber, and plan the tests around that ruling","Rent an external chamber for the four weeks and charge the cost to the project’s contingency reserve","Have the chamber manager check the booking log, and give the chamber to whichever project booked first"],ans:[0],why:["Đúng: lịch buồng còn ngày trống trong bốn tuần và chamber manager trung lập, nên hai PM cùng nhau tìm lịch phù hợp cả hai dự án; thương lượng trực tiếp trước, chưa cần leo thang hay tiêu tiền.","Sai: đúng nếu hai PM đã thương lượng mà không ra, nhưng ở đây chưa ai trao đổi trực tiếp và lịch còn ngày trống; nhờ PMO director phán quyết bỏ qua bước hợp tác giữa các bên liên quan.","Sai: đúng nếu không còn cách xếp lịch nội bộ, nhưng buồng ngoài tốn nhiều hơn contingency reserve và lịch còn ngày trống; thuê ngoài là chọn phương án đắt nhất khi chưa thử thương lượng.","Sai: đúng nếu chỉ có một bên được dùng buồng, nhưng ở đây lịch còn ngày trống nên hai dự án có thể cùng dùng; chỉ xác định ai đặt trước sẽ bỏ dự án kia khỏi cuộc chơi và trễ phase gate."],exp:"B4 kiểm tra enabler collaborate with relevant stakeholders on an approach to resolve the issues. Với tài nguyên dùng chung, PM trước hết hợp tác với các bên liên quan, rồi mới xét leo thang hoặc chi tiền. Quy tắc nhớ: thương lượng trực tiếp trước, leo thang sau."},{id:"o460",n:460,t:0,origin:"original",eco:"B4",domain:"business",approach:"agile",tags:["agile","eco-2026","impediments","reassess","retrospective"],type:"mc",q:"For three sprints in a row, the team’s impediment board has shown “waiting for UX design approval.” After the first sprint, the project manager asked the UX lead to speed up reviews, and the item was moved to “resolved.” Stories are still stalling in the same way. What should the project manager do?",opts:["Reopen the impediment and set up a different intervention with the UX lead, such as fixed review slots, then check the result next sprint","Obtain a written commitment from the UX lead to a review turnaround time, and keep the item closed once it is given","Get the scrum master to analyze for another sprint how long each story waits for UX approval, and report the average before any action","Record it as an external dependency on the program risk register and keep the affected stories in progress"],ans:[0],why:["Đúng: hành động đầu (nhờ UX lead nhanh hơn) không cho kết quả vì các story vẫn kẹt, nên impediment phải mở lại; PM cùng UX lead và product owner chọn can thiệp khác rồi kiểm tra kết quả ở sprint sau.","Sai: đúng nếu trở ngại biến mất khi có cam kết, nhưng ở đây yêu cầu tăng tốc đã được thử và các story vẫn kẹt; một cam kết viết thêm lặp lại cách đã thất bại và vẫn đóng item theo hành động.","Sai: đúng nếu chưa có dữ liệu về trở ngại, nhưng ở đây impediment đã nằm trên bảng ba sprint liên tiếp; đo thêm một sprint chỉ kéo dài tình trạng, mà vẫn chưa có hành động nào xử lý.","Sai: đúng nếu việc duyệt UX nằm hẳn ngoài tầm kiểm soát của đội, nhưng ở đây UX lead làm việc cùng chương trình và có thể thương lượng; ghi sổ rủi ro chương trình chỉ ghi nhận mà không giải quyết."],exp:"B4 kiểm tra enabler reassess continually to help ensure impediments are being addressed. Trở ngại chỉ được coi là xong khi tác động biến mất, không phải khi đã gửi yêu cầu; khi cách đầu thất bại thì mở lại và chọn can thiệp khác cùng các bên. Quy tắc nhớ: đóng impediment dựa trên kết quả, không dựa trên hành động."},{id:"o461",n:461,t:0,origin:"original",eco:"B4",domain:"business",approach:"predictive",tags:["predictive","eco-2026","issue-management","impact-analysis","confirm-first"],type:"mc",q:"A bridge project’s supplier has just phoned the project manager to say the bearing assemblies will probably arrive about five weeks late, though when pressed the caller added it could be anywhere from three to eight weeks. Nothing is in writing, the contract requires delay notices in writing with cause and revised date before any schedule change, and the supplier gave no cause and no revised date. The assemblies are needed for the deck installation, and the schedule shows float on some tasks but not on others. What should the project manager do first?",opts:["Tell stakeholders about the five-week slip, and ask the sponsor to approve a revised end date for the whole project","Analyze with the scheduler how a five-week delay would affect the critical path, the cost and the dependent work","Crash the deck installation tasks with the site manager to recover five weeks and keep the finish date intact","Ask the supplier to confirm in writing the cause, the new delivery date and how firm that date is"],ans:[3],why:["Sai: đúng nếu ngày giao mới đã được nhà cung cấp xác nhận, nhưng ở đây chỉ có cuộc gọi nói miệng với khoảng từ 3 đến 8 tuần; báo stakeholder và xin sponsor duyệt ngày mới dựa trên thông tin chưa kiểm chứng.","Sai: đúng nếu nhà cung cấp đã đưa ngày giao chắc chắn, nhưng ở đây con số năm tuần chỉ là ước chừng trong khoảng ba đến tám tuần; phân tích tác động trên một con số chưa chắc là làm việc trên dữ kiện chưa xác nhận.","Sai: đúng nếu độ trễ đã chắc và không thể hoãn, nhưng ở đây độ trễ và nguyên nhân chưa được xác nhận; rút ngắn các task lắp đặt tốn chi phí cho một độ trễ có thể không xảy ra.","Đúng: thông tin chỉ nói miệng, khoảng dao động rộng, không có nguyên nhân hay ngày mới; PM xác nhận dữ kiện bằng văn bản (ngày giao, nguyên nhân, độ chắc chắn) trước, rồi mới đánh giá tác động và chọn phản ứng."],exp:"B4 kiểm tra enabler evaluate the impact of impediments. Khi thông tin về trở ngại còn miệng, rộng và chưa đầy đủ, PM xác nhận dữ kiện (ngày giao, nguyên nhân, độ chắc chắn) trước, rồi đánh giá tác động lên đường găng, chi phí, công việc phụ thuộc. Quy tắc nhớ: xác nhận dữ kiện, phân tích, rồi mới chọn phản ứng."},{id:"o462",n:462,t:0,origin:"original",eco:"B4",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","ai","impediments","adoption"],type:"mc",q:"A company mandated an AI-based estimation assistant for all project teams. On a hybrid project, the scrum team members have started to bypass it and estimate by hand, saying its story-point suggestions ignore their context. The scheduler for the predictive work package still uses it. Estimates are now inconsistent across the project. The PMO has confirmed that the tool owner can adjust settings for individual teams. What should the project manager do?",opts:["Raise the inconsistency with the PMO and ask it to repeat the mandate in a memo to the project teams","Ask the scrum team why the suggestions do not fit, and work out with the tool owner how the tool should be used on this project","Agree with the scrum master that the scrum team estimates by hand, and keep the tool for the scheduler’s predictive work package","Ask the tool owner to retrain the model with the PMO on past company projects, then release the new version to the teams"],ans:[1],why:["Sai: đúng nếu đội bỏ công cụ mà không có lý do, nhưng ở đây đội nêu lý do (gợi ý bỏ qua bối cảnh) và PMO xác nhận chủ công cụ chỉnh được theo từng đội; nhắc lại mandate là ép tuân thủ khi chưa hiểu.","Đúng: đội bỏ công cụ vì gợi ý không hợp bối cảnh nên đó là tín hiệu; PM hỏi lý do rồi cùng chủ công cụ điều chỉnh cách dùng theo từng đội, vì chủ công cụ có thể chỉnh thiết lập cho từng team.","Sai: đúng nếu việc ước lượng bằng tay không làm ảnh hưởng đến dự án, nhưng ở đây đã gây ước lượng không nhất quán và vẫn trái mandate của công ty; chia đôi cách làm không giải quyết nguyên nhân.","Sai: đúng nếu nguyên nhân đã biết là mô hình thiếu dữ liệu, nhưng ở đây chưa ai hỏi đội vì sao gợi ý không phù hợp; huấn luyện lại mô hình là giải pháp kỹ thuật khi chưa hiểu vấn đề."],exp:"B4 kiểm tra enabler determine and apply an intervention strategy to remove impediments, với AI là bối cảnh. Sự kháng cự công cụ là tín hiệu; PM tìm hiểu nguyên nhân và hợp tác điều chỉnh. Quy tắc nhớ: hiểu nguyên nhân trước khi ép tuân thủ hay bỏ công cụ."},{id:"o463",n:463,t:0,origin:"original",eco:"B4",domain:"business",approach:"predictive",tags:["predictive","eco-2026","issue-management","resources","negotiation"],type:"mc",q:"The project manager of a data warehouse migration needs a database administrator for six weeks, as planned. The administrator’s functional manager now says the person is needed for an operations outage, and no replacement is available. The project manager has the resource plan and a schedule showing the impact. What should the project manager do?",opts:["Hire an external consultant funded from the management reserve, and tell the functional manager after signing","Have the sponsor direct the functional manager to release the administrator for the six weeks as planned in the resource plan","Go through the impact data with the functional manager and negotiate a new timing or another resource for the work","Get the scheduler to model the migration without the administrator, then submit a schedule change request for a new end date"],ans:[2],why:["Sai: đúng nếu đã thương lượng mà không có người thay và management reserve cho phép, nhưng ở đây chưa nói chuyện với trưởng bộ phận; thuê ngoài rồi mới báo là hành động đơn phương dùng tiền dự phòng.","Sai: đúng nếu thương lượng với trưởng bộ phận thất bại, nhưng ở đây chưa thử; nhờ sponsor ra lệnh cho trưởng bộ phận bỏ qua dữ liệu tác động và làm tổn hại quan hệ với bộ phận vận hành.","Đúng: người quản lý chức năng kiểm soát nguồn lực và đang gặp sự cố vận hành; PM dùng dữ liệu tác động trong resource plan và lịch để thương lượng thời điểm hoặc nguồn lực khác trước khi leo thang.","Sai: đúng nếu không thể giữ quản trị viên và mọi thương lượng đã thất bại, nhưng ở đây chưa đàm phán; lập lại kế hoạch quanh sự vắng mặt và xin đổi ngày kết thúc là chấp nhận trễ trước khi thử giữ tiến độ."],exp:"B4 kiểm tra enabler determine and apply an intervention strategy to remove or minimize impediments. Với nguồn lực do bộ phận khác kiểm soát, PM dùng dữ liệu để thương lượng trước, leo thang sau. Quy tắc nhớ: thương lượng bằng dữ liệu, không ra lệnh qua sponsor ngay."},{id:"o464",n:464,t:0,origin:"original",eco:"B4",domain:"business",approach:"agile",tags:["agile","eco-2026","impediments","dependencies","facilitation"],type:"mc",q:"A scrum team depends on a data feed that the finance department must expose through an API. The finance team’s backlog has it at low priority, and the team has been blocked on two stories for a sprint. Both stories are needed for the release planned in six weeks. The scrum master has raised it at the standup, but no one on the team has authority over finance priorities. The finance lead owns the finance backlog and has not yet been approached about this dependency. What should the project manager do?",opts:["Meet the finance lead with the product owner and settle when the data feed will be delivered, while the team works on unblocked stories","Ask the product owner to analyze which release scope survives without the two stories, and plan the release on that scope","Have the team build its own copy of the data feed, and release against that copy instead of finance’s API","Escalate the dependency to the finance executive and request that finance be directed to reprioritize its backlog"],ans:[0],why:["Đúng: finance lead sở hữu backlog của finance và chưa được liên hệ về phụ thuộc này; PM đưa đội và finance lead lại cùng nhau chốt thời điểm, trong khi đội làm tiếp các story không bị chặn.","Sai: đúng nếu finance đã từ chối giao data feed, nhưng ở đây finance lead chưa được hỏi gì; cắt hai story khỏi bản phát hành và dựng lại phạm vi là đầu hàng trước khi thử thương lượng.","Sai: đúng nếu API của finance không thể dùng được, nhưng ở đây vấn đề chỉ là thứ tự ưu tiên của finance; làm bản sao riêng tạo trùng lặp, nợ kỹ thuật và rủi ro tích hợp lệch với hệ thống thật.","Sai: đúng nếu đã trao đổi với finance lead mà không có kết quả, nhưng ở đây finance lead chưa được tiếp cận; leo thang lên giám đốc finance bỏ qua bước hợp tác và làm xấu quan hệ giữa hai bộ phận."],exp:"B4 kiểm tra enabler collaborate with relevant stakeholders on an approach to resolve the issues, và intervention strategy. Trở ngại ngoài quyền của đội thì PM hoặc scrum master làm cầu nối; đội vẫn tiến hành phần không bị chặn. Quy tắc nhớ: hợp tác trước, leo thang sau."},{id:"o465",n:465,t:0,origin:"original",eco:"B4",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","issue-management","root-cause","integration"],type:"mc",q:"On a hybrid vehicle-charging project, the firmware team (sprints) and the hardware team (phase plan) report intermittent test failures at integration. Each team says the other side’s interface is at fault, and two weeks have passed without a fix. Both team leads are skilled and available. What should the project manager do?",opts:["Escalate the disagreement to the steering committee and ask for a ruling on which team must fix the interface","Get the firmware lead to adapt the software to the hardware interface, which the change control board has not reopened","Go through the integration test data with both leads to find the root cause, and name an owner for the fix","Ask both leads to present their interface specifications, and agree a change request to the baseline interface"],ans:[2],why:["Sai: đúng nếu hai trưởng nhóm không thể làm việc cùng nhau, nhưng ở đây cả hai đều giỏi và sẵn sàng; chuyển lên steering committee xin phán quyết khi chưa biết nguyên nhân là tìm người thắng, không tìm lỗi.","Sai: đúng nếu đã biết lỗi nằm ở phía firmware, nhưng ở đây nguyên nhân chưa được tìm ra; việc phần cứng đã baseline không chứng minh lỗi nằm ở phần mềm, và ép một bên sửa là chọn bên trước khi có dữ liệu.","Đúng: hai nhóm đổ lỗi cho nhau hai tuần mà chưa có nguyên nhân; PM cùng hai trưởng nhóm xem dữ liệu kiểm thử tích hợp để tìm root cause và giao owner cho việc sửa, thay vì tìm bên có lỗi.","Sai: đúng nếu đã biết thông số giao diện là nguyên nhân, nhưng ở đây chưa xác định nguyên nhân gốc; đồng ý một change request vào giao diện baseline là đổi thiết kế trước khi biết thiết kế có sai."],exp:"B4 kiểm tra enabler collaborate with relevant stakeholders on an approach to resolve the issues. Với lỗi tích hợp ở giao diện hai nhóm, PM tạo điều kiện phân tích chung dựa trên dữ liệu và gán owner. Quy tắc nhớ: tìm nguyên nhân gốc cùng nhau, không tìm người có lỗi."},{id:"o466",n:466,t:0,origin:"original",eco:"B4",domain:"business",approach:"predictive",tags:["predictive","eco-2026","issue-management","escalation","thresholds"],type:"mc",q:"Steel prices have pushed a plant-construction project’s cost variance to 9 percent. The governance plan says the project manager must escalate any variance above 7 percent to the steering committee. For two weeks the project manager has negotiated with the supplier, with no result. What should the project manager do?",opts:["Analyze the steel price trend with the cost engineer to forecast whether the variance will fall under 7 percent","Extend the negotiation with the supplier by two weeks with the procurement lead, and escalate only if the variance is still above 7 percent","Escalate to the steering committee as the governance plan requires, and attach an analysis of the options and their costs","Ask the sponsor to approve drawing on the contingency reserve to cover the gap, and report it to the steering committee at the next monthly meeting"],ans:[2],why:["Sai: đúng nếu chênh lệch chưa vượt 7%, nhưng ở đây đã là 9% và vượt ngưỡng; dự báo xem nó có tự xuống không là né ngưỡng thay vì thực hiện quy tắc leo thang trong governance plan.","Sai: đúng nếu governance plan cho phép gia hạn đàm phán, nhưng plan yêu cầu leo thang khi vượt 7% và PM đã đàm phán hai tuần không kết quả; kéo dài thêm là hoãn nghĩa vụ báo cáo.","Đúng: chênh lệch chi phí 9% vượt ngưỡng 7% và đàm phán hai tuần không kết quả; PM leo thang lên steering committee theo governance plan, kèm phân tích phương án và chi phí để ủy ban quyết định.","Sai: đúng nếu quyết định dùng contingency reserve thuộc quyền sponsor và chênh lệch dưới ngưỡng, nhưng ở đây ngưỡng 7% đã bị vượt; chỉ báo ở cuộc họp tháng sau là né nghĩa vụ leo thang ngay theo plan."],exp:"B4 kiểm tra enabler collaborate with relevant stakeholders to resolve issues, gắn với B1 (escalation thresholds). Khi issue vượt ngưỡng và PM không giải quyết được trong thẩm quyền, leo thang theo plan kèm phân tích. Quy tắc nhớ: ngưỡng bị vượt thì leo thang, đừng né ngưỡng."}],r=[{id:"o223",n:223,t:0,origin:"original",eco:"B5",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","risk-management-plan","thresholds"],type:"mc",q:"A utilities company launches a hybrid programme: a smart-meter hardware rollout planned in phases against a fixed baseline, and a customer app built in two-week sprints. The project manager is drafting the risk management plan. The hardware team scores risks on a 1-5 scale, the app team uses high/medium/low, and the sponsor has not stated how much exposure the programme can tolerate. What should the project manager do first?",opts:["Set one scale for both workstreams from the risk thresholds the sponsor defines to make risks comparable","Let each workstream keep its own scale and merge the two registers at the end of each quarter","Map the 1-5 scale and the high/medium/low scale onto each other in a conversion table for the register","Facilitate a session with the app team and move its risk reviews onto the hardware team's phase calendar"],ans:[0],why:["Đúng: kế hoạch quản lý rủi ro cần ngưỡng chấp nhận rủi ro của sponsor và một thang điểm chung. Nếu thiếu hai thứ này, thang 1-5 và cao/trung/thấp của hai nhóm không so sánh được với nhau.","Sai: phân tích định lượng để tính contingency reserve là bước đúng sau khi đã có thang điểm và ngưỡng chung. Ở đây sponsor chưa nêu mức chịu rủi ro và hai nhóm chấm điểm khác nhau, nên số liệu đầu vào chưa so sánh được.","Sai: bảng quy đổi giữa thang 1-5 và cao/trung/thấp giúp đọc hai register cạnh nhau, nhưng không cho biết mức rủi ro nào sponsor chấp nhận. Chưa có ngưỡng của sponsor thì quy đổi chỉ che đi vấn đề chính của kế hoạch.","Sai: nhịp rà soát khác nhau giữa nhánh theo phase và nhánh theo sprint là vấn đề có thật, nhưng vấn đề chính trong stem là thang điểm và ngưỡng. Đồng bộ lịch không làm hai register so sánh được."],exp:"B5 (Develop a risk management plan): kế hoạch phải xác định ngưỡng rủi ro, thang xác suất/tác động và vai trò trước khi đi vào nhận diện và phân tích. Quy tắc nhớ: chuẩn hóa ngôn ngữ rủi ro, tailor nhịp rà soát. Bẫy là chọn phân tích định lượng quá sớm."},{id:"o224",n:224,t:0,origin:"original",eco:"B6",domain:"business",approach:"agile",tags:["agile","eco-2026","retrospective","improvement-follow-through"],type:"mc",q:"At the end of each sprint, a Scrum team lists the same improvement ideas in its retrospective, such as clearer acceptance criteria and shorter code reviews. Three sprints later none has been tried, and the team is losing faith in the retrospective. The product owner says the backlog is too full for improvement work, but agrees that one or two small items could fit if the team picks them. What should the project manager do?",opts:["Escalate the capacity conflict to the sponsor and ask for a decision on how much sprint time goes to improvement work","Put one or two of the improvements into the next sprint backlog as items that have named owners and a review date in the retrospective","Create an improvement list on the team board and let developers pull items from it whenever they have spare time","Run a root-cause session with the team on why the same ideas keep returning, and agree one improvement to try"],ans:[1],why:["Sai: đúng nếu product owner và đội bế tắc về năng lực, nhưng ở đây product owner đã đồng ý rằng một hai mục nhỏ có thể vừa. Sponsor chỉ cần vào khi xung đột vượt quyền product owner, nên leo thang lúc này là sai diễn đàn và chậm thêm.","Đúng: cải tiến chỉ xảy ra khi có owner và chỗ trong sprint backlog. Product owner đã đồng ý cho một hai mục nhỏ, nên chọn ít việc, đặt owner và ngày xem lại giúp đội thấy retrospective có tác dụng.","Sai: đúng nếu đội thường xuyên có thời gian rảnh, nhưng backlog đang đầy nên danh sách «khi rảnh» sẽ không bao giờ được làm. Việc cải tiến cần owner và nằm trong kế hoạch sprint.","Sai: phân tích nguyên nhân là bước đúng khi ý tưởng còn mơ hồ, nhưng ý tưởng ở đây đã cụ thể (acceptance criteria rõ hơn, code review ngắn hơn) và lý do chưa làm đã nêu: backlog đầy. Cần đưa việc vào backlog."],exp:"B6 (Help ensure continuous improvement processes are updated, Utilize lessons learned): retrospective chỉ có giá trị khi hành động cải tiến được thực hiện. Quy tắc nhớ: ít hành động, có owner, nằm trong backlog, có kiểm tra ở lần sau."},{id:"o225",n:225,t:0,origin:"original",eco:"B7",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","organizational-change","merger","impact-assessment","escalation"],type:"mc",q:"A hybrid project to modernise a loan platform, with a phase-gated core build and sprint-based features, draws staff from the credit and retail divisions. The CEO announces that the two divisions will merge in four months, with new reporting lines still undecided. Since then the project's two sponsors have given the team conflicting priorities for the next release, and neither has authority over the other. The project has an executive steering group chaired by the chief operating officer. What should the project manager do first?",opts:["Model the likely post-merger structure with the team and start building the sprint backlog for that structure now","Ask HR to brief the team on what the merger means for roles and leave organisational matters to management","Raise a change request to re-baseline the project under a single sponsor ahead of the merger date in four months","Escalate the sponsors' conflicting priorities to the steering group, along with the merger's effect on scope and resources"],ans:[3],why:["Sai: đúng nếu cấu trúc sau sáp nhập đã được công bố, nhưng reporting line còn chưa quyết định và hai sponsor đang chỉ đạo mâu thuẫn. Backlog làm trên giả định như vậy có nguy cơ phải bỏ đi.","Sai: HR có thể hỗ trợ thông tin nhân sự, đúng nếu vấn đề chỉ là lo lắng về công việc, nhưng ở đây hai sponsor chỉ đạo mâu thuẫn ảnh hưởng đến dự án. Né tránh vấn đề tổ chức sẽ để dự án thiếu chuẩn bị.","Sai: re-baseline dưới một sponsor đúng nếu cấu trúc mới đã chốt, nhưng CEO nói rõ reporting line chưa quyết định và PM không có quyền chọn sponsor. Chưa có dữ liệu để đặt baseline mới.","Đúng: hai sponsor mâu thuẫn và không bên nào có quyền trên bên kia, nên vượt quyền PM. PM leo thang lên steering group do COO chủ trì, kèm đánh giá ảnh hưởng của sáp nhập lên phạm vi, nguồn lực và stakeholder để họ quyết định chủ sở hữu và ưu tiên."],exp:"B7 (Evaluate the impact of organizational change on the project and determine required actions): khi thay đổi tổ chức tạo xung đột chỉ đạo vượt quyền PM, PM đánh giá tác động bằng thông tin hiện có rồi leo thang lên cấp có thẩm quyền để quyết định. Quy tắc nhớ: sponsor mâu thuẫn thì đưa lên cấp trên chung, kèm phân tích; không đoán, không tự chọn bên."},{id:"o226",n:226,t:0,origin:"original",eco:"B8",domain:"business",approach:"agile",tags:["agile","eco-2026","market-change","backlog-prioritization"],type:"mc",q:"An agile team is building a fitness-tracking app. A competitor releases a feature that lets users share workouts in groups, and social media posts suggest it is gaining attention. Sprint 5 of 10 is under way, backlog refinement is on Thursday, and the product owner has not yet commented on the news. What should the project manager do?",opts:["Update the product vision with the stakeholders to include social features before the next sprint starts","Add a group-sharing story to the current sprint backlog and swap it with a lower-priority story","Ask the product owner to assess the competitor's new feature against the current backlog priorities","Commission a market study from an outside agency and bring the results to the product owner before refinement"],ans:[2],why:["Sai: cập nhật vision cùng stakeholders đúng khi đã có bằng chứng thị trường, nhưng ở đây mới chỉ có bài đăng mạng xã hội và product owner chưa nhận xét. Đánh giá tác động lên backlog phải đi trước khi đổi vision.","Sai: đúng nếu product owner đã quyết định ưu tiên tính năng này, nhưng ở đây chưa ai đánh giá giá trị và thay story giữa sprint phá cam kết sprint. Thay đổi ưu tiên là quyền của product owner qua backlog.","Đúng: PM đưa thông tin thị trường cho product owner và nhờ họ đánh giá tác động lên backlog, tốt nhất tại buổi refinement thứ Năm. Product owner là người quyết định thứ tự ưu tiên.","Sai: khảo sát bên ngoài đúng nếu đội hoàn toàn thiếu dữ liệu thị trường, nhưng ở đây việc cần làm trước là cho product owner đánh giá tin tức. Thuê agency vừa tốn kém vừa chậm hơn buổi refinement sắp tới."],exp:"B8 (Survey changes to the external business environment, Assess and prioritize the impact on scope/backlog): ở agile, thay đổi thị trường được đánh giá tác động lên backlog cùng product owner và đưa vào refinement. Bẫy là phản ứng ngay trong sprint hoặc phớt lờ."},{id:"o467",n:467,t:0,origin:"original",eco:"B5",domain:"business",approach:"agile",tags:["agile","eco-2026","it-security","risk-register"],type:"mc",q:"During a retrospective, two developers mention that the shared test environment holds copies of real customer records, uses one shared administrator password, and keeps no access logs. The Scrum team is in sprint 7 of a planned 12, and no breach has occurred. The team has no formal risk register, and the product owner asks what to do with the concern. What should the project manager do?",opts:["Ask the product owner to add a backlog item to rotate the password and continue with the sprint plan","Declare a security incident with the security lead and notify the affected customers about the exposure","Agree with the product owner on a Definition of Done item covering test-data handling for coming sprints","Record it as a security risk with a named owner and have the security lead assess its probability and impact"],ans:[3],why:["Sai: đổi mật khẩu chỉ xử lý một triệu chứng, bỏ qua dữ liệu khách hàng thật và việc thiếu log. Chưa phân tích thì chưa biết response nào đáng làm trước.","Sai: sự cố bảo mật và thông báo khách hàng áp dụng khi dữ liệu đã bị lộ, nhưng stem nói rõ chưa có vi phạm. Thông báo sớm gây hoang mang; việc đúng là ghi rủi ro và đánh giá xác suất, tác động.","Sai: Definition of Done là công cụ agile hợp lý để ngăn lỗi lặp lại, nhưng nó không đánh giá nguy cơ đang tồn tại trong môi trường test hiện tại (dữ liệu thật, mật khẩu chung, không log). Cần ghi vào register và đánh giá trước.","Đúng: chưa có vi phạm nên đây là risk, chưa phải issue. PM đưa nó vào risk register với risk owner rồi phân tích xác suất và tác động cùng chuyên gia bảo mật để chọn response phù hợp."],exp:"B5 (Identify risks, Maintain a risk register - ví dụ poor IT security): rủi ro bảo mật IT phải được ghi nhận, có owner và được phân tích. Nhớ: chưa xảy ra là risk, đã xảy ra là issue. Ở agile, risk vẫn cần chỗ ghi rõ ràng và được đưa vào nhịp làm việc của đội."},{id:"o468",n:468,t:0,origin:"original",eco:"B5",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","sustainability","risk-response","triggers"],type:"mc",q:"A hybrid programme builds a regional distribution centre. A sustainability risk is in the register: a freight vendor's emissions might exceed the carbon limit in the programme's sustainability commitments. The approved response is to switch bulk deliveries to rail, owned by the logistics lead, with an early-warning trigger at 90% of the limit. The vendor's latest monthly report shows 93%, and the limit has not yet been breached. What should the project manager do next?",opts:["Have the logistics lead start the approved switch to rail now that the trigger has been reached","Review the vendor's monthly report with the logistics lead to find the cause of the 93% before acting","Increase reporting with the vendor to weekly emissions statements so the trend is visible sooner","Rerun the risk analysis from the start to see whether the original response is still the best option"],ans:[0],why:["Đúng: mức 93% đã chạm trigger 90%, response chuyển sang đường sắt đã được duyệt và logistics lead là owner của nó. Việc kế tiếp là để owner thực thi response; cập nhật register đi kèm sau đó.","Sai: trigger 90% đã được kích hoạt bởi chính báo cáo hàng tháng này và response đã được duyệt. Xem lại báo cáo để tìm nguyên nhân là việc điều tra thừa, đúng nếu response chưa được duyệt, nhưng ở đây cần chuyển sang đường sắt.","Sai: báo cáo dày hơn là cải tiến theo dõi hợp lý, nhưng trigger 90% đã bị chạm (93%) và response đã được duyệt. Việc cần làm là kích hoạt response, không chỉ theo dõi dày hơn; đúng nếu chưa chạm trigger.","Sai: rủi ro đã được phân tích và response đã duyệt. Phân tích lại từ đầu khi trigger vừa kích hoạt chỉ trì hoãn hành động, trừ khi có dấu hiệu response không còn phù hợp."],exp:"B5 (Execute a risk management plan - risk response cho managing sustainability risks): rủi ro bền vững được quản lý như mọi rủi ro khác, gồm trigger, owner và response đã duyệt. Quy tắc nhớ: trigger kích hoạt thì thực thi response, không phân tích lại. Bẫy là coi chạm ngưỡng cảnh báo như đã vi phạm."},{id:"o469",n:469,t:0,origin:"original",eco:"B5",domain:"business",approach:"predictive",tags:["predictive","eco-2026","quantitative-analysis","contingency"],type:"mc",q:"On a predictive highway interchange project, qualitative analysis has ranked three risks as high: late utility relocation, soil-condition uncertainty, and a permit decision. Before approving the baseline, the sponsor asks for a defensible schedule and cost contingency that reflects the combined effect of these risks, with a stated confidence level. The risk register is current, each risk has a probability and an impact rating, and the estimators have supplied three-point estimates for the affected activities. What should the project manager do next?",opts:["Build a decision tree with the risk owners for the utility and permit decisions and set contingency from the best expected path","Run a sensitivity analysis with the schedule and cost leads to rank which activities the three risks affect most","Run a Monte Carlo simulation with the estimators on the schedule-cost models, using the three-point estimates for the three risks","Total the expected monetary value of each risk with the risk owners and set that sum as the schedule and cost contingency"],ans:[2],why:["Sai: decision tree hợp lý khi có quyết định tuần tự với các nhánh rõ (di dời hay chờ giấy phép), nhưng sponsor cần contingency cho lịch và chi phí kèm mức tin cậy. Cây quyết định chỉ cho giá trị kỳ vọng của đường đi tốt nhất, không cho phân phối.","Sai: sensitivity analysis đúng nếu mục tiêu chỉ là xếp hạng hoạt động nhạy nhất với rủi ro, nhưng sponsor cần con số contingency tổng hợp kèm mức tin cậy. Phân tích độ nhạy không cho con số đó.","Đúng: sponsor cần ảnh hưởng tổng hợp lên lịch và chi phí kèm mức tin cậy, và estimator đã có ước lượng ba điểm. Đó là mục đích của phân tích định lượng bằng mô phỏng trên các rủi ro đã được ưu tiên bằng định tính.","Sai: cộng EMV của từng rủi ro đúng nếu chỉ cần một con số trung bình, nhưng không cho phân phối hay mức tin cậy mà sponsor yêu cầu, và cộng riêng lẻ không phản ánh tác động tổng hợp lên lịch."],exp:"B5 (Analyze risks): sau phân tích định tính để ưu tiên, phân tích định lượng cho ra tác động số của các rủi ro lên mục tiêu, là cơ sở cho contingency reserve. Quy tắc nhớ: định tính để xếp hạng, định lượng để có số và độ tin cậy."},{id:"o470",n:470,t:0,origin:"original",eco:"B5",domain:"business",approach:"predictive",tags:["predictive","eco-2026","sustainability","residual-risk","monitoring"],type:"mc",q:"A predictive plant-expansion project has a sustainability risk in the register: demolition waste could exceed the landfill allowance in the company's environmental commitments. A waste-sorting subcontractor was added as the mitigation, and the risk owner reports the response as complete. Procurement confirms the subcontractor is meeting every contract term. The register sets a trigger for the fallback response, diverting waste to a licensed second landfill, when volumes pass 90% of the allowance with more than three months of demolition left. The latest site data shows 95% of the allowance used with four months left, and the risk owner reassessed the residual risk last week. What should the project manager do?",opts:["Reassess the residual risk in the register with the risk owner against the full site data before choosing a response","Convert the risk to an issue with the sponsor and ask for funds to buy additional landfill capacity now","Activate the fallback response in the register with the risk owner and record the new residual risk after the diversion","Review the subcontract with procurement to find out why sorting has not cut the volumes, and report back to the risk owner"],ans:[2],why:["Sai: đánh giá lại residual risk là đúng khi chưa có trigger, nhưng ở đây risk owner vừa đánh giá tuần trước và register đã đặt trigger 90% kèm response dự phòng. Đánh giá thêm chỉ làm chậm khi chỉ còn bốn tháng phá dỡ.","Sai: hạn mức chưa bị vượt nên rủi ro chưa thành issue. Xin tiền mua thêm bãi chôn lấp là nhảy sang giải pháp mới đắt tiền trong khi register đã có sẵn response dự phòng.","Đúng: trigger trong register (trên 90% hạn mức, còn hơn ba tháng) đã bị chạm vì số liệu là 95% và còn bốn tháng. PM cùng risk owner kích hoạt response dự phòng rồi ghi residual risk mới vào register.","Sai: xem lại hợp đồng đúng nếu nghi nhà thầu phụ làm không đạt, nhưng procurement đã xác nhận họ đáp ứng mọi điều khoản. Vấn đề là response chưa đủ so với hạn mức, và register đã nêu hướng xử lý khi chạm trigger."],exp:"B5 (Monitor and control risks, risk response cho sustainability): khi số liệu chạm trigger đã định trong register, kích hoạt response dự phòng qua risk owner rồi cập nhật residual risk. Quy tắc nhớ: trigger đã đặt thì dùng, đừng phân tích lại từ đầu. Bẫy là đóng rủi ro theo hoàn thành hoạt động thay vì theo kết quả."},{id:"o471",n:471,t:0,origin:"original",eco:"B5",domain:"business",approach:"agile",tags:["agile","eco-2026","generative-ai","data-confidentiality","risk-identification","ai"],type:"mc",q:"A product team on an agile project has started using a generative AI assistant to draft code and summarise customer interviews. Nobody has checked what data the tool retains, and its output goes into the sprint increment without a specific review. The team is pleased with its higher velocity, and the product owner wants the practice to continue. The PMO has said that project teams own tool decisions for their projects. What should the project manager do?",opts:["Ask the product owner and lead developer to prioritise a story that replaces the AI-drafted code with manually written code","Record the AI-use risk in the register with the team, name an owner, and plan responses such as human review of output","Refer the data-retention question to the PMO's security lead and ask for a ruling on AI tools for the whole organisation","Add a line to the definition of done, agreed with the testers, that requires them to log faulty AI output as defects"],ans:[1],why:["Sai: viết lại bằng tay đúng nếu mã AI đã gây lỗi nghiêm trọng, nhưng ở đây nó chỉ xử lý triệu chứng, bỏ qua rủi ro dữ liệu từ bản tóm tắt phỏng vấn và vẫn chưa có quy tắc rà soát.","Đúng: đây là risk chưa xảy ra. PM cùng đội ghi vào register với owner rồi lên kế hoạch response như con người rà soát kết quả AI và giới hạn dữ liệu đưa vào công cụ.","Sai: chuyển cho security lead của PMO đúng nếu cần chính sách cho cả tổ chức, nhưng PMO đã nói đội sở hữu quyết định công cụ của dự án. Chuyển câu hỏi đi cũng chưa ghi nhận rủi ro hay giao owner.","Sai: dòng trong definition of done để tester ghi lỗi AI là phản ứng thụ động, đúng nếu rủi ro chỉ là chất lượng đầu ra. Rủi ro lộ dữ liệu khách hàng thì không tester nào bắt được sau khi dữ liệu đã rời hệ thống."],exp:"B5 (Identify risks, Execute a risk management plan): AI là nguồn rủi ro mới như chất lượng đầu ra, dữ liệu nhạy cảm và trách nhiệm cuối cùng. Cách làm đúng là đưa nó vào register, gán owner và chọn response tương xứng thay vì cấm hay mặc kệ."},{id:"o472",n:472,t:0,origin:"original",eco:"B5",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","risk-communication","stakeholder-reporting","escalation"],type:"mc",q:"A hybrid medical-device project has a predictive regulatory workstream and an agile software workstream. The risk 'notified body audit slot slips' was rated medium last month. The body now says the planned slot is under review and may move by up to eleven weeks, which raises the risk to high and would affect the release milestone. The schedule team has already worked out the effect on the release milestone. The customer contract requires notice of any high milestone risk within five working days, and the steering committee meets in three weeks. What should the project manager do?",opts:["Tell the software team to reorder the backlog and hold the release to the original date","Run a schedule-impact analysis with both workstream leads on the eleven-week shift to the audit slot","Escalate the new high rating and its effect on the release milestone to the sponsor and stakeholders","Prepare a briefing on the new rating for the steering committee meeting, where the group can discuss options"],ans:[2],why:["Sai: sắp xếp lại backlog là đi thẳng vào giải pháp khi chưa thông báo hay phân tích. Lịch kiểm định do notified body quyết định và thuộc workstream predictive, nên dồn tiến độ phần mềm không giải quyết được nguyên nhân.","Sai: phân tích tác động lịch đúng khi chưa biết mức ảnh hưởng, nhưng schedule team đã tính xong tác động lên mốc release. Làm lại không thêm thông tin, còn sponsor cần được báo ngay.","Đúng: rủi ro đã lên mức cao, tác động mốc release đã biết, và hợp đồng khách hàng yêu cầu thông báo trong năm ngày làm việc. PM leo thang ngay cho sponsor và các bên bị ảnh hưởng thay vì chờ họp định kỳ.","Sai: chuẩn bị bản trình cho steering committee đúng nếu cuộc họp diễn ra trước hạn thông báo, nhưng ba tuần dài hơn hạn năm ngày làm việc của hợp đồng. Họp là nơi thảo luận phương án, không phải lý do trì hoãn thông báo."],exp:"B5 (Communicate the status of a risk impact on the project): khi mức rủi ro đổi và tác động đã rõ, leo thang kịp thời, ngắn gọn, đúng đối tượng và nêu rõ tác động cùng response, nhất là khi hợp đồng có hạn thông báo. Quy tắc nhớ: đừng chờ họp định kỳ khi rủi ro tăng và hạn thông báo ngắn hơn lịch họp."},{id:"o473",n:473,t:0,origin:"original",eco:"B5",domain:"business",approach:"predictive",tags:["predictive","eco-2026","risk-owner","risk-register"],type:"mc",q:"A predictive pipeline-replacement project has a risk register with 16 entries, all listing the project manager as owner. At the last review, nobody could say who was watching the early-warning signs for the land-access and steel-price risks, and two responses had no named action holder. The project manager wants to fix this before the next review. What is the best approach?",opts:["Ask the sponsor to appoint a risk manager as owner of all 16 risks, with the project manager as backup","Assign each risk to the department head whose budget would absorb the impact, as that person can approve the response","Hold a workshop with the team to re-score the 16 risks first, and name owners for the top five by score","Assign each risk to the team member closest to its early-warning signs and name an action holder for every response"],ans:[3],why:["Sai: một risk manager sở hữu cả register lặp lại nút thắt cũ ở người xa công việc thực tế, không theo dõi sát dấu hiệu cảnh báo sớm. Việc nhờ sponsor cũng chưa cần thiết cho thay đổi trong thẩm quyền của PM.","Sai: trưởng bộ phận có thẩm quyền duyệt response, nhưng thường không ở gần dấu hiệu cảnh báo như giá thép hay thủ tục tiếp cận đất. Thẩm quyền chỉ là điều kiện đi kèm, không phải tiêu chí chính của owner.","Sai: chấm điểm lại 16 rủi ro là sinh hoạt hợp lệ ở lần rà soát sau, nhưng vấn đề trong stem là không ai theo dõi dấu hiệu cảnh báo sớm và hai response chưa có người thực hiện. Điểm số không phải nguyên nhân.","Đúng: risk owner phải là người ở vị trí tốt nhất để theo dõi dấu hiệu cảnh báo, và mỗi response có người thực hiện được nêu tên. Land-access và steel-price cần những người khác nhau, không phải PM cho tất cả."],exp:"B5 (Maintain a risk register): mỗi rủi ro cần risk owner cụ thể, gần với rủi ro và có thẩm quyền, cùng người chịu trách nhiệm từng action của response. Bẫy là dồn mọi thứ về PM hoặc chọn theo cấp bậc."},{id:"o474",n:474,t:0,origin:"original",eco:"B5",domain:"business",approach:"agile",tags:["agile","eco-2026","sustainability","cloud-energy","risk-response"],type:"mc",q:"An agile team runs a data-analytics product on a cloud platform. The organisation has committed to a yearly energy-use target for its cloud workloads. The team's nightly automated load tests now run on large instances, and the monthly usage report shows the product trending toward 85% of its yearly energy budget by mid-year. The target has not been exceeded. What should the project manager do?",opts:["Tell the team to cut the nightly load tests to weekly runs, and agree the change with the product owner at the next review","Raise the trend with the sponsor and the sustainability lead for a decision on whether to adjust the yearly energy target","Commission an energy audit with the cloud provider and the platform owner to find which workloads use the most energy","Record a sustainability risk with the product owner, with a response such as smaller test instances in the backlog"],ans:[3],why:["Sai: giảm tần suất load test chỉ là đoán nguyên nhân mà chưa phân tích, và làm giảm chất lượng kiểm thử. Đúng nếu số liệu chứng minh test là nguyên nhân duy nhất, nhưng ở đây cần ghi rủi ro và chọn biện pháp như instance nhỏ hơn.","Sai: mục tiêu năng lượng là cam kết của tổ chức, chưa bị vượt và không phải là thứ PM xin sponsor điều chỉnh. Có xu hướng rõ ràng thì cần ghi rủi ro và hành động khi còn thời gian.","Sai: kiểm toán năng lượng hợp lý khi chưa biết nguyên nhân, nhưng stem đã chỉ rõ load test hàng đêm trên instance lớn là nguồn chính. Việc cần làm là ghi rủi ro và chọn biện pháp ngay trong backlog, không cần thêm kiểm toán.","Đúng: xu hướng 85% giữa năm là rủi ro vượt mục tiêu. PM cùng đội và product owner ghi rủi ro bền vững, chọn response như cỡ instance hay lịch chạy test, và đưa vào backlog để theo dõi."],exp:"B5 (Execute a risk management plan - managing sustainability risks): mục tiêu năng lượng hay carbon là ràng buộc của dự án nên vượt ngưỡng là rủi ro cần response. Trong agile, response được đưa vào backlog và chia sẻ với đội."},{id:"o475",n:475,t:0,origin:"original",eco:"B5",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","risk-to-issue","contingency"],type:"mc",q:"In a hybrid retail-systems project, the risk register contains 'payment-gateway vendor becomes insolvent', with a response of switching to a second pre-qualified vendor and a contingency fund set aside for it. This morning the vendor's administrator informed the project that it has ceased trading. The agile team is mid-sprint integrating the gateway. What should the project manager do first?",opts:["Reassess the probability of the risk and choose a new response strategy together with the team","Treat it as an issue, triggering the planned switch to the second pre-qualified payment vendor","Request a project change to rebaseline the schedule and budget before acting on the response","Ask the product owner to reprioritise the integration stories in the next sprint planning session"],ans:[1],why:["Sai: rủi ro đã xảy ra nên xác suất không còn là vấn đề. Chọn chiến lược mới khi đã có response và quỹ dự phòng được duyệt chỉ làm chậm xử lý.","Đúng: rủi ro đã xảy ra nên trở thành issue. PM kích hoạt kế hoạch chuyển sang nhà cung cấp thứ hai đã được qualify, dùng quỹ dự phòng đã lập sẵn; cập nhật register làm ngay sau đó.","Sai: response và contingency đã được duyệt trong kế hoạch, nên không cần chờ rebaseline mới hành động. Change request chỉ cần khi tác động vượt phần đã dự phòng.","Sai: đẩy việc sắp lại ưu tiên sang kỳ họp planning kế tiếp để đội tiếp tục tích hợp một cổng không còn tồn tại. Response đã chuẩn bị sẵn cần được kích hoạt trước, rồi product owner mới xếp lại backlog."],exp:"B5 (Execute a risk management plan, Maintain a risk register): khi rủi ro xảy ra nó thành issue, PM thực thi response đã duyệt dùng dự phòng đã có và cập nhật register. Quy tắc nhớ: có kế hoạch sẵn thì làm theo, đừng lập lại."},{id:"o476",n:476,t:0,origin:"original",eco:"B6",domain:"business",approach:"predictive",tags:["predictive","eco-2026","lessons-learned","phase-lessons"],type:"mc",q:"A predictive rail-signalling project runs for 18 months. During phase 1, the team learned that purchase orders for track-side cabinets took twice as long to approve as planned, and the procurement manager has already traced the delay to a three-step approval path. The plan says lessons will be collected in the closing phase, and phase 2 procurement starts in six weeks with the same approval path. What should the project manager do?",opts:["Analyse the phase 1 approval times with the procurement manager to find the cause before touching the phase 2 plan","Hold a lessons learned session with procurement now, applying the findings to the phase 2 purchasing schedule","Keep to the plan and collect lessons once, in a consistent format, with all teams during the closing phase","Add schedule buffer to phase 2 with the scheduler and record the cause of the delay for the final lessons report"],ans:[1],why:["Sai: phân tích nguyên nhân hợp lý nếu chưa biết, nhưng procurement manager đã truy ra đường duyệt ba bước. Điều còn thiếu là biến bài học thành thay đổi lịch phase 2, và chỉ còn sáu tuần.","Đúng: lessons learned nên được thu thập xuyên suốt, nhất là khi một phase vừa kết thúc. Ghi lại bài học về thời gian duyệt PO cùng procurement và áp dụng ngay vào lịch mua sắm phase 2 giúp tránh lặp lại.","Sai: chờ đến khi đóng dự án nghĩa là phase 2 lặp lại đúng thất bại của phase 1. Bài học chỉ có giá trị khi được dùng trong lúc dự án còn chạy.","Sai: thêm buffer chỉ xử lý triệu chứng, còn nguyên nhân chỉ được ghi lại cho báo cáo cuối thì phase 2 vẫn đi qua đúng đường phê duyệt chậm đó. Đúng nếu không còn thời gian xử lý, nhưng ở đây còn sáu tuần."],exp:"B6 (Utilize lessons learned): trong dự án predictive, thu thập bài học ở mỗi phase gate để dùng cho các phase sau, không dồn đến cuối. Quy tắc nhớ: bài học chỉ hữu ích khi dùng kịp."},{id:"o477",n:477,t:0,origin:"original",eco:"B6",domain:"business",approach:"agile",tags:["agile","eco-2026","opa-update","templates","pmo"],type:"mc",q:"A Scrum team on a banking project built a one-page template for writing acceptance criteria. Over four sprints, rework from misunderstood stories fell by almost half, and two other teams have asked for a copy. The PMO keeps a central repository of approved templates and has a procedure for submitting additions. What should the project manager do?",opts:["Route the template with its four-sprint results through the PMO's procedure for additions, via the Scrum Master","Ask the PMO director to make the template the standard for the portfolio starting from the next sprint","Pilot the template with the two requesting teams for another four sprints, then approach the PMO with the combined results","Publish the template on the project wiki for the two requesting teams and tell the PMO where it is stored"],ans:[0],why:["Đúng: cập nhật OPA nghĩa là đưa tài sản qua quy trình chính thức của PMO kèm số liệu hiệu quả. Nhờ vậy template được rà soát, lưu trữ chung và mọi dự án sau đều tìm thấy.","Sai: bắt buộc toàn bộ các đội dựa trên dữ liệu của một đội là nhảy quá xa. PMO phải rà soát và quyết định mức độ áp dụng, PM chỉ đề xuất kèm bằng chứng.","Sai: pilot thêm hợp lý khi dữ liệu còn mỏng, nhưng stem cho biết rework đã giảm gần một nửa sau bốn sprint. PMO có quy trình nộp bổ sung nên PM nộp kèm bằng chứng đã có.","Sai: wiki của dự án giúp hai đội dùng ngay, nhưng PMO có repository và quy trình nộp bổ sung chính thức. Để ngoài repository thì các đội khác trong tổ chức không tìm thấy và template không được phê duyệt."],exp:"B6 (Update organizational process assets): template, checklist và dữ liệu hiệu quả được nộp theo quy trình của tổ chức để trở thành OPA. Quy tắc nhớ: nộp kèm bằng chứng, để PMO quyết mức áp dụng."},{id:"o478",n:478,t:0,origin:"original",eco:"B6",domain:"business",approach:"predictive",tags:["predictive","eco-2026","process-improvement","root-cause","quality"],type:"mc",q:"A predictive pharmaceutical-plant project has a quality plan with sign-off steps. A quality audit finds that 40% of design drawings reach procurement with missing revision data. The audit's root-cause review, which the design leads have agreed with, traced the problem to a handoff step that has no checklist. The audit report is accepted and the team is told to be more careful. What should the project manager do?",opts:["Analyse a further sample of the drawings with the design leads to confirm the cause before changing the process","Ask the design manager to retrain the design team on revision control and add the topic to the next project's onboarding","Add a revision-data checklist to the handoff step with the design leads and track the defect rate each month","Add a second inspection before procurement, owned by the quality manager, to catch missing data before orders are placed"],ans:[2],why:["Sai: phân tích thêm mẫu bản vẽ là đúng khi chưa rõ nguyên nhân, nhưng root-cause review của audit đã được design leads đồng ý: bước bàn giao không có checklist. Phân tích thêm không đổi kết luận; cần sửa quy trình.","Sai: đào tạo có thể giúp một phần nhưng nguyên nhân gốc là bước chuyển giao không có checklist. Hoãn sang dự án sau không sửa 40% bản vẽ lỗi hiện tại.","Đúng: nguyên nhân gốc đã rõ là bước chuyển giao không có checklist. Cải tiến liên tục nghĩa là cập nhật quy trình (thêm checklist) cùng design leads và đo lại tỷ lệ lỗi; nhắc đội cẩn thận hơn không phải là cải tiến quy trình.","Sai: thêm khâu kiểm tra tăng chi phí đánh giá mà vẫn để bước chuyển giao thiếu checklist. Lỗi vẫn sinh ra rồi mới bị bắt."],exp:"B6 (Help ensure continuous improvement processes are updated): lỗi lặp lại thường do quy trình, nên sửa quy trình rồi đo hiệu quả (vòng plan-do-check-act). Bẫy là dùng thêm kiểm tra hoặc nhắc nhở thay cho sửa nguyên nhân."},{id:"o479",n:479,t:0,origin:"original",eco:"B6",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","lessons-learned","historical-information","planning"],type:"mc",q:"A newly assigned project manager begins planning a hybrid e-commerce replatforming, with a phase-gated infrastructure migration and sprint-based storefront work. The PMO repository holds lessons learned from three similar completed projects, including notes on vendor onboarding delays and unstable third-party integrations. Some team members suggest starting fresh because 'this project is different'. What should the project manager do before finalising the plan?",opts:["Verify with the PMO that the three earlier projects are comparable, then adopt the best-fitting plan as this project's baseline","Invite the three previous project managers to a workshop to pick the lessons that fit, and rely on their advice for the estimates","Review the relevant lessons with the team and build the ones that fit into the estimates and risk register","Copy the recorded lessons from the three projects into the new plan with the PMO to prevent earlier problems recurring"],ans:[2],why:["Sai: xác nhận mức độ tương đồng với PMO rồi lấy kế hoạch cũ làm baseline bỏ qua đặc thù của dự án này. Các dự án chỉ tương tự, không giống hệt, nên chỉ nên lấy bài học chứ không lấy nguyên kế hoạch.","Sai: ý kiến của ba PM cũ là nguồn tốt, nhưng bài học đã được ghi trong repository và cần được xem xét có hệ thống để đưa vào estimate và risk register. Dựa riêng vào trí nhớ bỏ sót ghi chú về vendor onboarding và tích hợp bên thứ ba.","Đúng: PM cùng đội xem lessons liên quan, đánh giá cái nào phù hợp với bối cảnh rồi đưa vào ước lượng và risk register. Ý kiến 'dự án này khác' được xử lý bằng cách chọn lọc, không bỏ qua hoàn toàn.","Sai: sao chép các bài học từ ba dự án vào kế hoạch sinh ra biện pháp thừa và ảnh hưởng đến ngân sách và tiến độ. Bài học cần được chọn lọc theo bối cảnh, không áp dụng máy móc."],exp:"B6 (Utilize lessons learned): trước khi lập kế hoạch, xem lại lessons learned và dữ liệu lịch sử từ dự án tương tự trong OPA. Quy tắc nhớ: dùng có chọn lọc và gắn với bối cảnh, không bỏ qua và không sao chép máy móc."},{id:"o480",n:480,t:0,origin:"original",eco:"B6",domain:"business",approach:"predictive",tags:["predictive","eco-2026","opa-update","historical-data","estimating"],type:"mc",q:"A predictive project to commission a water-treatment facility has closed its final phase. Pipe testing and commissioning ran 30% over the estimates, which came from a parametric rate in the organisation's historical database. The team recorded the actual durations and the conditions that caused the overrun. The PMO accepts updates to that database through its closing checklist. What should the project manager do?",opts:["Submit the actual durations and context notes to the PMO so its historical data is updated","Adjust the parametric rate in the project's own estimate file for the next similar project to reuse","Analyse the overrun with the commissioning team to confirm the causes before sending anything to the PMO","Mention the overrun in the lessons learned report and leave the historical database as it is"],ans:[0],why:["Đúng: số liệu thực tế cùng bối cảnh là thông tin lịch sử có giá trị. Nộp qua quy trình đóng dự án của PMO để tổ chức cập nhật OPA và hiệu chỉnh mức ước lượng.","Sai: sửa trong file riêng của dự án không đưa dữ liệu vào cơ sở dữ liệu của tổ chức. Dự án sau sẽ không dùng được và còn dễ dùng nhầm bản cũ.","Sai: phân tích nguyên nhân cần thiết nếu chưa có dữ liệu, nhưng stem cho biết đội đã ghi lại thời lượng thực tế và điều kiện gây vượt. PMO nhận cập nhật qua checklist đóng dự án nên nộp ngay.","Sai: chỉ nêu trong báo cáo thì dữ liệu không đi vào kho ước lượng. Người lập ước lượng kế tiếp vẫn dùng mức cũ và có thể lặp lại sai số."],exp:"B6 (Update organizational process assets): dữ liệu thực tế cuối dự án như thời lượng, chi phí, số liệu hiệu suất cần được nộp để cập nhật thông tin lịch sử. Quy tắc nhớ: nộp số liệu kèm bối cảnh, không tự suy rộng từ một dự án."},{id:"o481",n:481,t:0,origin:"original",eco:"B6",domain:"business",approach:"agile",tags:["agile","eco-2026","experiment","retrospective","kanban"],type:"mc",q:"A Kanban team on a software maintenance project wants to try pair programming to reduce escaped defects, which averaged nine per month over the last quarter. Some members doubt it will help, and the service manager worries about lost throughput. The team asks the project manager how to proceed. What is the best advice?",opts:["Analyse last quarter's escaped defects with the team to find which ones pairing would have prevented, then decide","Let the service manager decide whether the team may pair, with the team's views noted for the record","Adopt it across the team now with the team's agreement and measure the effect on defects and throughput at year end","Trial it with the team for a fixed period, tracking escaped defects as well as throughput against last quarter"],ans:[3],why:["Sai: phân tích lỗi cũ là hợp lý để chọn phạm vi, nhưng chỉ là ước lượng trên giấy, trong khi stem có số liệu nền (chín lỗi mỗi tháng) và đội muốn thử. Thử nghiệm có thời hạn cho bằng chứng thật về cả lỗi và throughput.","Sai: đội là người sở hữu cách làm việc của mình. Service manager nên là bên cung cấp ràng buộc và xem kết quả đo, không quyết định thay đội.","Sai: áp dụng toàn đội rồi đo vào cuối năm là cam kết lớn trước khi có bằng chứng, kể cả khi đội đồng ý. Nếu không hiệu quả đội đã mất cả năm.","Đúng: thử trong một khoảng thời gian cố định và theo dõi lỗi thoát cùng throughput so với quý trước cho phép đội học từ dữ liệu. Mối lo về throughput trở thành điều kiện đo, không phải lý do ngăn thử; kết quả sẽ được đội xem lại sau đó."],exp:"B6 (Help ensure continuous improvement processes are updated): cải tiến trong agile đi theo vòng thử nghiệm nhỏ, có giả thuyết, thước đo và thời hạn, rồi inspect and adapt. Bẫy là áp dụng đại trà hoặc để người ngoài đội quyết."},{id:"o482",n:482,t:0,origin:"original",eco:"B6",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","generative-ai","verify-ai-output","lessons-learned","ai"],type:"mc",q:"In the closing review of a hybrid project (a predictive build phase followed by sprint-based enhancements), the PMO asks the project manager to feed 180 lessons learned entries into a generative AI tool to produce a summary for the organisation's repository. The summary reads well, but it attributes a vendor-management problem to the wrong phase and omits an entry about a safety near-miss. What should the project manager do?",opts:["Reconcile the summary against the 180 source entries with their authors, correct its errors, add the missing safety entry","Publish the summary with a note that it was AI-generated, after the PMO reviewer has spot-checked ten entries","Re-run the tool with a prompt that names the phases and the safety near-miss, and file the new summary with the prompt log","Submit the summary as the PMO requested, with a note naming the tool, the number of entries processed and the two errors found"],ans:[0],why:["Đúng: dùng AI để tăng tốc, nhưng PM cùng tác giả các mục gốc đối chiếu đầu ra với 180 mục, sửa lỗi phase và bổ sung mục an toàn bị bỏ sót rồi mới cập nhật OPA.","Sai: ghi chú dùng AI và kiểm tra mười mục giúp minh bạch, nhưng mẫu nhỏ không phát hiện được các mục bị bỏ sót hay gán sai phase đã biết. Đúng nếu lỗi chỉ là nhỏ, nhưng ở đây có một mục an toàn bị thiếu.","Sai: chạy lại công cụ với prompt tốt hơn có thể giảm lỗi, nhưng không ai đối chiếu với mục gốc nên lỗi khác có thể còn lại. Đúng nếu bản chạy lại được kiểm chứng trước khi nộp, nhưng ở đây thì chưa.","Sai: bản tóm tắt có hai lỗi cụ thể, trong đó một mục an toàn bị bỏ sót. Người nộp vẫn chịu trách nhiệm về nội dung đưa vào OPA, nên nêu việc PMO yêu cầu và ghi chú lỗi không thay cho việc sửa."],exp:"B6 (Utilize lessons learned, Update OPAs): AI được dùng như công cụ hỗ trợ, nhưng con người vẫn chịu trách nhiệm cuối cùng và phải kiểm chứng đầu ra trước khi đưa vào tài sản của tổ chức. Bẫy là tin đầu ra trơn tru."},{id:"o483",n:483,t:0,origin:"original",eco:"B6",domain:"business",approach:"predictive",tags:["predictive","eco-2026","process-improvement","evidence","change-control"],type:"mc",q:"Six months ago, a predictive infrastructure project added a pre-screening step to its change-request procedure, aiming to cut the average approval time of 18 days. The change log holds submission and approval dates for every request before and after the step, and the team is happy with it. The PMO now asks whether the process should become the standard for all projects. What should the project manager do?",opts:["Ask the PMO to pilot the step on two other projects, and report this project's results afterwards","Survey the requesters and the team on how the step felt, and report the satisfaction scores to the PMO","Measure approval times in the change log before versus after the step, then give the PMO the results","Recommend the standard to the PMO now, with the team lead presenting the team's view that the step is working well"],ans:[2],why:["Sai: dự án này đã có sáu tháng dữ liệu trong change log, nên đẩy cho pilot ở dự án khác trước khi báo cáo là bỏ qua bằng chứng sẵn có. Pilot chỉ cần khi dữ liệu chưa đủ; PMO có thể yêu cầu thêm sau khi nhận kết quả.","Sai: khảo sát mức hài lòng cho góc nhìn trải nghiệm, nhưng PMO hỏi về quy trình chuẩn hóa dựa trên chỉ số. Change log có ngày nộp và duyệt trước/sau cho mọi request, nên đo trực tiếp thời gian duyệt chắc chắn hơn.","Đúng: kiểm chứng cải tiến bằng dữ liệu đã có trong change log (thời gian duyệt trước và sau so với mức 18 ngày ban đầu) rồi đưa kết quả cho PMO. Nhờ đó PMO quyết định được dựa trên dữ liệu.","Sai: cảm nhận của đội chưa phải bằng chứng, dù do team lead trình bày. Đề xuất chuẩn hóa cho toàn tổ chức cần số liệu so sánh trước-sau."],exp:"B6 (Help ensure continuous improvement processes are updated): cải tiến phải được đo, so với mức cơ sở, rồi mới đề xuất chuẩn hóa. Quy tắc nhớ: dữ liệu trước-sau là bằng chứng, cảm nhận thì không."},{id:"o484",n:484,t:0,origin:"original",eco:"B6",domain:"business",approach:"agile",tags:["agile","eco-2026","cross-team-retrospective","lessons-learned","scaling"],type:"mc",q:"Four Scrum teams have finished a release of one product. Each held its own retrospective, and the notes show that three teams hit the same problem: stories entering sprints with unclear dependencies, which caused late handoffs. Each team has made its own small fix, and the fixes differ. Backlog items span several teams, so no single team can fix the dependencies alone. The next release starts in two weeks. What should the project manager do?",opts:["Collect the late-handoff data from the four teams with their Scrum Masters and analyse the dependency problem before meeting anyone","Let each team continue with its own fix and have the Scrum Masters compare the results after the next release","Select the fix from the best-performing team with the product owner and ask the other three teams to adopt it","Bring the four teams' representatives to a cross-team retrospective on the dependency problem before the next release"],ans:[3],why:["Sai: thu thập và phân tích số liệu là hợp lý, nhưng ghi chú retrospective của ba đội đã chỉ ra cùng một vấn đề (phụ thuộc không rõ) và release kế tiếp chỉ còn hai tuần. Cần họp liên đội để chốt cách sửa chung.","Sai: tự tổ chức không có nghĩa là nhiều giải pháp khác nhau cho một vấn đề chung về phụ thuộc, và so sánh sau release kế tiếp là quá muộn. Vấn đề liên đội cần giải pháp thống nhất để các handoff khớp nhau.","Sai: chọn của đội giỏi nhất là áp đặt, bỏ qua việc cải tiến đó có hợp với bối cảnh các đội khác hay không. Cam kết sẽ yếu hơn khi các đội không tham gia chọn.","Đúng: vấn đề phụ thuộc xuất hiện ở ba đội và release kế tiếp bắt đầu sau hai tuần, nên cần một retrospective liên đội. Tại đó các đội so sánh cách xử lý, chọn một cải tiến chung và vẫn tự quyết định cùng nhau."],exp:"B6 (Utilize lessons learned): khi nhiều đội gặp cùng vấn đề, retrospective cấp release hay cộng đồng thực hành giúp chia sẻ bài học và thống nhất cải tiến. Quy tắc nhớ: bài học liên đội cần diễn đàn liên đội."},{id:"o485",n:485,t:0,origin:"original",eco:"B7",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","generative-ai","change-resistance","adoption","ai"],type:"mc",q:"A hybrid project is introducing an AI assistant that drafts first-pass responses for an insurer's claims handlers. The pilot runs in sprints alongside a fixed training and roll-out plan. Several senior handlers say they will not use it because they feel their judgement is being replaced, and adoption in the pilot is at 20%. What should the project manager do?",opts:["Redesign the tool's workflow with the claims lead so handlers approve each draft before sending, and relaunch the pilot","Meet the senior handlers to hear their concerns and involve them in shaping how the tool is used","Ask the sponsor to make use of the tool a performance objective for the claims handlers, agreed with HR","Run a training day on the tool with the vendor's trainer for all claims handlers before the next sprint starts"],ans:[1],why:["Sai: bước duyệt từng bản nháp là thiết kế hợp lý và có thể là một phần giải pháp, nhưng stem chưa cho biết nỗi lo cụ thể của các handler cấp cao. Thiết kế lại trước khi lắng nghe là đoán, và họ vẫn không được tham gia.","Đúng: kháng cự thường xuất phát từ lo ngại thật (bị thay thế phán đoán). PM gặp các handler cấp cao, lắng nghe và cho họ tham gia định hình cách dùng công cụ, nên mức chấp nhận có cơ sở tăng lên.","Sai: biến việc dùng công cụ thành chỉ tiêu hiệu suất là cách ép buộc, có thể làm tăng kháng cự và không giải quyết nỗi lo. Cách này cũng đẩy lên sponsor khi chưa cần.","Sai: buổi đào tạo giúp dùng công cụ thành thạo, đúng nếu lý do không dùng là thiếu kỹ năng. Ở đây các handler cấp cao lo phán đoán của mình bị thay thế, nên đào tạo không trả lời nỗi lo đó."],exp:"B7 (Assess organizational culture, Evaluate the impact of organizational change): việc nhận AI vào quy trình là thay đổi tổ chức, kháng cự cần được hiểu và xử lý bằng sự tham gia. Con người vẫn chịu trách nhiệm quyết định cuối cùng nên cần nói rõ vai trò của họ. Bẫy là dùng áp lực hoặc số liệu một chiều."},{id:"o486",n:486,t:0,origin:"original",eco:"B7",domain:"business",approach:"predictive",tags:["predictive","eco-2026","organizational-culture","tailoring"],type:"mc",q:"A project manager joins a multinational firm to deliver an ERP upgrade using a predictive approach. At the previous employer, decisions were made by the team quickly. Here, colleagues say decisions are taken at senior level and junior staff seldom speak in meetings. The project manager is about to finalise the communications and governance plans. What should the project manager do?",opts:["Apply the approach that worked at the previous employer for the first two meetings, then review the response with the sponsor","Set up an anonymous feedback channel and a rotating chair for meetings, then review its use with the team lead after a month","Define decision rights from the organisation chart with the PMO, then check them with the senior managers before finalising","Assess the culture through interviews and observation before finalising the governance and communications plans"],ans:[3],why:["Sai: cách làm cũ gắn với văn hóa cũ. Áp dụng rồi sửa sau làm đội im lặng và bỏ lỡ thông tin quan trọng từ người ở cấp thấp ngay từ đầu.","Sai: kênh góp ý ẩn danh và chủ tọa luân phiên là kỹ thuật hợp lý để lấy ý kiến cấp thấp, nhưng PM mới vào chưa hiểu văn hóa quyết định ở đây. Đặt công cụ trước khi đánh giá có thể phản tác dụng trong môi trường coi trọng cấp bậc.","Sai: sơ đồ tổ chức cho biết thẩm quyền trên giấy, không cho biết ai thật sự ảnh hưởng quyết định hay vì sao nhân viên ít phát biểu. Kiểm tra lại với quản lý cấp cao vẫn chỉ phản ánh góc nhìn từ trên xuống.","Đúng: B7 nói rõ việc đánh giá văn hóa tổ chức. PM tìm hiểu bằng phỏng vấn và quan sát trước khi chốt các kế hoạch, để quản trị và truyền thông được tailor cho phù hợp với môi trường quyết định ở cấp cao này."],exp:"B7 (Assess organizational culture): văn hóa ảnh hưởng đến cách ra quyết định, truyền thông và mức độ tham gia. Đánh giá trước, rồi tailor kế hoạch. Bẫy là mang nguyên cách làm từ nơi khác sang."},{id:"o487",n:487,t:0,origin:"original",eco:"B7",domain:"business",approach:"predictive",tags:["predictive","eco-2026","organizational-change","policy-change","baseline-impact"],type:"mc",q:"A predictive facility-upgrade project has an approved baseline and a funded budget. The new CFO announces that, from next month, capital spending above a set limit needs a second approval from a finance committee that meets quarterly. Three procurement packages on the critical path exceed the limit and are due for release in two months, once their bid documents are finished. What should the project manager do?",opts:["Add the committee approval to the plan as a milestone with the scheduler and continue on the same dates","Rush the bid documents with the procurement lead to release the three packages this month, before the rule takes effect","Ask the CFO to exempt projects with approved baselines and funded budgets from the new approval rule","Evaluate with the scheduler how the new step affects the three packages, then submit a change request if needed"],ans:[3],why:["Sai: chỉ thêm milestone mà không phân tích thì bỏ qua việc ủy ban họp mỗi quý: có thể mất tới ba tháng chờ, ảnh hưởng đường găng và baseline.","Sai: dồn hồ sơ mời thầu để phát hành trước ngày áp dụng quy tắc là lách quy trình, và có thể khiến gói thầu chưa chín muồi. Một thay đổi chính sách hợp lệ cần được tuân thủ, không né.","Sai: xin miễn trừ là một lựa chọn có thể, nhưng khi chưa phân tích tác động thì chưa biết cần xin gì. Đây cũng là leo thang trước khi đánh giá.","Đúng: PM đánh giá tác động của bước phê duyệt mới lên ba gói trên đường găng và lịch, rồi dùng change control nếu baseline bị ảnh hưởng. Đó là cách xử lý một thay đổi tổ chức hợp lệ."],exp:"B7 (Evaluate the impact of organizational change on the project and determine required actions): phân tích ảnh hưởng đến lịch, chi phí rồi dùng change control khi baseline bị tác động. Bẫy là né quy định hoặc thêm bước mà không tính thời gian chờ."},{id:"o488",n:488,t:0,origin:"original",eco:"B7",domain:"business",approach:"agile",tags:["agile","eco-2026","team-capacity","reorganization","release-forecast"],type:"mc",q:"Midway through a product build, the organisation moves from a shared QA pool to product-aligned teams. Two of the Scrum team's three testers are reassigned to another product from the next sprint, though the product owner's release date is unchanged. The remaining tester is concerned. What should the project manager do?",opts:["Escalate to the sponsor and request that the release date move out by one sprint per reassigned tester","Ask the QA manager to keep the two reassigned testers on the product until the release is complete","Analyse the capacity change with the team and product owner, then update the release forecast for the sponsor","Keep the sprint plan and ask the lead developer to have developers cover the testing, preserving the date"],ans:[2],why:["Sai: dời release có thể là kết quả cuối, nhưng chưa tính năng lực còn lại mà đã xin mức dời cố định. Đúng nếu forecast cho thấy không đạt ngày; ở đây cần phân tích với đội và product owner trước.","Sai: xin giữ lại tester là ngược với thay đổi tổ chức đã quyết định. PM phải điều chỉnh dự án theo thay đổi này trước, không lùi thay đổi.","Đúng: tác động là mất hai trong ba tester. PM cùng đội và product owner phân tích lại năng lực rồi cập nhật dự báo release, thay vì giữ ngày bằng mọi giá. Phạm vi làm được sẽ được product owner điều chỉnh từ dự báo đó.","Sai: bảo toàn ngày bằng cách bắt developer kiêm kiểm thử bỏ qua việc năng lực thực tế đã giảm, và làm giảm chất lượng. Giữ ngày không phải mục tiêu duy nhất của đội."],exp:"B7 (Evaluate the impact of organizational change on the project and determine required actions): thay đổi nguồn lực ảnh hưởng đến năng lực đội, nên cập nhật velocity, forecast và phạm vi cùng product owner. Bẫy là giữ ngày cố định và để chất lượng gánh hậu quả."},{id:"o489",n:489,t:0,origin:"original",eco:"B7",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","organizational-culture","merger","working-agreements"],type:"mc",q:"Two companies have merged, and a hybrid project team now combines engineers from a company that uses stage gates with detailed documentation and engineers from one that works in short iterations with little paperwork. Reviews have become tense, with each group calling the other's practices wasteful. The sponsor wants delivery to continue. What should the project manager do?",opts:["Facilitate a session where both groups draft working agreements that blend the practices of the merged teams","Run a workshop with both groups' leads to adopt the stage-gate process for the programme and its approved documentation templates","Bring in a process authority, named by the sponsor, to settle disagreements about ways of working in the merged teams","Separate the two groups into their own workstreams, each following its familiar way of working, with a joint integration review"],ans:[0],why:["Đúng: PM tổ chức buổi làm việc để hai nhóm cùng soạn working agreement kết hợp thực hành của cả hai bên. Đây là cách xử lý khác biệt văn hóa ở mức đội, phù hợp với dự án hybrid.","Sai: stage-gate có tài liệu sẵn và hợp phần việc tuần tự, nhưng ép nhóm lặp ngắn theo gate làm mất lợi ích của họ và không giải quyết xung đột. Đúng nếu dự án hoàn toàn dự đoán, nhưng ở đây là hybrid.","Sai: nhờ sponsor chỉ định người phân xử là leo thang sớm cho một vấn đề đội có thể tự thống nhất. Sponsor nên được biết nhưng không phải làm trọng tài.","Sai: tách thành hai nhóm giữ nguyên thói quen cũ làm tăng khoảng cách và khiến việc tích hợp khó hơn. Nó né xung đột chứ không giải quyết."],exp:"B7 (Assess organizational culture): khi hai văn hóa gặp nhau, PM làm rõ khác biệt và cùng đội xây dựng working agreement chung. Quy tắc nhớ: hợp tác trước, tailor theo bối cảnh, không áp đặt một bên."},{id:"o490",n:490,t:0,origin:"original",eco:"B7",domain:"business",approach:"predictive",tags:["predictive","eco-2026","outsourcing","knowledge-transfer","impact-assessment"],type:"mc",q:"A predictive banking project has a test group of six internal engineers. Management announces that test work will be outsourced within the year, with no dates or details yet. Defect reports from the group have dropped, two engineers are job hunting, and the test phase is scheduled to start in three months. What should the project manager do?",opts:["Move the test activities earlier with the test lead so they finish before the outsourcing takes place","Evaluate with the test lead how outsourcing affects the test phase, including knowledge transfer from the engineers","Ask HR to offer retention bonuses to the six engineers, payable once the test phase has ended","Ask management to share the outsourcing dates, then re-plan the test phase with the sponsor around them"],ans:[1],why:["Sai: đẩy sớm lịch kiểm thử dựa trên một ngày chưa hề được công bố là đoán. Phase kiểm thử cần điều kiện đầu vào sẵn sàng nên làm sớm có thể gây rủi ro chất lượng.","Đúng: PM đánh giá tác động lên giai đoạn kiểm thử và nguồn lực, đồng thời tính đến chuyển giao tri thức từ các kỹ sư. Nhờ vậy dự án giảm rủi ro dù chưa có chi tiết, và có thể trao đổi mốc thời gian với sponsor sau đó.","Sai: thưởng giữ chân nằm ngoài thẩm quyền PM và chưa giải quyết lo lắng về công việc. Cần phân tích tác động trước khi đề xuất biện pháp.","Sai: nhờ quản lý chia sẻ ngày rồi mới lập kế hoạch lại khiến PM bị động khi hai kỹ sư đang tìm việc và năng suất giảm. Có thể đánh giá tác động và chuẩn bị chuyển giao kiến thức ngay."],exp:"B7 (Evaluate the impact of organizational change on the project and determine required actions): khi chi tiết chưa rõ, PM đánh giá theo thông tin có và chuẩn bị các hành động như chuyển giao tri thức, trao đổi với sponsor. Bẫy là chờ hoặc đoán ngày."},{id:"o491",n:491,t:0,origin:"original",eco:"B7",domain:"business",approach:"agile",tags:["agile","eco-2026","organizational-culture","status-reporting","transparency"],type:"mc",q:"A product team has adopted agile practices, but its department heads ask for a detailed weekly status document listing each team member's tasks, because that is how the department has always tracked work. The team spends about a day a week producing it and says it undermines self-organisation. What should the project manager do?",opts:["Keep the work visible on a team board and invite the department heads to the sprint reviews with the product owner","Ask a team member to present the agile principles to the department heads, with the Scrum Master, at the next meeting","Create the weekly document from the board on the team's behalf, with the Scrum Master checking it for accuracy","Agree with the department heads to cut the weekly document to a monthly summary and use the time saved for refinement"],ans:[0],why:["Đúng: lãnh đạo cần thấy tiến độ và kiểm soát, không nhất thiết cần tài liệu tốn một ngày mỗi tuần. Bảng công việc hiển thị và lời mời dự sprint review đáp ứng nhu cầu đó mà không làm mất thời gian của đội.","Sai: thuyết trình về nguyên tắc agile là truyền thông một chiều. Điều lãnh đạo cần là thông tin họ dùng để theo dõi công việc, không phải lý thuyết.","Sai: tự làm tài liệu từ board giữ nguyên thói quen cũ và đặt gánh nặng lên PM. Lãnh đạo không biết có cách khác nên vấn đề văn hóa vẫn còn.","Sai: giảm tần suất giảm lãng phí, nhưng vẫn là tài liệu liệt kê việc từng người nên vẫn xung đột với tự tổ chức, và department heads vẫn chưa thấy tiến độ thật. Đúng nếu họ chỉ cần số liệu tổng, nhưng ở đây họ muốn theo dõi công việc."],exp:"B7 (Assess organizational culture): hiểu nhu cầu đằng sau yêu cầu báo cáo và cung cấp thông tin minh bạch phù hợp văn hóa. Quy tắc nhớ: giải quyết nhu cầu, không chỉ sửa hình thức."},{id:"o492",n:492,t:0,origin:"original",eco:"B7",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","transformation","hr-alignment","governance"],type:"mc",q:"A company has launched a transformation from phase-gated delivery to a hybrid way of working, and the PMO owns the transformation roadmap. A pilot project follows the new approach, but the company-wide HR annual review still scores individuals on gate-date adherence and documentation volume. Team members tell the project manager they avoid iteration changes to protect their ratings. What should the project manager do?",opts:["Bring evidence of the conflict between the review criteria and the new approach to the sponsor and the PMO","Ask the functional managers of the pilot members to adjust their ratings by hand at the year-end review","Revise the team's goals and ratings within the project to reflect delivery of working increments","Return the pilot to gate-based delivery with the PMO until the HR system has been changed to suit the new approach"],ans:[0],why:["Đúng: xung đột nằm ở tiêu chí đánh giá của HR cho cả công ty, ngoài thẩm quyền PM, và PMO sở hữu lộ trình chuyển đổi. PM ghi lại bằng chứng và đưa lên sponsor cùng PMO để căn chỉnh tiêu chí.","Sai: functional manager có quyền đánh giá nhân sự nhưng tiêu chí do HR đặt cho cả công ty. Điều chỉnh tay từng trường hợp không sửa nguồn xung đột và gây bất công với nhân sự ngoài pilot; đúng nếu HR cho phép ngoại lệ.","Sai: PM không có quyền thay đổi hệ thống đánh giá của HR. Tự sửa mục tiêu trong dự án tạo ra tiêu chuẩn không được tổ chức công nhận.","Sai: quay lại gate làm mất mục đích của pilot chuyển đổi, kể cả khi có sự đồng ý của PMO. Vấn đề được giải quyết bằng căn chỉnh tiêu chí, không bằng bỏ cách làm mới."],exp:"B7 (Evaluate the impact of organizational change on the project and determine required actions): chuyển đổi cần các hệ thống hỗ trợ (đánh giá, quản trị) đồng bộ. PM nêu mâu thuẫn bằng bằng chứng cho người có quyền thay đổi, không tự xử hay bỏ cuộc."},{id:"o493",n:493,t:0,origin:"original",eco:"B8",domain:"business",approach:"predictive",tags:["predictive","eco-2026","regulation","compliance-impact","change-request"],type:"mc",q:"A predictive project is building a customer-data portal, and its design baseline is approved. The government publishes a new data-protection regulation that takes effect in 14 months, two months after planned go-live, with consent-recording requirements. The scope statement does not mention them, and nobody has yet worked out what they would cost or change. What should the project manager do?",opts:["Add the consent requirements to the design baseline with the architect now and update the cost and schedule baselines to match","Complete the portal as baselined and ask the compliance team to deal with the regulation after go-live","Ask the sponsor whether to continue the project, given that the regulation may affect the business case","Consult legal and compliance on how the regulation affects scope, then raise a change request if needed"],ans:[3],why:["Sai: tuân thủ là bắt buộc và đúng nếu thay đổi đã được duyệt, nhưng thay đổi baseline phải đi qua change control sau khi đánh giá. Thêm trực tiếp bỏ qua phân tích chi phí và lịch.","Sai: quy định có hiệu lực hai tháng sau go-live, có thể buộc làm lại phần đã xây. Quyết định làm sau phải dựa trên phân tích, không phải mặc định.","Sai: hỏi sponsor có nên tiếp tục đúng khi phân tích cho thấy business case mất hiệu lực, nhưng chưa có phân tích nào như vậy. Yêu cầu ghi nhận sự đồng ý chỉ bổ sung vào phạm vi của portal chứ không làm portal mất giá trị.","Đúng: PM khảo sát quy định và cùng pháp chế đánh giá tác động lên yêu cầu và phạm vi trước khi đụng đến baseline. Nếu cần thay đổi thì đi qua change request, phù hợp với dự án predictive có baseline đã duyệt."],exp:"B8 (Survey changes ... regulations, Assess and prioritize the impact on scope): quy định mới được phân tích tác động rồi mới quyết định hành động qua change control. Quy tắc nhớ: khảo sát, đánh giá, rồi mới thay đổi."},{id:"o494",n:494,t:0,origin:"original",eco:"B8",domain:"business",approach:"predictive",tags:["predictive","eco-2026","environmental-scanning","continuous-review"],type:"mc",q:"A predictive eight-year port-expansion programme scanned the external environment during initiation, covering regulations, technology, and trade conditions. The programme has a gate review at the end of each of its five phases, where scope and budget are re-approved. Four years later, no further scan has taken place, and a stakeholder complains that two new emissions rules surfaced with no warning. What should the project manager have done?",opts:["Scheduled a full re-scan of regulations, technology and trade conditions every two years, led by the programme office","Asked the sponsor to brief the programme on external developments at each quarterly steering committee meeting","Built an external scan into each phase gate review, prepared by the programme office before re-approval","Assigned the legal department to monitor emissions regulations and report any new rule to the programme each month"],ans:[2],why:["Sai: quét lại toàn bộ mỗi hai năm đúng nếu thay đổi bên ngoài chậm, nhưng chu kỳ này không gắn với các cổng duyệt phạm vi và ngân sách nên quy định mới vẫn có thể xuất hiện giữa hai lần quét.","Sai: báo cáo của sponsor hàng quý không đảm bảo bao phủ quy định, công nghệ và thương mại. Đúng nếu sponsor có nguồn tin chuyên trách, nhưng ở đây không có, và việc này không gắn với cổng duyệt.","Đúng: tám năm là thời gian dài nên cần rà soát môi trường bên ngoài lặp lại theo kế hoạch, gắn với phase gate, nơi phạm vi và ngân sách được duyệt lại, và có người chuẩn bị. Nhờ vậy tác động lên scope được phát hiện sớm.","Sai: pháp chế theo dõi quy định phát thải là hợp lý, nhưng stem nêu rà soát gồm cả quy định, công nghệ và điều kiện thương mại. Chỉ giao cho một phòng và một loại quy định thì bỏ sót công nghệ và thương mại."],exp:"B8 (Continually review the external business environment for impacts on project scope): rà soát bên ngoài phải là hoạt động lặp có kế hoạch, có chủ sở hữu và nguồn tin, đặc biệt với dự án dài. Bẫy là chỉ quét một lần lúc khởi động."},{id:"o495",n:495,t:0,origin:"original",eco:"B8",domain:"business",approach:"agile",tags:["agile","eco-2026","technology-change","end-of-support","backlog"],type:"mc",q:"A Scrum team's product relies on a managed database service. The cloud provider announces that the service version will reach end of support in nine months, and later versions change several features the product uses. The team's tech lead has already listed the affected features. The team is in sprint 9, and the product owner is focused on new customer features. What should the project manager do?",opts:["Ask the team and product owner to migrate in the next sprint and set aside other work while the changes are fresh","Ask the provider's support team to decide the migration timing for the product's managed database service","Place prioritised migration items in the backlog with the product owner, ahead of the end-of-support date","Analyse with the team how each listed feature breaks on newer versions and prepare a report for the product owner"],ans:[2],why:["Sai: di chuyển ngay sprint sau mà chưa xếp ưu tiên là phản ứng quá mức. Chín tháng đủ để lập kế hoạch và ưu tiên cạnh các tính năng đang có giá trị.","Sai: nhà cung cấp biết phiên bản nhưng không biết những tính năng nào sản phẩm của đội dựa vào. Quyết định ưu tiên là của đội và product owner.","Đúng: thay đổi công nghệ bên ngoài có hạn chót cụ thể và tech lead đã liệt kê tính năng bị ảnh hưởng. PM làm việc với đội và product owner để đưa các mục di chuyển đã được ưu tiên vào backlog trước thời hạn.","Sai: phân tích và làm báo cáo là cần khi chưa biết tác động, nhưng tech lead đã liệt kê các tính năng bị ảnh hưởng. Báo cáo không đưa việc vào backlog; cần xếp ưu tiên cùng product owner ngay."],exp:"B8 (Survey changes ... technology, Assess and prioritize the impact on backlog): thay đổi công nghệ có thời hạn được đưa vào backlog theo mức ưu tiên cùng giá trị khác. Quy tắc nhớ: đánh giá, ưu tiên, xếp lịch."},{id:"o496",n:496,t:0,origin:"original",eco:"B8",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","generative-ai","competitor","market-analysis","ai"],type:"mc",q:"A hybrid project is developing a customer-service platform with a predictive hardware-integration phase and agile software releases. A competitor launches an AI chat feature at a lower price, and the sponsor asks the project manager to add something similar to the scope this quarter and wants a decision within three weeks. No customer research on the feature has been done, and no estimates exist for it. What should the project manager do?",opts:["Ask the product owner to put a time-boxed discovery item in the next refinement, producing demand data plus an estimate","Add an AI chat epic to the backlog now, and have the product owner rank it against the current items this sprint","Ask the team to build a prototype this sprint, and let the sponsor judge the feature from the prototype","Commission a full customer and market study with marketing and hold the backlog unchanged until the results arrive"],ans:[0],why:["Đúng: PM cùng product owner đưa một mục khám phá có time-box vào refinement kế tiếp để có dữ liệu nhu cầu và ước lượng, kịp quyết định trong ba tuần. Tính năng của đối thủ là thông tin cần phân tích, không phải mệnh lệnh.","Sai: thêm epic rồi để product owner xếp hạng đúng nếu đã có dữ liệu để xếp, nhưng ở đây chưa có nghiên cứu khách hàng và chưa có ước lượng. Thêm epic ngay chỉ để chứng minh phản ứng là hành động theo áp lực.","Sai: làm prototype trong sprint này tốn năng lực đội và có thể gây gián đoạn nhánh phần cứng. Prototype có thể là bước sau, khi đánh giá cho thấy cần.","Sai: nghiên cứu thị trường đầy đủ cho biết nhu cầu, đúng nếu không bị giới hạn thời gian, nhưng sponsor cần quyết định trong ba tuần và nghiên cứu lớn sẽ không kịp. Giữ nguyên backlog trong lúc chờ cũng không cho ước lượng chi phí."],exp:"B8 (Assess and prioritize the impact on project scope/backlog based on changes in the external business environment): tính năng AI của đối thủ là thay đổi thị trường. Cách đúng là thu thập nhu cầu, chi phí, tác động bằng một bước khám phá có thời hạn rồi mới sửa backlog. Bẫy là chạy theo đối thủ hoặc phớt lờ."},{id:"o497",n:497,t:0,origin:"original",eco:"B8",domain:"business",approach:"predictive",tags:["predictive","eco-2026","geopolitical","procurement","supply-chain","confirm-first"],type:"mc",q:"A predictive project builds a solar-farm control system using inverters imported from one country. That country's trade ministry announces export licensing for such equipment, effective in three months, while the inverters are scheduled for delivery in five months. The announcement does not list the covered equipment codes, and the contract has no clause covering licensing changes. What should the project manager do first?",opts:["Ask the supplier to guarantee the original delivery date through a contract amendment with delay penalties","Confirm the alternative supplier's availability with procurement and prepare a change request for the baseline as soon as possible","Check with the supplier's export desk whether the rule covers these inverters and how long a licence would take","Place orders for the inverters with procurement before the rule takes effect and accept the storage cost of holding them on site"],ans:[2],why:["Sai: đòi bảo đảm và phạt đúng nếu rule chắc chắn áp dụng và lỗi do nhà cung cấp, nhưng hợp đồng không có điều khoản về giấy phép nên họ khó cam kết. Yêu cầu này có thể làm hỏng quan hệ mà chưa giải quyết vấn đề.","Sai: xác nhận nhà cung cấp thay thế và làm change request đúng nếu đã biết inverter bị ảnh hưởng, nhưng thông báo chưa nêu mã thiết bị bị áp dụng. Chưa biết liệu cần thay nhà cung cấp hay không.","Đúng: thông báo không nêu rõ thiết bị nào bị áp dụng, nên PM xác nhận với nhà cung cấp xem rule có bao gồm các inverter này không và giấy phép làm thêm bao lâu. Sau đó mới phân tích tác động lên baseline và chọn phương án với procurement và sponsor.","Sai: đặt hàng sớm là một lựa chọn có thể, đúng nếu đã chắc inverter bị áp dụng, nhưng quyết định trước khi xác nhận phạm vi rule và đánh giá chi phí lưu kho, dòng tiền thì chưa có cơ sở."],exp:"B8 (Survey changes ... geopolitical, Assess impact on scope): khi thông báo của chính phủ chưa rõ phạm vi, PM xác nhận rule có áp dụng cho sản phẩm của dự án và thời gian cấp phép trước, rồi mới đánh giá tác động lên baseline và chọn đối phó. Quy tắc nhớ: xác nhận phạm vi, đánh giá, rồi mới chọn phương án."},{id:"o498",n:498,t:0,origin:"original",eco:"B8",domain:"business",approach:"agile",tags:["agile","eco-2026","market-review","product-owner","roadmap"],type:"mc",q:"After eight sprints, the product team's backlog still reflects the market research done at project start. Sales reports that two customer segments have shifted to a competitor, and new pricing norms have emerged in the industry. No one has been assigned to follow external developments, and refinement sessions focus on team-internal topics. What should the project manager do?",opts:["Commission a new market study owned by marketing and pause refinement until its findings are ready for the team","Ask the product owner to redraft the roadmap every month from the sales team's input on the two segments","Ask sales to prepare a report on the competitor and have the team build features to match it quickly","Set up a regular review of external information that feeds refinement with the product owner"],ans:[3],why:["Sai: dừng refinement chờ nghiên cứu mới làm đội trống việc và quá mức. Thông tin mới nên đi vào refinement liên tục, không đợi một báo cáo lớn.","Sai: viết lại roadmap chỉ dựa trên ý kiến của bộ phận bán hàng là phản ứng quá đà với dữ liệu một phía. Roadmap cần được điều chỉnh qua rà soát thông tin bên ngoài, đúng nếu có nhiều nguồn xác nhận.","Sai: chạy theo tính năng đối thủ dựa trên báo cáo của một bộ phận thiếu kiểm chứng giá trị. Cần đánh giá nhu cầu trước khi quyết định xây gì.","Đúng: B8 nhấn mạnh rà soát liên tục. PM thống nhất với product owner một nhịp rà soát thông tin bên ngoài và đưa kết quả vào refinement cùng release planning."],exp:"B8 (Continually review the external business environment for impacts on backlog): ở agile, backlog được điều chỉnh liên tục theo thông tin thị trường qua refinement và release planning. Quy tắc nhớ: rà soát có nhịp, có chủ sở hữu."},{id:"o499",n:499,t:0,origin:"original",eco:"B8",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","regulation","accessibility","dual-workstream"],type:"mc",q:"A hybrid project delivers a public-service kiosk. The physical kiosk is built in a phase-gated workstream with an approved baseline, while the on-screen software is delivered in sprints. A new accessibility regulation is published that affects touchscreen height and screen contrast, and the compliance officer has confirmed that it applies to the kiosk. What should the project manager do?",opts:["Treat the regulation as a backlog item for both workstreams and let the product owner decide the ordering of work","Raise one change request covering both workstreams and have the product owner reorder the backlog","Raise a change request for the kiosk workstream and prioritise backlog items for the software workstream","Ask the compliance officer to confirm that it applies, then deal with it in the kiosk workstream"],ans:[2],why:["Sai: đưa vào backlog cho cả hai nhánh bỏ qua baseline của phần cứng. Chiều cao màn hình là thay đổi thiết kế phải qua change control, không do product owner quyết thứ tự.","Sai: một change request chung cho cả hai nhánh áp quy trình thay đổi của nhánh có baseline lên nhánh sprint. Phần mềm quản lý thay đổi qua backlog và product owner, còn kiosk có baseline đã duyệt mới cần change request.","Đúng: quy định ảnh hưởng cả phần cứng (độ cao) và phần mềm (độ tương phản). Với kiosk có baseline thì dùng change request, với phần mềm thì ưu tiên các mục trong backlog theo nhịp sprint.","Sai: compliance officer đã xác nhận quy định áp dụng, nên bước xác nhận thêm là thừa. Ngoài ra xử lý riêng nhánh kiosk bỏ sót phần mềm, vốn trực tiếp bị ảnh hưởng bởi yêu cầu về độ tương phản."],exp:"B8 (Assess and prioritize the impact on project scope/backlog): dự án hybrid xử lý một thay đổi bên ngoài theo cách khác nhau cho từng nhánh: change control cho nhánh predictive, backlog cho nhánh agile. Quy tắc nhớ: tailor theo từng nhánh."},{id:"o500",n:500,t:0,origin:"original",eco:"B8",domain:"business",approach:"predictive",tags:["predictive","eco-2026","prioritization","regulation","competitor","technology"],type:"mc",q:"A predictive 30-month data-centre project receives three external updates in one month: a new fire-safety code that applies to the project's building permit and takes effect in six months, a competitor's price cut on colocation space, and a vendor's announcement of a new generation of cooling units. Construction begins in eight months. How should the project manager handle them?",opts:["Rank the three by effect on scope, putting the mandatory fire-safety code at the top of the list","Rank the three by their effect on the business case, with the competitor's price cut at the top of the list","Rank the three by the number of design drawings each would change, with the cooling announcement at the top","Submit one combined change request for all three updates and let the sponsor and change board sort out the order"],ans:[0],why:["Đúng: PM xếp hạng ba thay đổi theo tác động lên phạm vi và hạn chót, đặt bộ luật phòng cháy lên đầu vì bắt buộc và có hạn chót trong dòng thời gian dự án. Hai thay đổi còn lại xem xét sau.","Sai: xếp theo tác động lên business case đặt giá của đối thủ lên đầu. Giá đối thủ ảnh hưởng đến kinh doanh nhưng chưa có yêu cầu bắt buộc đối với dự án; ưu tiên phải dựa trên tác động lên phạm vi.","Sai: xếp theo số bản vẽ bị đổi đặt công nghệ làm mát lên đầu, nhưng đó mới là thông báo của nhà cung cấp, chưa có yêu cầu bắt buộc. Thay thiết kế khi chưa có lý do cụ thể có thể gây thêm chi phí.","Sai: gộp ba thay đổi có bản chất khác nhau vào một change request rồi nhờ sponsor sắp xếp là bỏ việc phân tích của PM. Sponsor cần được trình ưu tiên đã đánh giá."],exp:"B8 (Assess and prioritize the impact on project scope based on changes in the external business environment): nhiều thay đổi cùng lúc được xếp hạng theo tác động lên phạm vi và tính bắt buộc. Quy tắc nhớ: quy định bắt buộc trong khung thời gian dự án ưu tiên cao nhất."}],e=[...h,...i,...a,...o,...c,...r].sort((n,t)=>n.n-t.n),s=e.filter(n=>n.n<=226),g=e.filter(n=>n.n>=227);export{s as O,g as a};
